INSERT INTO "texts" VALUES ('ZZ100001', '游戏', '只有你的领域会变成黑暗（恶魔族·魔法师族的攻击力及守备力都会各增加200点，天使族的攻击力及守备力下降200点。）祭品召唤「黑魔术师」，我方的准备阶段失去300点的生命值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100002', '达姿', '发动这张卡，可以任意让「奥利哈钢的结界」、「奥利哈钢之气」、「奥利哈钢  托利托斯」其中1张无条件跳到卡组最上方。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100003', '不死之欧贝利斯克·巨神兵', '这张卡不能特殊召唤只能将自己场上3只不死族怪兽解放作召唤，这张卡的召唤不会被无效化，这张卡召唤成功后回合，对方不能发动卡片效果。可以把我方场上1只不死族怪兽解放，对方场上所有怪兽全部破坏。这张卡攻击时可以对对方场上所有怪兽各攻击1次。这张卡在攻击时直接伤害计算结束阶段，对方不能发动魔法·陷阱卡效果。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100004', '不死之太阳神·翼神龙', '这张卡不能特殊召唤只能将自己场上3只不死族怪兽解放作召唤，这张卡的召唤不会被无效化。这张卡召唤成功后回合，对方不能发动卡片效果，这张卡的攻击力为祭品怪兽攻击力的总合。此外，可以把生命值支付到变为100，这张卡的攻击力·守备力上升支付的数值，当这张卡成为对方魔法·陷阱·怪兽效果对象时，将我方墓地3张名字带有「不死」的卡片移除，让那个效果无效化，并破坏那张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100005', '不死之青眼究极龙', '此卡不能特殊召唤，只能把我方场上3只不死族怪兽作为祭品通常召唤。这张卡召唤成功回合，我方不受对方卡片效果影响，并选择破坏对方怪兽区域或魔法陷阱区域所有卡片。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100006', '不死之青眼白龙', '这张卡的攻击力，我方墓地每存在1只不死族怪兽，上升500点。移除我方墓地1只不死族怪兽，可以把以这张卡为对象的魔法·陷阱·怪兽的效果无效化。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100007', '不死之栗子球', '从手牌丢弃这张卡，我方受到的战斗伤害1次为0。并给予对方这张卡攻击力数值的生命值伤害。这个效果只能在对方的战斗回合使用。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100008', '被封印的不死之亡灵', '这张卡和「不死之亡灵的右足」「不死之亡灵的左足」「不死之亡灵的右腕」「不死之亡灵的左腕」在墓地全部齐集时，可以从卡组·墓地·手卡特殊召唤「不死之亡灵艾克佐迪亚」。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100009', '不死之亡灵的右腕', '进行不死族怪兽的祭品召唤时，此怪兽1只可以作为2只祭品使用这张卡因卡效果或作为祭品从场上送去墓地时，可以从卡组选择1张名字带有「不死之亡灵」的卡片加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100010', '不死之亡灵的左腕', '进行不死族怪兽的祭品召唤时，此怪兽1只可以作为2只祭品使用这张卡因卡效果或作为祭品从场上送去墓地时，可以从卡组选择1张名字带有「不死之亡灵」的卡片加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100011', '法老王 亚图姆', '此卡特殊召唤成功后，可以将我方卡组1张名字带有「千年」的魔法卡加入手牌。1回合1次，将此卡攻击力下降500，可以将墓地1张名字带有「神官」的卡特殊召唤上场。特殊召唤的卡效果无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100012', '爱西斯神官', '此卡特殊召唤成功后，可以将墓地的5张卡加入卡组并洗切，此卡在场上正面表示存在场上时，对方不能发动陷阱卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100013', '胡狼神之法老', '此卡被特殊召唤成功的回合，此卡不能发动攻击，舍弃我方全部手牌，对方场上的所有卡片全部破坏。此卡在场上正面表示存在时，双方除此卡外的神属性怪兽无法召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100014', '千年积木', '七神器之卡。
INSERT INTO "texts" VALUES ('ZZ100015', '千年首饰', '七神器之卡。
INSERT INTO "texts" VALUES ('ZZ100016', '千年智慧轮', '七神器之卡。
INSERT INTO "texts" VALUES ('ZZ100017', '千年锡杖', '七神器之卡。
INSERT INTO "texts" VALUES ('ZZ100018', '千年眼', '七神器之卡。
INSERT INTO "texts" VALUES ('ZZ100019', '千年秤', '七神器之卡。
INSERT INTO "texts" VALUES ('ZZ100020', '千年钥匙', '七神器之卡。
INSERT INTO "texts" VALUES ('ZZ100021', '太阳神之钢铁进化龙', '此卡召唤成功后可以视为任意属性，针对此卡的效果怪兽的效果和魔法卡只有1回合，针对此卡的陷阱卡效果无效并破坏。1回合1次，降低此卡1000点攻击力数值，给予对方此卡等级×300点的生命值伤害。发动此效果的回合，此卡不能发动攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100022', '太阳神之绿化龙', '此卡召唤成功后可以视为任意属性，针对此卡的效果怪兽的效果和魔法卡只有1回合，针对此卡的陷阱卡效果无效并破坏。从卡组抽取5张卡，此卡攻击力上升抽出的卡中名字带有「太阳神」的怪兽等级之和×200点。之后将抽取的卡放入卡组洗切。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100023', '太阳神之异能判决', '此卡召唤成功后可以视为任意属性，针对此卡的效果怪兽的效果和魔法卡只有1回合，针对此卡的陷阱卡效果无效并破坏。我方每发动1张名字带有「太阳神」的魔法·陷阱卡，给此卡添加1个「太阳神指示物」，取除1个「太阳神指示物」可以让对方发动的魔法·陷阱卡效果无效并破坏，1个回合最多取除2个「太阳神指示物」。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100024', '太阳神之岩石龙', '此卡召唤成功后可以视为任意属性，针对此卡的效果怪兽的效果和魔法卡只有1回合，针对此卡的陷阱卡效果无效并破坏。墓地存在2只以上名字带有「太阳神」的怪兽时，此卡可以从手牌·卡组特殊召唤上场。1回合1次，此卡直接攻击对方玩家并造成伤害时给予对方追加此卡守备力数值的伤害。此卡被破坏送去墓地时，可以从手牌·卡组特殊召唤1张同名卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100025', '太阳神之幻影使者', '此卡召唤成功后可以视为任意属性，针对此卡的效果怪兽的效果和魔法卡只有1回合，针对此卡的陷阱卡效果无效并破坏。1回合1次，战斗阶段时，掷1次骰子，此卡攻击力上升骰子数值×300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100026', '太阳神之女圣战', '此卡召唤成功后可以视为任意属性，针对此卡的效果怪兽的效果和魔法卡只有1回合，针对此卡的陷阱卡效果无效并破坏。此卡战斗破坏对方怪兽时，不计算战斗伤害，下个我方回合，被此卡战斗破坏的那只怪兽特殊召唤到我方场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100027', '太阳神之圣龙徽章', '此卡召唤成功后可以视为任意属性，针对此卡的效果怪兽的效果和魔法卡只有1回合，针对此卡的陷阱卡效果无效并破坏。此卡发动攻击宣言时，对方从我方卡组最上方抽1张卡，我方猜那张卡的种类怪兽·魔法·陷阱卡，猜对的场合那张卡加入手牌，此卡直接攻击对方生命值。猜错的场合，那张卡和此卡破坏送入墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100028', '太阳神之鹰身人', '此卡召唤成功后可以视为任意属性，针对此卡的效果怪兽的效果和魔法卡只有1回合，针对此卡的陷阱卡效果无效并破坏。我方墓地名字带有「太阳神」的怪兽有3个种类时，此卡可以从手牌·卡组特殊召唤上场。用这个效果特殊召唤不会被无效化。1回合1次，宣言1个种族，给予对方手牌那个种族的怪兽数量×500点的生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100029', '太阳神之光龙', '此卡召唤成功后可以视为任意属性，针对此卡的效果怪兽的效果和魔法卡只有1回合，针对此卡的陷阱卡效果无效并破坏。1回合1次，此卡不会被破坏，此卡被送去墓地时，我方回复此卡攻击力数值的生命值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100030', '太阳神之红魔顿龙', '此卡召唤成功后可以视为任意属性，针对此卡的效果怪兽的效果和魔法卡只有1回合，针对此卡的陷阱卡效果无效并破坏。当此卡被选为攻击对象时，可以将手牌1只名字带有「太阳神」的怪兽送去墓地，伤害计算减半，此卡不会被战斗破坏，我方准备阶段，此卡攻击力上升那次攻击伤害计算结果数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100031', '太阳神之守护女', '此卡召唤成功后可以视为任意属性，针对此卡的效果怪兽的效果和魔法卡只有1回合，针对此卡的陷阱卡效果无效并破坏。翻转：选择对方场上1只怪兽，给予对方那只怪兽等级×600点生命值伤害，此效果不会被无效化。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100032', '太阳神之雷龙', '此卡召唤成功后可以视为任意属性，针对此卡的效果怪兽的效果和魔法卡效果只有1回合，针对此卡的陷阱卡效果无效并破坏。此卡可以直接从手牌送入墓地，从卡组特殊召唤1只名字带有「太阳神」的怪兽正面攻击表示上场，此效果的发动不会被无效化。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100033', '太阳神之失败的恶果', '针对此卡的效果怪兽的效果和魔法卡效果只有1回合，针对此卡的陷阱卡效果无效并破坏。每当我方直接攻击成功时，对方手牌全部送入卡组洗切，然后抽1张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100034', '太阳神之能量封印', '针对此卡的效果怪兽的效果和魔法卡效果只有1回合，针对此卡的陷阱卡效果无效并破坏。每当对方发动魔法·陷阱卡，发动时必须支付500点生命值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100035', '太阳神之黄金巨盾', '针对此卡的效果怪兽的效果和魔法卡效果只有1回合，针对此卡的陷阱卡效果无效并破坏。此卡只能装备给名字带有「太阳神」的怪兽，装备此卡的怪兽不受对方效果怪兽的效果影响。装备此卡的怪兽被破坏送入墓地时，我方从墓地选1张卡加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100036', '太阳神之无懈可击', '针对此卡的效果怪兽的效果和魔法卡效果只有1回合，针对此卡的陷阱卡效果无效并破坏。我方受到战斗伤害以外的伤害时发动，我方所受的伤害转移给对方。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100037', '太阳神的诅咒', '针对此卡的效果怪兽的效果和魔法卡效果只有1回合，针对此卡的陷阱卡效果无效并破坏。限此卡在场上时，对方每回合损失800点的生命值，对方可以支付2000点的生命值将这张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100038', '太阳神的意志', '针对此卡的效果怪兽的效果和魔法卡效果只有1回合，针对此卡的陷阱卡效果无效并破坏。根据我方墓地名字带有「太阳神」的怪兽数量得到以下效果：●3张·对方魔法·陷阱卡区域的1张卡破坏。●5张·对方场上1只怪兽破坏。●8张·对方手牌全部破坏。
INSERT INTO "texts" VALUES ('ZZ100039', '太阳神之紧急提升', '针对此卡的效果怪兽的效果和魔法卡效果只有1回合，针对此卡的陷阱卡效果无效并破坏。选择我方场上正面表示存在的1只名字带有「太阳神」的怪兽，选择的怪兽在此回合结束前攻击力上升墓地名字带有「太阳神」的怪兽数量×500点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100040', '太阳神的光辉', '针对此卡的效果怪兽的效果和魔法卡效果只有1回合，针对此卡的陷阱卡效果无效并破坏。我方从卡组抽取3张卡给对方看并加入手牌。每有1张名字带有「太阳神」的卡，我方回复1000点生命值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100041', '太阳神的血之祭召', '针对此卡的效果怪兽的效果和魔法卡效果只有1回合，针对此卡的陷阱卡效果无效并破坏。将我方墓地名字带有「太阳神」怪兽尽可能多的特殊召唤上场，因此效果每召唤1只怪兽我方需要支付500点生命值。此卡效果无效送去墓地时，对方场上正面表示的怪兽全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100042', '太阳神之黑鸟的恐惧', '针对此卡的效果怪兽的效果和魔法卡效果只有1回合，针对此卡的陷阱卡效果无效并破坏。对方发动魔法·陷阱卡时发动，那个效果无效和对方场上的所有卡回到手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100043', '太阳神之领域升华', '针对此卡的效果怪兽的效果和魔法卡效果只有1回合，针对此卡的陷阱卡效果无效并破坏。支付600点生命值，让对方怪兽卡的效果发动无效并破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100044', '太阳神的六武之道', '针对此卡的效果怪兽的效果和魔法卡效果只有1回合，针对此卡的陷阱卡效果无效并破坏。让对方掷1次骰子，根据所掷数值发动以下效果：●1和4·对方选择对方场上1张盖放的卡破坏。●2和5·破坏对方场上的1只怪兽。●3和6·确认对方的手牌，我方选择对方的1张手牌送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100045', '太阳神之恶魔的恐吓', '针对此卡的效果怪兽的效果和魔法卡效果只有1回合，针对此卡的陷阱卡效果无效并破坏。每当对方发动攻击时，必须猜我方卡组最上方1张卡的种类怪兽·魔法·陷阱卡，猜对的场合继续攻击，猜错的场合，那张卡加入我方手牌，直接跳过对方的攻击阶段。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100046', '太阳神之手牌舍弃', '针对此卡的效果怪兽的效果和魔法卡效果只有1回合，针对此卡的陷阱卡效果无效并破坏。将2张手牌送去墓地，对方跳过抽卡阶段，此效果2个回合才可以使用1次。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100047', '冥界大邪神石板', '只要战斗场上或墓地中同时存在7张不同的“七神器之卡”与」「遗失七神器的石板」，就可以特殊召唤此卡并释放冥界大邪神的无限力量，破坏对方所有的手牌而获得胜利。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100048', '诸神遗迹·巨臂龙神 布赫斯', '
INSERT INTO "texts" VALUES ('ZZ100049', '欧贝利斯克之王', '1回合1次，此卡不受对方任何卡效果影响，此卡发动攻击宣言时可以对对方场上所有怪兽攻击1次，并无视被攻击的怪兽效果直接破坏那只怪兽，每战斗破坏对方场上1只怪兽，将对方魔法陷阱区1张卡片移除到游戏外。此卡不能直接攻击对方玩家生命值。限此卡在场，每个我方回合的准备阶段可以选择我方卡组·手牌或墓地1张名字带有「欧贝利斯克」的怪兽无条件特殊召唤到我方场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100050', '欧贝利斯克之主宰者-海马', '这张卡不能特殊召唤。这张卡的召唤不会无效化。这张卡通常召唤成功时，对方不能针对此卡发动魔法·陷阱·效果怪兽的效果。此外，1回合1次，可以把自己手牌2只怪兽送去墓地，对方场上的怪兽全部破坏。这个效果发动的回合，这个回合这张卡不能攻击宣言。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100051', '欧贝利斯克之铠甲-胸铠', '这张卡不能特殊召唤。这张卡的召唤不会无效化。这张卡通常召唤成功时，对方不能针对此卡发动魔法·陷阱·效果怪兽的效果。此外，限此卡在我方场上正面表示存在时，我方攻击阶段对方所有效果怪兽的效果无效化。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100052', '欧贝利斯克之铠甲-护臂', '这张卡不能特殊召唤。这张卡的召唤不会无效化。这张卡通常召唤成功时，对方不能针对此卡发动魔法·陷阱·效果怪兽的效果。此外，1回合1次，选择对方场上1只攻击力在此卡以下的怪兽才能发动。选择的怪兽送入墓地，给予对方生命值那只怪兽攻击力点数的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100053', '欧贝利斯克之铠甲-羽翼', '这张卡不能特殊召唤。这张卡的召唤不会无效化。这张卡通常召唤成功时，对方不能针对此卡发动魔法·陷阱·效果怪兽的效果。此外，此卡被战斗破坏后，可以当做永续魔法或陷阱卡使用。只要此卡存在魔法陷阱区域，对方不能发动魔法或陷阱卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100054', '欧贝利斯克之铠甲-头盔', '这张卡不能特殊召唤。这张卡不能特殊召唤。这张卡的召唤不会被无效化。在这张卡的召唤成功时，魔法·陷阱·怪兽的效果不能发动。
INSERT INTO "texts" VALUES ('ZZ100055', '欧贝利斯克之铠甲-护腿', '这张卡不能特殊召唤。这张卡的召唤不会无效化。这张卡通常召唤成功时，对方不能针对此卡发动魔法·陷阱·效果怪兽的效果。此外，限此卡在我方场上正面攻击表示存在时，我方抽卡阶段时，抽到的卡为怪兽卡可以无视条件特殊召唤到场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100056', '欧贝利斯克之火焰兵', '只要此卡正面表示存在于场上，对方场上所有名字带有「植物」和「装甲」的卡片效果无效并破坏，对方无法召唤和发动名字带有「植物」和「装甲」的卡片。将我方场上3只怪兽作为祭品才能从手牌·墓地·卡组·游戏外特殊召唤上场。舍弃1张手牌可以直接攻击对方，对方对应此效果发动魔法·陷阱·效果怪兽的效果无效并破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100057', '欧贝利斯克之甲虫恶魔', '只要此卡正面表示存在于场上，对方场上所有名字带有「植物」和「装甲」的卡片效果无效并破坏，对方无法召唤和发动名字带有「植物」和「装甲」的卡片。支付1000点生命值，此卡从手牌·墓地·卡组·游戏外特殊召唤到场上，此召唤不会被无效化，召唤成功后，不能直接攻击对方，破坏对方魔法陷阱区的卡，给予对方被破坏的魔法·陷阱卡数量×1000点的生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100058', '神兵裁决', '只要我方场上存在名字带有「欧贝利斯克」的怪兽正面表示存在时，我方抽卡阶段时将抽出的卡给对方观看，只要抽出的是名字带有「欧贝利斯克」的卡时我方可以继续抽牌，直到抽到其他卡为止。当此卡因对方卡的效果破坏时，无条件强制破坏对方场上1张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100059', '三国传-刘备', '此卡不能通常召唤。只要此卡守备表示存在于我方场上对方就不能以我方其他卡片作为攻击对象。每到我方回合的准备阶段，此卡增加1个「魔力指示物」，每当对方发动魔法·陷阱·怪兽效果时去除此卡1个「魔力指示物」，让那个效果发动无效，并破坏那张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100060', '三国传-曹操', '这张卡的攻击力等于对方墓地存在的卡片数×300的数值。当此卡被破坏从场上离开时，可以将我方场上1只或手牌2只名字带有「三国传」的怪兽移除到游戏外，让此卡重新回到场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100061', '三国传-吕布·炎', '这张卡不能特殊召唤，只能用3只名字带有「三国传」的怪兽作为祭品的场合才能通常召唤。此卡召唤成功后破坏对方场上所有卡片。每到我方回合的准备阶段，给予对方我方场上存在的名字带有「三国传」的卡片数量×500的生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100062', '三国传-吕布·暗', '这张卡不能特殊召唤。把自己场上存在的名字带有「三国传」的怪兽作为祭品的场合才能通常召唤。这张卡召唤成功的场合，用对方回合计算的3回合内对方不能发动魔法·陷阱卡。这张卡的攻击·守备力变成双方墓地攻击力最高的怪兽的攻击力+500的数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100063', '三国传-赵云', '这张卡攻击的场合，对方直到伤害步骤结束时不能发动怪兽效果。这张卡攻击的伤害步骤结束时，给予对方追加此卡攻击力1半数值的生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100064', '三国传-张飞', '1回合1次，这张卡不受对方怪兽效果影响。当此卡发动攻击宣言后可以对对方场上所有怪兽各攻击1次。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100065', 'CF-M-60STD 狙击枪', '此卡在场上正面攻击表示存在时，对方不能特殊召唤怪兽上场。此卡由于战斗破坏送入墓地时，可以选择对方场上1只怪兽破坏，给予双方玩家那只怪兽攻击力数值的生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100066', 'CF-SPAS12 散弹枪', '双方魔法陷阱区每有1张卡片，此卡攻击力上升300点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100067', 'CF-MC51 冲锋枪', '1回合1次，此卡攻击宣言时发动，掷1次骰子，直到我方回合结束阶段，此卡攻击力上升骰子点数×100的攻击力数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100068', '真红眼究极巨龙', '4星怪兽×2
INSERT INTO "texts" VALUES ('ZZ100069', '真红眼操控龙', '5星怪兽×3
INSERT INTO "texts" VALUES ('ZZ100070', '真红眼闪光龙', '此卡可以从手牌直接召唤上场，此卡不会被战斗破坏，此回合结束阶段时，可从手牌或卡组把名字带有「真红眼」的怪兽尽可能的特殊召唤上场。当场上有3只名字带有「真红眼」的怪兽时，此卡可以直接对对方玩家造成所有生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100071', '真红眼究极龙', '「真红眼电子龙」+「真红眼电子龙」+「真红眼电子龙」
INSERT INTO "texts" VALUES ('ZZ100072', '灰钢真红眼黑龙 Ⅱ', '1回合1次，将2张手牌丢弃，从卡组抽2张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100073', '真红眼电子龙', '反转：从自己卡组抽1张卡。被对方怪兽的攻击反转的场合，从自己卡组选择1张卡加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100074', '真红眼长颈龙', '被对方怪兽攻击时，这张卡可变成装备卡装备在对方怪兽之上，得到那只怪兽的控制权。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100075', '黑龙的缠绕', '从卡组将1只「真红眼黑龙」召唤上场。
INSERT INTO "texts" VALUES ('ZZ100076', '真红爆发', '从墓地选择最多2张「真红眼电子龙」特殊召唤上场。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100077', '真红的保护', '我方场上存在「真红眼」的怪兽时，对方不能发动卡片效果，我方场上没有「真红眼」的怪兽存在时此卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100078', '长颈龙真红进化', '场上存在1只「真红眼长颈龙」时，可变为3只。其中两只效果无效也不能攻击，不能作为同调素材只能用作超量召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100079', '幻神器-巨神兵之恨', '此卡由于卡片效果而被送去墓地时，可以将我方手牌·卡组·墓地1张「欧贝利斯克之巨神兵」无视召唤条件特殊召唤上场，这个效果不会被无效化。之后，此卡作为装备卡装备在「欧贝利斯克之巨神兵」上。装备此卡的怪兽攻击力守备力上升2000点。此外，1回合1次，舍弃1张手牌，可以选择墓地1张卡特殊召唤到场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100080', '幻神器-天空龙之伤', '此卡由于战斗被破坏送去墓地时，可以将我方手牌·卡组·墓地1张「奥西里斯之天空龙」无视召唤条件特殊召唤上场。这个效果不会无效化。之后，此卡作为装备卡装备在「奥西里斯之天空龙」上。装备此卡的怪兽攻击力守备力上升2000点。此外，1回合1次，支付500点生命值，可以选择对方场上的1张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100081', '幻神器-翼神龙之怨', '此卡特殊召唤成功时，可以将我方手牌·卡组·墓地1张「太阳神之翼神龙」无视召唤条件特殊召唤上场。这个效果不会无效化。之后，此卡作为装备卡装备在「太阳神之翼神龙」上。装备此卡的怪兽攻击力守备力上升2000点。此外，1回合1次，将墓地1张卡移除到游戏外，可以选择卡组1张卡加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100082', '无名之龙 海聶兽斯之爪', '一万年前的“石之荒野之战”中传说之龙与「奥利哈钢之神」的对战！最后一起封印。
INSERT INTO "texts" VALUES ('ZZ100083', '无名之龙 克里提钨斯之牙', '一万年前的“石之荒野之战”中传说之龙与「奥利哈钢之神」的对战！最后一起封印。
INSERT INTO "texts" VALUES ('ZZ100084', '龙怒之波', '此卡只能装备在「青眼白龙王」之上。装备后的「青眼白龙王」发动的效果不作为卡效果发动。对方不能作出卡片效果反击。装备后的怪兽不会被破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100086', '绝对魔法圣结界', '自己场上存在怪兽卡的时候此卡不受对方任何卡影响。根据自己场上存在的卡片的种类得到以下效果：怪兽卡：自己场上存在的怪兽一回合又有一次机会，可以不被战斗破坏。同时根据自己场上存在的怪兽卡的种类此此卡可以再获得一下效果：（1）通常怪兽：可以一回合一次破坏对方场上一只怪兽。（2）效果怪兽：可破坏对方场上一张魔法/陷阱卡。（3）融合怪兽：可丢弃对方手牌的一张卡。（4）仪式怪兽：可以一回合一次破坏对方场上一张卡。（5）同步怪兽：一回合一次把对方卡组最上的一张卡送去墓地。根据自己场上存在的怪兽卡的属性此卡可以再获得一下效果：（1）风：我方怪兽攻击力上升500.（2）水：对方怪兽攻击力下降500。（3）炎：我方恢复我方怪兽×400生命。（4）地：对方消灭对方怪兽×400生命。（5）光：对方怪兽无法发动效果。（6）暗：对方怪兽必须攻击召唤的怪兽。魔法/陷阱卡：一回合一次把对方发动效果的卡发动无效并破坏。同时根据自己场上存在魔法/陷阱的数量此卡可以再获得一下效果：1：一回合一次从我方卡组拿一张魔法/陷阱卡到手牌。2.一回合一次从对方卡组拿一张卡送入墓地。3.对方一直公开手牌。4.一回合一次从对方卡组拿一张卡在对方卡组最上方安置。5.一回合一次猜对方卡组上一张的种类，对·那张卡从游戏中除外。错·那张卡回到对方手中。6.每到对方结束流程，对方卡组最上方的5张卡送入墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100087', '圣结界的巫女', '这张卡不能通常召唤，只有在只有【绝对魔法圣结界】在场上时，将自己场上的3只怪兽解放才能特殊召唤。这张卡不受对方任何效果影响。这张卡在场上正面表示存在时，属性也可以视为【地】【水】【炎】【风】【暗】。这张卡的种类也视为【通常怪兽】【效果怪兽】【融合怪兽】【同调怪兽】【仪式怪兽】。当场地魔法为【绝对魔法圣结界】时，此卡每回合可以选择以下一项发动。●一回合一次，无条件破坏对方场上3张卡。●一回合一次，在准备阶段给予对方1000点伤害。●一回合一次，查看对方卡组，并选择一张加入自己手牌。●一回合一次，选择对方卡组10张卡片送去墓地。●一回合一次，选择自己或对方卡组一张怪兽无条件召唤到自己场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100088', '终极魔法圣结界', '此卡发动第2回合后，我方领域上（牌组·额外牌组·手牌·场上及墓地）所有的卡不受对方卡片效果的影响，并可以任意发动或取消以下的效果。●我方怪兽1回合1次不被战斗破坏。●我方每回合可恢复我方现有生命值点数的数值。●我方场上有怪兽时，对方的怪兽不能直接攻击玩家。●我方场上所有怪兽攻守各增加1000点，并拥有贯穿伤害的能力。●我方怪兽破坏对方怪兽时，给予被破坏怪兽攻击力或守备力大小的伤害。●我方每回合可从双方领域或排除到游戏外的怪兽无视召唤条件并特殊召唤一只怪兽。●对方要一直公开手牌。●对方回合给予对方1000点的伤害。●对方回合可强制对方怪兽发动攻击。●1回合1次：破坏对方场上3张卡。●1回合1次，选择对方卡组中的10张卡送进墓地。●1回合1次：从我方牌组拿一张魔法或陷阱卡到手牌。●1回合1次，降低我方生命值来增加一只怪兽的攻击力。●1回合1次，查看对方牌组，并选择一张卡片加入到自己手牌。●1回合1次，将我方怪兽当祭品来增加一只怪兽的攻守能力，其上升数值是祭品怪兽的攻守能力。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100089', '巴斯达·比雷达', '这张卡的攻击力上升对方的场上·墓地的龙族怪兽数量×500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100090', '磁石的战士 马克宁多巴鲁其利翁', '这张卡不能通常召唤。从自己的手卡·卡组把「磁石战士α」「磁石战士β」「磁石战士γ」各1只解放的场合可以特殊召唤，可以把这张卡解放，以自己墓地的「磁石战士α」「磁石战士β」「磁石战士γ」各1只为对象才能发动。那只怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100091', '黑暗大法师', '
INSERT INTO "texts" VALUES ('ZZ100092', '青眼的光龙', '此卡不能被一般召唤和设置，也不能被特殊召唤除非用一张我方的「青眼的究极龙」当作祭品，我方墓地中每只龙族怪兽都会此卡增加300点攻击力，此卡也使得为目标的一切魔法陷阱，攻击都无效化。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100093', '惑星直列', '在对方场上存在的全部怪兽破坏。并给予对方基本分300伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100094', '欲望的代价', '可以从手牌中特殊召唤2只怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100095', '念动力低气压', '对方发动攻击宣言时，此卡可以发动，对方那只怪兽破坏，对方场上的魔法、陷阱卡全部回到对方手牌。我方每有1张手牌，对方必须把1张手牌丢弃。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100096', '恶作剧的神抽', '我方从卡组抽3张卡，不要的送入墓地，被抽出的卡是魔法、陷阱卡这回合可以直接发动，效果怪兽卡可以直接召唤上场，当场上正面表示的怪兽被破坏时，此卡代替破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100097', '邪心教典', '将「邪心教义-疑」、「邪心教义-憎」、「邪心教义-苦」、「邪心教义-怒」、「邪心教义-悲」这5张卡从场上或墓地移除游戏外时此卡才可以发动。对方每回合可以选择支付800点的生命值作为代价，如果对方不支付生命值的话，已方就可以无条件的从额外卡组里特殊召唤1只怪兽到场上，此卡被破坏，被特殊召唤出来的怪兽也被破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100098', '邪心教义-疑', '装备到自己场上的1只怪兽身上，每回合猜正反面，自己猜对我方场上的怪兽直接攻击对方，猜错我方场上该怪兽以外的怪兽全部被破坏。这张卡被送入墓地的时候，墓地里的同名卡从游戏中除外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100099', '邪心教义-憎', '可以把对方卡组最上面的2张卡送到墓地，每回合1次，这张卡被送入墓地的时候，墓地里的同名卡从游戏中除外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100100', '邪心教义-苦', '从手牌丢弃1张卡，可以破坏对方场上最多2张卡。这张卡被送入墓地的时候，墓地里的同名卡从游戏中除外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100101', '邪心教义-怒', '装备到自己场上的1只怪兽身上，将自己场上其他怪兽的攻击力集合到该怪兽身上，并且被集合的怪兽破坏。这张卡被送入墓地的时候，墓地里的同名卡从游戏中除外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100102', '邪心教义-悲', '每当自己从墓地里排除卡片到游戏外时，对方也要跟着从墓地里排除相同数目的卡片。这张卡被送入墓地的时候，墓地里的同名卡从游戏中除外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100103', '暗黑的霸王', '此卡成功发动时，就如「黑暗的霸王」降临，将会得到以下效果：
INSERT INTO "texts" VALUES ('ZZ100104', '祖母暗之书', 'Darknass暗黑道具之一：从自己的卡组或墓地选择3张卡加入到自己的手牌中。  ', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100105', '暗之魔力', 'Darknass暗黑道具之一：该卡能控制对方场上的1只怪兽，且不受对方任何怪兽效果·魔法·陷阱的影响。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100106', '暗黑之眼', 'Darknass暗黑道具之一：当自己场上有暗属性怪兽正面表示时，每回合可以观看对方的手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100107', '暗黑套索', 'Darknass暗黑道具之一：让自己或对方墓地的1只怪兽复活到我方场上，该怪兽每回合上升300点攻击·防守力。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100108', '暗黑之复活', 'Darknass暗黑道具之一：将我方墓地里的1只暗属性怪兽复活到自己的场上，破坏对方场上的1只原本攻击力比这只怪兽攻击力低的怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100109', '魔手', 'Darknass暗黑道具之一：从对方卡组中选择1张加入到自己手牌，并且对方必须从手牌中再舍弃1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100110', '死亡面具', 'Darknass暗黑道具之一：：自己场上的1只怪兽每回合共有2次攻击的机会，该怪兽每回合上升300点攻击·防守力。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100111', '黑暗根源', '发动此卡后，场上所有暗属性·恶魔族的怪兽每回合可以提高1000点的攻击力，场上除这张卡以外的魔法卡都不能发动，此卡的控制者每回合必须舍弃1张手牌，此卡被破坏送入墓地时，场上双方玩家各受1000点的生命伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100112', '邪神 迪亚邦多', '支付一半生命值可从手牌特殊召唤此卡，此卡不会被战斗破坏，也不受怪兽效果影响，当此卡战斗破坏对方怪兽时，被破坏的怪兽做装备卡装备在此卡上，每张提升500点攻击力，并获取被破坏怪兽的效果。（效果可叠加）', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100113', '奥利哈钢 天神荡', '此卡发动成功后，破坏对方卡组·手牌·场上区域中所有卡，并除外。此卡的发动和效果不会被破坏和无效化，此卡不受任何卡效果影响。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100114', '地狱之迪亚邦多', '当我方生命值低于1000时，此卡可以从手牌特殊召唤上场，此卡召唤成功时，场上除此卡以外的怪兽卡全部破坏，将我方生命值变为1点，此卡发动攻击时不受任何卡片效果影响。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100115', '祭品魔盘', '选择对方场上最多2只怪兽发动。这个回合可以把对方的怪兽解放（作祭品）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100116', '停时的时针', '每回合我方可以宣告一个卡片种类（魔法·陷阱·怪兽卡片），对方在此回合无法使用和发动宣告的卡片种类。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100118', '神的援助', '对方怪兽召唤·反转召唤·特殊召唤怪兽时可以发动。破坏对方怪兽区域或魔法陷阱区所有卡片。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100119', '哈尔摩尼亚之镜', '对方场上有怪兽特殊召唤时此卡可发动，我方得到对方那只怪兽的控制权，并强制终止对方回合。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100120', '凤凰爪兽', '该卡的攻击·守备力是根据场上的卡片的张数×400点。该卡升级召唤时，可以破坏场上1张魔法·陷阱卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100121', '预警机械虫', '该卡在场上正面表示时，对方每从卡组中抽牌都必须公开让对方看过。每当对方抽到魔法卡时，给对方500点生命值的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100122', '狱魔天使', '每回合可以牺牲自己300点生命值，给予对方900点生命值的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100123', '灵魂战魔', '我方墓地中每存在1张卡片，该卡的攻击力上升200点，被该卡破坏的怪兽，将直接从游戏中除外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100124', '不死魔', '自己的准备阶段，这张卡在墓地存在的场合，这张卡可以特殊召唤到自己场上。自己场上每存在1只恶魔族怪兽时，该卡攻击力上升300点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100125', '乾坤之师', '只要该卡在场上正面表示时，自己的每个准备阶段流程恶魔族怪兽的攻击力都会上升200点。该卡给对方生命值造成伤害时，对方的额外卡组随机1张卡从游戏中除外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100126', '甲皮王', '场上每存在1只兽战士族·战士族怪兽，这张卡的攻击力上升200点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100127', '双生猫咪', '该卡在1回合内被攻击2次才会被破坏。用该卡升级召唤时，可以当作2只祭品来使用。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100128', '冥界守护者 埃涅阿斯', '此卡召唤成功后，可以选择场上正面表示存在的最多2只比这张卡的攻击力低的怪兽破坏。这个效果发动的回合，自己不能进行战斗阶段。此外，指定我方场上1张名字带有「冥界」的卡，只要这张卡在自己场上正面表示存在，那张卡就不会被效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100129', '冥界骑士', '当此卡由「冥界勇士」特殊召唤出来时，攻击·守备力各上升400点。这张卡从场上送去墓地时，可以从卡组选1只守备力2000以下的恶魔族怪兽特殊召唤上场，之后卡组重新洗牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100130', '幻魔圣士', '这张卡用祭品召唤成功时，每次轮到自己回合的准备流程，这张卡的攻击力上升300点。可以自己付出1000点生命值，选自己墓地的1只恶魔族怪兽特殊召唤到场上。这个效果特殊召唤的怪兽在这个回合内不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100131', '阴阳战士', '我方场上每存在一只战士族怪兽攻击力上升500点，每一回合结束时破坏敌方场上所有战士族怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100132', '冥界勇士', '当此卡通常召唤时，可以特殊召唤1只「冥界骑士」到场上。这张卡给对方玩家战斗伤害时，对方卡组最上面的1张卡被送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100133', '龙狮之魔', '该卡必须将场上2只恶魔族和墓地里的1只恶魔族怪兽从游戏中除外才能特殊召唤。场上每存在1张怪兽卡，该怪兽的攻击力上升500点。该怪兽不受陷阱卡的效果影响。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100134', '炎狱龙', '墓地每存在1只龙族怪兽，该卡的攻击力·守备力上升300点。对方直到伤害阶段结束时不能发动魔法、陷阱卡。用以下的怪兽数量升级召唤的场合可以到以下效果。
INSERT INTO "texts" VALUES ('ZZ100135', '混沌神官', '只要该卡在场上正面表示，对方场上怪兽的效果发动无效。该卡在墓地里，魔法师族怪兽升级召唤时需要的祭品减少1只。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100136', '血影', '此卡攻击时，投硬币猜正反面，猜对了该卡攻击力×2，猜错了该卡攻击力不变。在战斗阶段结束时，将战斗中被该卡破坏的对方怪兽，当成增加300点攻击力的卡片装备到该卡上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100137', '空间穿梭', '从卡组里选择1只冥属性怪兽从游戏中除外，到自己第2个回合流程时，特殊召唤到自己场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100138', '亚修罗炼狱', '该卡不因魔法·陷阱卡的效果而被破坏。该卡在场上时，全场的冥属性怪兽不会被怪兽攻击而破坏。该卡在每回合结束时，如不从手牌中舍弃1张卡，就被破坏掉。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100139', '闪光爆发', '当对方发动攻击时，此卡才能发动，从卡组里特殊召唤1只冥属性7星以下的怪兽到场上以正面表示，该怪兽成为此攻击对象。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100140', '冥界守护者 忒拉蒙', '可以将此卡从手牌丢弃。这回合我方所受到的伤害转移给对方，此效果可以在对方回合发动。只要此卡在墓地，每回合回复我方受到伤害的生命值一半的数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100141', '冥界守护者 淮德拉', '此效果只能在对方回合发动。自己场上正面表示存在的名字带有「冥界」的怪兽攻击力直到结束阶段时攻击力上升3000，效果无效化。强制对方发动攻击宣言。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100143', '盔甲·超越靴', '我方此回合有其他盔甲怪兽发动了攻击，则此卡不能攻击。此卡不受怪兽卡区域数量限制，当我方名字带有「盔甲」的怪兽受到攻击时，攻击目标由我方选择。限此卡在场，我方盔甲怪兽不会被指定的对象的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100145', '反射板', '这也是组队决斗的专用卡之一，它能吸收对方所有的攻击力，然后把伤害弹射给己方同伴的怪兽。它的另一个效果是当受到战斗以外的伤害时，可以令伤害无效化，并能给与对方500点的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100146', '转移', '发动魔法卡「转移」让对方攻击的怪兽从对方转移到我方场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100147', '移咒', '陷阱卡发动的时候此卡才可以发动，将怪兽攻击方向转移到对方身上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100148', '教皇的锡杖', '对方抽1张卡，这个回合里，自己场上的卡不因对方的卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100149', '5除2', '从我方卡组抽5张卡给对方看。对方从这些卡中选择2张卡加入我方手牌，其他卡放入卡组洗切。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100150', '火光之壁', '这张卡以正面表示存在的场合，这张卡的操控者不会受到对方的魔法·陷阱·怪兽效果的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100151', '稀有金属灵魂-临', '稀有金属灵魂之一：指定我方场上的1只怪兽，被指定的这只怪兽的攻击力与守备力上升我方与对方场上的每1只怪兽×200点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100152', '稀有金属灵魂-兵', '稀有金属灵魂之一：我方付出600点的生命值，可以从我方或对方的墓地特殊召唤1只怪兽到我方场上，此怪兽攻击力每回合上升600点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100153', '稀有金属灵魂-斗', '稀有金属灵魂之一：对方怪兽发动攻击宣言时，将对方怪兽破坏并送去墓地，破坏的怪兽移除到游戏外，且对方遭受到300点的生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100154', '稀有金属灵魂-者', '稀有金属灵魂之一：给予对方1000点生命值伤害。此卡发动时，对方的魔法·陷阱·效果怪兽的效果不可发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100155', '稀有金属灵魂-皆', '稀有金属灵魂之一：指定对方场上的1只不死族或恶魔族怪兽由我方控制，对方3回合内不能使用魔法·陷阱卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100156', '稀有金属灵魂-阵', '稀有金属灵魂之一：对方的魔法·陷阱卡的效果发动无效，并把那张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100157', '稀有金属灵魂-裂', '稀有金属灵魂之一：发动此卡，对方的怪兽攻击无效，并且直接跳到我方回合。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100158', '稀有金属灵魂-在', '稀有金属灵魂之一：对方等级5或等级5以上的怪兽无法发动，且那只怪兽的攻击力直接对对方造成生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100159', '稀有金属灵魂-前', '稀有金属灵魂之一：可直接终止对方的抽卡阶段，再度回到我方回合，当我方的生命值比对方的生命值低时，可指定我方场上的1只怪兽的攻击力变成原本攻击力的2倍。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100160', '神之对决', '此卡发动后，双方魔法陷阱区卡片全部破坏，此效果的发动不受任何卡片效果限制，被破坏的卡片每有1张给予双方各400点生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100161', '黑魔导·红将', '可以让此卡的攻击力下降500点，从手牌进行特殊召唤。支付500生命值，本回合此卡可以向对方进行直接攻击，且此卡攻击时对手发动的1张卡片效果无效，直接破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100162', '黑魔导·紫将', '可以让此卡攻击力下降500点，从手牌进行特殊召唤。此卡召唤成功时，此手牌·卡组把1只「黑魔导女孩」作为装备卡装备在此卡上，此卡攻击力上升装备怪兽的攻击力数值。或者把装备解除，「黑魔导女孩」以正面攻击表示特殊召唤。
INSERT INTO "texts" VALUES ('ZZ100163', '黑魔导·黑将', '可以让此卡攻击力下降500点，从手牌进行特殊召唤。当此卡在场上时，对方不能发动怪兽的效果。当此卡被送去墓地时，自己场上把1只「黑魔导衍生物A」（魔法师族·暗·5星·攻1800/守1400）和1只「黑魔导衍生物B」（魔法师族·暗·2星·攻700/守700）特殊召唤。「黑魔导衍生物A」不会被卡的效果破坏。「黑魔导衍生物B」不会被战斗破坏。这些衍生物可以作为召唤的祭品。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100164', '黑魔导衍生物A', '由「黑魔导·黑将」的效果特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100165', '黑魔导衍生物B', '由「黑魔导·黑将」的效果特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100166', '黑魔导·蓝将', '可以让此卡攻击力下降500点，从手牌进行特殊召唤。1回合1次，在回合结束前得到对方场上1只怪兽的控制权，得到控制权的那只怪兽攻击的场合，可以直接攻击对方玩家。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100167', '超黑魔法神官', '此卡不能通常召唤，自己场上·手牌存在6星以上魔法师族怪兽2只做祭品的场合可以特殊召唤上场。只要这张卡在场上存在，可以让陷阱的发动无效并且破坏。墓地每有1只魔法师族效果，对方攻击力降低500点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100168', '超魔导剑士·斩龙女武士', '「魔导·女武神」＋「黑魔导女孩」
INSERT INTO "texts" VALUES ('ZZ100170', '魔导之瞳', '对方发动卡效果时可以发动，发动的效果无效，并给予对方生命值1000点伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100171', '黑魔导女贤者', '可以用场上的1张魔法师族怪兽做祭品。从手牌或卡组特殊召唤这只怪兽。这个时候，从卡组选择4张卡，加入手牌，之后卡组洗牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100172', '魔导皇', '从手牌·卡组·墓地·除外区域把名字带有「黑魔导·将」的怪兽最少4只返回卡组。此卡可以从任何区域特殊召唤上场。此卡的攻击力与守备力数值是特殊召唤此卡的怪兽攻击力与守备力的总和。当此卡被破坏时，可以把名字中带有「黑魔导·将」的怪兽从任何区域特殊召唤上场。此卡在场上正面表示存在时，弃掉1张手牌就可以使对方魔法·陷阱·怪兽效果的发动无效，并且把它破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100173', '反击魔术', '对方怪兽发动攻击时。把1张卡片从手牌送去墓地，此卡发动。指定对方场上1只怪兽。并选择我方场上1只怪兽的攻击力上升进行战斗的对方1只怪兽的攻击力数值。且对方被指定的那只怪兽必须强制攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100174', '魔导爆发', '对手攻击时发动。使对手的攻击无效化，并破坏对手场上所有的卡片。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100175', '法老王的归来', '1回合1次确认对方手牌。我方回复对方手牌所有怪兽攻击力的总和的生命值数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100176', '魔神对决', '将我方场上2张怪兽卡送入墓地，破坏对方场上除神属性以外的所有卡片。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100177', '神石板 神哮', '当我方场上名字带有「神石板」的怪兽最高攻击力比对方怪兽最高攻击力低时，回合结束前，此怪兽攻击力上升对方那只怪兽的攻击力。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100178', '神石板 强势回击', '名字带有「神石板」的怪兽被破坏时，可从墓地将名字带有「神石板」的怪兽特殊召唤上场，召唤数量是被破坏的怪兽数量×2。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100179', '神石板 王之灵息', '装备我方场上1只名字带有「神石板」的怪兽，此怪兽攻击对方怪兽时给予贯穿伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100180', '神石板 王之战甲', '装备我方场上1只名字带有「神石板」的怪兽。此怪兽不受对方效果影响，不会被战斗破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100181', '巨神兵的召唤之雏', '此卡不受魔法·陷阱·效果怪兽的效果影响，此卡存在场上时，可从卡组或手牌特殊召唤1只「欧贝利斯克之巨神兵」，此回合结束时，此卡回到我方手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100182', '天空龙的召唤之雏', '此卡不受魔法·陷阱·效果怪兽的效果影响。此卡存在场上时，可从卡组或手牌特殊召唤1只「奥西里斯之天空龙」，此回合结束时，此卡回到我方手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100183', '翼神龙的召唤之雏', '此卡不受魔法·陷阱·效果怪兽的效果影响。此卡存在场上时，可从卡组或手牌特殊召唤1只「太阳神之翼神龙」，此回合结束时，此卡回到我方手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100184', '地狱之巨神兵', '此卡需要3只怪兽作为解放才可召唤，此卡召唤不能被无效化，墓地每有1只怪兽此卡攻击力提升500点。把场上2只怪兽作为祭品，对方受到4000点伤害，此卡不会被破坏，不计算伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100185', '地狱之天空龙', '此卡需要3只祭品才能召唤，此卡召唤不能被无效化，此卡的攻击力为对方手牌数量×1000的数值，对方召唤怪兽时攻击·守备减去4000点，不足4000被破坏，超出的数值给予对方生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100186', '地狱之翼神龙', '此卡需要3只怪兽作解放才能召唤，此卡召唤不能被无效化，此卡攻击为墓地怪兽攻击力的总和，支付1000点生命值，对方场上所有卡破坏，破坏的每张卡给对方造成1000点伤害。此卡不能被破坏，不计算伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100187', '神石板 巨神兵', '可以把自己场上2只怪兽解放，对方场上的怪兽全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100188', '神石板 天空龙', '对方怪兽攻击表示召唤·特殊召唤时，那只怪兽的攻击力下降2000，攻击力变成0的场合那怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100189', '神石板 翼神龙', '这张卡召唤成功时，可以把基本分支付到变成100，这张卡的攻击力和守备力上升支付的数值，此外，可以支付1000基本分选择场上1只怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100190', '神石板 游戏', '可装备到怪兽身上，攻击力上升1000点。装备「神石板 天空龙」上，攻击力上升2000点。装备的怪兽不受对方魔法卡效果影响。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100191', '神石板 海马', '可装备到怪兽身上，攻击力上升1000点，装备「神石板 巨神兵」上，攻击力上升2000点，装备的怪兽不受对方怪兽效果影响。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100192', '神石板 马利克', '可装备到怪兽身上，攻击力上升1000点，装备「神石板 翼神龙」上，攻击力上升2000点，装备的怪兽不受对方陷阱卡效果影响。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100193', '法老王的宝座', '1回合1次，将我方手牌1只神属性怪兽无视召唤条件特殊召唤到我方场上来。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100194', '召雷弹', '对方召唤·反转召唤·特殊召唤时，若以攻击表示看攻击力，若以守备表示看守备力，在2000点以下遭破坏，在2000以上时，攻击力·守备力各扣2000点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100195', '神石板 光构体', '光属性的通常怪兽祭品召唤的场合，这1只怪兽可以作为2只的数量的祭品。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100196', '神石板 神力拥有者', '每支付1000生命值，就可以从自己的手牌或卡组选择2张「神石板 光之蛋」特殊召唤到自己场上。
INSERT INTO "texts" VALUES ('ZZ100197', '神石板 光之蛋', '
INSERT INTO "texts" VALUES ('ZZ100198', '神石板 翼神龙之光', '这张卡不会被光属性以外的怪兽战斗破坏，那次战斗发生的对自己的战斗伤害变成0.只要这张卡在场上正面表示存在，暗属性怪兽不能攻击宣言，双方不能把光属性以外的怪兽召唤·特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100199', '神石板 王者归来', '全部卡片破坏，此卡从手牌召唤。此卡的发动全场卡片效果无效。攻击力上升破坏的卡数量×1000。每回合可从卡组、墓地将1张「神石板 巨神兵」/「神石板 翼神龙」/「神石板 天空龙」召唤上场。3回合后此卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100200', '千年之书', '1回合1次将我方卡组1只神属性怪兽加入我方手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100201', '青眼白龙·三体连结', '用「恶魔的锁链」特殊召唤。特殊召唤，必须以场上或手牌合计12颗星以上的怪兽作为祭品，此卡片成功召唤的回合破坏对方场上所有卡片。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100202', '恶魔的锁链', '「青眼白龙·三体连结」降临必要。将我方场上或手牌合计星数12以上的卡片做祭品，可以从手牌·卡组·墓地特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100203', '青眼圣约龙', '由「白龙女的净化」的效果或支付一半的生命值特殊召唤，每回合选择1个效果发动：●每除外自己墓地的怪物卡1张，破坏对方场上全部的卡片。●每回合对方准备阶段，对方把卡组中的一半的卡送去墓地。●特殊召唤1只名字带有「青眼」怪兽上场。此卡不被破坏，且魔法·陷阱·怪兽效果对它无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100204', '白龙女的净化', '支付100点生命值或者把自己场上1只「青眼白龙三体连结」作为祭品，就能从手牌·卡组·墓地或除外区域特殊召唤1只「青眼圣约龙」。此卡的发动不会被无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100205', '地狱之青眼白龙', '此卡不能特殊召唤，只能用2张祭品召唤上场。此卡召唤成功的场合，对方场上所有卡片全部破坏。此卡成功攻击并给对方玩家战斗伤害的场合，我方下回合必须跳过攻击阶段，并抽2张卡，当此卡被破坏送入墓地时，可以将我方卡组·手牌·墓地·游戏外的「青眼白龙」尽可能多的召唤到我方场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100206', '青眼白龙LV9', '将「青眼白龙」寄生于「青眼白龙LV9」上，从手牌丢弃1张龙族怪兽，此卡可被特殊召唤。其攻击力可上升「青眼白龙」的攻击力，自己墓地每存在1只龙族怪兽，对方必须从卡组把3张卡送入墓地，每入墓1张，对方受到300点生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100207', '青眼水晶龙', '移除我方墓地1只名字带有「青眼」的怪兽，此卡可以从墓地·手牌特殊召唤，当此卡存在墓地，1回合1次，我方场上所有龙族怪兽攻击力永久上升500点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100208', '青龙的缠绕', '从卡组将1只「青眼白龙」召唤上场。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100209', '白龙之魔导骑士', '「青眼白龙」＋「黑魔术师」
INSERT INTO "texts" VALUES ('ZZ100210', '白龙女', '
INSERT INTO "texts" VALUES ('ZZ100211', '青眼究极巨龙', '4星怪兽×2
INSERT INTO "texts" VALUES ('ZZ100212', '白龙的守护', '我方场上1只怪兽攻击力永久上升我方墓地存在的怪兽数量×300的攻击力数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100213', '晶体青眼白龙', '1回合1次，将自己场上这张卡以外的1只怪兽破坏，可从墓地将1张卡加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100214', '龙的寄望者', '只有他能看到太阳中的青眼白龙幻影，千万年来他也注定了是青眼白龙的宿主。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100215', '青眼白龙圣骑士', '此卡融合召唤不需要融合卡，将我方手牌场上合计2张「青眼白龙」送入墓地，这张卡直接召唤上场。此卡战斗破坏对方怪兽送入墓地时，可以将对方场上1张卡移除到游戏外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100216', '海马的仪式', '付出我方600点生命值，此卡才能进行仪式召唤。此卡可以被特殊召唤，此卡存在场上时，可以最多召唤3只龙族怪兽上场，以此卡召唤出来的怪兽效果这回合不能发动，此卡正面表示存在时，我方场上名字带有「青眼」的怪兽不会被战斗与卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100217', '青眼白龙 仪式', '化身仪式怪兽的「青眼白龙」，属于「海马的仪式」专用仪式怪兽卡，此卡需要牺牲1张「海马的仪式」才能进行仪式召唤，而牺牲1张之后，每再牺牲1张「海马的仪式」此卡的攻击力就会增加1000点，守备力就会增加500点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100218', '传说-青眼之魂', '此卡召唤成功后，可以从卡组选择1张龙族怪兽卡加入手牌，此卡可以作为装备卡装备，当此卡装备在名字带有「青眼」的怪兽卡身上，装备怪兽攻击力上升2000，装备怪兽每次攻击额外给予对方装备怪兽的等级×300点生命值伤害。装备怪兽被对方破坏送入墓地时，此卡可以代替破坏送入墓地，此卡送入墓地时，可以从手牌特殊召唤1张名字带有「青眼」的怪兽上场。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100219', '青眼反射龙', '「青眼白龙」＋「青眼白龙」
INSERT INTO "texts" VALUES ('ZZ100220', '青眼白龙王', '从手牌舍弃1张龙族怪兽卡，此卡可以特殊召唤。此卡装备「龙怒之波」后，得到对方场上的2只怪兽装备，攻击力上升2只怪兽的攻击力之和。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100221', '青眼玉石龙', '将我方场上正面表示此卡送入墓地，我方回复此卡等级×600数值的生命值，当此卡因对方卡效果送入墓地时，我方回复此卡攻击力的生命值数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100222', '古代的机械青眼白龙', '移除我方墓地1只龙族怪兽。此卡可以从手牌特殊召唤到场上，此卡的攻击力增加移除怪兽的攻击力数值。当此卡发动攻击宣言时，如果我方手牌存在名字带有「青眼」的怪兽时，给对方观看，直到战斗伤害阶段结束时，对方不能发动卡片效果。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100223', '究极青眼日龙', '「白龙望日」降临。若不从场上和手牌把2张「龙的守望者」的卡作为祭品，则「究极青眼日龙」不能降临。这张卡召唤成功时，可以把对方的手牌·场上·墓地的卡各最多1张从游戏中除外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100224', '白龙望日', '「究极青眼日龙」的降临必须。若不从场合和首领把2张「龙的寄望者」作为祭品，则「究极青眼日龙」不能降临。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100225', '青眼白龙·蓝眼琪莎拉', '此卡只能用「控龙神官 塞特」的效果进行特殊召唤。此卡的召唤不会被无效。当此卡召唤成功时，对方不能发动卡，并且跳过对方所有回合，此卡在场上时，此卡和「控龙神官 塞特」不会被破坏，且魔法·陷阱·怪兽效果对它们无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100226', '控龙神官·塞特', '由。「白龙女的守护」特殊召唤。选择以下一个效果发动：●从任何地方特殊召唤龙族·恐龙族·海龙族怪兽各1只上场。且对方这3种怪兽占为己有。●舍弃1张卡，可再攻击。●每有1只龙族·恐龙族·海龙族的怪兽时，攻击力增加1000点，能特殊召唤「青眼白龙·蓝眼琪莎拉」。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100227', '白龙女的守候', '将场上的1只「青眼白龙」作祭品，就能从手牌·卡组·墓地特殊召唤1张「控龙神官·塞特」。此卡发动不会被无效化（怪兽强制召唤，且不会被破坏）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100228', '青眼的究极龙', '场上存在3张「海马的仪式」的场合，支付300基本分，这张卡才能从手卡特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100229', '青眼究极龙之墓', '将对方场上所有怪兽送入墓地后，将此卡以攻击表示特殊召唤到对方场上，此卡不能作攻击，不能改变表示形式，也不能作为祭品。此卡被破坏后给予对方3000点生命值的伤害，就此卡在场攻击力每回合下降1000点，此卡在对方场上特殊召唤后，在双方战斗阶段，我方都可以选定此卡为攻击目标攻击1次，此卡不会被战斗破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('DCOR0047', '究极蓝眼龙', '这张卡只能在我方场上1只龙族怪兽上叠放来超量召唤。
INSERT INTO "texts" VALUES ('ZZ100231', '完全魔法引力', '可以在自己的卡组中抽出10张卡片，并且特殊召唤出其中的所有盔甲怪兽，而其余卡片则送入墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100232', '成功报酬', '对方从卡组抽卡直到手卡变成6张为止。这个效果每抽1张卡我方基本分回复1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100233', '借卡', '对方回复1000基本分，我方受到1000伤害，那之后，我方从卡组选1张卡，给双方确认加入手卡。那张卡在这个回合的结束阶段没有送入墓地或除外的场合回到持有者卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100235', '红宝石之龙', '
INSERT INTO "texts" VALUES ('ZZ100236', '绿宝石之龙', '
INSERT INTO "texts" VALUES ('ZZ100237', '魔力的封印', '只要此卡在场时，可以选择对方1张卡，被选择的那张卡不能改变表示形式，无法发动效果，并不能攻击或作为祭品。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100238', '恶魔戒律', '可以就我方卡组选择1张卡送去墓地，跳过对方的战斗阶段。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100239', '吸血恐兽', '限此卡在场，对方每召唤·特殊召唤需要支付500点生命值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100242', '反转抽卡', '当我方受到生命值伤害时可以发动，双方从卡组抽取2张卡，我方抽取的卡中有怪兽卡时，可以直接召唤上场，对方抽取的卡中有怪兽卡时，我方生命值回复2000点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100243', '超贪婪之壶', '我方每回合抽牌以外选择抽4张卡。因此卡效果抽的每一张卡回复我方1000点生命值。此卡发动后三回合后，对方宣告胜利。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100244', '矿山爆破', '从卡组将5张卡送入墓地。下次自己回合的抽卡阶段不能抽卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100245', '奥西里斯的制裁', '每祭掉我方场上一只怪兽，可选择破坏对方场上两张卡或将对方的两张手牌送入墓地。当这个效果发动成功时，如果被破坏送入墓地的卡中有怪兽卡可无视召唤条件特殊召唤到我方场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100246', '魔神冲击', '对方场上存在的怪兽全部破坏，我方特殊召唤墓地的2只怪兽（这个时候无视召唤条件）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100247', '时间的消停', '对方攻击宣言时才能发动，用对方回合计算的3回合对方不能攻击宣言。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100248', '黑暗大法师的链结', '此怪兽强制召唤上场后，每1个回合可以发动1次（包含此回合），可以从卡组、手牌、墓地、除外区，将1张名字带有「被封印的」卡片放到此卡上方（此卡不会参与战斗场上的战斗和不受其他卡影响），当5张名字带有「被封印的」卡片集齐到场上后，战斗胜利。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100249', '强制的黑暗觉醒', '此卡发动后3个回合内，我方的怪兽不会被破坏，3个回合后此卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100250', '史莱姆突破口', '怪兽特殊召唤时发动。自己恢复该怪兽的攻击力数值的生命值。之后该怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100251', '绒儿的暗伤', '我方的怪兽被战斗破坏时，对方攻击的怪兽从游戏中除外，对方承受此怪兽攻击数值的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100252', '死亡流星', '支付500点的生命值，给予对手1500点的生命值伤害。那之后，承受1500点伤害的玩家场上的1只怪兽可以发动1次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100254', '幻魔逆袭', '对方的魔法卡·陷阱卡·怪兽卡的发动和效果无效，并把那张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100255', '无敌流星龙', '这张卡不能通常召唤。从自己的额外卡组把1只「流星龙」从游戏中除外的场合才能特殊召唤。此卡召唤成功时，可在同1次阶段中对对方怪兽做出最多3次攻击（若对方场上没有怪兽时，可直接攻击对方玩家）。只要这张卡在场上正面表示存在，对方不能把魔法·陷阱卡发动，此卡不会被战斗破坏。此外，此回合的结束阶段，可以把自己墓地存在的1只「流星龙」特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100257', '神魂龙', '此卡不会被战斗破坏，只要此卡在场时，对方场上的怪兽不能攻击除此卡之外的怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100258', '护主栗', '指定对方1只怪兽攻击力及防守值下降1000点，我方1只怪兽攻击力及防守值上升1000点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100259', '断言术', '对方把卡组最上方的2张卡送去墓地才能进行攻击宣言。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100260', '不死之护封剑', '对方场上的怪兽全部变成正面表示。这张卡发动后，用对方回合计算的3回合内继续留在场上。只要这张卡在场上存在，对方场上的怪兽不能攻击宣言，攻击力下降500点。我方场上不死族怪兽的攻击力上升500点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100261', '究极的青眼钢铁龙', '「金属化·魔法反射装甲」＋「青眼的究极龙」
INSERT INTO "texts" VALUES ('ZZ100262', '青眼钢铁龙', '「金属化·魔法反射装甲」＋「青眼白龙」
INSERT INTO "texts" VALUES ('ZZ100263', '青眼暴君龙', '「暴君翼」＋「青眼白龙」
INSERT INTO "texts" VALUES ('ZZ100264', '暴君炸裂龙', '「暴君翼」＋「克里提乌之牙」
INSERT INTO "texts" VALUES ('ZZ100265', '青眼暴君炸裂龙', '「暴君炸裂龙」＋「青眼白龙」
INSERT INTO "texts" VALUES ('ZZ100266', '青眼白龙·三体连结 ', '
INSERT INTO "texts" VALUES ('ZZ100267', '君临天下', '每当我方回合的准备阶段对方场上所有怪兽攻击力永久下降500点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100268', '修特姆贝洛克的黄金城', '当这卡片被召唤到场上时病毒程式就开始扩散了，发动「修特姆贝洛克的黄金城」的效果时，我方可以从卡组中特殊召唤出等级4以下的怪兽。就在准备阶段时，将卡组中一半的卡片，送进墓地当交换代价，而这维持代价是由对方玩家付出的。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100271', '苏生的石板', '我方怪兽被破坏时可发动，将该怪兽复活到我方场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100272', '奥利哈钢 达姿前世', '此卡的攻击力·守备力上升场上攻击力最高的怪兽的攻击力·守备力×2。此卡被效果破坏时，可以丢弃1张手牌破坏无效，此卡受到的战斗伤害为0。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100273', '奥利哈钢 蕾欧丝', '此卡战斗破坏对方怪兽时，下个对方的主要阶段一跳过，此卡攻击守备表示怪兽时，若攻击力超过那个守备力，给与对方生命值那个数值的战斗伤害，把场上此卡作为祭品，可以从任何地方特殊召唤「奥利哈钢 恶魔化蕾欧丝」。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100274', '奥利哈钢 克莉丝', '只要此卡在场上，战斗流程时对方不能发动魔法·陷阱，此卡给与对方战斗伤害时，对方每有1张手牌给予对方600伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100275', '奥利哈钢 艾恩哈特', '当自己场上名字带有「奥利哈钢」的怪兽战斗时，可以将手牌中的此卡送入墓地，自己场上名字带有「奥利哈钢」的怪兽攻击力和守备力上升对方1只怪兽攻击力的数值，此卡在墓地时，自己场上名字带有「奥利哈钢」的怪兽攻击力上升500点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100276', '奥利哈钢 恶魔化蕾欧丝', '此卡不能通常召唤。可以将自己场上的3只名字带有「奥利哈钢」的怪兽送入墓地或者由「奥利哈钢 蕾欧丝」的效果特殊召唤。只要此卡在场上，自己名字带有「奥利哈钢」的怪兽不受对方的效果影响，同时此卡控制者受到的伤害为0。场上每有1只名字带有「奥利哈钢」的怪兽此卡攻击力上升500点。每当自己主要流程在自己场上特殊召唤1只「奥利哈钢 恶魔复制体」（星4/暗/传说神兽族/攻0/守2500，对方不能攻击「奥利哈钢 恶魔复制体」以外的怪兽），可以将卡组中1只怪兽给对方观看，此卡拥有那只怪兽的效果，此效果1回合1次。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100277', '奥利哈钢 恶魔复制体', '由「奥利哈钢 恶魔化蕾欧丝」的效果特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100278', '奥利哈钢 巴龙', '当我方场上没有怪兽时，此卡可以从任何地方特殊召唤。此卡每破坏对方场上1只怪兽，此卡攻击力上升500点，此卡离场时，将对方场上此卡攻击力数值除以700的数量的卡送入墓地，与此卡战斗的怪兽效果无效化。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100279', '奥利哈钢 亚美鲁达', '每当自己的准备流程时，给予对方场上名字带有「奥利哈钢」的怪兽数量×500点的伤害。当自己场上存在这张卡以外的名字带有「奥利哈钢」的怪兽时，对方不能选择此卡为攻击对象。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100280', '奥利哈钢 拉菲鲁', '当我方场上没有怪兽时，此卡可以从任何地方特殊召唤。1回合1次，宣告1只怪兽名，若对方手牌存在那只怪兽，在自己场上特殊召唤。由于此效果特殊召唤的怪兽当做名字带有「奥利哈钢」的怪兽使用。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100281', '奥利哈钢 艾亚托斯', '我方墓地存在名字带有「奥利哈钢」的卡时此卡可以从手牌特殊召唤，此卡召唤成功后可以选择1张魔法卡加入手牌。此卡发动攻击宣言时，只要我方场上存在其他名字带有「奥利哈钢」的卡片，直到战斗伤害结束阶段，此卡攻击力增加被攻击的怪兽攻击力的数值。当此卡因对方卡效果被破坏时，无条件破坏对方场上1张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100282', '奥利哈钢 灵魂操控者', '反转：1回合1次，可以变成背面守备表示。这张卡反转召唤成功时，选择对方场上1只怪兽强制攻击。攻击对象由我方选择场上任意1只怪兽。战斗伤害由对方代受。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100283', '奥利哈钢 阿拉克涅', '当此卡的控制权被转移时，此卡不能攻击不能改变正面形式，无法做为祭品召唤及融合或同调素材，每回合对方损失500生命值，我方增加那个伤害的数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100284', '奥利哈钢 埃瑞克特', '此卡不能攻击，不能改变正面形式，控制权不能变更，每舍弃我方1张手牌名字带有「奥利哈钢」的卡此卡攻击力增加1000。可以选择将此卡送入墓地，双方承受此卡攻击力数值的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100285', '奥利哈钢 红光蛇', '被破坏时，可以从卡组将最多2只「奥利哈钢 红光蛇」特殊召唤上场。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100286', '奥利哈钢 达人僵尸', '当此卡存在墓地时，1回合1次可以将此卡守备表示特殊召唤上场，限此卡在场对方只能攻击此卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100287', '奥利哈钢 邪魔导', '此卡被破坏时，对方生命值上限为1，这回合自己受到的伤害为0。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100288', '奥利哈钢 神的强控者', '此卡召唤·翻转召唤·特殊召唤时，场上每有一只怪兽恢复自己500点生命值，并添加「奥利哈钢第四层结界控神阵」、「奥利哈钢 末日残影」到手牌。此卡宣告战斗时，可以改变攻击对象的表示形式。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100289', '奥利哈钢 亡灵士兵部队', '此卡可以通常召唤，也可由「奥利哈钢 亡灵士兵」的效果特殊召唤。此卡召唤·翻转召唤·特殊召唤时，将墓地中1只名字带有「奥利哈钢」的怪兽特殊召唤。1回合1次，在此卡上放置一个指示物，此卡攻击力上升500点。舍弃1个指示物，此卡不会被破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100290', '奥利哈钢 奇甲之盾', '只要此卡在场上，自己场上名字带有「奥利哈钢」的怪兽不受对方效果影响。对方只能选择此卡为攻击对象，此卡战斗时，可以将手牌中卡片送入墓地（最多4张），送入墓地的卡每有1张，此卡守备力上升600点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100291', '奥利哈钢 欧墨尼得', '1回合1次，此卡不会被破坏，不受战斗伤害。当此卡存在墓地时，可以将场上1只名字带有「奥利哈钢」的怪兽送入墓地，将此卡从墓地特殊召唤。此卡在卡组只能存在1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100292', '奥利哈钢 米诺', '当场上存在此卡时，对方不能选择此卡以外的怪兽作为攻击对象，此卡被破坏送入墓地时，我方场上1只名字带有「奥利哈钢」的怪兽攻击力增加此卡的守备力。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100293', '奥利哈钢 刻拉多斯', '当我方场上有除此卡外名字带有「奥利哈钢」的怪兽存在时，将此卡的守备力增加到此卡攻击力上，当此卡攻击成功时，变为守备表示直到下个回合我方的准备阶段不能改变表示形式。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100294', '奥利哈钢 极思克', '此卡召唤·翻转召唤·特殊召唤时，将墓地中1只名字带有「奥利哈钢」的怪兽特殊召唤，此卡离场时，将对方卡组最上方5张卡送入墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100295', '奥利哈钢 圣犬', '翻转：得到对方场上1只怪兽的控制权，控制的怪兽攻击力和守备力上升500点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100296', '奥利哈钢 赫克艾德斯', '此卡召唤成功后如果我方场上存在名字带有「奥利哈钢」的怪兽，此卡控制权转移到对方场上，只要对方场上存在此卡对方不能召唤怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100297', '奥利哈钢 炎魔象', '我方场上存在「奥利哈钢的结界」时，这张卡可以从手牌·墓地特殊召唤。这个效果1回合只能使用1次。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100298', '奥利哈钢 九头狂蛇', '对方场上有怪兽存在时，可以直接盖放到场上。
INSERT INTO "texts" VALUES ('ZZ100299', '奥利哈钢 蓝光蛇', '被破坏时，可以从卡组把最多2只「奥利哈钢 蓝光蛇」特殊召唤上场。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100300', '奥利哈钢 奇甲卡拉', '只要此卡在场上，自己场上名字带有「奥利哈钢」的怪兽不受对方效果的影响。此卡可以直接攻击对方玩家。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100301', '奥利哈钢之神', '通过「达姿的仪式」降临。需将我方生命值归0才可召唤。此时我方战斗胜负将不受生命值影响。对方发动针对此卡的所有魔法·陷阱卡的效果无效并破坏，此卡破坏对方怪兽时，给予对方破坏怪兽攻击力两倍+2000点的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100302', '奥利哈钢 巨神兵', '需用3只怪兽作解放或者支付一半生命值才能召唤。此卡召唤时以及任何时候都不受怪兽效果·魔法与陷阱影响。当此卡在场上时，把我方或者对方2只怪兽当作解放，发动以下效果：●此卡不会被破坏。●对方场上所有卡片全部破坏，对方生命值受到5000点伤害。●本回合攻击力（无限大），可以直接攻击对方。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100303', '奥利哈钢 天空龙', '需用3只怪兽当作解放或者支付一半生命值才能召唤。此卡的攻击力与守备力是由自己的手牌数量×2000来计算。此卡召唤以及任何时候都不受怪兽效果·魔法与陷阱影响。此卡在场上时，对方召唤·翻转召唤·特殊召唤时，召唤怪兽攻击力·守备力在5000点以下遭破坏，不足的给予对方生命值伤害，在5000点以上时，攻击力·守备力各扣5000点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100304', '奥利哈钢 翼神龙', '需用3只怪兽当作解放或者支付一半生命值才可召唤。此卡召唤时以及任何时候都不受怪兽效果·魔法与陷阱影响。而此卡的攻击力与守备力数值是双方玩家墓地怪兽攻击力总和。可发动以下效果：●把对方的生命值扣剩1点，把场上怪兽作解放，扣去的生命值和解放怪兽攻·守会加到此卡攻击力和守备力上。●支付1000点生命值，可除外对方2张卡片。●此卡不会被破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100305', '奥利哈钢 黑魔导女孩', '双方墓地每存在1张名字带有「奥利哈钢」的魔法师族怪兽，此卡攻击力增加1000点。当此卡从场上离开时可以将我方墓地1张名字带有「奥利哈钢」的魔法师族怪兽移除到游戏外，让此卡直接回到场上来。当此卡因对方卡效果被破坏时，无条件强制破坏对方场上1张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100306', '奥利哈钢 万蛇神', '这张卡只能通过「奥利哈钢 万蛇灵」的效果召唤。这张卡的攻击力自己墓地每有1只「奥利哈钢」怪兽上升1000。只要这张卡在场上正面表示存在，不能成为这张卡以外的怪兽·魔法·陷阱的效果的对象且不受效果影响。这张卡被战斗破坏送去墓地时，可以把自己墓地这张卡以外的1只「奥利哈钢」怪兽从游戏中除外把这张卡特殊召唤。每次这张卡给予对方玩家战斗伤害，给这张卡放置1个「奥利哈钢指示物」。这张卡放置有3个「奥利哈钢指示物」时，这张卡的控制者决斗胜利。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100307', '奥利哈钢 万蛇灵', '此卡在我方场上正面表示存在时，可以将此卡送入墓地，将手牌中的「奥利哈钢 万蛇神」特殊召唤上场，召唤成功时，此卡除外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100308', '奥利哈钢 亡灵之眼', '支付一半生命值可从手牌·卡组特殊召唤此卡，此卡不会被战斗破坏，不受怪兽效果影响。当此卡战斗破坏对方怪兽时，被破坏的怪兽作为装备卡装备到此卡上，并攻击力提高500点，此卡获得有被破坏怪兽效果（效果可叠加）。当此卡从场上离开时可从卡组·墓地特殊召唤1张名字带有「奥利哈钢」的卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100309', '奥利哈钢 赫耳墨斯', '支付100倍数的生命值，给予对方这个数值的生命值伤害。此效果1回合只能使用1次。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100310', '达姿的仪式', '此卡由「奥利哈钢之圣都 亚特兰提斯」的效果或者丢弃卡组任意一张仪式卡进行特殊召唤。我方发动任何卡片不必支付生命值。此卡不会被破坏。魔法·陷阱·怪兽效果对此卡无效此卡召唤成功时，就从卡组·手牌·墓地中特殊召唤「原始奥利哈钢之神」。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100311', '奥利哈钢 末日残影', '将墓地中名字带有「奥利哈钢」的怪兽在自己场上尽可能特殊召唤，由于此效果召唤的怪兽不能攻击并在自己的结束流程时破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100312', '奥利哈钢 末日之音', '每当对方结束阶段时这张卡放上1个暗指示物，当这张卡的指示物到达6个时，我方直接获得胜利，这个效果不受对方影响。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100313', '奥利哈钢 黑暗磁场', '名字带有「奥利哈钢」的怪兽才能装备，只要被装备怪兽在场上，对方不能发动魔法卡，对方场上所有魔法卡的效果无效化。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100314', '奥利哈钢 穿心箭', '此卡只能装在名字带有「奥利哈钢」的怪兽上，当被装备怪兽攻击破坏对方怪兽时，给予对方那只被破坏怪兽攻击力数值的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100315', '奥利哈钢 黑暗气息', '将对方场上自己场上名字带有「奥利哈钢」的怪兽数量的魔法·陷阱卡无效并破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100316', '奥利哈钢之城', '此卡在场上，每次我方回合可从墓地/手牌中特殊召唤2只4星以下的名字带有「奥利哈钢」的怪兽，此卡破坏，可将「奥利哈钢之神」从手牌特殊召唤上场。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100317', '奥利哈钢 拷问刑具', '限此卡在场，场上每有1张卡给予对方100点生命值伤害。此效果1回合可以使用1次，此卡发动3回合后从游戏中除外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100318', '奥利哈钢 无限追击', '在自己战斗流程结束后发动，选择对方墓地中一只怪兽在对方场上攻击表示特殊召唤，并且攻击力上升500点，之后我方可以再进行一次战斗流程。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100319', '奥利哈钢的元素', '限此卡在场，我方发动任何卡无需支付代价。对方场上每有1张卡，我方场上怪兽攻击力提高500点。每回合对方需要从卡组随机丢弃3张卡，否则破坏对方场上所有卡，此卡从场上离开时返回持有者手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100320', '奥利哈钢 绝对黑暗力', '名字带有「奥利哈钢」的怪兽才能装备，装备怪兽攻击力·守备力上升700点，装备怪兽破坏对方怪兽时，给予对方破坏怪兽攻击力一半的伤害，自己生命值回复那个数值。装备怪兽破坏时，可以让此卡代替破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100321', '奥利哈钢 灵魂摄取', '将自己场上1只名字带有「奥利哈钢」的怪兽送入墓地，我方生命值恢复那个怪兽攻击力与守备力的总和，之后从我方卡组中特殊召唤1只名字带有「奥利哈钢」的4星怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100322', '奥利哈钢 暗黑的赠礼', '自己场上每有1张名字带有「奥利哈钢」的怪兽，从自己卡组中抽1张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100323', '奥利哈钢 魔性之月', '祭掉我方场上1只怪兽，从手牌特殊召唤1只等级4以下名字带有「奥利哈钢」的怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100324', '达姿的仪式 ', '「奥利哈钢之神」降临之必需品。此卡的发动不能被无效化。将生命值归0后召唤，此时我方胜负条件不受生命值影响。当「奥利哈钢之神」从场上离开时，对方宣告胜利。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100325', '奥利哈钢之神怒', '我方或对方有「奥利哈钢之神」在场上时，我方回合舍弃两张手牌，对方将一半卡组送入墓地。每个我方回合只能发动1次，发动不受对方卡影响。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100326', '奥利哈钢 超强欲之壶', '当我方墓地不存在魔法卡时可以发动，每抽1张卡回复我方1000点生命值，以下效果我方每回合只能各发动1次：
INSERT INTO "texts" VALUES ('ZZ100327', '奥利哈钢 地狱之战', '我方墓地存在3只以上名字带有「奥利哈钢」的怪兽时发动。选择将我方墓地任意只名字带有「奥利哈钢」的怪兽除外，将对方场上相同数量的卡片从游戏中除外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100328', '奥利哈钢的结界', '●自己场上的怪兽属性消除，并提升500点攻击力。
INSERT INTO "texts" VALUES ('ZZ100329', '奥利哈钢之气', '●「奥利哈钢的结界」在场时才能发动，发动此卡的回合，「奥利哈钢的结界」和此卡共同占用场地魔法区域。
INSERT INTO "texts" VALUES ('ZZ100330', '奥利哈钢 托利托斯', '●只有「奥利哈钢之气」在场时才能发动，发动此卡时，「奥利哈钢的结界」、「奥利哈钢之气」和此卡共同占用场地魔法区域。
INSERT INTO "texts" VALUES ('ZZ100331', '奥利哈钢第四层结界控神阵', '●当此卡在手牌时，从卡组·手牌发动「奥利哈钢的结界」、「奥利哈钢之气」、「奥利哈钢 托利托斯」。
INSERT INTO "texts" VALUES ('ZZ100332', '奥利哈钢第五层结界操控阵', '●当此卡在手牌时可以从卡组·手牌发动「奥利哈钢的结界」、「奥利哈钢之气」、「奥利哈钢 托利托斯」、「奥利哈钢第四层结界控神阵」。
INSERT INTO "texts" VALUES ('ZZ100333', '奥利哈钢的遗迹 亚特兰提斯2', '此卡不受对方卡效果影响，此卡发动成功后增加1个「指示物」，每次双方使用卡片或发动卡片效果时（不包括此卡），增加1个「指示物」，去除「指示物」得到以下效果：
INSERT INTO "texts" VALUES ('ZZ100334', '奥利哈钢混沌黄金之虹', '场上的牌位数量无限化，对方不能发动任何卡片及攻击，我方卡片不会破坏。我方怪兽可直接攻击对方2次。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100335', '达姿的第二仪式', '此卡能使「究极奥利哈钢之神」降临。发动此卡，玩家需保持生命值为1点。当我方场·手牌·卡组·墓地除外区域有「奥利哈钢之圣都 亚特兰提斯」、「达姿的仪式」、「原始奥利哈钢之神」、「究极奥利哈钢之神」、「达姿的第二仪式」时，立即获得胜利，此卡的发动不能被无效化，发动后回到手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100336', '奥利哈钢之怒', '自己场上名字带有「奥利哈钢」的怪兽被攻击时可以发动，破坏对方场上攻击表示所有怪兽，每有1张给予对方300点伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100337', '奥利哈钢 雷电灭世', '对方怪兽召唤成功时，对方场上所有卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100338', '奥利哈钢 多兰之盾', '当对方发动以我方场上名字带有「奥利哈钢」的怪兽为对象的卡片效果时，让那个效果无效，破坏那张卡，并将对方卡组的同名字的其他卡全部移除到游戏外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100339', '奥利哈钢 不灭阶段', '可以将自己场上1只怪兽送入墓地，从墓地里特殊召唤1只8星以上的怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100340', '暗黑奥利哈钢之魂', '获得对方最多3只怪兽的控制权，我方回复的生命值等于那些被控制怪兽的攻击力和守备力的总和。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100341', '圣辉仪式', '当我方生命值低于1000时可以发动，强制破坏双方场上所有卡片，我方从卡组·手牌·墓地·游戏外无条件特殊召唤5只名字带有「奥利哈钢」的魔法师族怪兽。发动此效果的3个回合内我方不能发动攻击宣言。当此卡因对方卡效果被破坏时，无条件强制破坏对方场上1张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100342', '哈刚封印', '当对方发动对我方名字带有「奥利哈钢」的怪兽为目标的卡片效果时可以发动，将我方场上1只名字带有「奥利哈钢」的魔法师族怪兽送入墓地，让对方那张卡的发动无效并强制破坏。当此卡因对方卡效果被破坏时，无条件强制破坏对方场上1张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100343', '奥利哈钢的诅咒', '此卡只能在游戏前（猜拳后，抽卡前）从牌组中发动。是我方攻击顺序获得以下效果：
INSERT INTO "texts" VALUES ('ZZ100344', '奥利哈钢之圣都 亚特兰提斯', '此卡不会被破坏，此卡的发动不会被无效，强制发动效果。从我方手牌·卡组·墓地· 除外区域无限制特殊召唤名字带有「奥利哈钢」和「达姿」的怪兽，并能让召唤出来的怪兽的攻击力·守备力每回合各增加1000点。我方怪兽可直接攻击对方玩家，且怪兽攻击必须强制发动，我方怪兽不会被破坏。此卡可以与名字带有「奥利哈钢」的卡共同占用场地魔法区域。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100345', '奥利哈钢 死之计数器', '每当我方场上名字带有「奥利哈钢」的怪兽攻击成功或送入墓地时，此卡增加1个「诅咒指示物」，每去除1个「诅咒指示物」，将对方卡组或墓地1张卡移除到游戏外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100346', '奥利哈钢的圣光', '此卡选择以下效果1个效果发动：
INSERT INTO "texts" VALUES ('ZZ100347', '奥利哈钢 徘徊之魂', '1回合1次，选择双方除外怪兽最多3张特殊召唤到我方场上，因此效果特殊召唤的怪兽从场上离开时，移除到游戏外，我方回复那只怪兽一半的攻击力数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100348', '奥利哈钢 黑蛇蜕化', '自己场上的1只名字带有「奥利哈钢」的怪兽被破坏时，可以在我方场上正面表示特殊召唤1只 「奥利哈钢 黑蛇魔」。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100349', '奥利哈钢 光之创造神', '将我方手牌·场上·墓地中的「奥利哈钢 天空龙」「奥利哈钢 巨神兵」「奥利哈钢 翼神龙」各1只从游戏中除外才能召唤。此卡的召唤不能被破坏和无效化。此卡不受对方卡效果影响，此卡召唤成功后对方场上所有魔法·陷阱卡无视效果无条件破坏。我方生命值不足8000时变为8000。限此卡在场，我方受到的所有伤害（包括支付生命值代价）为0。此卡和暗属性怪兽战斗时，不进行伤害计算，无视对方卡效果直接将那只怪兽移除到游戏外，当此卡送入墓地时，将对方场上和手牌所有卡片移除到游戏外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100350', '奥利哈钢 黑暗大法师', '移除我方墓地10张名字带有「奥利哈钢」的怪兽，此卡可以从手牌特殊召唤，此卡与攻击力无限大的怪兽战斗时，攻击力永远比对方那只怪兽高500点，此卡召唤成功后对方手牌全部舍弃到墓地，我方从卡组抽取相应数量的卡片，只要其中有名字带有「奥利哈钢」的怪兽就可以无视召唤条件特殊召唤到场上，限此卡正面表示存在场上或手牌时，当我方场上有4张名字带有「奥利哈钢」的魔法师族怪兽时我方获得这场决斗的胜利，当此卡因对方卡效果被破坏时，无条件强制破坏对方场上1张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100351', '究极奥利哈钢之神', '由「达姿的第二仪式」或「奥利哈钢之圣都 亚特兰提斯」的效果，从卡组·手牌·墓地除外区域降临，把场上的「原始奥利哈钢之神」除外，给予对方伤害等于除外卡的攻击力。把已方或对方场上1只怪兽做祭品，给予对方4000点的伤害。支付100点生命值可以破坏对方场上的全部卡片，此卡不受魔法·陷阱·效果的影响。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100353', '奥利哈钢 黑蛇魔', '调整＋调整以外的传说神人族怪兽1只以上
INSERT INTO "texts" VALUES ('ZZ100355', '殉道者 虚无大天使', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。当我方场上有3只以上怪兽被破坏送入墓地时可以将此卡从卡组特殊召唤，限此卡在场上，跳过我方抽卡阶段，对方场上所有怪兽效果无效。只要我方墓地存在名字带有「殉道者」的卡片，此卡便不会被破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100356', '殉道者 地狱战神', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。当对方场上存在3只以上怪兽时，此卡可以从卡组特殊召唤，此卡召唤成功后对方场上所有怪兽变为守备表示，此卡不能直接攻击对方玩家生命值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100357', '殉道者 地狱天神', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。此卡在卡组里只能存在1张。当我方墓地存在20只以上名字带有「殉道者」的卡片时，此卡可以从卡组·手牌·墓地·游戏外区域特殊召唤上场。此卡不受对方任何卡效果影响。此卡不能直接攻击对方玩家生命值，限此卡在场上时，对方不能将此卡外名字带有「殉道者」的怪兽卡作为攻击对象，每解放方场上1只名字带有「殉道者」的怪兽给予对方那个怪兽攻击力数值的相等伤害。当我方受到战斗伤害以外伤害时，将我方墓地1张名字带有「殉道者」的卡片移除到游戏外那个伤害无效化。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100358', '殉道者 控水神将', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。此卡不能通常召唤，将我方场上3张名字带有「殉道者」的怪兽送入墓地后特殊召唤，只要我方场上存在其他名字带有「殉道者」的怪兽，此卡就不受对方卡效果影响，也不能被破坏，每个我方回合的准备阶段，在我方场上特殊召唤1只「水妖衍生物」，并选择对方场上1只怪兽，得到那只怪兽的等级·种族·属性·攻·守·效果。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100359', '水妖衍生物', '由「殉道者 控水神将」的效果特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100360', '殉道者 黑鸦骑士', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。舍弃全部手牌，可以将这张卡从卡组特殊召唤到场上，此卡攻击力·守备力为丢弃手牌数×1000点。此效果不会被无效化。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100361', '殉道者 地狱魔神', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。将我方卡组·手牌·墓地「奥西里斯之天空龙」、「欧贝利斯克之巨神兵」、「太阳神之翼神龙」移除到游戏外才能召唤，此卡的攻击力为我方场上手牌怪兽攻击力的总和，每祭掉我方场上1只怪兽。此卡增加那只怪兽的攻击力数值。此卡的召唤不能被无效化，不会成为魔法·陷阱·怪兽效果的对象。此卡召唤成功后破坏对方场上所有卡片，因此效果破坏的每1张给予对方生命值1000点伤害。此卡召唤后的第2回合的结束阶段时送入墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100362', '殉道者 遮面幻王', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。此卡召唤成功后，将我方卡组最上方10张卡送入墓地，每有1张名字带有「殉道者」的卡片，此卡攻击力上升1000点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100363', '殉道者 狱炼魔王', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。此卡不能特殊召唤，将我方场上名字带有「殉道者」的3只怪兽当做祭品才能召唤，此卡的攻击力为祭品怪兽的攻击力总和，每当对方发动魔法·陷阱·怪兽效果时，下降此卡500点攻击力让那个效果发动无效并破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100364', '殉道者 地狱主导者', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。此卡无法通常召唤，祭掉我方魔法陷阱区域1张卡才可以特殊召唤，此卡的攻击力为对方手牌张数×1000点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100365', '殉道者 梵天摩诃', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。我方或对方有卡被移除到游戏外时，此卡从手牌·墓地·卡组特殊召唤上场，攻击力为移除到游戏外卡片数量×1000。每个我方回合的准备阶段，将我方手牌的1张卡移除到游戏外，当我方手牌为0时，此卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100366', '殉道者 魁首龙', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。此卡的攻击力·守备力一直比对方场上攻击力最高的怪兽高300点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100367', '殉道者 变异魔人', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。此卡不能通常召唤，把我方或对方场上1只名字带有「殉道者」的怪兽从游戏中除外的场合才能特殊召唤。这张卡的特殊召唤不会被无效化。这张卡特殊召唤成功时，这张卡以外的双方的手牌·场上·墓地的卡全部从游戏中除外，对应这个效果的魔法·陷阱·效果怪兽的效果发动无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100368', '殉道者 地狱天神奴仆', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。此卡不会被战斗破坏，受到的战斗伤害为0。可以将这张卡做祭品，从自己卡组无视召唤条件特殊召唤「殉道者 地狱天神」上场，使用了这个效果的回合，自己不能攻击宣言。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100369', '殉道者 魔导绿', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。此卡的攻击力上升自己墓地的名字带有「殉道者」的怪兽数量×200点的数值。此外，1回合1次，把自己墓地1只7星以下的名字带有「殉道者」的怪兽从游戏中除外才能发动。直到结束阶段时，这张卡当作和除外的怪兽同名卡使用，并叠加相同效果。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100370', '殉道者 引导觉醒之龙', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。当我方场上不存在怪兽卡时，可以将此卡送入墓地，从手牌·卡组特殊召唤2只6星以下的名字带有「殉道者」的怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100371', '殉道者 龙骑鲁克', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。我方场上名字带有「殉道者」的怪兽有2只以上被送入墓地的场合，这张卡可以从手牌特殊召唤上场，这张卡的攻击力为送入墓地的怪兽攻击力的总和。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100372', '殉道者 魔导红', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。只要这张卡在场上正面表示存在，1回合1次，我方可以做2次通常召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100373', '殉道者 摩克达的魔将', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。此卡的攻击力为对方生命值的一半，每当此卡攻击力发生变化时，我方从卡组抽1张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100374', '殉道者 百鬼夜行将', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。此卡攻击成功后，对方每有1张手牌，给予对方1000点生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100375', '殉道者 人马战士', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。从卡组抽1张卡，给双方确认，确认的卡是名字带有「殉道者」的卡的场合，将这张卡加入手牌，并选择场上1张卡送入墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100376', '殉道者 效果锁定兽', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。此卡在场上正面表示存在时，对方每发动1次魔法卡或陷阱卡，我方可以将对方墓地对应的魔法或陷阱卡加入我方手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100377', '殉道者 火焰驱魔人', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。1回合1次，选择持有这张卡攻击力以下的对方场上1只怪兽才能发动。选择的怪兽送去墓地，给予对方生命值2000点伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100378', '殉道者 火炎焱君', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。此卡的攻击力上升对方墓地名字带有「殉道者」外怪兽数量×300点的数值，此外，1回合1次，把自己墓地1只7星以下的名字带有「殉道者」的怪兽从游戏中除外才能发动，直到结束阶段时，这张卡当作和除外的怪兽同名卡使用，并叠加相同效果。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100379', '殉道者 戏剧师西索', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。这张卡召唤成功时，将手牌1张名字带有「殉道者」的怪兽特殊召唤。这个效果发动的回合，对方下个回合不能通常召唤怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100380', '殉道者 地狱狩猎兵', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。1回合1次，从墓地选择2张卡片放回我方手牌或卡组中并洗牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100381', '殉道者 抗魔师', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。只要此卡正面表示存在于场上，对方就不能发动魔法卡，对方场上所有魔法卡效果无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100382', '殉道者 邪天使·露利丝', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。选择我方场上1只名字带有「殉道者」的怪兽，攻击力下降1000点，被选择的怪兽可以直接攻击对方玩家生命值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100383', '殉道者 冥界女巫', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。这张卡召唤成功时，自己场上的全部名字带有「殉道者」的怪兽的攻击力上升此卡攻击力数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100384', '殉道者 地狱魔人使', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。1回合1次，自己场上的名字带有「殉道者」的怪兽进行战斗的伤害计算时把卡组最上面任意张数卡送入墓地，那只怪兽的攻击力直到结束阶段时上升送入墓地的卡片数×100点。这个效果在对方回合也能发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100385', '殉道者 改装兔', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。1回合1次，将这张卡的等级下降1，攻击力上升原攻击力数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100386', '殉道者 双子白骨', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。只要这张卡在墓地，1回合1次可以在场上特殊召唤「殉道者衍生物」2只(攻/守0·恶魔族·1星·暗属性)', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100387', '殉道者衍生物', '由「殉道者 双子白骨」的效果特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100388', '殉道者 区域开拓士離', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。1回合1次，我方魔法陷阱卡区域永久增加1。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100389', '殉道者之轮', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。1回合1次，我方场上的全部名字带有「殉道者」的怪兽在我方回合不受对方魔法·陷阱卡的效果影响。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100390', '殉道者之预兆', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。1回合1次掷1次骰子，我方从卡组上方抽出那个点数数量的卡片。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100391', '殉道者输送', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。对方每回合损失1000点生命值。每当我方准备阶段时必须支付1000点生命值，否则此卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100392', '殉道者的回魂技', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。1回合1次，将墓地1只名字带有「殉道者」的怪兽返回卡组，双方抽1张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100393', '殉道者血的代价', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。支付5000点生命值，将对方卡组所有陷阱卡移除到游戏外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100394', '殉道者的邪恶交换', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。支付6000点生命值，将对方卡组所有魔法卡移除到游戏外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100395', '殉道者之脉搏悸动', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。跳过我方抽卡阶段，给予对方生命值一半的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100396', '殉道者之深渊审判官', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。每当对方正面表示召唤怪兽时，那只怪兽的攻击力下降2000点，攻击力不足2000点的场合，破坏那只怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100397', '殉道者的雷击', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。每移除我方魔法陷阱区1张卡，破坏对方魔法陷阱区1张卡。这个效果在对方的回合也可以发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100398', '殉道者之宿命', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。此卡发动被送入墓地，此卡发动后的第5个回合，我方赢得这次决斗的胜利。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100399', '殉道者之盾', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。我方魔法陷阱区域数量无限制，此卡只能给名字带有「殉道者」的怪兽装备，装备怪兽1回合2次不受怪兽卡效果影响。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100400', '殉道者之灵巫', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。我方魔法陷阱区域数量无限制。此卡只能给名字带有「殉道者」的怪兽装备。装备怪兽1回合2次不受魔法·陷阱效果影响。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100401', '殉道者之盔', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。我方魔法陷阱区域数量无限制。此卡只能给名字带有「殉道者」的怪兽装备，装备怪兽1回合2次不会被战斗破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100402', '殉道者的无情反击', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。对方发动攻击宣言时可以发动，破坏对方场上所有卡片。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100403', '殉道者毁灭区', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。只要此卡在场上正面表示存在，每当对方怪兽送入墓地时，我方可以选择以下1个效果发动。●将那只怪兽无视条件特殊召唤到我方场上。●回复那只怪兽攻击力数值的生命值。●给予对方那只怪兽攻击力一半的生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100404', '殉道者之回归', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。将墓地任意张数名字带有「殉道者」的卡片返回卡组，我方回合送入卡组张数×1000点的生命值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100405', '殉道者造卡器', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。对方抽卡阶段时，我方手牌比对方手牌少时可以发动，我方从卡组中抽出直到与对方手牌数量相同为止。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100406', '殉道者的悠暗时刻', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。支付3000点生命值，跳过对方的抽卡阶段，我方抽1张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100407', '殉道者的结界限制', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。只要此卡在场上正面表示存在，对方需要跳过抽卡阶段才可以召唤怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100408', '殉道者的痛彻一击', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。破坏我方场上所有怪兽，将对方所有手牌移除到游戏外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100409', '殉道者之意志', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。我方魔法陷阱区域数量无限制，我方每回合回复场上名字带有「殉道者」的卡片数量×1000点的生命值数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100410', '殉道者的强苦之痛', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。将我方生命值降为1点，将对方卡组所有怪兽卡送入墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100411', '殉道者之无忌的怪兽', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。当对方发动怪兽卡效果时，祭掉我方场上1只名字带有「殉道者」的怪兽让那个怪兽效果无效并破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100412', '殉道者之无忌的魔法', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。当对方发动魔法卡效果时，丢弃1张手牌，让那张卡无效并破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100413', '殉道者之无忌的陷阱', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。当对方发动陷阱卡效果时，丢弃1张手牌，让那张卡无效并破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100414', '殉道者之崩坏', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。对方怪兽变为正面守备形式时可以发动，那只怪兽效果无效，对方场上正面守备表示的怪兽全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100415', '殉道者之逆转', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。此卡在卡组中只能加入1张，此效果每场决斗只能使用1次，此卡发动成功后移除到游戏外。将我方卡组·手牌·墓地·场上所有卡片返回卡组，并抽5张卡，我方生命值变为8000点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100416', '殉道者之异次元穿越', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。对方特殊召唤怪兽成功时发动，我方可以将卡组1只比对方特殊召唤的怪兽高2星的怪兽无视召唤条件特殊召唤到我方场上。（最高可以召唤12星的怪兽）', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100417', '殉道者军团', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。只要此卡在场上，每当我方给对方造成伤害时，追加那个数值的生命值伤害，我方损失那个数值一半的生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100418', '殉道者之反射罩', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。每当我方召唤·特殊召唤成功时，我方回复召唤怪兽等级×100的生命值。此卡从场上送入墓地时，给予对方3000点生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100419', 'No.93六芒星の神 巨龙神', '12星怪兽×2
INSERT INTO "texts" VALUES ('ZZ100420', '六芒星之龙 黄金地龙', '召唤的场合，必须把自己场上1只名字带有「六芒」怪兽或地属性怪兽2只解放召唤。这张卡召唤不会无效化，不会成为对方魔法/陷阱/效果怪兽的对象。攻击时可以选择场上2张卡破坏。只要此卡存在场上名字带有「奥利哈钢」的卡无效并除外。每1张给予对方1000点生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100421', '六芒星之龙 长翼风龙', '召唤的场合，必须把自己场上1只名字带有「六芒」怪兽或风属性怪兽2只解放召唤。这张卡召唤不会无效化，1回合1次舍弃手牌可以破坏对方场上相同数量的卡。只要此卡存在场上名字带有「奥利哈钢」的卡无效并除外。每1张给予对方1000点生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100422', '六芒星之龙 深渊暗龙', '召唤的场合，必须把自己场上1只名字带有「六芒」怪兽或暗属性怪兽2只祭品召唤。这张卡召唤不会无效化，对方场上怪兽效果无效，攻击力每舍弃1张手牌上升1000点，只要此卡存在场上名字带有「奥利哈钢」的卡无效并除外，每1张给予对方1000点生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100423', '六芒星之龙 烈阳光龙', '召唤的场合，必须把自己场上1只名字带有「六芒」怪兽或光属性怪兽2只解放召唤。这张卡召唤不会无效化，对方手牌全部破坏，自己墓地每1张光属性怪兽此卡攻击力上升1000。只要此卡存在场上名字带有「奥利哈钢」的卡无效并除外，每1张给予对方1000点生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100424', '六芒星之龙 赤炎火龙', '召唤的场合，必须把自己场上1只名字带有「六芒」怪兽或炎属性怪兽2只解放召唤。这张卡召唤不会无效化，对方魔法/陷阱效果发动无效并破坏，攻击时可以选择场上最多2只怪兽破坏。只要此卡存在场上名字带有「奥利哈钢」的卡无效并除外，每1张给予对方1000点生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100425', '六芒星之龙 封锁水龙', '召唤的场合，必须把自己场上1只名字带有「六芒」怪兽或水属性怪兽2只解放召唤。这张卡召唤不会无效化，只要此卡存在场上对方陷阱卡无效并破坏，怪兽不能特殊召唤。场上名字带有「奥利哈钢」的卡无效并除外，每1张给予对方1000点生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100426', '六芒星 日光龙', '将此卡从手牌送入墓地，可从卡组将最多2张「六芒星 日光龙」加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100427', '六芒星 龙父', '1回合1次，从手牌舍弃带有「六芒星」的怪兽，每舍弃1张，破坏场上1张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100428', '六芒星 幼龙', '召唤成功的场合可从卡组1只12星的怪兽加入手牌，这回合此卡不能用作祭品使用。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100429', '六芒星 元老王', '1回合1次可以从手牌将1只名字带有「六芒星」的怪兽特殊召唤上场，对方场上已存在的卡效果发动无效并破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100430', '六芒星 龙斗士', '自己场上有陷阱卡存在的场合，这张卡可以不用祭品从手牌特殊召唤。这个效果特殊召唤的这张卡的原本攻击力和守备力变成一半数值，在下1回合恢复。召唤成功后可从卡组将1张「六芒星 龙骑士」加入手牌，此卡在场上陷阱卡不会被破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100431', '六芒星 龙武士', '自己场上有怪兽存在的场合，这张卡可以不用祭品从手牌特殊召唤。这个效果特殊召唤的这张卡的原本攻击力和守备力变成一半数值，在下1回合恢复，召唤成功后可从卡组将1张名字带有「六芒星」加入手牌。1回合1次，可从2张手牌送入墓地，从手牌特殊召唤1只怪兽，怪兽的召唤不能被无效化。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100432', '六芒星 龙狂士', '自己场上有魔法卡存在的场合，这张卡可以不用祭品从手牌特殊召唤。这个效果特殊召唤的这张卡的原本攻击力和守备力变成一半数值，在下1回合恢复，1回合1次，可将自己场上1只怪兽送入墓地，从手牌将1只名字带有「六芒星」的怪兽特殊召唤，卡在场上魔法卡不会被破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100433', '六芒星 龙骑士', '自己场上有怪兽存在的场合，这张卡可以不用祭品从手牌特殊召唤，这个效果特殊召唤的这张卡的原本攻击力和守备力变成一半数值，在下1回合恢复，此卡不会被战斗破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100434', '六芒星碎片', '我方场上名字带有「六芒星」的怪兽被战斗破坏时，将手牌中名字带有「六芒星」的怪兽全部召唤上场。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100435', '六芒星的裁决', '对方每次战斗结束后，手牌全部送入墓地。此卡正面表示存在的场合，对方不能从墓地特殊召唤怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100436', '六芒星的水祭', '我方怪兽被破坏时发动，将那只怪兽和对方场上的1只怪兽当作水属性怪兽送入墓地，可从手牌特殊召唤「六芒星之龙 封锁水龙」。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100437', '六芒星源', '场上1只名字带有「六芒」的怪兽正面表示存在，1回合1次可在抽卡阶段抽两张卡。在战斗结束时，必需将1张手牌送入墓地，否则此卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100438', '六芒星天界', '这张卡存在场上，对方不能召唤怪兽，自己场上没有陷阱卡的场合，这张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100439', '六芒星地界', '这张卡存在场上，对方不能发动魔法卡和陷阱卡，自己场上没有怪兽的场合，这张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100440', '六芒星龙斗哈刚', '此卡正面存在场上，对方不能使用名字带有「奥利哈钢」的卡片。此卡的发动不会被无效和破坏，此卡发动后在10个我方回合后破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100441', '六芒龙反击', '自己场上1只名字带有「六芒星之龙」的怪兽被破坏时，破坏对手场上所有卡片。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100442', '六芒星风之乡', '从卡组将1张「六芒星 长翼凤龙」加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100443', '千年禁忌-夏达之锤', '此卡在场上正面表示存在时，对方对此卡发动魔法·陷阱·怪兽卡的效果时，那张卡的效果无效并破坏。1回合1次，舍弃手牌所有卡，之后，在卡组抽取那个数量的卡。
INSERT INTO "texts" VALUES ('ZZ100444', '千年禁忌-爱西丝之斧', '此卡在场上正面表示存在时，对方对此卡发动魔法·陷阱·怪兽卡的效果时，那张卡的效果无效并破坏。1回合1次，选择对方场上1只怪兽发动，我方得到那只怪兽的控制权。
INSERT INTO "texts" VALUES ('ZZ100445', '千年青龙', '四神兽之卡。
INSERT INTO "texts" VALUES ('ZZ100446', '千年白虎', '四神兽之卡。
INSERT INTO "texts" VALUES ('ZZ100447', '千年朱雀', '四神兽之卡。
INSERT INTO "texts" VALUES ('ZZ100448', '千年玄武', '四神兽之卡。
INSERT INTO "texts" VALUES ('ZZ100449', '千年轩辕剑', '十神器之卡。
INSERT INTO "texts" VALUES ('ZZ100450', '千年断魂刃', '千年神器之卡。
INSERT INTO "texts" VALUES ('ZZ100451', '千年宝莲灯', '千年神器之卡。
INSERT INTO "texts" VALUES ('ZZ100452', '提玛欧斯之眼', '一万年前的“石之荒野之战”中传说之龙与「奥利哈钢之神」的对战！最后一起封印。
INSERT INTO "texts" VALUES ('ZZ100453', '火神龙·骑玛利欧斯', '「传说骑士-提玛欧斯之眼」+「传说骑士 克里提钨斯之牙」+「传说骑士 海聂默斯之爪」
INSERT INTO "texts" VALUES ('ZZ100454', '无名-提玛之心', '此卡作为装备卡装备时，装备怪兽不受任何卡的效果影响。装备怪兽被破坏时，此卡也同时被破坏，此卡召唤成功的场合，可以从卡组选择1张「提玛欧斯之眼」特殊召唤上场。此卡被破坏送入墓地时，选择对方场上最多3张卡破坏，此效果不会被卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100455', '无名-克里之心', '此卡在场上存在时，场上除此卡外的其他卡不能被选为攻击对象。此卡不会被攻击破坏，此卡被送入墓地时，给予对方此卡一半攻击力数值的生命值伤害。同时从卡组选择1张「克里提钨斯之牙」同时召唤上场。用此效果特殊召唤上场的「克里提钨斯之牙」不会被对方选为攻击对象。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100456', '无名-海聶之心', '此卡召唤成功后，从卡组选择1张「海聂默斯之爪」特殊召唤上场，给予对方此卡一半攻击力数值的生命值伤害。此卡被送入墓地时，场上所有怪兽将受到「海聶默斯之爪」一半攻击力的生命值的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100457', '无名-传说之心', '「无名-海聶之心」+「无名-克里之心」+「无名-提玛之心」
INSERT INTO "texts" VALUES ('ZZ100458', '女子佣兵 魔音', '此卡只能用「女子佣兵 高音」做祭品召唤上场，此卡召唤成功后，可以将手牌·卡组·墓地中名字带有「高等宝玉」的卡尽可能的召唤上场。此效果的发动不被任何卡的效果影响。由于此效果的发动每召唤成功1只怪兽，对方受到2000点生命值的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100459', '女子佣兵 卡灵', '此卡正面表示存在场上时，1回合1次，额外从卡组抽取2张卡，抽到的卡是怪兽卡不受场地限制特殊召唤上场，此卡被选择为攻击对象时，破坏我方场上1张卡，那次攻击或效果无效并破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100460', '女子佣兵 镜灵', '将我方手牌1张名字带有「女子佣兵」的怪兽送入墓地，可以从墓地将此卡特殊召唤上场，此召唤视为正面召唤。我方场上每存在1张名字带有「女子佣兵」的卡，选择对方场上1张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100461', '女子佣兵 光灵', '只要此卡正面表示存在于场上。我方召唤名字带有「女子佣兵」的怪兽不需要祭品。每召唤1只此卡攻击力下降1000点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100462', '女子佣兵 水灵', '攻击比此卡攻击力高的怪兽时，此卡不会被破坏，此卡同被攻击的怪兽攻击力转换，此卡被卡的效果破坏时，对方受到此卡攻击力数值的生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100463', '女子佣兵 火灵', '攻击比此卡攻击力低的怪兽时，被攻击的怪兽不会被破坏且攻击力变成此卡守备力数值，此卡攻击守备表示的怪兽时，对方受到守备表示怪兽的守备力数值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100464', '女子佣兵 暗灵', '1回合1次，降低此卡500点攻击力，选择对方卡组5张卡送入墓地，选择的卡里面有暗属性怪兽的场合，对方受到那只暗属性怪兽攻击力的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100465', '女子佣兵 风灵', '此卡被选为攻击对象时，此卡的攻击力变成0，此卡和攻击的怪兽控制权交换且战斗不能被停止。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100466', '女子佣兵 地灵', '1回合1次，选择对方场上最多2只怪兽改变表示形式。此卡攻击时，对方场上没有地属性怪兽时，此卡不被任何效果影响，直接攻击对方生命值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100467', '女子佣兵 圣魔师', '只要此卡存在于场上，对方魔法师族的怪兽不能发动攻击宣言，1回合1次，将我方场上1只名字带有「女子佣兵」的怪兽送入墓地，此卡可以直接攻击对方且不受任何卡片效果影响。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100468', '女子佣兵 玄冰', '攻击比此卡攻击力高的水属性怪兽时，不计算战斗伤害，直接破坏那只怪兽，破坏的怪兽下个我方回合，在我方场上特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100469', '女子佣兵 吸血魔', '将此卡攻击力变为0.此卡可以不用祭品召唤上场，我方场上每存在1只名字带有「女子佣兵」的怪兽时，此卡攻击力上升2000点。此卡战斗破坏对方怪兽时，破坏的怪兽再次回到对方场上，对方生命值受到那只怪兽1半攻击力数值的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100470', '女子佣兵 驱风', '攻击比此卡攻击力高的风属性怪兽时，不计算战斗伤害，直接破坏那只怪兽。破坏的怪兽下个我方回合，在我方场上特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100471', '女子佣兵 狐妖', '此卡守备表示存在于场上时，我方场上存在的名字带有「女子佣兵」的怪兽攻击力上升1000点，此卡被战斗破坏的场合，从卡组选择1张同名卡加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100472', '女子佣兵 封魂兔', '此卡给予对方战斗伤害的场合，每造成100点伤害破坏对方卡组1张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100473', '女子佣兵 光辉师', '此卡召唤成功时，在场上召唤1只（光辉衍生物），每回合此卡放弃战斗，可以召唤1只（光辉衍生物），当场上出现2只（光辉衍生物）的场合，对方损失此卡攻击力×2的生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100474', '女子佣兵 机控者', '我方受到卡的效果伤害时，此卡从手牌直接送入墓地，那张卡的效果无效并破坏，下个我方回合此卡从墓地特殊召唤上场。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100475', '女子佣兵 天使', '将此卡从场上送入墓地，选择墓地1只怪兽特殊召唤上场，此卡被战斗破坏的场合，可以从卡组选择1张同名卡加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100476', '女子佣兵 小魔牙', '此卡召唤成功后不能发动攻击。1回合1次，降低此卡700点攻击力破坏对方场上魔法陷阱区1张卡，破坏的卡是陷阱卡时，对方损失1000点生命值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100477', '女子佣兵 薄姬', '此卡被卡片效果特殊召唤上场的回合，该回合可以选择攻击2次，且不被任何卡片效果影响。此卡被送入墓地时，可以从卡组选择1张名字带有「女子佣兵」的怪兽卡加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100478', '女子佣兵 高音', '墓地存在名字带有「低音」、「高音」的卡各1张时，此卡可以从手牌·卡组特殊召唤上场，此召唤不受任何卡效果影响，此卡召唤成功时，将我方手牌光属性卡全部丢弃，此卡可以攻击那个丢弃的数量的次数。
INSERT INTO "texts" VALUES ('ZZ100479', '女子佣兵 低音', '此卡从手牌送入墓地的场合，可以从卡组特殊召唤「女子佣兵 初音」上场，此卡被选为攻击对象时，可以将此卡攻击力变成0，对方将受到我方受到的双倍伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100480', '女子佣兵 初音', '此卡被特殊召唤上场的回合，对方场上除光属性以外的所有卡全部破坏，1回合1次，跳过攻击阶段发动，我方墓地每存在1张光属性卡对方受到1000点生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100481', '女子佣兵 购物者', '此卡召唤成功时，1回合1次，降低500点攻击力，选择对方场上1张卡，选择的卡直接送入墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100482', '女子佣兵 武藏', '此卡特殊召唤成功的回合，选择对方场上1张怪兽卡破坏，对方受到破坏的怪兽攻击力数值的生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100483', '女子佣兵 子龙', '此卡用祭品召唤成功时，攻击力上升那只祭品怪兽的攻击力数值。此卡发动攻击宣言时，双方需要支付2000点生命值才能发动魔法·陷阱卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100484', '女子佣兵 樱刃', '只要我方场上有其他名字带有「女子佣兵」的怪兽时，此卡不能被选为攻击对象，同此卡战斗的怪兽攻击力减半，且不会被此卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100485', '女子佣兵 枪手', '我方场上有名字带有「女子佣兵」的怪兽时，此卡可以从手牌特殊召唤，此卡召唤成功时，对方场上的陷阱卡全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100486', '女子佣兵 伯爵', '此卡发动攻击时，将我方场上1只名字带有「女子佣兵」的怪兽送入墓地，选择对方场上1只怪兽攻击力变为0，双方魔法·陷阱卡不能发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100487', '女子佣兵 魔法仆人', '此卡被破坏送入墓地的场合，可以从卡组·手牌将「女子佣兵 圣魔师」特殊召唤上场，任何针对此效果发动的效果无效并破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100488', '女子佣兵 初学者', '当墓地存在3张「女子佣兵 初学者」的场合，可以将手牌名字带有「女子佣兵」的怪兽尽可能多的召唤上场。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100489', '女子佣兵 雷闪', '此卡不会被战斗破坏。1回合1次，此卡攻击力上升手牌中名字带有「女子佣兵」的怪兽数量×500点，此卡被卡的效果送入墓地时，对方手牌全部送入墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100490', '女子佣兵 陆虎', '此卡被作为祭品送入墓地时，选择对方场上1张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100491', '女子佣兵 烈火', '攻击比此卡攻击力高的炎属性怪兽时，不计算战斗伤害，直接破坏那只怪兽，破坏的怪兽下个我方回合在我方场上特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100492', '女子佣兵 机甲师', '此卡被特殊召唤成功时，可以从卡组·手牌特殊召唤2只机械族名字带有「女子佣兵」的怪兽上场，对方场上低于2只怪兽时，此卡可以直接攻击对方玩家生命值，此卡发动攻击时双方不能将魔法·陷阱卡发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100493', '女子佣兵 狐地', '攻击比此卡攻击力高的地属性怪兽时，不计算战斗伤害，直接破坏那只怪兽。破坏的怪兽下个我方回合，在我方场上特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100494', '女子佣兵 灭灵者', '当我方手牌·卡组有卡送入墓地的场合，次可以从手牌·卡组特殊召唤上场，此卡特殊召唤成功时，给予对方生命值2000点伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100495', '光辉衍生物', '由「女子佣兵 光辉师」的效果特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100496', '灵族的意识', '此卡发动后，我方场上名字带有「女子佣兵 灵」的怪兽不能被选为攻击对象，且不被卡片效果影响。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100497', '伯爵的审判', '我方生命值受到战斗伤害时发动，对方受到我方双倍的生命值伤害数值的伤害。此效果的发动被无效时，选择对方场上1只怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100498', '甜蜜的婚礼', '对方回合可以发动。双方手牌·场上的卡全部破坏送入墓地，各自从卡组抽取5张牌，将名字带有「女子佣兵」的怪兽最多2只召唤上场。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100499', '佣灵的意识', '当我方墓地存在名字带有「水灵」、「火灵」、「地灵」、「风灵」、「光灵」、「暗灵」的卡各1张时发动，将这些移除游戏外，对方生命值直接变成0。
INSERT INTO "texts" VALUES ('ZZ100500', '伯爵上位', '我方墓地有名字带有「女子佣兵」的怪兽时，可以从手牌或者卡组选择1张名字带有「女子佣兵」的怪兽上场。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100501', '团结之力', '当我方生命值低于1000点，且场上没有名字带有「女子佣兵」的怪兽时发动，从手牌·卡组·墓地选择3只名字带有「女子佣兵」的怪兽特殊召唤，特殊召唤成功的怪兽可以立即发动攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100502', '钻研', '我方场上没有名字带有「女子佣兵」时发动，从手牌·卡组特殊召唤1只「女子佣兵 圣魔师」，只要此卡在场上存在，被此卡特殊召唤的怪兽不被任何效果影响。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100503', '女子佣兵 斩月', '被此卡选为攻击对象的怪兽等级变为0，此卡破坏对方怪兽的场合，给予对方被选为攻击对象目标的怪兽等级数乘以500点的生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100504', '时间魔女', '对方回合发动，发动后对方直接跳过回合，不进行任何阶段，直接进入我方回合。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100505', '女仆的援手', '当我方生命值低于1000点时发动，我方生命值回复手牌卡片张数x1000点的数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100506', '伯爵的封印', '对方对我方造成生命值伤害时发动，将那次伤害数值变成0，并判定1个系列，被判定的系列怪兽召唤上场时，攻击力下降2000点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100507', '姐妹同心', '我方场上有名字带有「女子佣兵」的怪兽被破坏送入墓地时发动，从手牌或卡组选择1张同名卡特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100508', '暗黑抽牌', '抽牌前预测抽到的卡的种类（魔法·陷阱·怪兽）猜对的场合，我方可以继续抽牌。直到预测失败为止。当我方因此效果抽牌阶段抽了5张牌时，我方获得这场决斗的胜利。当此卡因对方卡效果被破坏时，无条件强制破坏对方场上1张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100509', '邪之于贝尔', '这张卡不会被战斗破坏，这张卡受到的战斗伤害变成0。1回合1次跳过此卡的攻击阶段，舍弃手牌1张怪兽卡，给予对方那只怪兽攻击力数值的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100510', '神之裁决', '每当对方魔法·陷阱卡发动或怪兽召唤·反转召唤·特殊召唤时。可以支付一半生命值，让那张卡发动无效并破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100511', '灵魂对换', '每将我方手牌1张名字带有「青眼」的怪兽送入墓地，可以选择我方卡组1张名字带有「青眼」的怪兽加入手牌，此卡发动成功后的第3个回合送入墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100512', '王者的决断', '选择我方场上1只怪兽发动，对方在自己手牌随机选择1张，我方对那张卡的种类（怪兽·魔法·陷阱）作猜测。猜中的场合，选择的怪兽的攻击力上升1000点，并给予对方生命值直接伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100513', '剑士燔祭', '对方发动的效果怪兽的效果无效并破坏，对方受到那只怪兽攻击力数值的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100514', '战魂附体', '将我方场上1只怪兽除外，选择我方或对方场上1只怪兽增加被除外怪兽的攻击力。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('DCOR0008', '恶魂的伪物', '对方墓地存在的所有卡的效果无效。只要此卡在我方场上存在，对方无法发动陷阱卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100516', '魄气激增', '将我方场上1只怪兽送入墓地，第2个回合返回场上，攻击力变为原来的2倍。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100517', '聚集的祈愿', '支付800点生命值才能发动。此卡存在场上，我方场上所有的龙族怪兽不会被卡的效果及战斗破坏，自己场上龙族怪兽的攻击力直到结束阶段时上升700点，此卡被破坏送入墓地时，对方失去5000点生命值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100518', '邪之千年眼', '只能在对方抽牌阶段发动效果，预测那张卡的种类（魔法·陷阱·怪兽）预测成功的场合那张卡加入我方手牌，是怪兽的场合可以特殊召唤到我方场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100519', 'Flower Garden', '直到回合结束阶段前我方场上的的衍生物可以直接攻击玩家，这张卡发动的回合我方不能进行通常召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100520', '这颗行星的生日歌', '每次将怪兽战斗破坏的控制者，从卡组抽1张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100521', '鬼技师', '这张卡被卡效果送去墓地的时候，可以从卡组选择2只暗属性怪兽正面攻击表示特殊召唤到自己场上。之后卡组洗切。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100522', '岩鬼', '这张卡被卡效果送去墓地的时候，我方生命值可以回复此卡的攻击力数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100523', '邪恶魔手', '选择我方卡组1只等级6以上的怪兽特殊召唤到我方场上，并装备，当此卡被破坏送到墓地时，那只怪兽返回卡组，我方受到那只怪兽攻击力一半的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100524', '血之祭品', '支付3000点生命值，从卡组·手牌无条件特殊召唤3只以下名字带有「地狱」的神属性怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100525', '生与死的呼唤声', '只要此卡在场上，我方每回合都可以将自己墓地怪兽尽可能多的召唤到我方场上来。以此效果召唤成功的怪兽增加百分之十的攻击力。当自己场上怪兽被破坏时在对方回合也可发动此卡效果。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100526', '爆发冲击', '此卡只能装备在4星以下的怪兽身上，被装备的怪兽攻击力x2倍。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100527', '暗黑摄取', '双方从卡组最上方抽3张卡片，将等级在5星以下的怪兽特殊召唤，其他怪兽送入墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100528', '稻草人的诅咒', '我方每抽1张卡，此卡增加1个魔力指示物，●去除5个魔力指示物，破坏对方场上的魔法·陷阱卡。●去除8个魔力指示物，破坏对方场上的怪兽卡。●去除15个魔力指示物，破坏对方场上的所有卡。●去除30个魔力指示物，将对方卡组的一半怪兽卡从游戏中除外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100529', '盗贼王的呼声', '支付1000点生命值，并把手牌或卡组的1只暗属性怪兽送入墓地，从自己的手牌·墓地·卡组特殊召唤1只「魔神 迪亚邦多」到场上。此卡的发动不能被无效化。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100530', '代价', '只要这张卡在场上存在，对方怪兽召唤成功时，我方可以抽2张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('DCOR0024', '暗黑武装飞龙', '6星怪兽×2
INSERT INTO "texts" VALUES ('DCOR0040', '魔导精灵剑士', '
INSERT INTO "texts" VALUES ('ZZ100538', '七彩幻界植物女王', '●只要这张卡在怪兽区域存在，对方不能选择其他的名字带有「植物的愤怒」的怪兽作为攻击对象。
INSERT INTO "texts" VALUES ('ZZ100539', '植物の愤怒 魔王树', '植物族怪兽×5
INSERT INTO "texts" VALUES ('ZZ100540', '植物の愤怒 狂树虎', '「植物の愤怒  青苔虎」+「植物の愤怒  古树」
INSERT INTO "texts" VALUES ('ZZ100541', '植物の愤怒 古之战树', '名字带有「植物の愤怒」的调整＋调整以外的怪兽1只以上
INSERT INTO "texts" VALUES ('ZZ100542', '植物の愤怒 五齿花', '名字带有「植物の愤怒」的调整＋调整以外的怪兽1只以上
INSERT INTO "texts" VALUES ('ZZ100543', '植物の愤怒 青苔石龙', '名字带有「植物の愤怒」的调整＋调整以外的怪兽1只以上
INSERT INTO "texts" VALUES ('ZZ100544', '植物の愤怒 魔巨树', '将我方墓地1张「植物の愤怒 魔古树」从游戏中除外可将这张卡从手牌特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100545', '植物の愤怒 魔古树', '我方场上有名字带有「植物的愤怒」的怪兽存在时，这张卡战斗破坏对方怪兽送去墓地时，给予对方生命值2000点伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100546', '植物の愤怒 花蛙激光炮', '场上存在的这张卡可用作装备卡使用，只能装备在名字带有「植物の愤怒」的怪兽上，装备后的怪兽攻击力在每个对方回合2000。那只怪兽被破坏时，可把这张卡送入墓地代替破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100547', '植物の愤怒 红刺食人花', '将3张手牌送入墓地，这张卡可从手牌特殊召唤。这张卡可以直接攻击对方，1回合最多攻击3次。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100548', '植物の愤怒 青藤食人花', '自己场上有名字带有「植物の愤怒」的怪兽正面表示存在时，这张卡可以从手牌特殊召唤，这张卡可1回合攻击2次。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100549', '植物の愤怒 古树', '1回合1次从自己卡组·墓地将1只2星怪兽加入手牌，这张被战斗破坏送入墓地时，可从卡组将多张同名卡特殊召唤到场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100550', '植物の愤怒 白松人', '这张卡战斗破坏对方怪兽或对方怪兽战斗破坏时，可以从自己卡组把1只攻击力1000以下的名字带有「植物の愤怒」的怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100551', '植物の愤怒 三齿花', '自己场上除了「植物の愤怒 三齿花」以外没有怪兽正面表示存在时，这张卡可选择对方场上最多3只怪兽的控制权，被控制的怪兽不能用作攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100552', '植物の愤怒 植物老守者', '这张卡在场上，对方1回合只能攻击1次，攻击对象只能攻击此卡，这张卡的守备力上升对方场上对方场卡片数×500点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100553', '植物の愤怒 青苔石人', '对方怪兽攻击力超过这张卡的守备力时，可以有3次不受战斗破坏和生命值伤害。3次后这张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100554', '植物の愤怒 青苔小石人', '召唤成功时，可从卡组将1张「植物の愤怒 青苔石人」加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100555', '植物の愤怒 蓝花炮', '每次我方回合指定对方1只怪兽，怪兽攻击力4000以下的变为原来的一半，攻击力4000以上的变为1800。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100556', '植物の愤怒 南瓜蛛', '这张卡召唤成功时，可以从卡组将1张「植物の愤怒 紧急援助」加入手牌。自己场上名字带有「植物の愤怒 」的怪兽进行战斗时可以把这张卡送入墓地，那只怪兽攻击力上升1500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100557', '植物の愤怒 魔椎树', '选择以下其中一项发动：
INSERT INTO "texts" VALUES ('ZZ100558', '植物の愤怒 青苔虎', '自己场上除了「植物の愤怒 青苔虎」以外没有名字带有「植物の愤怒」的怪兽存在时，可将1张「植物の愤怒 古树」从卡组·墓地加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100559', '植物の愤怒 魔树苗', '此卡被破坏时，选择以下其中一项发动：
INSERT INTO "texts" VALUES ('ZZ100560', '植物の愤怒 地罗葡', '这张卡不能特殊召唤。这张卡召唤成功时，可以从自己卡组存在的1只4星以下的名字带有「植物の愤怒」的怪兽正面表示特殊召唤，将场上这张卡送入墓地，可以从卡组将1张「植物の愤怒 古树逢春」加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100561', '植物の愤怒 沙虫', '自己场上有名字带有「植物の愤怒」的怪兽正面表示存在，这张卡可以从手牌特殊召唤。1回合1次，可以把对方1只怪兽攻击力·守备力变为0，将场上这张卡送入墓地，可以从卡组将1张「植物の愤怒 古树逢春」加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100562', '植物の愤怒 树椿', '反转：从卡组选择2张名字带有「植物の愤怒」的怪兽送入墓地，下一个我方回合特殊召唤到我方场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100563', '植物の愤怒 青绵宝宝', '受到战斗伤害时，可以把这张卡从手牌送去墓地发动。自己场上名字带有「植物の愤怒」的怪兽不被战斗破坏，伤害为0。此卡在场上，对方魔法卡发动无效。1回合1次，选择1只攻击力500以上的怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100564', '植物の愤怒 水巨藤的吸引', '每次我方回合可从卡组抽2张卡，之后再从手牌选择最多3张卡送入墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100565', '植物の愤怒 绿色超融合', '将所有手牌送入墓地。从自己或对方墓地或场上把融合怪兽卡决定的怪兽除外，把那1只融合怪兽从融合卡组特殊召唤，不能对应这张卡的发动把魔法/陷阱/效果怪兽的效果发动。（这个特殊召唤当作融合召唤使用）', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100566', '植物の愤怒 花能量', '我方场上存在「植物の愤怒 三齿花」时，可从卡组将「植物の愤怒 青藤食人花」加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100567', '植物の愤怒 绿能转化', '我方场上名字带有「植物の愤怒」的卡被破坏时，被破坏的卡可选择放回卡组最上方或最下方。我方场上名字带有「植物の愤怒」的怪兽存在2只以上时，得到对方1只怪兽的控制权。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100568', '植物の愤怒 古树逢春', '自己场上存在「植物の愤怒 古树」时，可特殊召唤「植物の愤怒 古之战树」。我方场上名字带有「植物の愤怒」的怪兽正面表示存在时，对方发动的效果对名字带有「植物の愤怒」的卡无效。这张卡发动的效果对方不能用已经存在场上的卡来无效化。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100569', '植物の愤怒 人类光辉', '此卡在场上，对方召唤怪兽成功的回合，回合结束后，可选择对方场上的卡片和召唤成功的相等数量破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100570', '植物の愤怒 异变', '我方场上有怪兽正面存在回合，得到对方1只怪兽的控制权，那只怪兽变为我方场上1只怪兽的同名卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
