INSERT INTO "texts" VALUES ('ZZ100576', '七星门钥匙-日', '
INSERT INTO "texts" VALUES ('ZZ100577', '七星门钥匙-月', '
INSERT INTO "texts" VALUES ('ZZ100579', '始祖龙', '我方场上不存在怪兽卡时，此卡可以从手牌·卡组·墓地特殊召唤上场。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100580', '钢钻侠', '限此卡在场上正面表示存在，对方的准备阶段时，可以给予对方场上存在的卡数量x500的生命值伤害。此外，对方把魔法·陷阱卡盖放时，给予对方生命值500点伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100581', '亡灵守护神 阿努比斯', '
INSERT INTO "texts" VALUES ('ZZ100582', '青眼双头龙', '「青眼白龙」＋「青眼白龙」
INSERT INTO "texts" VALUES ('ZZ100583', '召唤神的黑暗大法师', '
INSERT INTO "texts" VALUES ('ZZ100584', '黑暗大法师   ', '
INSERT INTO "texts" VALUES ('ZZ100585', '毁灭的大法师', '将手牌的3只魔法师族怪兽送入墓地，此卡在对方的场上特殊召唤。此卡不能作为祭品，不能攻击和改变表示形式，也无法成为魔法·陷阱卡的目标，1回合1次和除此卡控制者生命值一半的数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100586', '黑暗大法师 魔神火焰炮', '将我方场地·手牌·墓地里存在的「被封印者的黑暗大法师」·「被封印者的右足」「被封印者的左足」·「被封印者的右腕」·「被封印者的左足腕」从游戏中除外，特殊召唤此卡，此卡的攻击不受魔法·陷阱卡的影响，此卡的攻击具有贯穿效果。此卡从场地上离开时，从游戏中除外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100587', '黑暗大法师埋葬殉道之灵', '普通同调不能召唤，只能通过以下效果召唤：
INSERT INTO "texts" VALUES ('ZZ100588', '混沌魔波', '对方怪兽的攻击宣言时才能发动，那只怪兽破坏。那之后，给予对方基本分2000分伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100589', '连击之力', '选择1只6星以下龙族怪兽，在攻击阶段可作3次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100590', '月蚀', '对方在抽卡阶段以外抽卡时，向我方公开抽到的卡，如果有魔法·陷阱卡加入到我方手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100591', '某海贼王的心血来潮', '这张卡发动的回合，我方场上原本攻击力1000以下的怪兽可以直接攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100592', '只有两个人的方舟', '以场上1只风属性怪兽为对象发动，那只怪兽攻击力上升1000，那只怪兽战斗破坏对方怪兽时，从卡组把1张「只有两个人的方舟」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100593', '邪古 分裂魔王', '召唤成功的第二个我方回合，将此卡解放，从卡组上面抽5张卡，其中怪兽卡全部特殊召唤，其余卡和手牌全部送入墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100594', '邪恶的神龙', '从卡组抽取5张卡，里面有神属性的怪兽卡场合，尽可能多的神属性怪兽卡无条件召唤上场。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100595', '神圣召唤', '限此卡在场，每当我方场上魔法师族怪兽从场上离开时，可以从卡组·手牌无条件特殊召唤1只比被破坏的怪兽攻击力高的魔法师族怪兽上场。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100596', '光明的神龙', '当我方场上有「奥西里斯之天空龙」存在时，给予对方1000点生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('DCOR0021', '超流星黑龙', '5星怪兽×2
INSERT INTO "texts" VALUES ('ZZ100598', '双龙聚合体', '8星怪兽x2
INSERT INTO "texts" VALUES ('ZZ100599', '龙纹骑士朱红', '10星光属性怪兽x3
INSERT INTO "texts" VALUES ('ZZ100600', '纹章兽耶和华', '4星光属性怪兽x3
INSERT INTO "texts" VALUES ('DCOR0045', '流星黑龙', '这张卡不能作超量召唤以外的特殊召唤。这张卡可以直接从手牌或卡组把3只8星怪兽叠放作超量召唤。以下效果1回合各能使用1次。●可以对对方作出我方超量素材数量的攻击。●对方把场上的卡的效果发动时，可以把那个效果无效并破坏。●对方怪兽攻击宣言时，可以把这张卡的1个超量素材去除，让对方1只怪兽的攻击无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('DCOR0042', '天神战击集约', '这张卡不能作超量召唤以外的特殊召唤。把我方手卡·场上所有怪兽卡在这张卡下面叠放作超量素材，这张卡从额外卡组特殊召唤。
INSERT INTO "texts" VALUES ('ZZ100603', '混沌战士-开辟的使者', '8星怪兽×2
INSERT INTO "texts" VALUES ('ZZ100604', '魔导月皇 娜芭特', '9星魔法师族怪兽X2
INSERT INTO "texts" VALUES ('ZZ100605', '电子龙 终结之月', '名字带有「电子」的10星怪兽X2
INSERT INTO "texts" VALUES ('ZZ100606', '幸运的丽酱', '2星怪兽×2
INSERT INTO "texts" VALUES ('ZZ100607', '奥西里斯之圣阶天使', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。此卡召唤成功后不受任何卡影响。此卡攻击对方怪兽不计算战斗伤害无视效果直接破坏那只怪兽，并增加那只怪兽攻击力数值的生命值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100608', '奥西里斯之炎帝', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。此卡的召唤不会被无效化。这张卡特殊召唤成功时，这张卡以外的双方的手牌·场上·墓地的卡全部从游戏中除外，不能对应这个效果的发动让魔法·陷阱·效果怪兽的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100609', '奥西里斯之剑与魔灵', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。此卡破坏后，可以当作永续魔法卡或陷阱卡使用，只要此卡存在魔法陷阱卡区域，对方不能发动魔法或陷阱卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100610', '奥西里斯之祭坛翼龙', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。只要此卡在场上存在，除名字带有「奥西里斯」的怪兽卡，其他怪兽全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100611', '奥西里斯之太阳武士', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。掷1枚硬币，根据情况发动以下效果●1枚正面：特殊召唤1只名字带有「奥西里斯」的怪兽。●2枚正面：我方场上怪兽卡数量无限制，得到对方场上所有怪兽的控制权。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100612', '奥西里斯之荒野义贼 红枭', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。限此卡在场，我方攻击阶段对方所有效果怪兽的效果无效化。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100613', '奥西里斯之业火凤凰', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。每当此卡攻击成功时，我方生命值不足6000点时，生命值变为6000点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100614', '奥西里斯之光魔杖宙斯', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。限此卡正面表示存在于场上，我方每次祭品召唤时，会增加祭品怪兽攻击力数值的生命值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100615', '奥西里斯之怒斧刽子手', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。1回合移除我方墓地1张卡片，从双方墓地选择1张怪兽卡，此卡叠加那只怪兽的效果。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100616', '奥西里斯之异筋肉人', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。1回合1次，选择对方场上1只攻击力在此卡以下的怪兽才能发动。选择的怪兽送入墓地，给予对方生命值那只怪兽攻击力数值的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100617', '奥西里斯之嗜血小丑', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。当此卡成为攻击对象时可以选择将此卡返回手牌，之后，跳过对方的下个回合的抽牌阶段。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100618', '奥西里斯之秃魔', '①：这张卡从场上离开时可以发动。以对方墓地2只和这张卡相同等级的怪兽为对象才能发动。那些怪兽在自己场上特殊召唤。
INSERT INTO "texts" VALUES ('ZZ100619', '奥西里斯之血池魔女', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。此卡因卡效果被送入墓地时，可以从卡组选择2张名字带有「奥西里斯」的卡加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100620', '奥西里斯之女孤魂', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。只要这张卡正面表示存在，1回合1次，可以通常召唤2次。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100621', '奥西里斯之未来女警', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。1回合1次，选择我方场上的1张卡不受对方魔法·陷阱卡的效果影响。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100622', '奥西里斯之邪恶贝斯', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。此卡被破坏送入墓地时，给予对方墓地此属性怪兽数量×1000点的生命伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100623', '奥西里斯之暮光驯兽师', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。此卡召唤成功后抽1张卡，如果是怪兽卡，此卡增加那只怪兽卡的攻击力数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100624', '奥西里斯之地狱女巫', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。选择双方墓地里1只怪兽卡特殊召唤到我方场上来，召唤成功时，我方从卡组抽1张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100625', '奥西里斯之同源劫', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。对方发动卡片效果时发动，舍弃1张相同属性的卡让对方发动效果的卡效果无效并破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100626', '奥西里斯之积极防御', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。1回合1次，可以跳过我方的战斗阶段，在我方下个回合的准备阶段将手牌补满7张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100627', '奥西里斯之生命代价', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。对方召唤·特殊召唤怪兽时，支付一半生命值，让那个召唤无效并破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100628', '红通通☆奥西里斯的天空龙', '12星怪兽×2
INSERT INTO "texts" VALUES ('ZZ100629', '装甲 古代兵器', '5星怪兽×3
INSERT INTO "texts" VALUES ('ZZ100630', '装甲 能源供给', '我方场上正面表示存在名字带有「装甲」卡存在时，每回合抽卡阶段可抽3张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100631', '装甲 新代文明', '我方场上所有名字带有「装甲」的卡的效果不会被无效，此场地魔法卡不会被对方破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100632', '装甲 自爆式', '破坏我方场上1只怪兽，对方受到怪兽的防守力2倍的伤害。此效果不能被无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100633', '装甲 回收站', '对方有怪兽存在时，对方回合我方可选择墓地1只以上的名字带有「装甲」的怪兽返回卡组，从卡组抽3张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100634', '天空龙 游戏の正义', '此卡必须献祭我方场上3只等级4以上的怪兽才能特殊召唤，此卡的召唤不能被无效化，此卡召唤成功时，双方不能发动魔法·陷阱·怪兽效果，此卡宣言攻击时，从手牌·卡组把1只怪兽送往墓地，我方墓地每存在1只等级4以上的怪兽，此卡攻击力上升500点并具有贯穿效果，此卡从场地上离开时，从游戏中除外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100635', '巨神兵 海马の灵魂', '此卡必须献祭我方场上3只等级4以上的怪兽才能特殊召唤，此卡的召唤不能被无效化，此卡召唤成功时，不能发动魔法·陷阱·怪兽效果，此卡的攻击·守备力变为我方手牌·场地上的怪兽数量这张卡不能通常召唤。
INSERT INTO "texts" VALUES ('ZZ100636', '翼神龙 马利克の恶念', '此卡必须献祭我方场上3只等级4以上的怪兽才能特殊召唤，此卡的召唤不能被无效化，此卡召唤成功时，不能发动魔法·陷阱·怪兽效果。对方所有魔法·陷阱卡的效果无效并破坏发动的卡。当此卡破坏对方怪兽时，给对方被破坏怪兽的攻击力加上1000点的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100637', '盗贼王', '只要此刻看存在于场上，1回合1次，观看并选择对方1张手牌加入到我方手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100640', '异次元胖丁', '光属性调整＋调整以外的怪兽1只以上
INSERT INTO "texts" VALUES ('ZZ100641', '神兽王 巴巴罗斯', '①：这张卡可以不用解放作通常召唤。
INSERT INTO "texts" VALUES ('ZZ100643', '超量的真红莲魔龙', '8星怪兽X2
INSERT INTO "texts" VALUES ('ZZ100644', '梵天使徒 混沌终结者', '4星怪兽×3
INSERT INTO "texts" VALUES ('ZZ100645', '超量的终焉使者', '5星怪兽×2
INSERT INTO "texts" VALUES ('ZZ100646', '核变异兽 叢林王', '←9 【灵摆】 9→　
INSERT INTO "texts" VALUES ('ZZ100647', '深渊海怪 鱼头师令', '←2 【灵摆】 10→　
INSERT INTO "texts" VALUES ('ZZ100648', '地狱之神炎皇 乌利亚', '此卡只能在「降临 地狱幻兽」的效果下特殊召唤。限此卡在场，双方墓地每有1张陷阱卡，此卡攻击力上升1000，每降低500点攻击力可以抵消对方1次魔法陷阱的发动无效果，并破坏那张卡。当对方发动效果怪兽无效时，移除我方墓地1张陷阱卡可以使那个怪兽无效，并得到那只怪兽的控制权。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100649', '地狱之幻魔皇 拉比艾尔', '此卡只能在「降临 地狱幻兽」的效果下特殊召唤。限此卡在场，每次对方召唤怪兽，这张卡的攻击力上升对方召唤的怪兽的原本攻击力的数值，把自己墓地的「幻魔皇 拉比艾尔」移除到游戏外，此卡可以直接攻击对方玩家，当我方场上存在此卡的场合，对方不能选择其他怪兽作为攻击对象。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100650', '地狱之降雷皇 哈蒙', '此卡只能在「降临 地狱幻兽」的效果下特殊召唤，此卡不能直接攻击对方玩家，此卡攻击对方怪兽时，直接破坏那只怪兽，并给予对方生命值1000点的伤害，当此卡攻击力高过战斗怪兽时，给予对方超过的攻击力数值的伤害。此卡的攻击力提升破坏怪兽的攻击力或守备力的数值，当此卡被破坏时，移除我方墓地中1张魔法卡，使那个破坏效果无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100651', '光之创造神-赫尔阿克帝', '「奥西里斯之天空龙」+「欧贝利斯克之巨神兵」+「太阳神之翼神龙」
INSERT INTO "texts" VALUES ('ZZ100652', '光之创造神 赫尔阿克帝', '「奥西里斯之天空龙」+「欧贝利斯克之巨神兵」+「太阳神之翼神龙」
INSERT INTO "texts" VALUES ('ZZ100653', '光之创造神 赫尔阿克帝 ', '用「法老王的觉醒」的效果才能降临，添加「三幻神之光」、「王之名 亚图姆」、「幻神一体」到手牌，此卡破坏暗属性怪兽时，给予对方玩家1500点生命值伤害。每回合可破坏场上1张卡片，把此卡做祭品，可以将墓地的三幻神特殊召唤到场上，此卡不受魔法·陷阱·怪兽的效果影响。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100654', '光之创造神-赫尔阿克帝 ', '此卡只能通过「三幻神之光」的效果特殊召唤，此卡成功召唤时，对方场上所有魔法·陷阱卡全部破坏（包括不能破坏的）。此卡召唤时，自己生命值变为0.此卡被破坏时，此卡的控制者败北。此卡和暗属性怪兽战斗时，不进行伤害计算，直接破坏该怪兽，此卡不受魔法·陷阱·效果怪兽的效果影响。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100655', '光之创造神-赫尔阿克帝  ', '此卡只能通过「三幻神之光」的效果特殊召唤，此卡成功召唤时，对方场上所有魔法·陷阱卡全部破坏（包括不能破坏的）。此卡召唤时，自己生命值变为0.此卡被破坏时，此卡的控制者败北。此卡和暗属性怪兽战斗时，不进行伤害计算，直接破坏该怪兽，此卡不受魔法·陷阱·效果怪兽的效果影响。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100656', '光之创造神-赫尔阿克帝   ', '在神的名下，将三幻神结合变成「光之创造神-赫尔阿克帝」，它能让黑暗永远消失。这张卡不能通常召唤，把自己场上的名字带有「奥西里斯之天空龙」、「欧贝利斯克之巨神兵」、「太阳神之翼神龙」的怪兽各1只解放才能特殊召唤。这张卡的特殊召唤不会被无效化，把这张卡特殊召唤的玩家决斗胜利。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100657', '游戏 神的天空龙', '把手牌两张龙族怪兽做祭品才能特殊召唤，除此卡以外的魔法·陷阱·效果怪兽的效果无效，此卡召唤成功时，对方场上攻击力6000以下的怪兽破坏，此卡被破坏时，由对方场上1只怪兽代替破坏，若对方没有怪兽存在场上，直接扣除对方生命值，此回合结束时，从手牌特殊召唤1只「奥西里斯之天空龙」。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100658', '究极的幻神', '一回合一次，选择一项效果发动：●除外对方手牌，每除外1张卡片，给予对方500点伤害；●支付1000点生命值，对方的墓地将封印3回合，卡片全部除外；●支付1000点生命值，对方的手牌封印3回合，且卡片全部除外。此卡拥有三幻神的效果，此卡不受魔法·陷阱和怪兽的效果影响，此卡被破坏时，此卡的控制者失败游戏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100659', '三幻神之光', '支付1000点生命值，将自己墓地·手牌·卡组中的「奥西里斯之天空龙」、「欧贝利斯克之巨神兵」、「太阳神之翼神龙」从游戏除外，从自己的手牌·墓地或卡组特殊召唤一只「光之创造神 赫尔阿克帝」到场上并攻击表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100660', '幻神一体', '使「究极的幻神」降临的必要。将自己场上·手牌·卡组中的「奥西里斯之天空龙」、「欧贝利斯克之巨神兵」、「太阳神之翼神龙」作为祭品送入墓地，从自己的手牌·墓地或卡组特殊召唤一只「究极的幻神」到场上。此卡的发动不能被无效化。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100661', '王之名 亚图姆', '将自己场上·手牌·卡组的三幻神「奥西里斯之天空龙」、「欧贝利斯克之巨神兵」、「太阳神之翼神龙」送入墓地，从额外卡组特殊召唤1只融合怪兽「光之创造神 赫尔阿克帝」，此卡的发动不会被无效和破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100662', '法老王的觉醒', '将自己场上·手牌·卡组中的三幻神「奥西里斯之天空龙」、「欧贝利斯克之巨神兵」、「太阳神之翼神龙」做祭品送入墓地，从墓地手牌·卡组特殊召唤仪式怪兽「光之创造神 赫尔阿克帝」、「光之创造神石板」各一只到场上。此卡的发动不会被无效和破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100663', '神之三神连体的巨神龙', '咒文：天空雷鸣的巨兽，裂天空与大地所有神的力量变换的灵魂，其力量可无限！
INSERT INTO "texts" VALUES ('ZZ100664', '神之欧贝利斯克的巨神龙', '咒文：其到来之时，灼热之疾风农吹荒大地，生者比成尸骸！此卡需将欧贝利斯克之巨神兵」与「太阳神之翼神龙」从卡组或手牌送入墓地从而被特殊召唤。召唤此卡时，这张卡以外的魔法、陷阱、效果怪兽的效果无效。此卡召唤成功时，我方需支付1000点生命值，此卡的攻击力与守备力上升我方手牌、墓地数量×2000点的数值。这张卡特殊召唤的场合结束阶段攻击力与守备力恢复至4000点。此卡被破坏送入墓地时，可从墓地特殊召唤「欧贝利斯克之巨神兵」与「太阳神之翼神龙」上场。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100665', '欧贝利斯克之巨神兵', '在他降临大地时，烧灼的疾风将狂吹大地，所有生物都变成了尸骸。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100666', '太阳神之翼神龙', '歌咏的精灵。拥有伟大的力量掌管着万物的生命、灵魂甚至骨骸。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100667', '奥西里斯之天空龙', '混沌之天际雷声隆隆，连串的锁中系着一张古代的魔法引导书，夸示着无限的神力。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100668', '光之创造神石板', '只要此卡出现在场上，就可同时召唤墓地或手牌中的3张神之卡（天空龙、巨神龙、翼神龙），并得到」「光之创造神」的无限力量，破坏」「冥界大邪神石板」其效果也同时消失。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100669', '神之奇迹', '此卡的发动不能被破坏或无效化，生命值归1后将卡组·手牌或墓地三张三幻神兽族怪兽无视召唤条件以攻击表示特殊召唤到场上来，回合结束时因此效果召唤的怪兽移除到游戏外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100670', '神之怒', '将由「神之领域」降临，此卡召唤不会被无效化，此卡召唤成功后对方无法发动和放置卡片，并将对方场上所有卡片全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100671', '太阳神的地狱翼神龙', '●我方墓地存在神属性怪兽的场合，这张卡可以从手卡·卡组·墓地特殊召唤，这张卡的召唤不会被无效化。
INSERT INTO "texts" VALUES ('ZZ100672', '地狱之神不死鸟', '当「太阳神之翼神龙」与「死者苏生」同时存在我方墓地时即可特殊召唤此卡，此卡的特殊召唤不会被无效化，在特殊召唤回合双方玩家不能做出攻击宣言，此卡的攻击力，守备力上升双方玩家墓地中卡片数量×1000点的数值，此卡可以直接攻击对方。1回合1次，可以直接给予对方此卡攻击数值的伤害，此卡在特殊召唤回合的结束阶段回到墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100673', '太阳神龙的加护', '场上有幻兽族怪兽时，这张卡不用祭品直接召唤，这张卡的召唤不会无效化，这张卡召唤成功时，对方以这张卡为对象的魔法·陷阱·效果怪兽的效果无效，这张卡的攻击力与守备力上升双方生命值数值的总和。1回合次。支付500点生命值，指定对方场上1只怪兽移除到游戏外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100674', '三幻神连体', '神的降临！此卡只能把手牌或卡组的「奥西里斯之天空龙」、「欧贝利斯克之巨神兵」、「太阳神之翼神龙」和名字带有「游戏」的卡送入墓地的场合才能召唤上场，除此卡以外的魔法·陷阱·效果怪兽的效果无效，此卡存在场上时，我方战斗获得胜利。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100675', '邪神降临', '当我方场上·手牌·卡组·墓地存在三幻神「奥西里斯之天空龙」、「欧贝利斯克之巨神兵」、「太阳神之翼神龙」时，支付生命值1000点，此卡可以发动，将三幻神从游戏中除外，从手牌·卡组·墓地特殊召唤「邪神 奥西里斯之天空龙」、「邪神 欧贝利斯克之巨神兵」、「邪神 太阳神之翼神龙」到场上。此卡的发动不能被无效化。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100676', '邪神·奥西里斯之天空龙', '此卡只能由「邪神降临」才能从手牌·卡组·墓地特殊召唤上场，此卡的攻击力与守备力是由自己手牌×1000，并且攻击力与守备力再加1000来计算，此卡不受任何卡片影响。此卡在场上时，对方召唤·反转召唤·特殊召唤时，若以攻击表示看攻击力，若以守备表示看守备力，在2000点以下遭破坏，在2000点以上时，攻击力·守备力各扣2000点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100677', '邪神·欧贝利斯克之巨神兵', '此卡只能由「邪神降临」才能从手牌·卡组·墓地特殊召唤上场，此卡不受任何卡片影响，攻击力与守备力数值是除外的三幻神攻击力与守备力的总和，并且再加1000点决定。把2只怪兽作祭品，发动攻击时：●对方场上所有怪兽全部破坏，对方生命值受到4000点伤害。●本回合攻击力MAX（无限大）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100678', '邪神·太阳神之翼神龙', '此卡只能由「邪神降临」才能从手牌·卡组·墓地特殊召唤上场。此卡不受任何卡片影响，攻击力与守备力数值是除外的三幻神攻击力与守备力的总和，并且再加1000决定。可以选择1个效果发动：●支付1000点生命值，破坏并除外场上1只怪兽，且此卡不受对方战斗伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100679', '邪神 神化身亚瓦塔', '从邪恶、黑暗中疯狂诞生出来的邪神！这张卡不能特殊召唤。自己场上存在的3只怪兽作为祭品的场合通常召唤。此卡召唤成功的场合，用对方回合计算的3回合内对方不能发动任何卡，此卡可以直接攻击对方玩家至生命值变为0，这张卡的控制者获得决斗胜利。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100680', '巨神兵衍生物', '由「沉默的圣石巨神兵 LVMAX」的效果特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100681', '沉默的圣石巨神兵 LV0', '每当双方抽卡时，此卡攻击力·守备力提升500点，等级上升1级，此卡受到的战斗伤害为0。当此卡从场上离开时，可以从手牌·卡组·墓地·除外区域特殊召唤「沉默的圣石巨神兵 LVMAX」上场。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100682', '沉默的地狱判官天空龙 LV0', '每当双方抽卡时，此卡攻击力·守备力提升500点，等级上升1级，此卡受到的战斗伤害为0，当此卡从场上离开时，可以从手牌·卡组·墓地·除外区域特殊召唤「沉默的地狱判官天空龙 LVMAX」上场。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100683', '沉默的太阳神翼神龙 LV0', '每当双方抽卡时，此卡攻击力·守备力提升500点，等级上升1级，此卡受到的战斗伤害为0。当此卡从场上离开时，可以从手牌·卡组·墓地·除外区域特殊召唤「沉默的太阳神翼神龙 LVMAX」上场。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100684', '沉默的圣石巨神兵 LVMAX', '通过「沉默的圣石巨神兵 LV0」的效果或支付一半的生命值才能特殊召唤。此卡召唤不能被无效。1回合1次，●将对方发动的卡效果选择对方或者我方承受。●对方场上的怪兽被破坏送入墓地时，每有1只给予对方生命值4000点伤害。●破坏对方场上所有卡片。●每回合可召唤2只「巨神兵衍生物」（幻神兽族/神/10星/攻/守4000）到场上。共同占用1个怪兽区域。●此卡不会受对方的魔法·陷阱·效果怪兽的效果影响。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100685', '沉默的地狱判官天空龙 LVMAX', '通过「沉默的地狱判官天空龙 LV0」的效果或支付一半基本分才能特殊召唤。此卡召唤不能被无效，这个召唤也可以在对方的回合进行。1回合1次，●确认自己场上魔法·陷阱区域卡片张数，这张卡在同1从战斗阶段可以作出最多有那之中的卡片数量的攻击。●要把场上的卡破坏的效果发动时，可以把那个效果无效并破坏。●我方生命值回复对方手牌数量×2000的数值。●此卡不会被破坏，不受对方任何卡的效果影响。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100686', '沉默的太阳神翼神龙 LVMAX', '通过「沉默的太阳神翼神龙 LV0」的效果或支付一半基本分才能特殊召唤。此卡召唤不能被无效，这个召唤也可以在对方的回合进行。1回合1次，●可以将对方场上以正面表示存在的怪兽的效果无效，将所有效果当作此卡的效果使用。●可以把场上以正面表示存在的这张卡送入墓地，结束阶段可以从墓地特殊召唤到自己的场上，因这个效果特殊召唤成功时，给予对方生命值4000点伤害。●将对方一半卡组送入墓地。●此卡不会被破坏，不受对方任何卡效果的影响。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100687', '沉默的王 LVMAX', '此卡不能通常召唤，通过「沉默的王 LV0」的效果或者让自己的生命值降为1才能特殊召唤，此卡召唤不能被无效，只要这张卡在场上正面表示存在，对方发动的魔法·陷阱·怪兽的所有效果无效。当我方发动魔法·陷阱卡·怪兽的效果时，每张卡给予对方2000的生命伤害。我方回合结束时，从任何地方特殊召唤「沉默的圣石巨神兵 LVMAX」、「沉默的地狱判官天空龙 LVMAX」、「沉默的太阳神翼神龙 LVMAX」上场。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100688', '沉默的黑暗大法师 LVMAX', '12星怪兽×2
INSERT INTO "texts" VALUES ('ZZ100689', '黑魔導女孩大聚会', '魔法师族7星怪兽×2
INSERT INTO "texts" VALUES ('ZZ100690', '黑魔導女孩 蓝将', '双方墓地存在的「黑魔术师」、「黑混沌之魔术师」每有1只，这张卡的攻击力上升300。1回合1次，将此卡攻击力下降0，可以将我方卡组·手牌·墓地1张名字带有「黑魔導女孩」的卡片加入手牌或特殊召唤到我方场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100691', '黑魔導女孩 白将', '当我方场上存在名字带有「黑魔导女孩」的怪兽时，此卡1回合只有1次不会被战斗破坏。此卡召唤成功后，可以从卡组中选1只等级5以上的魔法师族怪兽和1张名字带有「黑魔导」的魔法卡加入手牌，此卡的攻击力为双方墓地中魔法师族怪兽数量×300的数值，当此卡从场上离开时可以作为装备卡给我方场上1只魔法师族怪兽上，装备怪兽的怪兽等级上升1，攻击力上升500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100692', '黑魔導女孩 黑将', '当我方场上存在名字带有「黑魔导女孩」的怪兽时，此卡1回合只有1次不会被战斗破坏。此卡召唤成功后，作为永久魔法卡放在魔法陷阱区，当对方发动卡片效果时可以从我方卡组上面把1张卡送去墓地，让那个发动无效并破坏。如果送入墓地的那张卡为魔法师族怪兽时，则可以将对方场上所有魔法·陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100693', '黑魔導女孩 红将', '当我方场上存在名字带有「黑魔导女孩」的怪兽时，此卡1回合只有1次不会被战斗破坏。此卡召唤成功后变为守备表示，此卡的守备力为双方墓地魔法师族怪兽数量×500点，当我方场上存在其他魔法师族怪兽时，对方攻击宣言必须攻击，攻击目标必须为此卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100694', '黑魔導女孩 绿将', '当我方场上存在名字带有「黑魔导女孩」的怪兽时，此卡1回合只有1次不会被战斗破坏。1回合1次，把我方场上正面表示存在的1只魔法师族怪兽从游戏中除外并给予对方对方生命值1000点伤害，因此效果除外的怪兽在下次的我方的回合的准备阶段时特殊召唤到我方场上，发动此效果的回合，我方不能发动攻击宣言。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100695', '黑魔導女孩 紫将', '当我方场上存在名字带有「黑魔导女孩」的怪兽时，此卡1回合只有1次不会被战斗破坏。把我方墓地存在的1只魔法师族怪兽从游戏中除外，给予对方生命值除外的怪兽的原本攻击力数值的伤害。这个效果1回合只能使用1次。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100696', '黑魔導女孩 橙将', '当我方场上存在名字带有「黑魔导女孩」的怪兽时，此卡1回合只有1次不会被战斗破坏。将手牌1只魔法师族送入墓地此卡增加那只怪兽的效果（效果可叠加）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100697', '黑魔導女孩 黄将', '当我方场上存在名字带有「黑魔导女孩」的怪兽时，此卡1回合只有1次不会被战斗破坏。我方场上没有卡存在的场合这张卡召唤成功时，从卡组抽2张卡，这个效果抽到的卡给双方确认，有魔法师族怪兽的场合可以选择无视条件特殊召唤到自己场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100698', '黑魔導女孩 粉将', '当我方场上存在名字带有「黑魔导女孩」的怪兽时，此卡1回合只有1次不会被战斗破坏。可以从手牌1只魔法师族怪兽送去墓地，将此卡从手牌或墓地特殊召唤上场。此卡的攻·守·效果·等级·属性和那只怪兽相同。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100699', '见习魔术师·玛娜', '支付500点生命值，从卡组特殊召唤1个「黑魔導少女」到场上，可把此卡装备到「黑魔導少女」上，1回合1次，「黑魔導少女」的攻击力·守备力上升1000点。「黑魔導少女」被破坏时，此卡可代替被破坏，并将魔法卡「混沌黑魔术的第二仪式」加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100700', '黑魔導女孩 玛尼', '此卡可用作装备卡使用，怪兽装备后，攻击力上升1500点，将此装备卡去除，可破坏对方场上所有怪兽。强制执行，不能无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100701', '黑魔導女孩 玛古', '此卡可用作装备卡使用，怪兽装备后，攻击力上升1500点。舍弃1张手牌，可从卡组、墓地将1张名字带有「黑魔導女孩」的卡片加入手牌。将此装备卡去除，可破坏对方场上所有陷阱卡。强制执行，不能无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100702', '天空龙黑魔導女孩', '●把我方场上3只怪兽送去墓地，从手卡特殊召唤。
INSERT INTO "texts" VALUES ('ZZ100703', '黑魔導女孩 红辣妹', '反转：对方场上所有魔法陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100704', '黑魔導女孩 小辣妹', '反转：这个回合结束前得到对方场上所有怪兽的控制权。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100705', '地狱之黑魔導女孩', '●这张卡不能特殊召唤。
INSERT INTO "texts" VALUES ('ZZ100706', '决斗盔甲·黑魔导装', '协调+协调以外的怪兽2只以上
INSERT INTO "texts" VALUES ('ZZ100707', '决斗盔甲·混沌黑魔导装', '同调怪兽的协调1只+「决斗盔甲·黑魔导装」
INSERT INTO "texts" VALUES ('ZZ100708', '魔导同调士', '协调+协调以外的怪兽1只
INSERT INTO "texts" VALUES ('ZZ100709', '魔导协调师', '这张卡召唤成功时，可以将卡组上方手牌最多2张卡片送入墓地发动。因这个效果送入墓地的卡每有1张，在自己场上特殊召唤1只「魔导协调衍生物」」(魔法师族·暗·4星·攻1000守1000)。当此卡作为同调召唤素材送入墓地时，从卡组特殊召唤1只2星的协调怪兽到场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100710', '魔导协调衍生物', '由「魔导协调师」的效果特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100711', '魔法引力', '1回合1次，可以从下面的效果选择1个发动：●可以从我方卡组把1只魔法师族的怪兽加入手牌。●可以把最多有自己场上存在的魔法师族的怪兽的数量的场上的魔法或者陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100712', '协力魔术', '丢弃1张手牌，破坏对方场上全部卡片，并把墓地1只魔法师族怪兽特殊召唤。此卡的发动不会无效化。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100713', '力量倍返', '使对方1只怪兽的攻击无效化，并将其攻击力直接给与对方2倍伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100714', '混沌黑魔术的第二仪式', '把我方手卡·场上·卡组把等级合计到8的怪兽送去墓地，从手卡·卡组·墓地把1只「混沌黑魔導少女」仪式召唤，这张卡的发动不会被无效化。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100715', '混沌黑魔導少女', '此卡由「混沌黑魔术的第二仪式」降临。此卡召唤成功时，发动以下效果：●对方场上全部魔法师族怪兽攻击力上升1500点。●从墓地选择2张卡加入手牌。此卡送入墓地时，特殊召唤「见习魔术师·玛娜」、「混沌之黑魔术师」各1个上场。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100716', '魔导的师徒倍返', '●作为这张卡的发动时的效果处理，可以从手卡·卡组把「黑魔术女孩」和名字带有「黑魔术」的怪兽尽可能多的特殊召唤。
INSERT INTO "texts" VALUES ('ZZ100717', '魔导联击', '从我方手卡·场上把1只怪兽送去墓地才能发动，直到回合结束前我方场上的怪兽可以直接攻击玩家。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100718', '黑魔導女孩 小白', '装备在1只魔法师怪兽，那只怪兽攻击力增加500点，直接攻击，对方生命值受到伤害，攻击不会被无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100719', '黑魔導女孩 樱子', '手牌或场上存在名字带有「黑魔導女孩 小白」，此卡可特殊召唤上场，攻击时，对方生命值变为3000点，直接攻击，对方生命值受到伤害，此卡不受对方的卡片影响。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100720', '黑魔導女孩 樱子 ', '手牌或场上存在名字带有「黑魔導女孩 小白」，此卡可特殊召唤上场，攻击时，对方生命值变为3000点，直接攻击，对方生命值受到伤害，此卡不受对方的卡片影响。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100721', '超魔导剑士-黑暗帕拉丁', '「黑魔术师」＋「黑魔导女孩」
INSERT INTO "texts" VALUES ('ZZ100722', '魔导战士 破坏女剑士', '此卡召唤成功时，在此卡上放置1个「魔力指示物」，最多只能在此卡上放置3个，此卡每存在1个「魔力指示物」，场地上1张冠有「魔导剑士」之名的怪兽攻击力上升300点，移除1个「魔力指示物」，破坏场上合计等级7以下的怪兽卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100723', '高等魔法师 黑魔导', '
INSERT INTO "texts" VALUES ('ZZ100724', '仪式的黑魔术师', '无需仪式魔法卡，手牌或场上有「黑魔术师」的怪兽时，把那只怪兽送去墓地，此卡可从手牌特殊召唤。场上有魔法师族怪兽存在的场合，此卡不会选择作为攻击对象。这张卡在自己墓地时，可以把自己墓地的2张魔法师族怪兽从墓地除外，从墓地特殊召唤这张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100725', '新宇圣龙魔导骑士', '「元素英雄 新宇侠」+「黑魔术师」+「星尘龙」
INSERT INTO "texts" VALUES ('ZZ100726', '黑魔導 LV3', '我方场上没有魔法师族怪兽存在时，此卡可以从手牌特殊召唤上场，此卡的攻击力为双方场上魔法师族怪兽数量×500的数值，当对方发动以我方场上卡片为对象的魔法·陷阱卡时，可以选择将此卡送入墓地让对方那张卡片的效果发动无效并破坏，同时从我方手牌·卡组特殊召唤1只「黑魔導 LV6」。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100727', '黑魔導 LV6', '将我方墓地6张魔法师族怪兽移除到游戏外，此卡可以从手牌以守备表示特殊召唤上场，此卡的守备力为移除的魔法师族怪兽守备力的总和。当我方场上存在此卡以外的魔法师族怪兽时，对方只能选择作为攻击对象，只要此卡守备表示存在场上，对方不能跳过战斗阶段，对方场上有攻击表示怪兽必须攻击，当此卡在场上离开时，将我方被移除到游戏外的卡片放回卡组并洗牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100728', '黑魔導 LV9', '此卡不能通常召唤，将我方场上存在「黑魔導 LV3」和」「黑魔導 LV6」移除到游戏外，此卡可以从手牌·卡组·墓地召唤上场，此卡的召唤不能被破坏和无效化，此卡召唤成功的场合，破坏对方场上所有卡片，被破坏的卡每有1张可以将我方游戏外1张卡返回卡组并回复我方500点生命值。1回合1次，跳我方攻击阶段，对方这个回合无法召唤怪兽，每将我方场上1张卡送入墓地可以选择对方场上1张卡或手牌送入墓地，当此卡从场上离开时，将对方场上手牌所有卡片移除到游戏外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100729', '纳斯卡巨画-地缚神圣域', '此卡不会离场，不受卡效果影响。我方场上地缚神数量不受限制。1回合1次无视召唤条件召唤1只名字带有「地缚神」的怪兽。我方名字带有「地缚神」的怪兽攻守各上升1000点。以此效果召唤出的名字带有「地缚神」的怪兽每回合有两次不会被破坏离场，并不受怪兽效果影响。名字带有「地缚神」的怪兽在场，我方生命值不会减少。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100730', '魔导神官·马哈德', '此卡不会被破坏，魔法·陷阱·怪兽效果对其无效。已我方场上没有怪兽时，此卡可以特殊召唤。此卡召唤·反转召唤·特殊召唤时，从卡组添加「幻想的魔术师」、「见习魔术师 玛娜」各1张到手牌。并从卡组·手牌·墓地特殊召唤1个「黑魔导」到场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100731', '幻想的魔术师', '自己场上正面表示存在「魔导神官·马哈德」的场合，支付500点生命值可从手牌特殊召唤此卡，此卡成功召唤时，破坏场上所有卡。当此卡在场上正面表示存在的场合，不会被破坏，魔法·陷阱·怪兽效果对其无效。对方不能攻击「魔导神官·马哈德」。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100732', '友情的誓言', '丢弃1张手牌，把自己卡组·墓地或除外的「魔导神官·马哈德」、「幻想的魔术师」、「黑魔术师马哈德」各1张添加到手上，此卡的发动不会被无效化。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100733', '宿命的白龙女', '此卡不会被破坏。当此卡在场上时，每回合丢弃1张手牌，从对方手牌·卡组·墓地特殊召唤1只「青眼白龙」上场，并添加「白龙女的守候」、「恶魔的锁链」各1张到手牌。当「青眼白龙」存在于场上时，此卡不会成为被攻击的对象。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100734', '地狱之黑魔术师', '此卡不能特殊召唤，只能用2张祭品召唤上场。此卡召唤成功的场合，对方手牌所有卡全部移除到游戏外，此卡成功攻击并给对方玩家战斗伤害的场合，我方下回合必须跳过攻击阶段，并除外2张卡。当此卡被破坏送入墓地时，可以将我方卡组·手牌·墓地·游戏外的魔法师族怪兽尽可能多的无视条件特殊召唤到我方场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100735', '邪神·迪尔邦多', '需「盗贼王的呼声」或「蛇尾恶魔·迪亚邦多」做祭品才能召唤，1回合1次，此卡能获得对方1只怪兽的效果。当此卡破坏对方玩家怪兽时，对方丢弃卡组上方5张卡片，此卡不受魔法·陷阱·怪兽效果影响，也不会被战斗破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100736', '暗之破坏神—赫尔阿克帝', '我方场上存在「地狱之天空龙」「地狱之巨神兵」「地狱之翼神龙」的场合，这张卡可以从手卡·卡组·墓地·除外区域特殊召唤，这张卡的特殊召唤不被无效化。
INSERT INTO "texts" VALUES ('ZZ100737', '冥界的复仇', '将我方生命值归为1点，将对方场上手牌墓地所有卡片移除到游戏外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100738', '魔法使的光辉', '这张卡不能通常召唤。
INSERT INTO "texts" VALUES ('ZZ100739', '神之领域', '将墓地·手牌·卡组或场上「奥西里斯之天空龙」、「欧贝利斯克之巨神兵」、「太阳神之翼神龙」各一体移除到游戏外，三回合后从墓地·手牌·卡组特殊召唤「神之怒」一体。此卡的发动和效果不能被无效化。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100740', '黑魔术师大师', '支付500点生命值，将此卡从手牌特殊召唤，此卡攻击力与守备力上升我方手牌·卡组·墓地所有名字带有「黑魔导」的怪兽的攻击力之和。此卡不会受魔法·陷阱·效果怪兽的效果影响。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100741', 'DB-基纽特种部队-吉斯', '1回合1次，此卡不会被选为攻击对象。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100742', 'DB-孙悟空-超级赛亚人1', '当此卡因卡效果从手牌送入墓地时，得到对方场上1张怪兽卡的控制权。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100743', 'DB-孙悟空-超重拳', '此卡只要攻击表示就必须攻击。当此卡攻击时，可以对对方场上所有怪兽各攻击1次。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100744', 'DB-孙悟空-初出茅庐', '当此卡被战斗破坏送入墓地时，可以从墓地·手牌·卡组特殊召唤1张名字带有「DB」的卡片，此卡可以作为2张祭品使用。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100745', 'DB-孙悟空-夺取超圣水', '降低此卡一半攻击力，可以直接攻击对方生命值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100746', 'DB-孙悟空-龟派气功', '每当此卡战斗破坏对方怪兽时，可以选择对方魔法陷阱区1张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100747', 'DB-孙悟空-苦思对策', '此卡直接攻击对方生命值时，给予对方额外追加此卡攻击力数值的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100748', 'DB-孙悟空-勇往直前', '此卡召唤成功后的第3个回合送入墓地，限此卡在场，我方每受到伤害时，由对方承受那个伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100749', 'DB-孙悟空-茁壮成长', '此卡攻击时，对方目标怪兽攻击力低于此卡攻击力时，不进行伤害计算，那只怪兽效果无效，直接破坏那张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100750', 'DB-天津饭-恶念初生', '每当此卡给予对方战斗伤害时，我方从卡组抽1张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100751', 'DB-乌龙-魔法变身', '当我方场上有怪兽卡被战斗破坏送入墓地时，可以将手牌中的此卡送入墓地，让那次战斗破坏无效，那只怪兽重新回到场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100752', 'DB-小林-无忧无虑', '将场上这张卡送入墓地，可以从我方卡组·墓地选择1张名字带有「DB」的卡加入手牌。这个效果1场决斗只能使用1次。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100753', '暗之布道偶', '反转：选择我方墓地的2张卡加入自己手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100754', '奥利哈钢 蓝蛇男', '「奥利哈钢 蓝光蛇」＋「奥利哈钢 蓝光蛇」
INSERT INTO "texts" VALUES ('ZZ100755', '奥西里斯的精灵', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。从卡组抽1张卡，给对方确认，确认的卡是名字带有 「奥西里斯」的卡的场合，将这张卡加入手牌，并选择对方场上的1张卡送入墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100756', '奥西里斯的族人 格里', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。这张卡召唤·特殊召唤·反转召唤成功时，可以选择我方墓地1只名字带有「奥西里斯」的怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100757', '奥西里斯之蝙蝠剑士', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。1回合1次，把1张手牌从游戏中除外从以下效果选择1个发动。●得到对方场上1只怪兽的控制权。●选择对方墓地1只怪兽在我方场上特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100758', '奥西里斯之穿梭器', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。1回合1次，计算对方场上名字带有「殉道者」、「奥利哈钢」、「六芒」的卡片数量，我方从卡组抽取那个数量的卡片。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100759', '奥西里斯之极致伤害', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。1回合1次，翻开对方卡组最上方5张卡，并给予对方那些卡中名字带有「殉道者」、「奥利哈钢」、「六芒」的所有怪兽的总攻击力数值的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100760', '奥西里斯之寄生面具', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。此卡召唤·反转召唤时，可以直接高等召唤1次。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100761', '奥西里斯之绝对领域', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。只要对方场上有名字带有「奥利哈钢」和「六芒」的卡片，对方就不能发动攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100762', '奥西里斯之绝对守护', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。将我方场上1张盖伏的卡送入墓地，跳过对方的战斗阶段。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100763', '奥西里斯之连锁地狱犬者', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。此卡召唤成功后破坏对方场上所有魔法·陷阱卡。只要此卡正面表示存在场上，对方不能发动魔法·陷阱卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100764', '奥西里斯之魔人 娜塔莎', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。此卡不受对方魔法·陷阱卡的效果影响，降低此卡300点攻击力，可以破坏对方场上的1张魔法·陷阱卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100765', '奥西里斯之魔兽法师', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。当我方抽卡阶段时，抽出的卡为怪兽卡可以无视条件特殊召唤到场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100766', '奥西里斯之霓虹幻彩', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。支付一半的生命值，无条件特殊召唤手牌的1只怪兽，那只怪兽的攻击力为对方墓地中名字带有「奥利哈钢」和「六芒」的怪兽的攻击力总和。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100767', '奥西里斯之森林战士', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。1回合1次，宣言怪兽的种族或属性才能发动。查看对方卡组，将和宣言的种族或属性相同的怪兽移除到游戏外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100768', '奥西里斯之属性掌握者', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。此卡在场上存在时，对方不能召唤此卡属性以外的怪兽卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100769', '奥西里斯之炎狱龙', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。当我方墓地存在10张以上名字带有「奥西里斯」的卡时，此卡可以从卡组·手牌·墓地·游戏外无条件特殊召唤上场，此卡的攻击力为我方墓地名字带有「奥西里斯」的卡数量×500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100770', '奥西里斯之一换一', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。对方的魔法·陷阱卡发动时，舍弃我方1张手牌那张卡的发动无效并破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100771', '不死之黑魔导少女', '双方墓地存在的不死族怪兽每有1只，这张卡的攻击力永久上升300点，双方墓地每增加1只不死族怪兽这张卡的攻击力永久上升200点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100772', '不死之黑魔术师', '当此卡从我方场上离开送入墓地时，可以从墓地特殊召唤回我方场上。这个效果1场决斗只能使用1次。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100773', '不下雪的星球', '把墓地1只反转效果怪兽加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100774', '传说骑士-海聶默斯 城之内仪式', '此卡存在手牌时，可进行仪式召唤。成功召唤的此卡，可指定对方场上1只怪兽装备在此卡身上。装备后，此卡的攻击力上升那只怪兽的攻击力数值，获得那只怪兽的效果。此卡存在场上时，对方不能把魔法、陷阱卡发动。回合结束时，丢弃1张魔法卡，可跳过对方1回合。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100775', '垂钓苏生', '选择我方墓地1只名字带有「蛙」的怪兽在我方场上特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100777', '地狱战场', '自己墓地存在的怪兽每有1只，自己场上正面表示存在的怪兽攻击力每回合上升100点，这张卡在场上的时候，不能发动其他场地魔法卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100778', '电子反应', '特殊召唤3只「电子龙」，这3只怪兽不能做融合素材。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100779', '冻结的梦', '在场上把1只「冻结的梦衍生物」（机械族·水·4星·攻1900/守1600）特殊召唤。这张卡发动的回合，自己不能把怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100780', '冻结的梦衍生物', '由「冻结的梦」的效果特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100781', '毒黄蛇', '这张卡不能特殊召唤，这张卡给予对方玩家战斗伤害时，从卡组抽5张卡，选择4星以下的特殊召唤到场上，其余的舍弃到墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100782', '恶魔神王巴隆迪亚兹', '10星怪兽×3
INSERT INTO "texts" VALUES ('ZZ100784', '黑暗兽的红火焰', '此卡召唤成功时，对方场上存在的怪兽全部破坏。自己墓地存在的暗属性怪兽有5种类的场合，此卡的攻击力上升2000点。此卡在同1个战斗阶段中，可作2次攻击。对方有魔法、陷阱卡发动时，给予对方生命值1000伤害，召唤此卡的回合结束时，除外墓地的1只7星以上暗属性怪兽，不除外此卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100785', '幻魔之卡通援助', '自己场上有「卡通神炎皇」、「卡通降雷皇」、「卡通幻魔皇」其中至少1只正面表示存在时才能发动，可从手牌·卡组·墓地特殊召唤名字带有「卡通」的2只怪兽上场。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100786', '回击锤', '此卡因战斗被破坏送入墓地时，我方选择对方1张手牌舍弃墓地，此卡可以回到场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100787', '回吸', '只要此卡在场时，我方场上每存在1张不死族，我方生命值就回复500点。此效果1回合只能使用1次。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('DCOR0031', '混沌破坏龙', '8星怪兽×2
INSERT INTO "texts" VALUES ('ZZ100789', '火焰之纹章', '装备上此卡的怪兽攻击力和守备力上升500点。可以将墓地存在的2张装备魔法卡从游戏中除外发动，将墓地存在的这张卡加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100790', '机甲天龙 犬龙', '1回合可将手牌中的所有「机甲天龙 犬龙」召唤到场上。
INSERT INTO "texts" VALUES ('ZZ100791', '机甲天龙 炎翅双刀龙', '将我方场上1只龙族怪兽和对方场上存在的1只战士族怪兽解放，可特殊召唤此卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100792', '机甲天龙 重炮蓝龙', '←1 【灵摆】 1→
INSERT INTO "texts" VALUES ('ZZ100793', '机甲天龙的机甲强化', '我方场上名字带有「天龙」的怪兽存在时，可从手牌特殊召唤相同数量的名字带有「机甲天龙」的怪兽上场。
INSERT INTO "texts" VALUES ('ZZ100794', '终极幻魔兽-幻魔皇', '这张卡不能通常召唤，把自己场上存在的1只恶魔族怪兽作为祭品的场合才能特殊召唤。此卡不会被魔法·陷阱的效果无效化。1回合1次，破坏对方场上1只怪兽，对方生命值受到那只怪兽守备力数值的伤害。接着在对方场上特殊召唤1只「幻魔衍生物」（恶魔族·暗·1星·攻/守2000）。
INSERT INTO "texts" VALUES ('ZZ100795', '终极幻魔兽-降雷皇', '这张卡不能通常召唤，把对方场上存在的3张卡送入墓地场合才能特殊召唤。此卡不会被效果怪兽无效化，此卡战斗的场合，对方怪兽送入墓地并给予对方那只怪兽攻击力数值的伤害，此卡守备表示不会被战斗破坏，此卡存在场上时，对方不能选择其他怪兽作为攻击对象。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100796', '终极幻魔兽-神炎皇', '这张卡不能通常召唤，从墓地除外3张怪兽卡才能特殊召唤。此卡不会被场上卡的效果无效化，双方墓地每有1张卡，这张卡的攻击力与守备力上升1000.1回合1次，可以破坏对方场上盖伏的1张魔法·陷阱卡，此怪兽1回合可进行2次攻击，此外对方需把手牌给我方观看，给我方选中的1张手牌，需送入墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100797', '剧毒魔', '从卡组随机选择1张卡翻开，如果是怪兽的话，这个回合此卡在同1次的战斗阶段可以进行3次的攻击。那之后，翻开的卡回到卡组洗切。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100798', '卡通奥西里斯之天空龙', '我方场上有「卡通空间」、「卡通世界」、「卡通王国」中任意1张卡才能特殊召唤上场，此卡在场上，「卡通空间」、「卡通世界」、「卡通王国」不会被破坏和无效化，可直接攻击对方。此卡的攻击力与守备力是由自己的手牌数×1000来计算。此卡不受任何效果·魔法·陷阱影响。此卡在场上时，对方召唤·反转召唤·特殊召唤时，攻击表示的看攻击力，守备表示的看守备力，在2000点以下的破坏，在2000点以上时，攻击力·守备力各扣2000点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100799', '卡通欧贝利斯克之巨神兵', '我方场上有「卡通空间」、「卡通世界」、「卡通王国」中任意1张卡才能特殊召唤上场，此卡在场上，「卡通空间」、「卡通世界」、「卡通王国」不会被破坏和无效化，可直接攻击对方。此卡不受任何效果·魔法·陷阱影响。当此卡在场上时，把2只怪兽当作祭品，发动以下效果：·对方场上所有怪兽全部破坏，对方生命值受到4000点伤害。·本回合攻击力无限大。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100800', '卡通太阳神之翼神龙', '我方场上有「卡通空间」、「卡通世界」、「卡通王国」中任意1张卡才能特殊召唤上场，
INSERT INTO "texts" VALUES ('ZZ100801', '卡通地缚神', '自己场上有「卡通世界」时才能特殊召唤上场。「卡通世界」破坏时这张卡破坏。对方场上不存在卡通怪兽的场合这张卡可以直接攻击，自己和对方的墓地每存在1只名字带有「卡通」或「地缚神」的卡片这张卡的攻击力上升300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100802', '卡通黑暗大法师', '这张卡和5张名字带有「卡通」的怪兽在手牌时。将对方场上·墓地·手牌所有卡移除到游戏外。当此卡和5张名字带有「卡通」的怪兽在场上集齐时，我方宣告胜利。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100803', '卡通幻魔皇', '1回合1次，从卡组添加1张怪兽到手牌，把此卡作解放，从卡组·手牌特殊召唤1只「幻魔皇 拉比艾尔」上场。自己场上有「卡通世界」、「卡通空间」或者「失乐园」时，对方的场上没有卡通怪兽时，这张卡可以直接攻击对方，此卡不会被破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100804', '卡通降雷皇', '1回合1次，从卡组添加1张魔法卡到手牌，把此卡作解放，从卡组·手牌特殊召唤1只「降雷皇 哈蒙」上场。自己场上有「卡通世界」、「卡通空间」或者「失乐园」时，对方的场上没有卡通怪兽时，这张卡可以直接攻击对方，此卡不会被破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100805', '卡通神炎皇', '1回合1次，从卡组添加1张陷阱卡到手牌，把此卡作解放，从卡组·手牌特殊召唤1只「神炎皇 乌利亚」上场。自己场上有「卡通世界」、「卡通空间」或者「失乐园」时，对方的场上没有卡通怪兽时，这张卡可以直接攻击对方，此卡不会被破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100806', '奥利哈钢 红蛇女', '「奥利哈钢 红光蛇」＋「奥利哈钢 红光蛇」
INSERT INTO "texts" VALUES ('ZZ100807', '卡通黑魔导', '自己场上有「卡通世界」时才能特殊召唤上场。「卡通世界」破坏时这张卡破坏。对方场上不存在卡通怪兽的场合这张卡可以直接攻击。自己和对方墓地每存在1只魔法师族卡通怪兽此卡的攻击力上升500点。当对方发动以我方场上卡通怪兽为对象的卡片效果时可以选择墓地里1只魔法师族卡通怪兽片排除到游戏外，让那个效果无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100810', '冥王神祗之一天空龙', '从手牌把3张卡送入墓地的场合才能被特殊召唤。此卡不会被魔法、陷阱、效果怪兽的效果破坏。1回合1次，可以把双方玩家场上的怪兽当作装备卡使用给这张卡装备，这张卡的攻击力上升这个效果所有装备怪兽的攻击力数值总和。1回合1次，给予对方场上攻击力最低的那只怪兽的数值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100811', '命悬一线', '我方受到1000以上的战斗伤害的场合才能发动。给予对方生命值1000的伤害。这个效果1回合只能使用1次。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100812', '魔域之壶', '选择我方墓地5张速攻魔法卡返回卡组洗切。那之后，从卡组抽2张卡。这张卡在墓地里也视为速攻魔法卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100814', '千年番天印', '千年神器卡。
INSERT INTO "texts" VALUES ('ZZ100815', '千年混沌钟', '千年神器卡。
INSERT INTO "texts" VALUES ('ZZ100816', '千年女娲石', '十神器之卡。
INSERT INTO "texts" VALUES ('ZZ100817', '千年盘龙戟', '千年神器卡。
INSERT INTO "texts" VALUES ('ZZ100818', '强袭斗士 艾亚克雷', '3星怪兽×3
INSERT INTO "texts" VALUES ('ZZ100819', '切西亚的赠礼', '当我方受到伤害时才能发动，发动时选择其中1个效果发动：●从卡组特殊召唤1只等级8以上的怪兽，并将此卡作为装备卡装备在那只怪兽上，当装备了这张卡的怪兽进行战斗宣言时，如果那只怪兽的攻击力高于对方怪兽的攻击力，则不进行伤害计算直接破坏，并给与对方玩家对方怪兽攻击力数值的伤害。●我方与对方受到的所有伤害×2，此时此刻作为永续陷阱卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100820', '青眼白龙·海马仪式', '此卡存在手牌时，可进行仪式召唤。此卡存在场上时，可从墓地、卡组尽可能的召唤「青眼白龙」上场。此卡的发动不能被无效化。丢弃1张手牌，使对方的魔法、陷阱、怪兽效果的发动无效并破坏。1回合1次，破坏对方场上的1只怪兽，此卡的攻击力上升被破坏怪兽的攻击力数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100821', '融合前线基地', '自己场上有融合怪兽存在的场合可以发动。只要这张卡在魔法陷阱区域存在，自己要受到的来自对方的效果伤害变为0.自己场上没有融合怪兽存在的场合，这张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100822', '三色虎', '此卡召唤成功的回合，双方场上的魔法·陷阱卡全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100823', '森之精灵的愤怒', '对方场上的魔法·陷阱卡全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100824', '森之精灵的回馈', '我方受到生命值伤害时可以发动。这个回合我方受到的生命值伤害由对方承受。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100825', '狂战士', '反转：此卡成为装备卡装备在对方1只怪兽上，被装备的怪兽每回合攻击力下降一半的数值，对方每回合承受下降攻击力数值的生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100826', '女鬼阴爪', '反转：1回合1次，可以变成背面守备表示。这张卡反转召唤成功时，给予对方生命值1000点的伤害。此卡不受战斗破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100827', '深山食人虫', '反转：破坏对方场上最多2只怪兽，每成功破坏1只，给予对方500点伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100828', '神官的千年守墓者', '此卡由于战斗被破坏时，可以不送入墓地直接回到手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100829', '精灵的宝石', '此卡不能成为攻击对象，只要这张卡场上正面表示存在，我方光属性怪兽攻击力上升500。对方暗属性的怪兽攻击力下降500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100830', '神炎皇 甜点师', '这张卡召唤成时，选择对方的魔法与陷阱卡区域盖放的1张卡才能发动。把盖放的那张卡确认，陷阱卡的场合，那张卡破坏。不是的场合，加到我方手牌。这张卡从场上送去墓地时，对方场上的全部怪兽的攻击力下降1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100831', '神之操控者', '只要我方场上存在神属性怪兽此卡就不会被无效和破坏。1回合1次，从卡组·手牌·墓地无条件特殊召唤1只神属性怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100832', '神之毁灭', '当我方场上同时存在名字带有奥西里斯」，「欧贝利斯克」，「太阳神」的怪兽时，将对方场上·手牌所有卡片全部移除到游戏外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100833', '神的余晖', '只要这张卡在场上存在，持有「生命值回复」的卡的效果发动时，那次生命值回复的数值变为原来的2倍。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100834', '圣龙 五头龙', '将墓地5只龙族怪兽返回卡组可以从额外卡组特殊召唤。可以让自己场上正面表示存在的卡任意数量回到手牌。这张卡的攻击力上升这个效果回到手卡的牌数量×500的数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100835', '狮王之魂', '限此卡在场上正面表示存在，对方不能把攻击力1800以上的怪兽召唤·特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100836', '斯洛蛛女', '这张卡召唤成功时，场上每有1张守备怪兽，攻击力永久上升500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100837', '太阳神的补足', '针对此卡的效果怪兽的效果和魔法卡只有1回合，针对此卡的陷阱卡效果无效并破坏。我方场上没有盖放的卡时，从卡组抽2张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100838', '太阳神的龙之结界', '针对此卡的效果怪兽的效果和魔法卡只有1回合，针对此卡的陷阱卡效果无效并破坏。支付1000点生命值发动此卡，除名字带有「太阳神」以外的所有怪兽攻击力下降一半。此效果的发动不会被无效化，此卡被破坏时，对方损失1000点生命值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100839', '太阳神之恶魔取代', '针对此卡的效果怪兽的效果和魔法卡只有1回合，针对此卡的陷阱卡效果无效并破坏。支付600点生命值，让对方魔法·陷阱卡的发动无效并破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100840', '太阳神之封印龙', '此卡召唤成功后可以视为任意属性，针对此卡的效果怪兽的效果和魔法卡只有1回合，针对此卡的陷阱卡效果无效并破坏。此卡攻击宣言时，掷1枚硬币，是正面的场合此卡直接攻击对方生命值，是背面的场合，此卡破坏送入墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100841', '太阳神之僵尸娘', '此卡召唤成功后可以视为任意属性，针对此卡的效果怪兽的效果和魔法卡只有1回合，针对此卡的陷阱卡效果无效并破坏。将场上正面表示存在的这张卡送入墓地，从手牌·卡组特殊召唤1只名字带有「太阳神」的怪兽，此效果不会被无效化。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100842', '太阳神之连续攻击', '针对此卡的效果怪兽的效果和魔法卡只有1回合，针对此卡的陷阱卡效果无效并破坏。我方场上存在的怪兽全部名字带有「太阳神」时，选择我方场上攻击力最高的1只可以攻击2次，其他怪兽送入墓地，只有1只的场合不用送入墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100843', '太阳神之墓地复生', '针对此卡的效果怪兽的效果和魔法卡只有1回合，针对此卡的陷阱卡效果无效并破坏。1回合1次，将我方墓地1只等级7以下名字带有「太阳神」的怪兽特殊召唤上场，用此效果召唤上场的怪兽不会被对方卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100844', '太阳神的全力反击', '针对此卡的效果怪兽的效果和魔法卡只有1回合，针对此卡的陷阱卡效果无效并破坏。我方场上有名字带有「太阳神」的怪兽才能发动，从卡组把2张名字带有「太阳神」的卡加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100845', '太阳神之幽灵套装', '针对此卡的效果怪兽的效果和魔法卡只有1回合，针对此卡的陷阱卡效果无效并破坏。此卡只能装备给名字带有「太阳神」的怪兽，装备此卡的怪兽不受对方魔法·陷阱卡的效果影响。装备此卡的怪兽被破坏送入墓地时，我方从卡组抽1张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100846', '天龙 墓地之归来', '我方怪兽被破坏时，从墓地选择最多2只5星以下名字带有「天龙」的怪兽召唤到场上。●此卡不受对方卡片中以名字带有「天龙」为对象的效果影响。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100847', '天龙 逆袭', '此卡在场上时，我方手牌送入墓地的卡中存在5星的怪兽时可以直接召唤到场上。
INSERT INTO "texts" VALUES ('ZZ100848', '天龙 强力穿刺', '只能装备在5星以下的龙族怪兽身上，可以给予对方生命值伤害。
INSERT INTO "texts" VALUES ('ZZ100849', '天龙 热火龙', '舍弃1张手牌，此卡可以从手牌特殊召唤。1回合1次，选择自己墓地存在的2只名字带有「天龙」的怪兽发动，选择的怪兽回到手牌，双方从卡组抽1张卡。
INSERT INTO "texts" VALUES ('ZZ100850', '天龙 融化龙', '攻击对方成功时，可从卡组抽2张卡。
INSERT INTO "texts" VALUES ('ZZ100851', '天龙 闪电龙', '把这张卡解放，场上正面存在的1只怪兽破坏，从自己卡组把1只名字带有「天龙」的怪兽加入手牌。
INSERT INTO "texts" VALUES ('ZZ100852', '天龙 圣地龙', '1回合1次，舍弃1张手牌，指定1只怪兽不能攻击，超量召唤时当12星怪兽使用。
INSERT INTO "texts" VALUES ('ZZ100853', '天龙 圣风龙', '1回合1次，舍弃2张手牌，指定1只怪兽破坏，超量召唤时当12星怪兽使用。
INSERT INTO "texts" VALUES ('ZZ100854', '天龙 圣光', '此卡在场上时，自己场上名字带有「天龙」的怪兽不会被魔法/陷阱卡的效果破坏。
INSERT INTO "texts" VALUES ('ZZ100855', '天龙 圣剑龙', '1回合1次，指定没有使用的魔法/陷阱卡区域1处发动。只要这张卡在场上存在，指定的卡区变成不能使用。
INSERT INTO "texts" VALUES ('ZZ100856', '天龙 圣雪龙', '1回合1次，舍弃1张手牌，指定1张魔法·陷阱卡破坏。超量召唤时当12星使用。
INSERT INTO "texts" VALUES ('ZZ100857', '天龙 守穴龙', '此卡在场上，对方怪兽只能对此卡进行攻击，计算伤害时，双方各承受一半。
INSERT INTO "texts" VALUES ('ZZ100858', '天龙 突破', '只能装备在龙族的怪兽身上，怪兽不受对方卡的效果影响。
INSERT INTO "texts" VALUES ('ZZ100859', '天龙 吸灵龙', '此卡在场上，在通常召唤以外可以多1次将1只名字带有「天龙」的5星以下的怪兽从手牌召唤。超量召唤时当11星怪兽使用。
INSERT INTO "texts" VALUES ('ZZ100860', '天龙 小盗龙', '1回合1次，舍弃1张卡手牌，从卡组抽2张卡。
INSERT INTO "texts" VALUES ('ZZ100861', '天龙 追风龙', '场上正面攻击表示存在的这张卡变成正面防守表示时，这张卡破坏，从自己卡组抽2张卡。
INSERT INTO "texts" VALUES ('ZZ100862', '天龙之结界圣物', '只要这张卡在场上正面表示存在，双方不能把龙族以外的怪兽特殊召唤。
INSERT INTO "texts" VALUES ('ZZ100863', '无名之风', '对方攻击宣言时发动，我方的1只怪兽攻击力上升800点。此怪兽战斗破坏对方怪兽送去墓地时，从自己卡组抽1张卡，并洗切卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100864', '武藤游戏-光', '此卡存在手牌时可以特殊召唤上场，以此卡为对象的卡全部破坏。此卡可以直接对对方作出攻击，可以把对方的手牌、场上、墓地的卡各最多1张从游戏中除外，对方受到除外的卡的效果×1000点的数值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100866', '邪神·神化身亚瓦塔', '我方支付一半生命值可从手牌特殊召唤此卡，此卡不会被战斗破坏，也不受怪兽效果影响。此卡的攻击力与守备力上升至10000点，对方场上每存在1只怪兽，此卡的攻击力再上升对方场上怪兽数量×500点的数值，这个效果发动的回合，这个回合这张卡不能作出攻击。若我方生命值比对方低的场合，持有这张卡的玩家在决斗中获得胜利。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100867', '炎斗火域', '对方怪兽卡的效果发动无效，并从对方的手牌或场上选1张卡送去墓地。此外，盖放的此卡被对方破坏送去墓地时，我方从卡组抽1张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100868', '战斗终止', '对方怪兽的攻击宣言时才能发动。对方可以从手卡把1只怪兽给人观看让这张卡的效果无效。没给观看的场合，那只攻击怪兽破坏，战斗阶段结束。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100869', '装甲 巨型1号坦克', '此卡不受对方卡片中以名字带有「装甲」为对象的效果影响。此卡将对方和我方场上各1张卡送入墓地可特殊召唤。被除外时，可从手牌将3只名字带有「装甲」的怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100870', '装甲 巨型3号坦克', '此卡不受对方卡片中以名字带有「装甲」为对象的效果影响。此卡将对方和我方场上各1张卡送入墓地可特殊召唤，被战斗破坏时，可以从手卡将3只名字带有「装甲」的怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100871', '装甲 药水兵', '此卡不受对方卡片中以名字带有「装甲」为对象的效果影响。正面存在场上时，可给1只怪兽装备，装备怪兽上升这只怪兽的攻击力数值。当我方名字带有「装甲」的怪兽守备表示被攻击时，对方攻击的怪兽同时破坏，对方受到那只怪兽攻击力的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100872', '装甲 炸弹兵', '此卡不受对方卡片中以名字带有「装甲」为对象的效果影响。召唤成功时，可从墓地/卡组将1只「装甲 炸弹兵」加入手牌。被破坏时，可从卡组将1张魔法卡加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100873', '装甲 战地龙虾', '此卡不受对方卡片中以名字带有「装甲」为对象的效果影响。将卡组最上方2张卡送入墓地可特殊召唤。墓地有2只以上的「装甲 战地龙虾」卡存在时，可将其特殊召唤上场。当正面表示被破坏时，同时破坏对方场上和手牌所有魔法和陷阱卡，每破坏1张对方受到1000点的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100874', '元素英雄-摩天大楼', '自己的主要阶段时发动此卡，1回合1次，选择自己墓地的1只名字带有「元素英雄」的怪兽特殊召唤上场。场上全部名字带有「元素英雄」的怪兽的攻击力上升1000点。此卡存在场上时，对方无法发送任何魔法卡，我方受到的战斗伤害为0。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('DCOR0025', '真红眼不死黑龙', '7星怪兽×2
INSERT INTO "texts" VALUES ('ZZ100876', '植物の愤怒 紧急援助', '我方怪兽被战斗破坏时，受到的生命值伤害为0。从自己墓地和卡组各选择1只怪兽特殊召唤上场。效果发动不会被无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100877', '殉道者 盗墓人', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。这张卡因对方从场上离开时，选择对方墓地存在的最多2只怪兽特殊召唤到我方场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100878', '殉道者 地狱开啓灵', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。这张卡召唤·特殊召唤成功时，可以选择自己墓地1只名字带有「殉道者」的怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100879', '殉道者 地狱看守人', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。 1回合1次，从以下效果选择1个发动。●选择对方场上存在的1张卡回到持有者手牌。●对方手牌确认选1张送去墓地。●选择对方墓地存在的1张卡从游戏中除外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100880', '殉道者 地狱恋尸虫', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。 此卡召唤成功后将我方墓地1只名字带有「殉道者」的怪兽特殊召唤。此卡从场上离开时，将我方或对方卡组最上方10张卡送入墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100881', '殉道者 地狱右手·蒂斯', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。只要这张卡在场上正面表示存在，每支付1000点生命值。可以把1次魔法·陷阱卡的发动或怪兽的召唤·反转召唤·特殊好好无效并破坏。可以选择将此卡作为祭品，从我方卡组无条件特殊召唤1只名字带有「殉道者」的怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100882', '殉道者 地狱狱卒', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。 对方给予我方战斗伤害时，下个回合对方的抽卡阶段跳过。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100883', '殉道者 地狱召唤', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。限此卡在场，1回合1次，从我方或对方墓地选择1只怪兽特殊召唤到我方场上，这个效果特殊召唤的怪兽效果无效化，攻击力变为4000点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100884', '殉道者 地狱追踪兽', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。选择对方场上1只怪兽才能发动，选择的怪兽表示形式改变，这个时候，反转效果的怪兽的效果不能发动。这个效果在对方回合也能发动。 ', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100885', '殉道者 断援兽', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。此卡召唤成功后如果我方场上存在名字带有 「殉道者」的怪兽。此卡转移到对方场上，只要对方场上存在此卡，对方就不能召唤怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100886', '殉道者 堕落精灵', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。和这张卡进行战斗的效果怪兽的效果无效化。 ', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100887', '殉道者 海王巡查员', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。此卡不会被战斗破坏，只要此卡在场上正面表示存在，对方对我方造成的战斗伤害为0。1回合1次，把墓地里1只名字带有「殉道者」的怪兽特殊召唤，这张卡的攻击力直到结束阶段上升那只怪兽的攻击力数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100888', '殉道者 火焰战士', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。把自己墓地1只怪兽从游戏中除外才能发动。这张卡的攻击力直到对方的结束阶段时永久上升那只怪兽的攻击力数值。这个效果1回合最多可以使用2次。 ', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100889', '殉道者 极冻岩', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。此卡不能通过召唤，把我方或对方场上1只名字带有「殉道者」的怪兽从游戏中除外的场合才能特殊召唤。此卡的特殊召唤不会被无效化，此卡的攻击力上升除外怪兽的攻击力一半的数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100890', '殉道者 镜灵蛇', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。此卡召唤成功时，给这张卡增加双方墓地卡片数量的「镜灵指示物」。取除1个「镜灵指示物」，可以将对方的1次攻击或效果无效并破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100891', '殉道者 龙宝', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。反转：翻开我方卡组最上方10张卡，如果有怪兽可以尽可能多的特殊召唤，魔法·陷阱卡可以直接覆盖，之后将剩下的卡放回卡组并洗牌。 ', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100892', '殉道者 魅惑邪眼', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。1回合1次，选择对方场上盖放的1张卡发动，那张卡的控制权交由我方。 ', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100893', '殉道者 冥灵部队', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。 此卡不会被魔法·陷阱卡的效果破坏，被战斗破坏时，破坏对方场上和此卡等级相同数量的卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100894', '殉道者 魔导领主', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。1回合1次，宣言怪兽的种族或属性才能发动。查看对方卡组，将同种族或属性的卡片全部移除到游戏外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100895', '殉道者 魔羊人', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。对方的卡的效果让自己受到伤害时才能发动。这张卡从手牌特殊召唤，给予对方生命值此卡攻击力2倍的伤害。 ', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100896', '殉道者 蚀魂怪', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。当此卡被送入墓地时，可以增加1000点攻击力特殊召唤到场上来（提示的攻击力可以增加），此卡攻击成功的场合，跳过我方的下个抽卡阶段。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100897', '殉道者 外骨骼兽', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。1回合1次，可以将墓地1只名字带有「殉道者」的怪兽作为装备卡给此卡装备，装备后的此卡攻击力·守备力上升那只怪兽的攻击力·守备力数值，此卡攻击效果怪兽时，那只怪兽的效果无法发动。 ', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100898', '殉道者 无头使', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。1回合1次，选择对方场上正面表示存在的1只怪兽才能发动，选择的怪兽攻击力变成0。 ', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100899', '殉道者 狱兽杰纳斯', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。只要此卡在墓地，每当我方准备阶段，舍弃1张手牌可以将此卡特殊召唤到场上来，这个效果发动的回合对方不能把怪兽特殊召唤，再此卡战斗的怪兽移除到游戏外。 ', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100900', '殉道者 战士将领', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。此卡召唤成功时，将对方卡组最上方的5张卡翻开，是怪兽的尽可能多的召唤到我方场上，其翻开卡片移动到游戏外。 ', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100901', '殉道者 注射魔人', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。掷1枚硬币，若为正面此卡攻击力加倍，若为反面则攻击力翻倍，掷出正面的场合，我方可以选择继续投掷硬币，此效果只能在我方准备阶段时使用。 ', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100902', '殉道者的剥夺', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。1回合1次，将我方场上1只名字带有「殉道者」的怪兽解放，给予对方被解放怪兽攻击力数值的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100903', '殉道者的毁灭一击', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。1回合1次将我方场上1只名字带有「殉道者」的怪兽解放，选择以下效果中的1个发动。●从双方墓地选择1张卡片加入我方手牌。●查看对方手牌，选择1张加入我方手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100904', '殉道者的天使女郎', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。当对方怪兽召唤成功时，我方场上怪兽数量比对方数量少时可以发动。可以将我方手牌·墓地名字带有 「殉道者」的怪兽特殊召唤，直到与对方场上怪兽数量相同为止。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100905', '殉道者的吸泉', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。当我方场上怪兽1回合有2只以上被送入墓地时可以发动，对方所有手牌全部舍弃到墓地，每有1张我方回复500点生命值。 ', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100906', '殉道者归来', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。当此卡发动成功后，3个回合内我方场上名字带有 「殉道者」的怪兽不受对方任何卡效果影响。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100907', '殉道者之金钱攻略', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。对方召唤怪兽成功的回合的结束阶段，需要选择与对方召唤的怪兽等级相同数量的对方场上卡片送入墓地。 ', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100908', '殉道者之命运的抉择', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。每当我方抽卡阶段将抽出的卡给对方观看。并根据抽到的卡来发动以下效果：●陷阱卡：对方损失1000点生命值。●魔法卡：我方恢复1000点生命值。●怪兽卡：正面表示无条件特殊召唤到我方场上。这张卡的效果发动不会被无效化。 ', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100909', '殉道者之随机抽取', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。随机抽取对方卡组的3张卡加入我方手牌。 ', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100910', '太阳神之铠甲-头饰', '这张卡不能特殊召唤。这张卡的召唤不会被无效化。这张卡通常召唤成功时，对方不能针对此卡发动魔法·陷阱·效果怪兽的效果。此外，这张卡召唤成功的回合，可以查看我方卡组最上面5张卡，之后选择1张卡加入手牌并洗切。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100911', '太阳神之铠甲-胸铠', '这张卡不能特殊召唤。这张卡的召唤不会被无效化。这张卡通常召唤成功时，对方不能针对此卡发动魔法·陷阱·效果怪兽的效果。这张卡被战斗破坏送入墓地时，可以选择手牌1只名字带有「太阳神」的怪兽特殊召唤到场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100912', '太阳神之铠甲-护腿', '这张卡不能特殊召唤。这张卡的召唤不会被无效化。这张卡通常召唤成功时，对方不能针对此卡发动魔法·陷阱·效果怪兽的效果。此外，这张卡召唤成功的回合，攻击力上升对方魔法陷阱卡区卡片数量×500点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100913', '太阳神之主宰者 马利克', '这张卡不能特殊召唤。这张卡的召唤不会被无效化。这张卡通常召唤成功时，对方不能针对此卡发动魔法·陷阱·效果怪兽的效果。此外，1回合1次，可以舍弃手牌1张卡选择对方场上1只怪兽破坏，并给予对方500点的生命值伤害。发动这个效果的回合，此卡不能发动攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100914', '星尘龙之铠甲-护臂', '
INSERT INTO "texts" VALUES ('ZZ100915', '星尘龙之铠甲-羽翼', '
INSERT INTO "texts" VALUES ('ZZ100916', '星尘龙之铠甲-护腿', '持有「把场上的卡破坏」的魔法·陷阱·效果怪兽的效果发动时，把这张卡解放才能发动。那个发动无效并破坏。此外，1回合1次，战斗阶段时，掷1次骰子，此卡攻击力上升骰子数量×300点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100917', '星尘龙之铠甲-头饰', '
INSERT INTO "texts" VALUES ('ZZ100918', '星尘龙之铠甲-胸铠', '持有「把场上的卡破坏的效果」的魔法·陷阱·效果怪兽的效果发动时，把这张卡解放才能发动，那个发动无效并破坏。此外，此卡战斗破坏对方怪兽时，不计算战斗伤害，下个我方回合。被此卡战斗破坏的那只怪兽特殊召唤到我方场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100919', '奥西里斯之主宰者-游戏', '这张卡不能特殊召唤。这张卡的召唤不会被无效化。这张卡通常召唤成功时，对方不能针对此卡发动魔法·陷阱·效果怪兽的效果。只要此卡在场上正面表示，对方怪兽攻击召唤成功时，那些怪兽的攻击力下降2000，不足2000的场合那怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100920', '幻魔教主教', '支付一半的生命值此卡可以从手牌特殊召唤。1回合1次，可以选择自己墓地存在的1只效果怪兽从游戏中除外。只要这张卡在自己场上正面表示存在，直到结束阶段，此卡的攻击力提升选择怪兽的攻击力和得到怪兽效果，在自己场上特殊召唤2只「幻魔衍生物」(恶魔族·暗·1星·攻/守1000)，每祭品1只自己场上存在的「幻魔衍生物」，对方受到1000点伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100921', '奥利哈钢 七武神·火之灭', '我方墓地里存在7张等级5以上冠有「奥利哈钢」之名的怪兽才能特殊召唤，此卡在我方的主要阶段时可以宣告1种除炎之外的属性，此卡的攻击力上升的场地上被选择属性的怪兽中最强的攻击力×2的数值，对手场地·手牌·墓地只能的所有属性和被选择属性相同的怪兽从游戏中除外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100922', '奥利哈钢 七武神·暗之蚀', '我方墓地里存在7张等级5以上冠有「奥利哈钢」之名的怪兽才能特殊召唤，我方的主要阶段时可以宣告1种除暗之外的属性，此卡的攻击·守备力成为场地上被选择属性的怪兽中最弱的攻击·守备力×场地上暗属性的怪兽数量，对手每完成一种动作，我方可以选择对手场地·手牌·墓地中的所1只怪兽从游戏中除外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100923', '奥利哈钢 七武神·地之御', '我方墓地里存在7张等级5以上冠有「奥利哈钢」之名的怪兽才能特殊召唤，只要此卡存在我方场地上，对手不能以此卡以外的我方怪兽作为攻击和效果对象，此卡受到对手攻击时攻击·守备力各自上升为我方场地上所有怪兽的攻击·守备力的总和×2的数值，此的攻击·守备力变化时不能宣告攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100924', '奥利哈钢 七武神·水之伤', '我方墓地存在7张等级5以上名字带有「奥利哈钢」的怪兽卡才能特殊召唤。此卡在我方发动攻击宣言时，计算场上所有水属性的怪兽攻击力总和。此卡的攻击力上升那个攻击力总和×2的数值，对方场上所有怪兽的攻击·守备力下降那个攻击力的数值，攻击力·守备力下降为0的场合那些怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100925', '黑魔导女孩 LV3', '此卡特殊召唤成功时，可以直接攻击对方生命值，每当此卡给予对方造成战斗伤害时，此卡攻击力增加800点。当场上存在其他名字带有「黑魔导」的怪兽时，对方不能以此卡作为攻击对象，可以选择将此卡送入墓地，从我方手牌·卡组特殊召唤1只「黑魔导女孩 LV6」。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100926', '黑魔导女孩 LV6', '用「黑魔导 LV3」的效果特殊召唤的场合，此卡因卡的效果从场上离开时，给予对方生命值一半的伤害。此卡在场上存在时，1回合1次，我方场上名字带有「黑魔导」的怪兽攻击力上升400点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100927', '黑魔导女孩 LV9', '此卡不能通常召唤。将我方场上存在「黑魔导女孩 LV3」和「黑魔导女孩 LV6」移除到游戏外，此卡可以从手牌·卡组·墓地召唤上场。此卡的召唤不会被无效化。此卡召唤成功后，1回合1次，选择我方墓地1只魔法师族怪兽效果无效攻击力变为0在对方场上无条件特殊召唤，将此效果特殊召唤的怪兽不能攻击不能改变表示形式，不能成为祭品。此卡每战斗破坏对方1只魔法师族怪兽时，对方从卡组最上方把10张卡送入墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100928', '神之邪化', '支付600点生命值，将自己场上·手牌·卡组中1张「究极的幻神」或者「邪神·奥西里斯之天空龙」、「邪神·欧贝利斯克之巨神兵」、「邪神·太阳神之翼神龙」各1张作祭品送入墓地，从自己的手牌·墓地或卡组特殊召唤1只张「究极的邪神」到场上。此卡的发动不能被无效化。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100929', '三邪神之魂', '支付1000点生命值，把自己场上·手牌·卡组·除外区域的「邪神·奥西里斯之天空龙」、「邪神·欧贝利斯克之巨神兵」、「邪神·太阳神之翼神龙」放入墓地，从自己的手牌·墓地·卡组·除外区域特殊召唤1只「邪之创造神」到场上并攻击表示，此卡的发动不会被无效化。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100930', '究极的邪神', '由「神之邪化」的效果特殊召唤。加3个神力计数器到此卡上，每去除1个神力计数器，可发动以下的任何一个效果：●对方生命值扣去4000点。●破坏对方场上全部卡片。●将名字带有「邪」、「暗」字的怪兽特殊召唤。此卡拥有三邪神的效果。此卡不受魔法·陷阱·怪兽效果影响。也不会被战斗破坏，效果的发动和召唤不会被无效化。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100931', '邪之创造神', '此卡通过「三邪神之魂」的效果或支付一半生命值特殊召唤。●此卡不会被破坏，不受魔法·陷阱·怪兽效果影响。●每回合可破坏对方场上的全部卡，每有一张自己恢复1500点生命值。●每回合可从卡组·墓地·除外区特殊召唤3只暗属性怪兽或发动3张魔法卡。●给对方等于对方生命值的伤害。●此卡的效果不会被无效化。●此卡在场时，我方怪兽可占用魔法·陷阱卡区域（包括对方的场地）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100932', '传说骑士 提玛欧斯', '这张卡因「千年的心」的效果特殊召唤时，对方这个回合不能发动魔法卡。魔法卡不能以这张卡为对象。可以和其他的怪兽融合为未知的1只新的怪兽。此卡进行战斗结束后可以从自己墓地取1张魔法卡回到手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100933', '传说骑士 克里提钨斯', '当这张卡因「千年的心」的效果特殊召唤时，对方这个回合不能发动陷阱卡，陷阱卡不能以这张卡为对象。当场上此卡被选为攻击对象时，可以发动「神圣防护罩-反射镜力」的同样效果，将攻击全部反弹给对方怪兽，破坏对方所有正面表示的怪兽，此卡战斗结束后可以从自己墓地取1张陷阱卡回到手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100934', '传说骑士 海聂獸斯', '当这张卡因「千年的心」的效果特殊召唤成功时，对方这个回合场上所有怪兽效果无效，怪兽效果不能以这张卡为对象。自己场上的怪兽被选择攻击对象时，可以把攻击对象变成此卡，然后把自己墓地任意数量怪兽除外，此卡的攻击力变成“此卡的攻击×除外的怪兽数量”。战斗结束后可以从自己墓地取1张怪兽卡回到手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100935', '无名龙骑士的提玛欧斯之眼', '手牌中发动，不受对方卡片影响。可以从墓地、卡组、手牌中特殊召唤「传说骑士 提玛欧斯」，召唤效果视为「千年的心」。下一个我方回合，可以从墓地、卡组将「无名只龙 提玛欧斯之眼」加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100936', '无名龙骑士的克里提钨斯之牙', '手牌中发动，不受对方卡片影响。可以从墓地、卡组、手牌中特殊召唤「传说骑士 克里提钨斯」，召唤效果视为「千年的心」。下一个我方回合，可以从墓地、卡组将「无名只龙 克里提钨斯之牙」加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100937', '无名龙骑士的海聂獸斯之爪', '手牌中发动，不受对方卡片影响。可以从墓地、卡组、手牌中特殊召唤「传说骑士 海聂獸斯」，召唤效果视为「千年的心」。下一个我方回合，可以从墓地、卡组将「无名只龙 海聂獸斯之牙」加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100938', '千年的心', '支付1000点生命值，将自己场上的所有怪兽作为祭品，可以从墓地、卡组、手牌中特殊召唤「传说骑士 提玛欧斯之眼」、「传说骑士 克里提钨斯之牙」、「传说骑士 海聂獸斯之爪」，攻击力/守备力增加2000点。召唤成功后，破坏对方场上所有魔法卡，并且可以发动攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100939', '殉道者 地狱指示女神', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。限此卡在场，每祭掉我方场上1只名字带有「殉道者」的怪兽，可以指定对方一处未使用的魔法陷阱区禁止使用（最多4个）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100940', '殉道者 地狱指示男官', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。限此卡在场，每祭掉我方场上1只名字带有「殉道者」的怪兽，可以指定对方一处未使用的怪兽区域禁止使用（最多4个）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100941', '殉道者的粉碎', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。当我方场上名字带有「殉道者」的怪兽被选为攻击对象时，从手牌将1张名字带有「殉道者」的卡送入墓地，攻击怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100942', '殉道者之时空回廊', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。 我方场上有名字带有「殉道者」的怪兽被选为怪兽·魔法·陷阱的效果对象时才能发动。从卡组把1张名字带有「殉道者」的卡加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100943', '殉道者的繁殖兽鱼', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。 每当对方卡片送入墓地时，此卡会增加1个「殉道指示物」，当此卡「殉道指示物」为20个时，我方获得这场决斗的胜利。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100944', '殉道者之等级短路', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。 我方卡组·手牌怪兽等级永久下降2。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100945', '殉道者之禁忌召唤', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。对方场上有怪兽，我方场上没有怪兽时，我方从卡组特殊召唤2只4星以下的怪兽上场。 ', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100946', '殉道者的馈赠', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。 将任意手牌加入卡组中洗切，之后，抽取送入卡组数量×2的卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100947', '殉道者之奇迹的召唤', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。我方从卡组抽取5张卡，有3张怪兽卡以上的场合，可再从卡组无条件特殊召唤1只等级6以上的怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100948', '殉道者之魔法升华', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。 将我方发动的1张通常魔法卡变为永续魔法卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100949', '殉道者之天降等级', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。选择以下效果发动 ●将我方手牌·卡组·墓地所有怪兽的等级永久下降1.（最低等级为1）●将对方手牌·卡组·墓地所有怪兽等级永久上升2。（最高等级为12）', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100950', '奥利哈钢 阿喀琉斯', '此卡只能以攻击表示存在于场上，此卡不会被战斗破坏（伤害计算适用）。当此卡所受的战斗伤害超过3000时，将我方场上全部名字带有「奥利哈钢」的怪兽送入墓地，给予对方玩家送入墓地怪兽攻守合计数值的伤害，此伤害效果不能被无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100951', '殉道者之无限替换', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。可以从卡组选择1张卡和此卡替换，之后，洗切卡组。 ', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100952', '殉道者之神女的诱惑', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。1回合1次，确认对方抽卡阶段抽的卡，是怪兽卡的场合，无视召唤条件特殊召唤到我方场上。 ', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100953', '殉道者救护队', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。每当对方特殊召唤1只怪兽，我方可以从手牌或墓地特殊召唤1只名字带有「殉道者」的怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100954', '殉道者的宣言', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。1回合1次，宣言卡的种类（怪兽·魔法·陷阱），直到下次的对方回合结束时，宣言卡的种类双方不能发动。 ', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100955', '殉道者之等价交换', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。跳过我方的抽卡阶段，选择墓地的怪兽·魔法·陷阱卡各1张加入手牌。 ', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100956', '殉道者的庇护', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。将我方场上1只名字带有「殉道者」的怪兽作为祭品，从手牌特殊召唤1只名字带有「殉道者」的怪兽，这个召唤作为祭品召唤，之后可以选择对方场上1只怪兽破坏。 ', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100957', '殉道者之伤的倍返', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。 此卡不会被破坏和无效，当我方墓地·手牌名字带有「殉道者」的卡片数是20张以上时，我方获得胜利。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100958', '殉道者之能力封禁', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。此卡只能装备给对方怪兽，装备的怪兽效果无效，攻击力守备力变为0，不能改变表示形式，不能被当作祭品素材，装备怪兽从场上离开时，特殊召唤到我方场上，此卡回手牌。 ', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100959', '殉道者的极限装甲', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。只能装备给名字带有「殉道者」的怪兽上，装备怪兽不会被破坏，不受对方卡的效果影响。 ', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100960', '殉道者 祭师摩克达', '①：1回合1次，自己场上表侧表示存在的名字带有「殉道者」的怪兽被选择作为攻击对象时，可以把那只怪兽的攻击无效。
INSERT INTO "texts" VALUES ('ZZ100961', '六芒星之铁甲飞龙', '名字带有「六芒星 龙？士」的怪兽+「六芒星之龙」怪兽
INSERT INTO "texts" VALUES ('ZZ100962', '六芒星之铁甲焰龙', '名字带有「六芒星 龙？士」的怪兽+「六芒星之龙」怪兽
INSERT INTO "texts" VALUES ('ZZ100963', '六芒龙神骑术', '手牌中存在「六芒星之龙」的卡片，可将其以外的手牌全部送到墓地，从卡组将1只「六芒星龙骑士」加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100964', '六芒星的奥义', '这张卡存在场上·墓地或被除外，对方的所有卡中以名字带有「六芒」的卡作为对象时，将其除外并在此次决斗中无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100965', '六芒星之龙穴', '将我方场上所有怪兽破坏，把墓地中名字带有「六芒星之龙」的怪兽尽可能地特殊召唤，之后手牌全部送入墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100966', '六芒星黑海浮沉', '当场上名字带有「六芒星」的怪兽被对方发动卡片效果作为对象时，对方全场卡片破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100967', '六芒星之龙 黑海霸龙', '这张卡通常召唤的场合，必须把自己场上的1只「六芒星」怪兽或2只暗属性怪兽解放作召唤。
INSERT INTO "texts" VALUES ('ZZ100968', '奥西里斯之孤城斗士', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。此卡的攻击力上升自己墓地名字带有「奥西里斯」的卡数量×700的数值。此外，1回合1次，将自己墓地1只7星以下的名字带有「奥西里斯」的怪兽从游戏中除外才能发动，直到回合结束阶段时，这张卡当作和除外的怪兽同名卡使用，并叠加相同的效果。
INSERT INTO "texts" VALUES ('ZZ100969', '奥西里斯的族人 蒂娜', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。1回合1次，从墓地选择2张卡返回卡组，之后，洗牌并抽2张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100970', '奥西里斯之雷斧战士', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。这张卡可以不用祭品进行通常召唤，这个方法通常召唤的这张卡攻击力变为一半。此外，1回合1次，将墓地的1只怪兽移除到游戏外，此卡上升移除到游戏外的怪兽的攻击力一半的数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100971', '奥西里斯之魔法学徒', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。1回合1次，宣言卡的种类（魔法·陷阱·怪兽），确认对方场上盖伏的1张卡，猜对的场合，那张卡移除到游戏外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100972', '奥西里斯之兔女郎', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。1回合1次，从以下效果选择1个发动。●得到对方场上1只怪兽的控制权。●从对方墓地特殊召唤1只怪兽到我方场上。●从我方手牌特殊召唤1只怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100973', '奥西里斯之出战的国王', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。此卡在场上存在时，每次对方法怪兽召唤成功时，给予对方那只怪兽等级×500点的生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100974', '奥西里斯之祭品收割者', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。限此卡正面表示存在于场上，对方每次祭品召唤时，会损失祭品怪兽攻击力数值的生命值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100975', '奥西里斯之异变炎狼', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。解放此卡，将对方全部手牌送入墓地，发动这个效果的下个我方回合的准备阶段不能抽卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100976', '奥西里斯之重金属恶魔', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。此卡召唤成功时，计算双方手牌中名字带有「殉道者」、「奥利哈钢」和「六芒星」的卡片数量，此卡攻击力上升那个数量。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100977', '奥西里斯之卡牌封禁', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。对方抽卡阶段时可以发动，舍弃我方2张手牌跳过对方的抽卡阶段。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100978', '奥西里斯之魔术玩偶', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。当我方这个回合有怪兽从场上离开时，可以将那只怪兽送入卡组洗切，并抽1张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100979', '奥西里斯之傀儡', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。1回合1次，计算对方墓地名字带有「殉道者」、「奥利哈钢」、「六芒」的卡片数量，给予对方那个数量×1000的直接伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100980', '奥西里斯之优胜劣汰', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。1回合1次，宣言1个种族才能发动，我方怪兽和宣言的怪兽进行战斗的场合，不进行伤害计算把那只怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100981', '奥西里斯之号令', '每当我方从手牌把卡召唤·特殊召唤·盖放·发动时，可以选择我方卡组里1张名字带有「奥西里斯」的怪兽加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100982', '奥西里斯之神的制裁', '此卡只能在游戏前（猜拳后，抽卡前）从卡组中发动。确认卡组中名字带有「六芒」和「植物」的卡的数量，视情况获得以下效果：●只有名字带有「六芒」，名字带有「六芒」的卡全部移除到游戏外，给予对方该数量×1000的生命值伤害。（生命值下限为1点）●只有名字带有「植物」，名字带有「植物」的卡全部移除到游戏外，给予对方该数量×1000的生命值伤害。（生命值下限为1点）●名字带有「六芒」和「植物」的卡都有，我方获得这次决斗的胜利。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100983', '奥西里斯之伤害爆破器', '此卡不受名字带有「殉道者」的卡效果影响，以此卡为对象发动的名字带有「奥利哈钢」和「六芒」的卡片效果无效并破坏。对方每有1张卡因为我方卡效果或战斗破坏被送入墓地时，此卡增加1个「爆破指示物」，移除任意个「爆破指示物」获得以下效果：●3个，对方魔法陷阱区域所有卡片破坏。●5个：对方场上所有怪兽卡全部破坏。●8个：对方场上·手牌所有卡片移除到游戏外。●15个：我方获得这场决斗的胜利。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100984', '奥西里斯的统治者', '限此卡在场，我方场上所有卡片不受对方卡片效果影响，我方每有1张卡片送入墓地时，根据那张卡的种类得到以下效果●魔法：我方可以再次发动那张卡的效果。●陷阱：将对方魔法陷阱区1张卡加入我方手牌。●怪兽：我方回复那只怪兽的攻击力数值的生命值或给予对方那只怪兽攻击力数值的生命值伤害。此卡在双方场上只能存在1张，存在2张的场合，第2张的同名卡的效果无效并移除到游戏外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100985', '奥西里斯之王', '1回合1次，此卡不受对方任何卡效果影响，此卡发动攻击宣言时可以对对方场上所有怪兽攻击1次，并无视被攻击的怪兽效果直接破坏那只怪兽，每战斗破坏对方场上1只怪兽，将对方1张手牌移除到游戏外，此卡不能直接攻击对方玩家生命值，限此卡在场，每个我方回合的准备阶段可以选择我方卡组·手牌或墓地1只名字带有「奥西里斯」的怪兽无条件特殊召唤到我方场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100986', '奥西里斯之铠甲-护臂', '此卡不能特殊召唤，这张卡的召唤不会无效化。这张卡通常召唤成功时，对方不能针对此卡发动魔法·陷阱·效果怪兽的效果。此外，1回合1次，可以将我方墓地任意只名字带有「奥西里斯」的卡从游戏中除外，这张卡攻击力上升因此效果除外的卡片数量×500的攻击力数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100987', '奥西里斯之铠甲-胸铠', '这张卡不能特殊召唤，这张卡的召唤不会无效化，这张卡通常召唤成功时，对方不能对应此卡发动魔法·陷阱·效果怪兽的效果。此外，此卡可以直接攻击对方生命值。每当此卡攻击成功后，给予对方追加500点生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100988', '奥利哈钢 翁尼亚斯', '此卡不能改变表示形式，控制权不能变更。对方场上有怪兽存在时必须攻击，每祭掉我方场上1只名字带有「奥利哈钢」的卡，此卡攻击力增加1000.可以选择将此卡送入墓地，我方生命值回复此卡攻击力的数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100989', '奥利哈钢 元素召唤者', '1回合1次，宣言2个怪兽效果，将对方手牌中存在那个怪兽，在自己场上特殊召唤。此怪兽可以当名字带有「奥利哈钢」的怪兽使用。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100990', '奥利哈钢 时间指轮', '此卡战斗破坏对方怪兽时，下个对方的主要阶段1跳过。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100991', '奥利哈钢 盔甲巴龙', '只要此卡在场上，自己场上名字带有「奥利哈钢」的怪兽不受对方效果影响，对方只能选择此卡作为攻击的对象，此卡战斗时，可以将双方玩家手牌中卡片送入墓地（最多4张），送入墓地的卡每有1张，此卡守备力上升600，攻击力上升1000点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100992', '奥利哈钢的魔封剑', '此卡可以装备给对方的怪兽身上，装备怪兽攻击力变为0，卡片效果无法发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100993', '奥利哈钢的符咒', '限此卡在场，对方恢复生命值的效果无效并减少那个数值。我方恢复那个数值的2倍，对方陷阱卡的发动会被无效并破坏。此卡从场上离开时会回到持有者手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100994', '奥利哈钢 凌空击碎', '此卡存在手牌中时，可放到我方怪兽区，不作为召唤怪兽，也不能作解放召唤，此卡在场上，对方所有奥利哈钢的卡片效果无效，此卡不能破坏，直到战斗结束。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100995', '装甲 模仿水母', '此卡不受对方卡片中以名字带有「装甲」为对象的效果影响。可复制我方或对方场上的1张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100996', '装甲 特种战斗兵', '对方不能召唤攻击力1800以上的怪兽，当此卡被破坏时，同时破坏对方场上和手牌所有魔法·陷阱卡，每破坏1张对方受到1000点的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100997', '装甲 移动城堡', '1回合1次从自己卡组将1只4星以下的怪兽放在此卡下方，当此卡被破坏时，此卡下方的怪兽全部召唤上场。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100998', '装甲 潜水鱼', '此卡不受对方卡片中以名字带有「装甲」为对象的效果影响。1回合1次，从我方墓地选择1只名字带有「装甲」的怪兽放入对方卡组洗切，对方抽卡时，抽到我方名字带有「装甲」的怪兽时没我方宣布胜利。当我方名字带有「装甲」的怪兽守备表示被攻击时，对方攻击的怪兽同时破坏，对方受到那只怪兽攻击力的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100999', '装甲 捕猎龟', '此卡不受对方卡片中以名字带有「装甲」为对象的效果影响。可给1只怪兽装备，1回合1次，选择对方1只怪兽破坏，对方发动攻击宣言时，对方那只怪兽破坏并排除到游戏外。当我方名字带有「装甲」的怪兽守备表示被攻击时，对方攻击的怪兽同时破坏，对方受到那只怪兽攻击力的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101000', '装甲 东风大汽', '此卡不受对方卡片中以名字带有「装甲」为对象的效果影响。我方场上有正面表示的魔法卡时，此卡不用祭品直接作召唤。此卡和对方怪兽战斗的场合，伤害步骤内这只怪兽的攻击力上升1500点。回合结束时，此卡正面守备表示存在场上，当我方名字带有「装甲」的怪兽守备表示被攻击时，对方攻击的怪兽同时破坏，对方受到那只怪兽攻击力的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101001', '装甲 机枪直升机', '此卡不受对方卡片中以名字带有「装甲」为对象的效果影响。我方场上有陷阱卡发动时，此卡不用祭品直接作召唤。正面存在场上时，可给1只怪兽装备，那只怪兽的攻击力上升这只怪兽的攻击力数值。回合结束时，把此卡送入墓地，可跳过对方1回合。当我方名字带有「装甲」的怪兽守备表示被攻击时，对方攻击的怪兽同时破坏，对方受到那只怪兽攻击力的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101002', '装甲 霹雳战车', '此卡不受对方卡片中以名字带有「装甲」为对象的效果影响。对方场上没有怪兽存在时，此卡可从手牌或卡组特殊召唤。此卡成功召唤时，我方可从墓地召唤1只名字带有「装甲」的怪兽上场，被召唤上场的怪兽装备到此卡身上，此卡的攻击力上升那只怪兽的攻击力数值。「装甲 超巨型坦克」存在场上时，此卡1回合可作2次攻击。当我方名字带有「装甲」的怪兽守备表示被攻击时，对方攻击的怪兽同时破坏，对方受到那只怪兽攻击力的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101003', '装甲 领主铠甲', '此卡不受对方卡片中以名字带有「装甲」为对象的效果影响。此卡成功召唤的场合，对方场上所有怪兽的攻击力与守备力减半。我方场上有名字带有「装甲」的融合怪兽时，此卡可对对方直接攻击，当我方名字带有「装甲」的怪兽守备表示被攻击时，对方攻击的怪兽同时破坏，对方受到那只怪兽攻击力的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101004', '装甲 改造战士', '每次对方回合时，可将对方1只怪兽装备到此怪兽身上。当正面表示被破坏时，同时破坏对方场上和手牌所有怪兽卡，每破坏1张对方受到1000点的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101005', '装甲 巨型2号坦克', '此卡不受对方卡片中以名字带有「装甲」为对象的效果影响。将对方和我方场上各1张卡送入墓地可特殊召唤，此卡被效果破坏时，可从手牌将3只名字带有「装甲」的怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101006', '装甲 橄榄兵1型', '此卡不受对方卡片中以名字带有「装甲」为对象的效果影响。召唤成功的第二个我方回合，可以从卡组/墓地将1张名字带有「装甲 橄榄兵」的怪兽特殊召唤上场。当我方名字带有「装甲」的怪兽守备表示被攻击时，对方攻击的怪兽同时破坏，对方受到那只怪兽攻击力的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101007', '装甲 橄榄兵2型', '此卡不受对方卡片中以名字带有「装甲」为对象的效果影响。召唤成功的第二个我方回合，可以从卡组/墓地将1张名字带有「装甲 橄榄兵」的怪兽特殊召唤上场。当我方名字带有「装甲」的怪兽守备表示被攻击时，对方攻击的怪兽同时破坏，对方受到那只怪兽攻击力的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101008', '装甲 橄榄兵3型', '此卡不受对方卡片中以名字带有「装甲」为对象的效果影响。召唤成功的第二个我方回合，可以从卡组/墓地将1张名字带有「装甲 橄榄兵」的怪兽特殊召唤上场。当我方名字带有「装甲」的怪兽守备表示被攻击时，对方攻击的怪兽同时破坏，对方受到那只怪兽攻击力的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101009', '装甲 疯狂的枪兵', '此卡不受对方卡片中以名字带有「装甲」为对象的效果影响。反转：对方所有怪兽卡破坏。这张卡正面表示存在的时，对方不能发动直接伤害的效果。当我方名字带有「装甲」的怪兽守备表示存在被攻击时，对方攻击的怪兽同时破坏，对方受到那只怪兽攻击的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101010', '装甲 窝炉小坦克', '此卡不受对方卡片中以名字带有「装甲」为对象的效果影响。此卡召唤成功时，破坏对方场上所有魔法陷阱卡，每破坏1张，对方受到1000点的生命值伤害。此卡作名字带有「装甲」怪兽的融合、同调、超量怪兽的素材时，那些怪兽不会战斗破坏。当我方名字带有「装甲」的怪兽守备表示被攻击时，对方攻击的怪兽同时破坏，对方受到那只怪兽攻击力的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101011', '装甲 令人疯狂的武器', '装备在「装甲 疯狂的枪兵」身上，攻击力上升3000。装备在其他的怪兽身上，攻击力上升1000。装备此卡的怪兽不受对方魔法/陷阱卡的影响。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101012', '装甲 枪兵的坐骑', '2只名字带有「装甲 疯狂的枪兵」的怪兽融合（不需要「融合」魔法卡）。
INSERT INTO "texts" VALUES ('ZZ101013', '装甲 超巨型坦克', '名字带有「装甲」怪兽×3
INSERT INTO "texts" VALUES ('ZZ101014', '装甲 航天飞船', '名字带有「装甲」怪兽×3
INSERT INTO "texts" VALUES ('ZZ101015', '装甲 原始龙虾', '5星怪兽×2
INSERT INTO "texts" VALUES ('ZZ101016', '装甲 空间基地', '每个回合从手牌选择任意数量的卡片除外，同时除外对方场上相同数量的卡片。效果的发动不会被无效。此场地魔法卡不会被对方任何卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101017', '装甲 空间返回', '被「装甲 空间基地」除外的我方怪兽，全部尽可能的特殊召唤上场。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101018', '装甲 墓机城大炮', '我方回合从墓地将2只名字带有「装甲」的怪兽特殊召唤上场。召唤不能被无效化。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101019', '装甲 植物充能', '可以把对方场上1只植物族或机械族怪兽装备到我方1只怪兽身上，这只怪兽的攻击力上升对方那只怪兽的攻击力数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101020', '装甲 前线大激战', '每次对方的回合，选择对方场2只怪兽除外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101021', '装甲 三角盾', '我方场上的卡片·手牌·卡组，不受对方卡的效果影响，此卡召唤3个回合后自我破坏，对方不能无效和破坏除外此卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101022', '装甲 研究台', '选择以下其中1个效果发动。
INSERT INTO "texts" VALUES ('ZZ101023', '装甲 至宝黄金叉', '可装备我方场上1只怪兽。此怪兽在场时，对方所有效果无效，攻击力始终比对方场上怪兽多1000点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101024', '装甲 出战准备', '对方场上所有卡片3个回合效果无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101025', '装甲 半械能改造', '对方怪兽攻击时，攻击无效，选择那只怪兽当作装备卡，装备到我方怪兽身上，我方怪兽的攻击力上升那只怪兽的攻击力。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101026', '装甲 机临城下', '我方战斗破坏对方怪兽，对方发动魔法/陷阱卡时，对方所有魔法陷阱卡破坏。对方怪兽破坏，生命值受到直接的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101027', '装甲 绝地反击', '我方场上所有卡片被破坏时，可从墓地将全部名字带有「装甲」的怪兽尽可能的特殊召唤上场。这张卡在被破坏时才能发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101028', '装甲 地炮', '此卡有3个回合不会被破坏，对方召唤怪兽时，每召唤1只破坏对方2张魔法·陷阱卡，对方发动魔法时，每发动1张破坏对方2只怪兽，破坏时我方不受效果影响。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101029', '装甲 炮手侠', '此卡不受对方卡片中以名字带有「装甲」为对象的效果影响。正面存在场上时，可给1只怪兽装备。可将此卡和装备的怪兽一起送入墓地，从手牌将名字带有「装甲」的怪兽尽可能的召唤上场。此卡作融合素材时，此卡不送入墓地，正面表示存在我方场上。当我方名字带有「装甲」的怪兽守备表示被攻击时，对方攻击的怪兽同时破坏，对方受到那只怪兽攻击力的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101030', '装甲 铁斧将军', '「装甲 炮手侠」＋名字带有「装甲」的怪兽（不需要「融合」魔法卡）
INSERT INTO "texts" VALUES ('ZZ101031', '装甲 战斗壁垒枪手', '2只名字带有「装甲 橄榄兵」的怪兽融合（不需要「融合」魔法卡）。此卡不受对方卡片中以名字带有「装甲」为对象的效果影响。1回合1次，可以将墓地存在的1只名字带有「装甲」的怪兽从游戏中除外，这张卡的攻击力上升1000点。1回合1次，可以从卡组、手牌或墓地特殊召唤上场1张名字带有「橄榄兵」的怪兽，回合结束时，被除外的怪兽尽可能的召唤上场。当我方名字带有「装甲」的怪兽守备表示被攻击时，对方攻击的怪兽同时破坏，对方受到那只怪兽攻击力的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101032', '冥界亡灵', '此卡可支付1500点生命值从卡组·手牌·墓地及除外区特殊召唤到场上来。限此卡在场上对方无法召唤·放置或发动卡片效果，此卡不受任何卡片效果影响。每当对方准备阶段时受到1000点生命值伤害，此卡的召唤及效果不能被破坏和无效化。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101033', '灭冥之力', '对方场上存在和发动名字带有「冥界」的卡片时，跳过对方回合。这张卡片不会被无效和破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101034', '给冥界的报酬', '每回合给予对方墓地里卡片数量×100点伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101035', '冥界的鞭打', '此卡发动成功后可以装备在对方场上1只怪兽身上，被装备的怪兽不能攻击，发动效果或作为祭品。每当对方回合的结束阶段给予对方此怪兽攻击力一半的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101036', '冥界的通行令牌', '限此卡在场，我方可以选择我方手牌任意张数移除到游戏外，每移除到游戏外1张卡片对方也要将手牌的卡片移除到游戏外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101037', '冥界恶犬', '这张卡召唤成功时，可以从自己卡组把1只名字带有「冥界」的怪兽送去墓地，此卡，1回合1次，选择自己墓地存在的2只名字带有「冥界」的怪兽特殊召唤上场，我方抽2张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101038', '冥界守护者 曼托', '这张卡不能通常召唤，自己墓地存在的名字带有「冥界」的怪兽3只的场合才能特殊召唤。自己的主要阶段把自己墓地存在的1只名字带有「冥界」的怪兽从游戏中除外，此卡得到那张卡的效果。此卡最多叠加3个效果。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101039', '冥界守护者 俄琉斯', '把墓地的这张卡从游戏中除外，选择自己场上正面表示存在的1只名字带有「冥界」的怪兽发动。这个回合选择的怪兽攻击的场合，只要战斗破坏对方怪兽就可以追加一次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101040', '冥界守护者 埃涅阿斯', '此卡召唤成功后，可以选择场上正面表示存在的最多2只比这张卡的攻击力低的怪兽破坏。这个效果发动的回合，自己不能进行战斗阶段。此外，指定自己场上1张名字带有「冥界」的卡，只要这张卡在场上正面表示存在，那张卡就不会被效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101041', '冥界守护龙', '此卡只能在名字带有「冥界」的卡的效果下召唤。此卡的召唤和效果不能被无效化，此卡不能攻击，不能作祭品，也不能成为攻击对象，每回合攻击力上升1000，选择将场上此卡从游戏中除外，给予双方此卡攻击力数值的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101042', '冥界守护者 埃阿斯', '此卡被对方的效果破坏时，自己场上有名字带有「冥界」的怪兽正面表示存在的场合，给予双方那只怪兽攻击力数值的伤害，双方从卡组抽2张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101043', '冥界守护者 许拉斯', '这张卡1回合只有1次不会被战斗破坏。场上正面表示存在的这张卡被作为攻击对象时，给予对方生命值1000点伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101044', '究极体黑暗大邪神 索克', '支付500点生命值，把我方额外卡组的任意2只名字带有「No.」的怪兽作为此卡的超量素材，此卡从额外卡组特殊召唤。此卡不会成为对方卡的效果对象。只要此卡存在场上，名字带有「六芒星」的无效并破坏，每1张给予对方3000点生命值伤害。存在超量素材时，此卡不可直接攻击对方。1回合1次，可以将此卡1个超量素材取除，发动以下效果：●破坏场上所有怪兽卡。●破坏场上所有魔法·陷阱卡。●名字带有「千年」和「石板」的卡从卡组或额外卡组尽可能多的直接发动和召唤到场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101045', '太阳神之护庭队长', '此卡召唤成功时可以视为任意属性，针对此卡的效果怪兽的效果和魔法卡效果只有1回合，针对此卡的陷阱卡的效果无效并破坏。此卡从场上离开时，掷1次硬币，正面朝上时，下个我方的准备阶段此卡特殊召唤到场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101046', '太阳神之火炎之子', '此卡召唤成功时可以视为任意属性，针对此卡的效果怪兽的效果和魔法卡效果只有1回合，针对此卡的陷阱卡的效果无效并破坏。这张卡必须把3只名字带有「太阳神」的怪兽作为祭品进行特殊召唤。此卡的召唤不会被无效化。1回合1次，选择以下效果发动：●舍弃1张手牌，将此卡的攻击力变为2倍。●舍弃2张手牌，破坏对方魔法陷阱区的卡。●舍弃3张，破坏对方场上的所有卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101047', '太阳神之机械龙', '此卡召唤成功时可以视为任意属性，针对此卡的效果怪兽的效果和魔法卡效果只有1回合，针对此卡的陷阱卡的效果无效并破坏。自己墓地存在10只以上名字带有「太阳神」的怪兽时，此卡可以从手牌·墓地·除外区特殊召唤上场。次效果不会被无效化，此卡攻击力等于自己墓地名字带有「太阳神」的怪兽等级之和×200点。只要此卡正面表示存在场上，对方不能发动魔法·陷阱卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101048', '太阳神之海幼龙', '此卡召唤成功时可以视为任意属性，针对此卡的效果怪兽的效果和魔法卡效果只有1回合，针对此卡的陷阱卡的效果无效并破坏。只要此卡在场上正面表示存在，我方场上这张卡以外的名字带有「太阳神」的怪兽不能被选为攻击对象。我方场上所有名字带有「太阳神」的怪兽攻击力上升此卡攻击力数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101049', '太阳神之封印剑', '针对此卡的效果怪兽的效果和魔法卡效果只有1回合，针对此卡的陷阱卡的效果无效并破坏。装备此卡的怪兽攻击·发动效果·作祭品，必须支付800点生命值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101050', '太阳神的龙魔导', '针对此卡的效果怪兽的效果和魔法卡效果只有1回合，针对此卡的陷阱卡的效果无效并破坏。选择我方场上的1只怪兽发动，那只怪兽攻击对方怪兽时，不计算战斗伤害，直接将对方的那只怪兽破坏，给予对方那只怪兽攻击力数值的生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101051', '太阳神的蔷薇限定', '针对此卡的效果怪兽的效果和魔法卡效果只有1回合，针对此卡的陷阱卡的效果无效并破坏。对方的抽卡阶段时发动，确认对方所抽的那张卡的种类（魔法·陷阱·怪兽卡），破坏对方手牌或场上1张相同种类的卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101052', '太阳神之战争的代价', '针对此卡的效果怪兽的效果和魔法卡效果只有1回合，针对此卡的陷阱卡的效果无效并破坏。对方战斗阶段结束后，对方必须将1张手牌送入墓地，否则破坏此回合发动攻击宣言的怪兽，此效果不会被无效化。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101053', '太阳神之铠甲-护臂', '这张卡不能特殊召唤，这张卡的召唤不会被无效化，这张卡通常召唤成功时，对方不能针对此卡发动魔法·陷阱·效果怪兽的效果。此外，这张卡召唤成功的回合，此卡攻击力上升对方场上怪兽卡片数量×500点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101054', '太阳神之铠甲-羽翼', '这张卡不能特殊召唤，这张卡的召唤不会被无效化，这张卡通常召唤成功时，对方不能针对此卡发动魔法·陷阱·效果怪兽的效果。此外，1回合1次，舍弃手牌1张卡，可以令对方怪兽的攻击无效并给予对方500点的生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101055', '翼神龙 黄金火焰', '此卡不可特殊召唤，此卡必须解放我方场上的3只怪兽才能通常召唤，将我方场上怪兽的攻击力·守备力分别合计，其数值总和的差额变成此卡的攻击·守备力。献祭我方生命值1000点，此卡能化身为不死鸟，破坏对方场地·手牌的怪兽，此效果发动成功时，我方的生命值变成1点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101056', '太阳神的引导者', '此卡被卡效果破坏送入墓地时，可以从手牌特殊召唤1只名字带有「太阳神」的怪兽上场。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101057', '卡通星尘龙', '我方场上存在「卡通世界」时，此卡可以无视召唤条件特殊召唤，对方场上不存在卡通怪兽的场合这张卡可以直接攻击。限此卡在场，我方生命值不受对方卡效果影响。每当我方生命值受到伤害时可以把这张卡解放让那个伤害无效。这个效果适用的回合结束阶段时，为这个效果发动而解放在墓地存在的这张卡可以在自己场上特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101058', '卡通沉默剑士', '此卡召唤成功时此卡增加1个「魔力计数器」，根据此卡累计的「魔力计数器」得到以下效果，效果可叠加。1：此卡不会被战斗破坏。2：此卡不受对方魔法卡效果影响。3：此卡不受对方陷阱卡效果。4：此卡不受对方怪兽卡效果影响。5：限此卡在场对方卡效果发动无效破坏并移除到游戏外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101059', '卡通恶魔 绿', '自己场上有「卡通世界」时才能特殊召唤上场。「卡通世界」破坏时这张卡破坏，当我方场上有其他卡通怪兽存在时，对方不能以此卡为攻击目标。只要此卡正面表示存在场上，我方场上「卡通世界」不能被破坏和无效，对方无法发动场地魔法卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101060', '卡通树精', '自己场上有「卡通世界」时才能特殊召唤上场。「卡通世界」破坏时这张卡破坏，对方场上不存在卡通怪兽的场合这张卡可以直接攻击，移除我方墓地1张名字带有「卡通」的卡片获得对方场上1只怪兽的控制权。当我方墓地不存在名字带有卡通的卡片时，此卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101061', '卡通龙骑士黑魔导少女', '「卡通青眼白龙」+名字带有「卡通黑魔导少女」的卡片
INSERT INTO "texts" VALUES ('ZZ101062', '卡通极神皇 洛基', '名字带有「卡通」的怪兽3只以上
INSERT INTO "texts" VALUES ('ZZ101063', '卡通混沌黑魔导', '此卡的召唤不会被无效化，卡组每有1张魔法师族怪兽，此卡攻击力提高1000点，祭掉此卡给予对方此卡攻击力的直接伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101064', '卡通黑魔导 蓝', '自己场上有「卡通世界」时才能特殊召唤上场。「卡通世界」破坏时这张卡破坏，对方场上不存在卡通怪兽的场合这张卡可以直接攻击，自己和对方墓地每存在1只魔法师族卡通怪兽此卡的攻击力上升500点。当此卡被破坏时可以选择墓地里1只魔法师族卡通怪兽移除到游戏外，让那个破坏效果无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101065', '卡通光与暗之龙', '自己场上有「卡通世界」时才能特殊召唤上场。「卡通世界」破坏时这张卡破坏，当我方场上有其他卡通怪兽时，对方不能以此卡为攻击对象。这张卡的属性也当作「暗」使用。只要这张卡在场上正面表示存在，每当对方发动魔法·陷阱·怪兽效果时，移除我方墓地1张名字带有「卡通」的卡片让那个效果发动无效并破坏，当我方墓地卡片低于5张时，此卡移除到游戏外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101066', '卡通六武众 火门', '自己场上有「卡通世界」时才能特殊召唤上场。「卡通世界」破坏时这张卡破坏，对方场上不存在卡通怪兽的场合这张卡可以直接攻击。只要自己场上有除此卡以外的名字带有「卡通」的怪兽存在，1回合只有1次可以选择对方1张手牌移除到游戏外。使用这个效果的回合这只怪兽不能攻击宣言。这张卡被破坏的场合，可以舍弃1张手牌让那个破坏效果无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101067', '卡通毒蛇神 维诺米纳迦', '这张卡的攻击力自己墓地每有1只名字带有「卡通」的卡片上升500。只要这张卡在场上正面表示存在，不能成为这张卡以外的怪兽·魔法·陷阱的效果的对象并且不受效果影响。这张卡被战斗破坏送去墓地时，可以把自己墓地这张卡以外的1只卡通怪兽从游戏中除外把这张卡特殊召唤。每次这张卡给与对方玩家战斗伤害，给这张卡放置1个「超毒指示物」。这张卡放置有3个「超毒指示物」时，这张卡的控制者决斗胜利。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101068', '卡通的诅咒', '这张卡的名字当作「卡通世界」使用。1回合1次可以将我方墓地1张名字带有「卡通」的怪兽特殊召唤上场，或将我方游戏外1张名字带有「卡通」的怪兽返回墓地，我方从卡组抽1张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101069', '卡通空间', '支付600点生命值，可从手牌·卡组·墓地无视召唤条件，无需任何祭品，最大限度的召唤名字带有「卡通」的怪兽到场上，此卡的发动不会被无效化，且不能被破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101070', '拷贝猫', '此卡发动成功后，可视做墓地里任何一张卡，并使用。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101071', '不死之奥西里斯·天空龙', '这张卡不能特殊召唤只能将自己场上3只不死族怪兽解放作召唤。
INSERT INTO "texts" VALUES ('ZZ101072', '不死之人造人', '只要这张卡在场上正面表示存在，对方不能把陷阱卡发动，场上的陷阱卡的效果无效化。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101073', '不死之蒲公英狮', '这张卡被送去墓地时，在我方场上把4只「不死衍生物」（不死族·暗·1星·攻/守0）守备表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101074', '不死衍生物', '由「不死」怪兽的效果特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101075', '不死之猛毒药剂', '1回合1次，双方回复双方各自场上不死族怪兽数量×200的生命值。如果有玩家场上不存在不死族怪兽的场合，给予那个玩家自己场上怪兽数量×200的生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101076', '不死之时间魔术师', '掷1个硬币猜正反。猜中则把双方生命值互换。这个效果不受对方任何卡片效果影响。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101077', '不死之银狼', '这张卡召唤成功时可以选择墓地里2张名字带有「不死」的卡片放回卡组并洗切。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101078', '不死之恶魔的召唤', '1回合1次，移除我方墓地里2只不死族的怪兽可以获得对方场上1只正面表示怪兽的控制权。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101079', '不死之真红眼黑龙', '这张卡不能通常召唤，将我方墓地2只不死族怪兽移除到游戏外才能特殊召唤，这张卡特殊召唤成功的场合，可以将墓地里1张名字带有「不死」的卡片加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101080', '不死之千年龙', '每当我方准备阶段，在我方场上把1只「不死衍生物」」（不死族·暗·1星·攻/守1000）特殊召唤。此外，我方场上有「不死衍生物」存在，对方不能把这张卡作为攻击对象。这张卡的攻击力上升我方场上的「不死衍生物」数量×500的数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101081', '不死衍生物 ', '由「不死」怪兽的效果特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101082', '不死之元素英雄 新宇侠', '这张卡作为融合素材送入墓地时，可以特殊召唤到我方场上，这个效果1回合在决斗中只能使用1次。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101083', '不死之元素英雄 荒野侠', '1回合只有1次不会受到对方魔法或陷阱卡的效果影响。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101084', '不死之元素英雄 海洋侠', '1回合1次，我方的准备阶段时才能发动，选择我方墓地里的1只名字带有「不死之元素英雄」的怪兽回到持有者手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101085', '不死之元素英雄 羽翼侠', '这张卡作为融合素材送入墓地时，给予对方这张卡攻击力数值的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101086', '不死之元素英雄 水泡侠', '当我方手牌只有这1张名字带有「不死之元素英雄」的卡片时，这张卡可以从手牌特殊召唤。这张卡召唤·反转召唤·特殊召唤成功时可以从卡组抽2张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101087', '不死之英雄假面', '将这个回合作为融合素材送去墓地的怪兽特殊召唤到我方场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101088', '不死之R-正义审判', '把我方场上正面表示存在的名字带有「不死之元素英雄」的卡的数量的场上的卡片破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101089', '不死之O-超越灵魂', '从我方的墓地选择1只名字带有「不死之元素英雄」的怪兽，在我方场上特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101090', '不死之H-火热之心', '选择我方场上正面表示存在的1只怪兽发动。选择的怪兽攻击力上升1000。那张卡攻击守备表示怪兽时，若攻击力超过那个守备力，给予对方生命值那只怪兽守备表示守备力数值的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101091', '不死之E-紧急呼唤', '从我方卡组把2只名字带有「不死之元素英雄」的怪兽加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101092', '不死之英雄一闪！！', '把我方墓地的「不死之H-火热之心」、「不死之HE-紧急呼唤」、「不死之HR-正义审判」、「不死之HO-超越灵魂」从游戏中除外发动。从我方卡组特殊召唤1只名字带有「不死之元素英雄」的怪兽。这个回合我方场上的所有名字带有「不死之元素英雄」的怪兽可以直接攻击对方玩家。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101093', '不死之元素英雄 暴风侠', '「不死之元素英雄 水泡侠」＋名字带有「不死之元素英雄」的怪兽2张
INSERT INTO "texts" VALUES ('ZZ101094', '不死之元素英雄 铁壁炮手', '「不死之元素英雄 暴热女郎」＋名字带有「不死之元素英雄」的怪兽×1
INSERT INTO "texts" VALUES ('ZZ101095', '不死之元素英雄 锯齿荒野侠', '「不死之元素英雄 荒野侠」＋名字带有「不死之元素英雄」的怪兽×1
INSERT INTO "texts" VALUES ('ZZ101096', '不死之精灵卫士', '这张卡被攻击力3000以上的怪兽战斗破坏时，下个我方回合的准备阶段时，可以特殊召唤回我方场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101097', '不死之六武众-伊郎', '我方场上有除这张卡以外的名字带有「不死之六武众」的怪兽存在，这张卡向守备表示怪兽攻击的场合，不计算伤害将其正面守备表示状态的怪兽破坏，并给予对手破坏怪兽攻击力数值的生命值伤害。此外，场上正面表示存在的这张卡被破坏的场合，可以代替把这张卡以外的我方场上正面表示存在的1只名字带有「不死」的怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101098', '不死之六武众-二藏', '我方场上有除这张卡以外的名字带有「不死之六武众」的怪兽存在的场合，1回合1次，这张卡可以做2次攻击。因此效果直接攻击对方玩家生命值的场合，可以选择我方游戏外2张卡加入卡组并洗牌。此外，场上正面表示存在的这张卡被破坏的场合，可以作为代替把这张卡以外的我方场上正面表示存在的1只名字带有「不死」的怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101099', '不死之六武众-火门', '我方场上有除此卡以外的名字带有「不死之六武众」的怪兽存在的场合，1回合1次，可以选择场上1只背面表示的怪兽破坏。这个效果发动的回合，对方从卡组抽1张卡。此外，场上正面表示存在的这张卡被破坏的场合，可以作为代替这张卡以外的我方场上正面表示存在的1只名字带有「不死」的怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101100', '不死之大将军 紫炎', '我方场上有名字带有「不死之六武众」的怪兽2只以上存在的场合，这张卡可以从手牌特殊召唤。只要这张卡在场上正面表示存在，对方1回合只能有1次把魔法·陷阱卡发动。此外，场上正面表示存在的这张卡被破坏的场合，可以作为代替把我方场上正面表示存在的1只名字带有「不死」的怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101101', '不死之亡灵的右足', '进行不死族怪兽的祭品召唤时，此怪兽1只可以作为2只祭品使用这张卡因卡效果或作为祭品从场上送去墓地时，可以从卡组选择1张名字带有「不死之亡灵」的卡片加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101102', '不死之亡灵的左足', '进行不死族怪兽的祭品召唤时，此怪兽1只可以作为2只祭品使用这张卡因卡效果或作为祭品从场上送去墓地时，可以从卡组选择1张名字带有「不死之亡灵」的卡片加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101103', '不死之角', '只能给名字带有「不死」的怪兽装备。
INSERT INTO "texts" VALUES ('ZZ101104', '不死之心', '只有不死族怪兽可以装备。①：1回合1次，装备怪兽与攻击力比自身高的怪兽进行战斗的回合的结束阶段，或者有将装备怪兽破坏的效果发动过的回合的结束阶段可以发动，给予对方装备怪兽的攻击力数值的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101105', '卡通艾亚托斯', '自己场上有「卡通世界」时才能特殊召唤上场。「卡通世界」破坏时这张卡破坏。对方场上不存在卡通怪兽的场合这张卡可以直接攻击，当我方墓地存在1张以上名字带有「卡通」的卡片时，这张卡可以不用祭品特殊召唤上场，此卡召唤成功时可以从卡组或手牌墓地将1张「女神的圣剑」发动并装备，当「女神的圣剑」从场上离开时，将对方墓地全部怪兽移除到游戏外，此卡的攻击力上升被除外怪兽总和的攻击力。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101106', '原始昆虫 刀手螳螂', '1回合1次，破坏对方两张手牌。
INSERT INTO "texts" VALUES ('ZZ101107', '原始昆虫 蚊母之卵 LV1', '
INSERT INTO "texts" VALUES ('ZZ101108', '原始昆虫 甲虫蜥蜴兽', '可选择对方2只怪兽装备在此卡上。
INSERT INTO "texts" VALUES ('ZZ101109', '原始昆虫 草蜢青蛙兽', '此卡可以丢弃1张手牌，从手牌特殊召唤。
INSERT INTO "texts" VALUES ('ZZ101110', '原始昆虫 虫国蚊母', '4星昆虫族怪兽×2
INSERT INTO "texts" VALUES ('ZZ101111', '原始昆虫 沙地龙', '7星昆虫族怪兽×2
INSERT INTO "texts" VALUES ('ZZ101112', '原始昆虫 狂野蜈蚣兽', '调整＋调整以外的昆虫族怪兽1只
INSERT INTO "texts" VALUES ('ZZ101113', '原始昆虫 虫王之卵 LV1', '
INSERT INTO "texts" VALUES ('ZZ101114', '原始昆虫 虫王之卵 LV2', '解放此卡送入墓地可从墓地特殊召唤1只5星以下的怪兽。将场上的「原始昆虫 虫王之卵 LV1」解放，此卡可从手牌特殊召唤。
INSERT INTO "texts" VALUES ('ZZ101115', '原始昆虫 虫王之卵 LV3', '解放此卡送入墓地可从墓地特殊召唤1只8星以下的怪兽。将场上的「虫王之卵 LV2」解放，此卡可从手牌特殊召唤。
INSERT INTO "texts" VALUES ('ZZ101116', '原始昆虫 蚊母之卵 LV2', '战斗破坏时，与其战斗的对方怪兽同时破坏。
INSERT INTO "texts" VALUES ('ZZ101117', '原始昆虫 蚂蚁蜗牛兽', '可得到对方1只怪兽的控制权。
INSERT INTO "texts" VALUES ('ZZ101118', '原始昆虫 自然搬运工', '1回合1次，手牌5张以下时从卡组抽取到5张。
INSERT INTO "texts" VALUES ('ZZ101119', '原始昆虫 巫师毛虫', '1回合1次，破坏场上1张魔法、陷阱卡。
INSERT INTO "texts" VALUES ('ZZ101120', '原始昆虫 箭手蚂蚁', '1回合1次，指定对方1只怪兽不能攻击。
INSERT INTO "texts" VALUES ('ZZ101121', '原始昆虫 贪吃蛤蟆', '1回合1次，从卡组将1只5星以下的名字带有「原始昆虫」的怪兽特殊召唤上场。
INSERT INTO "texts" VALUES ('ZZ101122', '原始昆虫 树椿防线', '对方攻击力1000以上的怪兽不能攻击。
INSERT INTO "texts" VALUES ('ZZ101123', '原始昆虫 反射之镜', '对方怪兽的攻击宣言时才能发动。把1只对方怪兽的攻击无效，给予对方生命值那只怪兽的攻击力数值的伤害。
INSERT INTO "texts" VALUES ('ZZ101124', '原始昆虫 生命之果', '除外场上1只怪兽，生命值回复那只怪兽攻击力数值。
INSERT INTO "texts" VALUES ('ZZ101125', '原始昆虫 麻药狂蜂', '1回合1次，指定1只怪兽攻击力变为0。
INSERT INTO "texts" VALUES ('ZZ101126', '原始昆虫 树洞', '1回合1次，对方怪兽攻击时，除外我方1只怪兽，下一回合返回场上攻击力、守备力加倍。
INSERT INTO "texts" VALUES ('ZZ101127', '原始昆虫 蚊子孵化', '将场上「蚊母之卵 LV1」全部破坏，每破坏1只可以从卡组召唤1只「蚊母之卵 LV2」。
INSERT INTO "texts" VALUES ('ZZ101128', '原始昆虫 虫街', '不会被卡的效果破坏，对方不能发动名字带有「虫街」以外的场地魔法。伤害计算时，对方伤害加倍，我方伤害减半。1回合1次，对方1张卡效果发动无效。
INSERT INTO "texts" VALUES ('ZZ101129', '原始昆虫 战神虫王', '「原始昆虫 箭手蚂蚁」+「原始昆虫 刀手螳螂」
INSERT INTO "texts" VALUES ('ZZ101130', '原始昆虫 投石沙虫', '1回合1次，破坏场上1只怪兽。
INSERT INTO "texts" VALUES ('ZZ101131', '上古邪眼', '名字带有「上古」的卡不会被名字带有「上古」以外的怪兽战斗破坏，也不受名字带有「上古」以外的怪兽效果影响。只要此卡攻击表示存在场上，对方就不能发动魔法卡。当这张卡从场上离开时，从卡组选择1张名字带有「上古」的等级4以下怪兽加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101132', '上古海盗', '名字带有「上古」的卡不会被名字带有「上古」以外的怪兽战斗破坏，也不受名字带有「上古」以外的怪兽效果影响。当这张卡从场上离开时，可以将卡组里「上古海盗」尽可能多的特殊召唤。因此效果召唤的「上古海盗」攻击力提升1500点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101133', '上古美杜莎', '名字带有「上古」的卡不会被名字带有「上古」以外的怪兽战斗破坏，也不受名字带有「上古」以外的怪兽效果影响。反转：对方场上所有怪兽2个回合内不能攻击，改变表示形式，不能作祭品，受到的战斗伤害为0，战斗破坏适用。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101134', '上古剑齿虎', '名字带有「上古」的卡不会被名字带有「上古」以外的怪兽战斗破坏，也不受名字带有「上古」以外的怪兽效果影响。这张卡和等级4以下名字带有「上古」以外的怪战斗时，不进行战斗伤害直接破坏那只怪兽。当这张卡从场上离开时，可以作为装备卡装备给我方1只名字带有「上古」的怪兽，装备怪兽攻击力提升这张卡的攻击力数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101135', '上古半兽法师', '名字带有「上古」的卡不会被名字带有「上古」以外的怪兽战斗破坏，也不受名字带有「上古」以外的怪兽效果影响。这张卡的攻击力为我方魔法陷阱区卡片数量×600的数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101136', '上古恶魔', '名字带有「上古」的卡不会被名字带有「上古」以外的怪兽战斗破坏，也不受名字带有「上古」以外的怪兽效果影响。这张卡不能在「上古」以外的卡片效果下特殊召唤。这张卡的原本攻击力小于4000点时才可以发动攻击宣言，每当我方受到生命值伤害时，下降此卡攻击力那个生命值伤害的数值，让我方的生命值伤害变为0。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101137', '上古红龙', '这张卡不能特殊召唤，只能用名字带有「上古」的的怪兽3只以上作祭品通常召唤。名字带有「上古」的卡不会被名字带有「上古」以外的怪兽战斗破坏，也不受名字带有「上古」以外的怪兽效果影响。对方发动以此卡为对象的卡效果时必须先支付1000点生命值，否则无法发动，当此卡在场，对方攻击阶段时所有怪兽必须攻击，否则强制结束对方回合。从召唤回合开始计算，此卡在我方场上存在5个回合我方获得这场决斗的胜利。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101138', '上古半兽人', '名字带有「上古」的卡不会被名字带有「上古」以外的怪兽战斗破坏，也不受名字带有「上古」以外的怪兽效果影响。可以将手牌这张卡送入墓地，从卡组选择1张名字带有「上古半兽」的卡片加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101139', '上古奇美拉', '名字带有「上古」的卡不会被名字带有「上古」以外的怪兽战斗破坏，也不受名字带有「上古」以外的怪兽效果影响。这张卡的祭品素材存在名字带有「上古」以外的怪兽的场合，这张卡的攻击力下降2000点。这张卡攻击对方怪兽时，直到伤害计算结束阶段对方不能发动魔法·陷阱卡。让对方发动名字带有「上古」以外的魔法·陷阱卡时，可以降低此卡500点攻击力，让那张卡发动无效并破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101140', '上古地狱蝙蝠', '名字带有「上古」的卡不会被名字带有「上古」以外的怪兽战斗破坏，也不受名字带有「上古」以外的怪兽效果影响。当对方发动卡片效果时，可以将手牌的这张卡送入墓地让那个效果发动无效并破坏，之后从我方墓地里选择2张除此卡外名字带有「上古」的卡片加入手牌并洗牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101141', '上古鹰身女妖', '名字带有「上古」的卡不会被名字带有「上古」以外的怪兽战斗破坏，也不受名字带有「上古」以外的怪兽效果影响。此卡只能以攻击表示存在于场上，当此卡表示形式变更时，此卡破坏。当我方生命值低于3000点时，此卡可以直接攻击对方玩家生命值，当这张卡从场上离开时，将我方墓地1张名字带有「上古」的卡片加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101142', '上古魔鱼', '名字带有「上古」的卡不会被名字带有「上古」以外的怪兽战斗破坏，也不受名字带有「上古」以外的怪兽效果影响。当我方场上不存在名字带有「上古」的怪兽时，此卡可以从手牌特殊召唤。1回合1次，此卡不会被战斗破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101143', '上古牛头人', '名字带有「上古」的卡不会被名字带有「上古」以外的怪兽战斗破坏，也不受名字带有「上古」以外的怪兽效果影响。这张卡不能在名字带有「上古」以外的卡片效果下特殊召唤。只要这张卡攻击表示就必须攻击，每当这张卡直接攻击对方生命值成功时，这张卡攻击力下降500点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101144', '上古飞龙·雌', '名字带有「上古」的卡不会被名字带有「上古」以外的怪兽战斗破坏，也不受名字带有「上古」以外的怪兽效果影响。当我方场上存在「上古飞龙·雄」时，对方不能选择这张卡为攻击目标。当我方场上「上古飞龙·雄」给予对方造成战斗伤害时，这张卡的攻击力提升那个战斗伤害的数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101145', '上古飞龙·雄', '名字带有「上古」的卡不会被名字带有「上古」以外的怪兽战斗破坏，也不受名字带有「上古」以外的怪兽效果影响。当我方场上存在「上古飞龙·雌」，这张卡战斗破坏对方怪兽时，给予对方玩家追加此卡攻击力的生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101146', '上古绝对防御战士 杰瑞', '名字带有「上古」的卡不会被名字带有「上古」以外的怪兽战斗破坏，也不受名字带有「上古」以外的怪兽效果影响。此卡正面守备表示在场上时，每个我方回合的准备阶段，我方回复500点生命值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101147', '上古魔纹黑法师 特拉斯', '名字带有「上古」的卡不会被名字带有「上古」以外的怪兽战斗破坏，也不受名字带有「上古」以外的怪兽效果影响。此卡必须将场上2只名字带有「上古」的怪兽作祭品才能召唤到场上。此卡召唤成功时，破坏对方场上所有覆盖的卡，给予对方被破坏卡片数量×500点的生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101148', '上古花之精灵 莉莎', '名字带有「上古」的卡不会被名字带有「上古」以外的怪兽战斗破坏，也不受名字带有「上古」以外的怪兽效果影响。此卡从场上离开时，可以选择墓地1张除此卡以外名字带有「上古」的卡片加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101149', '上古末日甲虫之茧', '名字带有「上古」的卡不会被名字带有「上古」以外的怪兽战斗破坏，也不受名字带有「上古」以外的怪兽效果影响。这张卡召唤成功的第3个我方回合准备阶段，将这张卡送入墓地，从我方卡组·墓地特殊召唤1只「上古末日甲虫」。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101150', '上古猎魔人 爱丽丝', '名字带有「上古」的卡不会被名字带有「上古」以外的怪兽战斗破坏，也不受名字带有「上古」以外的怪兽效果影响。1回合1次，将我方场上1只名字带有「上古」的怪兽送入墓地，此卡攻击力提升那只怪兽的攻击力的一半数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101151', '上古龙王', '名字带有「上古」的卡不会被名字带有「上古」以外的怪兽战斗破坏，也不受名字带有「上古」以外的怪兽效果影响。这张卡不能通常召唤，我方场上有3只名字带有「上古」的怪兽的场合才能特殊召唤，我方场上正面表示存在的怪兽只有龙族的场合，可以把我方墓地1只龙族怪兽从游戏中除外，魔法·陷阱卡的发动无效并破坏。这个效果1之后只能使用1次。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101152', '上古战争', '这张卡不会被名字带有「上古」以外的魔法·陷阱卡破坏或无效。将我方墓地1只5星的怪兽从游戏中除外，对方回合结束。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101153', '上古神殿', '这张卡不会被名字带有「上古」以外的魔法·陷阱卡破坏或无效。只要这张卡存在场上，双方不能特殊召唤名字带有「上古」以外的怪兽，每当我方生命值发生变化时，这张卡增加1个「上古指示物」，去除1个「上古指示物」，可以从手牌·墓地特殊召唤1只名字带有「上古」的怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101154', '上古的监视', '这张卡不会被名字带有「上古」以外的魔法·陷阱卡破坏或无效。当对方发动攻击宣言时，我方场上存在「上古邪眼」，此卡才能发动，对方场上所有怪兽卡攻击力下降「上古邪眼」守备力数值。下降后的攻击力比「上古邪眼」守备力低则对方怪兽卡全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101155', '上古武器箱', '这张卡不会被名字带有「上古」以外的魔法·陷阱卡破坏或无效。选择我方墓地最多5张名字带有「上古」的卡片加入手牌，并从手牌选择3张卡加入卡组并洗牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101156', '上古十字弓', '这张卡不会被名字带有「上古」以外的魔法·陷阱卡破坏或无效。当对方发动魔法·陷阱卡时可以发动，让那张卡的发动无效并破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101157', '上古火器', '这张卡不会被名字带有「上古」以外的魔法·陷阱卡破坏或无效。此卡只能装备在名字带有「上古」的怪兽上，装备怪兽1回合1次可以直接攻击对方玩家生命值，这个效果使用3次后此卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101158', '上古五彩神石', '这张卡不会被名字带有「上古」以外的魔法·陷阱卡破坏或无效。名字带有「上古」的怪兽才能装备，装备怪兽的攻击力·守备力上升800点。此外，此卡被送去墓地时给予对方500点生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101159', '上古宝箱', '这张卡不会被名字带有「上古」以外的魔法·陷阱卡破坏或无效。
INSERT INTO "texts" VALUES ('ZZ101160', '上古之奋力抗争', '这张卡不会被名字带有「上古」以外的魔法·陷阱卡破坏或无效。对方发动攻击宣言时可以发动，破坏对方场上正面攻击表示存在的怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101161', '上古之魔鶯雏子', '这张卡不会被名字带有「上古」以外的魔法·陷阱卡破坏或无效。选择我方墓地1只名字带有「上古」的怪兽特殊召唤到我方场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101162', '上古怨灵首饰', '上古七邪器之卡。
INSERT INTO "texts" VALUES ('ZZ101163', '上古怨灵智慧轮', '七邪器之卡。
INSERT INTO "texts" VALUES ('ZZ101164', '上古恶灵眼', '七邪器之卡。
INSERT INTO "texts" VALUES ('ZZ101165', '上古邪灵积木', '七邪器之卡。
INSERT INTO "texts" VALUES ('ZZ101166', '上古邪灵锡杖', '七邪器之卡。
INSERT INTO "texts" VALUES ('ZZ101167', '上古亡灵秤', '七邪器之卡。
INSERT INTO "texts" VALUES ('ZZ101168', '上古死灵钥匙', '七邪器之卡。
INSERT INTO "texts" VALUES ('ZZ101169', '上古猫战士', '名字带有「上古」的卡不会被名字带有「上古」以外的怪兽战斗破坏，也不受名字带有「上古」以外的怪兽效果影响。此卡召唤成功时，可以从我方墓地特殊召唤1只「上古猫战士」正面守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101170', '上古死神', '名字带有「上古」的卡不会被名字带有「上古」以外的怪兽战斗破坏，也不受名字带有「上古」以外的怪兽效果影响。只要对方场上不存在光·炎属性怪兽，这张卡不会被战斗破坏，受到的战斗伤害为0。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101171', '上古魔像', '名字带有「上古」的卡不会被名字带有「上古」以外的怪兽战斗破坏，也不受名字带有「上古」以外的怪兽效果影响。每当我方受到生命值伤害时，下降此卡守备力那个生命值伤害的数值，让我方的生命值伤害变为0，当此卡因这个效果守备力变为0时，给予对方4000点生命值伤害，此卡从游戏中除外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101172', '上古吸血鬼', '名字带有「上古」的卡不会被名字带有「上古」以外的怪兽战斗破坏，也不受名字带有「上古」以外的怪兽效果影响。这张卡战斗破坏对方怪兽送去墓地的场合，可以让破坏的1只怪兽在那个回合的结束阶段从墓地特殊召唤到我方场上，攻击力上升1000点并视作名字带有「上古」的怪兽使用。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101173', '上古独眼巨人', '名字带有「上古」的卡不会被名字带有「上古」以外的怪兽战斗破坏，也不受名字带有「上古」以外的怪兽效果影响。当我方场上名字带有「上古」的怪兽因为对方卡效果送入墓地时，可以将此卡送入墓地代替那张卡破坏，并在我方场上把2只「上古衍生物」（恶魔族·暗·1星·攻/守2000）守备表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101174', '上古衍生物', '由「上古」怪兽的效果特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101175', '上古半兽勇士', '名字带有「上古」的卡不会被名字带有「上古」以外的怪兽战斗破坏，也不受名字带有「上古」以外的怪兽效果影响。这张卡在攻击阶段必须攻击，当这张卡受到战斗伤害时给予对方那个数值的生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101176', '上古毒蘑', '
INSERT INTO "texts" VALUES ('ZZ101177', '上古嗜血巨人', '名字带有「上古」的卡不会被名字带有「上古」以外的怪兽战斗破坏，也不受名字带有「上古」以外的怪兽效果影响。从手牌将此卡以外的1张名字带有「上古」的卡送去墓地，此卡可以从手牌特殊召唤上场，用此特殊召唤成功的回合，我方不能发动攻击宣言。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101178', '上古巨猿', '名字带有「上古」的卡不会被名字带有「上古」以外的怪兽战斗破坏，也不受名字带有「上古」以外的怪兽效果影响。此卡被送去墓地时，给予对方500点生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101179', '上古杀人蜂', '名字带有「上古」的卡不会被名字带有「上古」以外的怪兽战斗破坏，也不受名字带有「上古」以外的怪兽效果影响。这张卡可以直接攻击对方玩家生命值。每当此卡直接攻击并给予对方造成战斗伤害时，此卡攻击力上升700点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101180', '上古巨毒蘑王', '名字带有「上古」的卡不会被名字带有「上古」以外的怪兽战斗破坏，也不受名字带有「上古」以外的怪兽效果影响。将我方手牌·场上名字带有「上古毒蘑」合计3只送入墓地，此卡才能召唤。此召唤当作通常召唤，这张卡只能用这个效果进行召唤，这张卡的召唤不会被无效化。以这张召唤成功后的回合计算，3个回合内，给予对方场上的怪兽数量×500的生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101181', '上古末日甲虫', '名字带有「上古」的卡不会被名字带有「上古」以外的怪兽战斗破坏，也不受名字带有「上古」以外的怪兽效果影响。当这张卡攻击表示存在于我方场上，我方怪兽区不受限制。每当我方1回合受到生命值伤害超过2000点时，可以从卡组特殊召唤1只「上古末日甲虫」。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101182', '上古魔泥浆', '名字带有「上古」的卡不会被名字带有「上古」以外的怪兽战斗破坏，也不受名字带有「上古」以外的怪兽效果影响。此卡被送去墓地时，可以选择对方场上1张魔法卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101183', '上古判官', '名字带有「上古」的卡不会被名字带有「上古」以外的怪兽战斗破坏，也不受名字带有「上古」以外的怪兽效果影响。我方墓地存在的名字带有「上古」的怪兽每有1只，这张卡的攻击力上升300点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101184', '上古九头鸟', '名字带有「上古」的卡不会被名字带有「上古」以外的怪兽战斗破坏，也不受名字带有「上古」以外的怪兽效果影响。这张卡在场上正面表示存在时，我方场上魔法·陷阱卡不会被卡的效果破坏，我方场上存在的魔法·陷阱卡每有1张，攻击力上升200点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101185', '上古骷髅', '名字带有「上古」的卡不会被名字带有「上古」以外的怪兽战斗破坏，也不受名字带有「上古」以外的怪兽效果影响。当此卡被破坏从场上离开时，可以选择卡组1张名字带有「上古」的怪兽卡加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101186', '奥利哈钢 奇甲斯', '此卡被送入墓地时，可以增加500点攻击力后将此卡特殊召唤到场上来（增加的攻击力可以叠加），此卡在场时，跳过自己抽牌阶段。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101187', '奥利哈钢 铁甲战士', '此卡每破坏对方场上1只怪兽，此卡攻击力上升400点。此卡离场时，将对方场上此卡攻击力除以700的数量的卡送入墓地，与此卡战斗的怪兽效果无效化。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101188', '奥利哈钢 奇达拉', '支付500点生命值可以特殊召唤此卡，限此卡在场，自己受到的伤害变为0，此卡不会被战斗破坏，当此卡因卡效果破坏时，可以从手牌·卡组·墓地特殊召唤1只「奥利哈钢 西洛诺斯」到自己场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101189', '奥利哈钢 暗黑破坏神', '可以让场上1只怪兽改变为攻击表示，此效果1回合可以发动1次。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101190', '奥利哈钢 赫洛奈斯', '每当准备流程时，给予对方场上名字带有「奥利哈钢」的怪兽数量乘以400的伤害。当自己场上存在这张卡以外的名字带有「奥利哈钢」的怪兽时，对方不能选择此卡为攻击对象。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101191', '奥利哈钢 眼', '此卡攻击力上升场上攻击力最高的怪兽的原本攻击力x2，此卡被效果破坏时，可以舍弃1张手牌代替破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101192', '奥利哈钢 亚力克斯', '此卡召唤·反转召唤·特殊召唤时，场上每有1只怪兽恢复自己500点生命值。此卡宣告战斗时，可以改变攻击对象的表示形式。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101193', '奥利哈钢 莱克乌斯', '此卡破坏时，我方受到的伤害为0，对方生命值变为1，不能通过其他效果恢复。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101195', '奥利哈钢 梦拉克斯', '反转：得到对方场上1只怪兽的控制权，得到的怪兽攻击力与守备力上升500点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101196', '奥利哈钢 圣母EX', '此卡不能通常召唤。可以将自己场上3只名字带有「奥利哈钢」的怪兽送入墓地特殊召唤。只要此卡在场上，名字带有「奥利哈钢」的怪兽不受对方效果影响同时此卡攻击力上升1000。每当自己主要阶段时在自己场上特殊召唤1只奥利哈钢圣母复制体 星4光 传说神兽族 攻0 守2500（对方不能攻击奥利哈钢圣母复制体以外的怪兽），可以将卡组中1只怪兽给对方看，此卡拥有那只怪兽的效果，此效果只能使用一次。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101197', '奥利哈钢 圣母复制体', '由「奥利哈钢 圣母EX」的效果特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101198', '奥利哈钢 姆达兹', '只要此卡在场上，战斗流程时对方不能召唤怪兽卡和发动魔法·陷阱，此卡给予对方战斗伤害时，给予对方500点伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101199', '奥利哈钢第五层结界守护阵', '●当此卡在手牌时可以将「奥利哈钢第四层结界控神阵」加入手牌，此卡与名字带有「奥利哈钢」的魔法卡共同占用场地魔法区域。
INSERT INTO "texts" VALUES ('ZZ101201', '原始奥利哈钢之神', '由「达姿的仪式」或「奥利哈钢之圣都 亚特兰提斯」的效果特殊召唤。每破坏一只怪兽，给予对方伤害等于破坏怪兽的原本攻击力的2倍再加200点。支付1000点生命值，可以破坏对方场上全部怪兽。此卡不受魔法·陷阱·效果的影响，召唤回合结束时，将「达姿的第二仪式」加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101202', '奥利哈钢之魂 ', '此卡不能通常召唤。当我方场上「奥利哈钢之神」从场上离开或将我方场上「奥利哈钢之神」献祭可将此卡从手牌·卡组·墓地·游戏外特殊召唤上场。此卡的名字和效果视作「奥利哈钢之神」。限此卡在场跳过我方抽牌阶段，对方场上所有怪兽效果无效，只要我方卡组存在怪兽此卡便不会被破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101203', '反射镜的仪式', '手牌·场上的怪兽，合计4星以上的怪兽送入墓地，从手牌·卡组特殊召唤「奥利哈钢镜子骑士」1只。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101204', '奥利哈钢镜子骑士', '使用「反射镜的仪式」降临。限此卡在场上我方不受召唤怪兽数量限制，并获得以下效果：●特殊召唤「镜子骑士复制体」（战士族·1星·攻/守0）最多4只。●此卡在场，「镜子骑士复制体」不会战斗破坏。此卡在场时，「镜子骑士复制体」只有1次战斗不会被破坏。●「镜子骑士复制体」进行战斗时，其攻击力变成战斗对象的攻击力数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101205', '镜子骑士复制体', '由「奥利哈钢镜子骑士」的效果特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101207', '奥利哈钢 西洛诺斯', '此卡只能通过「奥利哈钢 奇达拉」的效果特殊召唤，此卡的攻击力是「奥利哈钢 奇达拉」所吸收的伤害值。此卡成功召唤时，从手牌·卡组·墓地特殊召唤「奥利哈钢 西洛诺斯右腕」和「奥利哈钢 西洛诺斯左腕」各一只到自己场上，此卡在场时，「奥利哈钢 西洛诺斯右腕」、「奥利哈钢 西洛诺斯左腕」不会被破坏，此卡进行战斗场合，伤害计算结束时，此卡攻击力下降对手怪兽攻击数值。此卡攻击为0时，可以舍弃全部手牌并支付10000点生命值，从手牌·卡组特殊召唤1只「奥利哈钢 蛇神彝」。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101208', '奥利哈钢 西洛诺斯右腕', '此卡只能通过「奥利哈钢 西洛诺斯」的效果特殊召唤，只要场上存在「奥利哈钢 西洛诺斯」此卡不会被破坏，此卡攻击力与守备力和对方怪兽战斗1次就增加对方怪兽攻击力300点的数值。伤害计算结束时，「奥利哈钢 西洛诺斯」的攻击力下降对方怪兽攻击力的数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101209', '奥利哈钢 西洛诺斯左腕', '此卡只能通过「奥利哈钢 西洛诺斯」的效果特殊召唤。只要场上存在「奥利哈钢 西洛诺斯」此卡无法攻击。此卡攻击力和守备力会一直比对方怪兽攻击力高300点，可以代替自己怪兽不受对方怪兽攻击。伤害结束时，「奥利哈钢 西洛诺斯」的攻击力下降对方怪兽攻击力的数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101210', '奥利哈钢 蛇神彝', '此卡不能通常召唤，此卡只能通过「奥利哈钢 西洛诺斯」的效果特殊召唤，需将我方生命值归0才可召唤，此时我方战斗胜负不受生命值影响。同时舍弃所有手牌，此卡不受对方魔法·陷阱及效果怪兽效果影响。此卡在场上时对方怪兽不能改变攻击力。我方卡组最上方10张卡舍弃，此卡才可以发动攻击，只要此卡在场上自己不会被宣为战败，每当自己结束流程时给此卡放上一个黑暗指示物，当此卡的指示物达4个时，直接宣告胜利，此卡的效果不会被无效化。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101211', '奥利哈钢 杰斯拉克', '当自己场上名字带有「奥利哈钢」的怪兽战斗时，可以将手牌中的卡送入墓地，选择对方1只怪兽破坏，我方场上的1只怪兽攻击力上升对方1只怪兽的攻击力。此卡在墓地时，我方场上的怪兽攻击力上升500点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101212', '奥利哈钢之神', '将由「达姿的仪式」降临。此卡召唤不会被无效化，限此卡在场上对方魔法·陷阱卡的发动和效果无效并被破坏。此卡攻击时破坏对方场上所有卡，当此卡被破坏时，对方宣告胜利。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101213', '双弓人马兽', '此卡在场上，每回合指定我方和对方怪兽1只，我方进行1次投掷硬币得到以下效果：
INSERT INTO "texts" VALUES ('ZZ101215', '奥利哈钢-支配者的庇护', '这张卡不能通常发动。对方发动卡的效果或对怪兽通常召唤成功时，这张卡从卡组发动。
INSERT INTO "texts" VALUES ('ZZ101223', '女子佣兵 弓弩者', '此卡被作为祭品时，被召唤出来的怪兽效果无效，可以直接攻击对方生命值，且不受对方任何卡片效果影响。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00049', '王之名字 亚图姆', '国王的记忆王之名。可以用来召唤之用。自己场上如果出现了这张卡我方的任何怪兽的攻守各增加1000点。对方在一回合不能发动攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101224', '遗失七神器的石板', '此卡与七神器卡同时在手牌／场上／墓地集齐时，可召唤出『国王记忆的石板』。获得无穷的力量。之后此八张卡从游戏除去，我们战斗胜利。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101226', '暗黑青眼究极龙', '「青眼白龙」+「青眼白龙」+「青眼白龙」
INSERT INTO "texts" VALUES ('ZZ101227', 'E·HERO 波涛新生侠', '「E·HERO 新生侠」+「E·HERO 羽翼侠」+「E·HERO 泡泡侠」
INSERT INTO "texts" VALUES ('ZZ101228', '奥西爆裂剑芒', '对方使用名字带有「奥西里斯」的卡片时，此卡从卡组/手牌/场上/墓地/除外区发动。对方场上卡片和手牌效果无效同时全部破坏，对方生命值变为100点。这张卡不会被无效和破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101229', '火神·赫淮斯托斯', '此卡不能通常召唤。必须封印我方怪兽魔法陷阱卡区域合计5个区域，即可从手牌特殊召唤。1回合1次，从手牌1张怪兽卡从游戏中除外，即可封印对方怪兽魔法陷阱卡区域合计2个区域。此卡被破坏时，场上所有封印区域解除，并给予对方封印区域合计×300点的生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101230', '海王·波塞冬', '此卡通常召唤的场合，必须把我方场上3只怪兽解放作召唤。此卡召唤不会被无效化。此卡召唤成功时，破坏对方场上所有魔法·陷阱卡。此卡被战斗破坏送去墓地时，给予对方800点的生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101231', '天帝·宙斯', '此卡通常召唤的场合，必须把我方场上3只怪兽解放作召唤。此卡召唤不会被无效化。此卡召唤成功时，此卡不能成为效果怪兽·魔法·陷阱卡的对象。此卡每当我方抽牌阶段时给予对方500点的生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101232', '智慧女神·雅典娜', '此卡通常召唤的场合，必须把我方场上3只怪兽解放作召唤。此卡召唤不会被无效化。此卡召唤成功时，此卡不能成为效果怪兽·魔法·陷阱卡的对象。此卡每当我方抽牌阶段时给予对方500点的生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101233', '冥王·哈迪斯', '此卡通常召唤的场合，必须把我方场上3只怪兽解放作召唤。此卡召唤不会被无效化。此卡召唤成功时，我方墓地存在的暗属性怪兽每有1只，此卡攻击力·守备力上升300点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101234', '狩猎女神·阿尔忒弥斯', '此卡召唤成功时，破坏对方场上1只怪兽。此卡在场上正面表示存在时，对方抽卡阶段如果抽出的是怪兽卡，则直接送入墓地并给予对方500点的生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101235', '太阳神·阿波罗', '此卡在通常召唤·特殊召唤成功时，给予对方500点的生命值伤害。此卡存在场上时，对方效果怪兽的效果无效化。此卡被战斗破坏送入墓地时，可以从手牌特殊召唤1只6星以下怪兽到场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101236', '大地女神·德墨忒尔', '当我方生命值低于1000点时，可以从手牌特殊召唤到场上。此卡在场上正面表示存在时，我方没有手牌数量限制，每回合依照手牌数量×600点回复我方生命值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101237', '天后·赫拉', '此卡不能成为效果怪兽·魔法·陷阱卡的对象。1回合1次，将对方1只怪兽的攻击无效化。此卡被战斗破坏送去墓地时，转变成装备魔法卡，装备在对方场上1只怪兽，该怪兽攻击力·守备力下降1000点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101238', '三国传-马超', '这张卡被卡的效果从手牌丢弃去墓地的场合，这张卡从墓地特殊召唤。这个效果特殊召唤成功时，对方场上的全部怪兽或者全部魔法·陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00334', '机械马', '
INSERT INTO "texts" VALUES ('TSK00323', '岩石龙', '传说中的岩石龙，以身上发出的岩石攻击对方，其攻击力无法估计。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00320', '诅咒之鹰', '邪恶的飞鹰会以天山的白云将一切变成邪恶之气，是遭到诅咒的鹰。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00313', '骷髅兽', '会放出有剧毒的毒气攻击敌人的不死族怪兽，喜欢在荒野游荡，所到之处花草树木都会枯萎。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00286', '灵魂的石像', '拥有龙族魂魄，系出名门的石像战士。当你以为它只是普通石像时，会突然以最自豪的岩石把你炸到粉身碎骨。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00277', '梦幻青龙', '生活在梦幻世界的青龙，能从梦幻世界中引发黑暗的大王来攻击对手。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00176', '异星战士β', '存在异星体上的超能力战士，只为正义而战的精神永不改变。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00170', '异星战士Α', '存在异星体上的超能力战士，只为正义而战的精神永不改变。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00166', '大地精灵兽', '时刻守护着苍苍大地的精灵，会变化成无数森林的隐身绝技。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00165', '异型铠装龙', '黑暗冥界最底层的守卫，凶残的性格和火暴的脾气让人不敢接近。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00158', '突袭者思理克', '矮小的身体是最好的伪装，当敌人靠近就会给它狠狠的一击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00157', '冥王卫兵相扑精灵', '力大无穷，身形壮硕的精灵战士，是冥王的忠心卫兵。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00154', '冥王卫兵铠力格', '全身铠装的战斗型精灵。冥王的近战护卫，日夜不息守护冥王的忠士。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00153', '野蛮鹰嘴魔', '当天际混沌之时出现的怪兽，拥有牛般的力气和鹰般的敏锐。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00164', '大嘴怪', '头上的吸管是强有力的吸盘，能牢牢地捉住狩物，入触须般密密麻麻的脚使它的行动更加快捷，是逃命的最佳工具。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00135', '精灵王子', '调皮捣蛋的小王子，老是喜欢捉弄人。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00103', '岩之战士', '手拿利剑的岩石战士，肩负保护岩石族不被侵犯的神圣使命。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00068', '控制火之恶灵', '全身以灼热的火焰包围着，能自由自在地操纵火海与火墙进行攻击，一旦被它碰到的话，就会找到严重的灼热。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00067', '利爪魔神', '长有翅膀的牛头恶魔，瑞丽的爪子能在一瞬间将敌人撕得粉碎。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00066', '前锋机械战将', '巨大的机械枪已经成为身体的一部分，善战的个性，总在战斗时冲锋陷阵，快速取得胜利。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00065', '森林之子玛洛', '居住在野兽出没的森林里，以神秘的魔法控制野兽，平时性格十分温和，一旦破坏它的宁静，就会毫不留情的攻击你。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00062', '魔鬼的刀斧', '沉睡魔鬼的刀斧，一旦被主人唤醒，能发挥无法想象的威力。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00061', '迷惑烟雾', '住在密林里的美丽精灵，能让手上的烟释放浓密的烟雾使敌人视线模糊，再将它们一一解决。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00031', '双角蜥蜴', '守卫上坡的蜥蜴，正专心的看守着山城。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00012', '咆哮的绿龙', '会以大嘴巴朝向四面八方喷火，发出如雷的咆哮声十分刺耳，让人无从适应。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00011', '森林守护士兵', '居住在森林深处神出鬼没的守护着森林。场上每存在一张正面显示的植物族，本身攻击力就增加100点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00007', '炎兽兵·布鲁士', '体内蕴藏着无穷火焰的巨兽，威力一般，但潜在力量很强大。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00004', '黑炎恶龙', '栖息在黑暗深处的龙，拥有单独的脚，小心它锋利的爪子！', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00023', '恶魔的源头', '将正面表示并存在于自己领域的恶魔族怪兽破坏，然后可以从手中的卡片传唤与破坏数量相同的恶魔族怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00024', '黑暗能量', '提高恶魔族1头怪兽的攻击力、守备力各500点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00027', '火龙炮', '双方存在战场上的水属性怪兽都会被破坏，但我方场上的炎属性怪兽守备力都增加500点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00041', '光之宫殿', '只有级别在6级以下的兽战士族怪兽才能进行武装。武装的怪兽的攻击力和防守力都增加1500分。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00133', '千年之盾', '支付1000点生命点，可察看对方的手牌，并可以从里面选出一张卡片丢进墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00168', '冥界之光', '自己场上的“暗”属性的怪兽攻击力、守备力增加300点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00171', '封印的圣经', '对手抽牌时发动，将对手手牌中和场上“暗”属性、7级以下的两只怪兽送往墓地，此回合结束前不能被召唤或特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00173', '超强装备', '装备此卡的怪兽攻击力增加400点：
INSERT INTO "texts" VALUES ('TSK00285', '光速的战斗', '从对方墓地剔除两张怪物卡片，往后该卡片无法在同一场对决中使用。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00017', '火焰圣域', '自己墓地存在有20张以上的卡片时可发动，会给对手2000点生命点的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00020', '使从格来臣', '此卡只能在主要阶段发动，发动后变成怪兽卡（兽族 地 3星 攻 1000   守 800）。可持续召唤到怪兽区（也可当成陷阱卡使用）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00025', '滑降妖精咖拉波', '丢下手中的一张牌，破坏自己手中的一只怪兽，将对方场上一只四星级以上作攻击状态的怪兽从游戏中清除。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00038', '充满利器的洞穴', '当对方攻击我方攻击力1000以上的怪兽时，就可把对方的怪兽送墓地，对手的生命值也受到500点的损伤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00054', '坚不可摧', '只要这张卡片还存在，就可让指定的一只怪兽无法攻击也无法变更显示形式。当指定的怪物被破坏时，此卡也会破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00119', '特殊的对抗', '丢弃一张手牌。正面表示存在于场上的永续魔法卡全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00121', '风暴大龙卷', '丢掉自己场上的两张魔法卡，使魔法发动无效，并且加以破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00122', '虔诚的海龙兽', '对方以怪兽攻击我方时，破坏对方所有呈攻击表示的怪兽。回合结束后，此卡送往墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00325', '成功算出', '把对手从融合底牌融合的 2 个随机怪兽送往墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00044', '红蓝兵战', '当对方使用能破坏陷阱的魔法、陷阱、效果怪兽时，可由这张卡片为替身被破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00039', '石岩的城堡', '在发动的回合里让一只怪兽的攻击力增加1000点。让对手陷入黑暗当中，进行攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00138', '魔光沼泽地', '只要这张卡存在场上以正面表示，就能让所有魔法卡片的效果发动无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00152', '邪恶附身', '只要此卡存在场上并正面表示，给对手场上光、水、炎属性的张数总和x300点的打击。对手在这一回合内不能发动陷阱卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00327', '开辟天门', '将对手场上的一只怪兽破坏后，从我方场上选出一只怪物，并将其控制权交给对手。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00034', '森林', '将场地变成密集的森林，能让植物、昆虫、不死族的攻击力与守备力各提升500点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00367', '魂之吞噬', '当对手进行攻击宣言时可以发动，可以直接得到对方的控制权。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00026', '小天使玛琪', '此卡可使装备上的天使族攻击力、守备力各增加1000点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00032', '黑炎双面龙', '宇宙诞生时产生的龙。以双面黑炎龙为目标的魔法卡，陷阱卡都将被破坏并抵消其效果。可让墓地里的一只怪兽复活。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00033', '黑炎龙杰克', '传说中以非常高的攻击力著称的龙，任何对手都可以打败，其破坏力无法估计。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00057', '燃烧人 使比库特', '每到一处地方，都带着熊熊烈火的燃烧人，四处寻找对手，并与之一决高下。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00064', '焰角兽', '火山王·亚夫斯西的跟随者，借着火山王的势力，到处挑衅生事，尖锐的火焰角能将任何东西挑起撕裂。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00072', '光之战士·奥发', '勇敢的正义神战士，挥剑速度有如音速一般的快，由于心中的强烈正义感。对一切邪恶的攻击毫不留情。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00100', '泉之妖精', '手捧装着泉水的神壶的妖精，一旦被她的泉水淋到，就会被腐蚀掉。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00101', '狩猎的魔人', '肩扛着锋利的大刀的魔人，正准备外出大开杀戒。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00104', '海之龙王', '拥有一口锋利的牙齿的海龙族之王，其破坏力极高，要小心它的尖牙。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00109', '舌鱼', '生活于黑暗的深海中的鱼，用它独有的长舌吞噬攻击它的对手。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00111', '钢铁的巨神像', '因为身体是铜铁的体系守备相当高，以粗大的手臂攻击敌人。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00113', '地雷兽', '眉开眼笑的地雷兽，背部装着三根避雷针。具有探测地雷的特殊能力。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00126', '绿树的灵王', '居住在长满翠绿茂密的森林里，温和且崇尚生命的植物之王。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00127', '水之女郎', '能将水变成冰箭攻击敌人的美丽大姐。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00131', '灼热蝙蝠兽', '被熊熊烈火燃烧的蝙蝠兽，听力极好。大大的耳朵能够听到遥远的地方传来的声音。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00132', '迷你小丑', '外表精灵古怪的小丑，总是喜欢躲在暗处攻击敌人。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00141', '月光女战士', '目光犀利的女将，她手上的宝剑是战胜一切敌人的最厉害的武器。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00150', '冥王卫兵大斧精灵', '手持大斧的精灵战士，是冥王的忠心卫兵。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00159', '冥王卫兵长矛精灵', '手持长矛的精灵战士，是冥王的忠心卫兵。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00174', '巨人西鲁巴', '巨大的身体让敌人无法轻视，双手可变成橡皮般柔韧缠住敌人并窒息。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00225', '愤怒的猛虎', '曾经在公园里玩耍的普通虎，在黑暗势力的作用下变得凶暴起来。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00241', '飞天龙', '传说中的龙，以超高攻击力而自豪，怎样的对手都可以完全打败，它的破坏力无法估计。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00254', '水晶龙', '原本是邪恶的水晶龙，后来遇到一位世外高人，被他点化，从此正义的力量在心中醒来。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00022', '吸入能量装置', '将存在于自己墓地的具有级别的2只怪兽加到自己的卡组。重新洗牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00229', '邪恶的灵魂', '扔掉手中的1张牌，在发动轮的最终场为止，让场上表侧表示存在的怪兽每只的攻击力增加 1500 点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00398', '堕入黑暗的天使', '臣服于黑暗的天使，只是一副杀人的傀儡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00269', '金银双龙', '传说中以非常高的攻击力的鸟，一旦生气就发出刺耳尖叫。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00236', '大力神·士迦拉', '传说中以非常高的攻击力著称的大力神，任何对手都可以打败，其破坏力无法估计。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00037', '究极恶魔火龙', '「恶魔龙」＋「恶魔龙」＋「恶魔龙」＋「恶魔龙」
INSERT INTO "texts" VALUES ('TSK00052', '光之创造神-赫尔阿克帝', '「只能以融合召唤来特殊召唤，自己付出1000点的生命值，以三幻神「太阳神」「天空龙」「巨神兵」和友谊的团结之力，在「王之名」下进行召唤。一旦被召唤出来，手牌和牌堆里四颗星以上的怪兽都送往墓地里永久不能使用。任何敌人都会在一瞬间破坏殆尽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00053', '黑暗大邪神-佐克·内洛法', '被封印在石板上的大邪神，集齐七件千年宝物「千年积木」「千年秤」「千年锡杖」「千年首饰」「千年眼」「千年锁匙」「千年智慧轮」和「遗失七神器的石板」当仪式的祭品才可召唤。此卡和地·水 ·炎·风·暗属性的怪兽战斗绝对会胜利。他是暗黑的霸主，威力无比。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00129', '卡通小精灵', '必须从场地或手牌中，献上星星数合计8个以上的祭品才能召唤。成功召唤此卡时，对手场上的魔法卡全部被破坏。破坏对手一只攻击力2000点以上的炎属性怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00002', '加沙里阿斯统·龙', '此卡片的攻击力为自己墓地存在的怪兽卡数×300的数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00005', '黑炎兽斯多克', '战场上存在该卡以外的炎属性的怪兽时，每张卡的攻击力将增加500分。每当该卡片以外的炎属性怪兽被送到墓地时，都将使对手损失200分。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00008', '红眼海怪', '拥有闪亮的大红眼睛的红眼海怪，能够喷出黑色的火焰，将映入眼中的一切烧尽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00009', '喷毒气的海星', '当对手领域存在有守备表示怪兽时，此卡片可直接攻击对手玩家。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00010', '幻想魔女卡秋阿', '自己墓地中有一只恶魔族的怪兽时，此卡的攻击力上升300点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00015', '远航归来的红精灵', '只要这张卡出现在场上，可以让墓地里的一致怪兽回到战场上。当此卡对对方造成损伤时，可从自己的牌组里抽出一张卡片。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00029', '昆虫王托拉斯', '需献祭一只光属性的怪兽才可以召唤此怪兽出现。场上每只光属性的怪兽能使此卡的攻击力增加300点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00030', '火焰真龙', '这张卡不能通常召唤，在场上存在时魔法发动无效，并且破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00035', '愤怒的火焰人兽', '藉由火焰活着的愤怒人兽，有着强烈的怨恨，他所到之处都会被烧毁。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00036', '愤怒的人类', '他可以形成极大的幻象让人极度恐慌，从而进行攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00043', '独角羊', '此卡作为活祭品进行活祭品召唤时，可恢复我方1000点生命点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00045', '暗骑士迦拉', '自己墓地的魔法卡2张会从游戏中除去，在对手回合结束前，此卡片的攻击力会增加200点，此效果一回合可以使用一次。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00046', '暴虐虫莱特', '当昆虫族因遭到破坏送往墓地时，该卡可以从自己的领域中召唤一只攻击力为1500以上的昆虫族怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00047', '恶魔的灵魂', '可从自己墓地剔除2张恶魔族怪物做特殊召唤。此卡遭对手破坏送往墓地时，可在回合结束时当做装备卡装备在对手怪兽上，得到对方怪兽的控制权。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00050', '击神兵玛信咖', '在战斗中能发射具有超强杀伤力的火炎飞弹，破坏对手以献祭召唤来的更高级的怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00056', '拼装组合', '此牌只要存在场上的正面，不能发动陷阱卡，场上所有的陷阱卡都变为无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00071', '锐利的攻击', '献出场上三只怪兽作为祭品，召唤「锐利的攻击」，可将敌方场上所有的怪物破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00116', '金色的魔像', '此卡发动时，我方战场上的暗属性怪兽的攻击力和守备力增加1000点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00117', '蓝猫', '当这张卡片因战斗而被送往墓地时，可从牌组里召唤一只攻击力在1500以下的怪兽（不用祭品）。之后牌组进行洗牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00123', '黑暗怒猫', '此卡存在场上时，所有陷阱卡无法发动。支付300点的生命值，可以进行特殊召唤。此卡在战斗中可以破坏以防守表示的怪兽，被破坏的怪兽防守力减半。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00124', '黑魔术师', '此牌成功召唤·特殊召唤时，可以从自己的墓地中选择一只怪兽加入到自己的手牌中。在战斗中此牌破坏的怪兽被排除出游戏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK90130', '黑暗佐拉', '从异界召唤出来的单眼的恶魔！防守能力极高的恶魔族怪兽。战场上一只暗属性怪兽的攻击力提高 600 点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK90133', '魔界的战士', '当此卡片翻到正面时，对方场上设置的每一张魔法、陷阱卡都将让对方受到500点的损伤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00136', '狂暴盔甲兽', '对方场上存在一只怪兽，此卡片的攻击力就可上升500点。攻击守备表示的怪兽时，只要攻击力超过其守备力的话，超过的数值就可直接伤害对手的生命点数。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00137', '灰色灵象', '攻击以守备表达的此卡片之怪兽，若攻击力比这张卡片还低时，该攻击怪兽就会破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00142', '深海巨龙', '如果深海巨龙从场上配送往墓地的话，在该回合结束时深海巨龙会以攻击力与守备力皆为1000点的状态再度被特殊召唤到场上来。该效果在每次决斗中只能使用一次。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00143', '海上仙鹤', '使场上所有水属性怪兽的攻击力上升500点。炎属性怪兽攻击力降低400点。将我方场上的怪兽作为祭品，并以该怪兽攻击力的一半直接伤害对方。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK90144', '圣鸟', '当此卡被成功召唤时，破坏对手场上一只暗属性怪兽。此卡正面表示时，对手不能发动魔法卡、陷阱卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00148', '千年巨蛇', '当这张卡转由对手控制时，对方会受到2000点的损害，该效果一回合只能使用一次。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00151', '正义使者佤奇', '此卡以战斗将怪兽破坏并送往墓地时，自己的生命点可以回复与被破坏怪兽攻击力相等的数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00155', '蝙蝠人克雷斯', '当场上存在6级以上怪兽时可以召唤。成功召唤此卡，破坏对方的一张陷阱卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00160', '巨舌荆棘', '只要此卡正面表示存在场上，双方玩家抽一张手牌，并交换其控制权，直至回合结束。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00161', '不死骷髅战士', '此卡以正面表示存在场上时，将对手场上一只正面表示形态的怪兽加以破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00162', '水与火的化身', '·此卡的攻击力为自己场上和墓地里水、炎属性怪兽数量 x300 点。
INSERT INTO "texts" VALUES ('TSK90167', '大力士达斯塔夫', '每次自己的待命阶段时，对手的生命点数受到600点的损伤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00194', '传说的剑客', '在一回合内可以一度让此卡片的攻击力加倍。使用这个效果之后，在该回合结束时此卡片会被破坏。其攻击力为此卡片的原来的攻击力。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00195', '五首神龙', '此卡无法进行普通召唤，必须将自己墓地里的光属性与暗属性怪兽各一只从游戏中剔除才能进行特殊召唤。只要支付1000点生命点，就能将双方手牌与场上的所有卡片送进墓地。被此效果送进墓地的每一张卡片都能让对方受到500点损伤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00283', '服从', '对方场上与墓地里每存在一只龙族怪物，此卡的攻击力就上升500点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00314', '野兽的合体', '当它翻到正面时，可让场上任一怪兽回到手牌中。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00336', '激斗战士-枪手', '对「激斗战士-枪手」发动攻击的不死族以外的怪物，下回合变成守备显示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00339', '野人-1', '我方场上每存在一张正面显示的「野人-2」，守备力就可上升500点！', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK90343', '元素英雄 透明人', '可以从自己的目的或者对方的墓地里把一只名字带有「元素英雄」光属性的怪兽特殊召唤到场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00343', '齿轮之魔母', '如果每有一张「齿轮」字样的卡片在场上表示，这张卡攻击力守备力各提高300点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00344', '虚无的暗女神', '此卡不能特殊召唤。只要此卡在场上表侧表示存在，对方暗属性的怪兽不能进行特殊召唤怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00345', '虚无的光女神', '此卡不能特殊召唤。只要此卡在场上表侧表示存在，对方光属性的怪兽不能进行特殊召唤怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00349', '鬼王使者', '当对方攻击我方时，我方的损害会计算在对方的生命值上给予损伤，此卡在这回合结束时被破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00350', '幸福之使者', '这张卡受到敌方怪兽的攻击，可以将攻击转移到敌方的一只怪兽身上。再进行伤害计算。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00361', '精灵之火', '永远不灭的精灵之火，长长的一队总让人觉得像是鬼火。如果这张卡在场侧面表示时让在场的炎属性的精灵攻击力提升300点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00373', '斩首的猎人', '只要此卡在场上攻击宣言，对手的生命值就会受到相对的损伤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00378', '魔法师女孩', '当此卡片转为攻击显示表示时，可以当场将场上任何一只龙族怪兽破坏。当此卡翻到正面时，可让场上两只怪兽回到拥有者的手牌里。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00395', '黑暗的暗杀剑士', '这张卡不能直接攻击玩家。每当此怪兽在战斗中破坏一只怪兽，攻击力就下降300点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00397', '痛下杀手', '此卡可以直接攻击对方玩家，在回合结束后被破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101239', '冲击升级', '将此回合被战斗破坏的对方1只怪兽复活到对方场上，并攻击力提升500点。我方可以在这个回合发动两次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101240', '千年禁忌-卡利姆之弓', '此卡在场上正面表示存在时，对方对此卡发动魔法·陷阱·怪兽卡的效果时，那张卡的效果无效并破坏。1回合1次，确认对方卡组最上面的1张卡，选择下面一个效果发动：·怪兽卡的回合，那张卡在我放场上特殊召唤。·魔法·陷阱卡的回合，那张卡送入墓地。
INSERT INTO "texts" VALUES ('ZZ101241', '千年禁忌-亚图姆之皇剑', '此卡在场上正面表示存在时，对方对此卡发动魔法·陷阱·怪兽卡的效果时，那张卡的效果无效并破坏。1回合1次，选择场上1只怪兽发动，那只怪兽这个回合可以直接攻击对方玩家。
INSERT INTO "texts" VALUES ('ZZ101242', '千年禁忌-马哈特之杖', '此卡在场上正面表示存在时，对方对此卡发动魔法·陷阱·怪兽卡的效果时，那张卡的效果无效并破坏。对方每个回合的抽卡阶段受到自己场上怪兽等级总数x200的生命值伤害。
INSERT INTO "texts" VALUES ('ZZ101243', '千年禁忌-阿克纳帝之盾', '此卡在场上正面表示存在时，对方对此卡发动魔法·陷阱·怪兽卡的效果时，那张卡的效果无效并破坏。1回合1次，舍弃1张手牌，可以选择墓地1张卡加入手牌。
INSERT INTO "texts" VALUES ('ZZ101244', '千年禁忌-瑟特之刃', '此卡在场上正面表示存在时，对方对此卡发动魔法·陷阱·怪兽卡的效果时，那张卡的效果无效并破坏。1回合1次，选择对方场上的1张覆盖的卡破坏。（反转效果发动无效）
INSERT INTO "texts" VALUES ('ZZ101245', '地缚神 库西略之印', '此场地魔法卡正面表示存在时，舍弃2张手牌，可以将1只「地缚神 库西略」从手牌特殊召唤。第3回合结束时此卡和「地缚神 库西略」破坏送入墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101246', '地缚神 乌鲁之印', '此场地魔法卡正面表示存在时，解放1只我方场上的怪兽，可以将1只「地缚神 乌鲁」从卡组特殊召唤。回合结束时此卡和「地缚神 乌鲁」破坏送入墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101247', '地缚神 查库·查略亚之印', '此场地魔法卡正面表示存在时，支付1000点生命值，可以将1只「地缚神 查库·查略亚」从墓地特殊召唤。第2回合结束时此卡和「地缚神 查库·查略亚」破坏送入墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101248', '红龙之首', '墓地存在1张名字带有「红龙」的魔法卡时，可以特殊召唤1只「星辰龙」上场。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101249', '红龙之尾', '手牌存在1张名字带有「红龙」的魔法卡时，可以特殊召唤1只「黑羽龙」上场。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101250', '红龙之右爪', '手牌·墓地存在1张名字带有「红龙之右爪」的魔法卡时，可以特殊召唤1只「黑蔷薇龙」上场。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101251', '红龙之翼', '手牌/墓地存在1张名字带有「红龙之尾」或「红龙之首」的魔法卡时，可以特殊召唤1只「真红魔龙」上场。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101252', '红龙之左爪', '手牌·墓地存在1张名字带有「红龙之右爪」的魔法卡时，可以特殊召唤1只「古代妖精龙」上场。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101253', '千年昊天塔', '十神器之卡。
INSERT INTO "texts" VALUES ('ZZ101254', '千年伏羲琴', '十神器之卡。
INSERT INTO "texts" VALUES ('ZZ101255', '千年崆峒印', '十神器之卡。
INSERT INTO "texts" VALUES ('ZZ101256', '千年盘古斧', '十神器之卡。
INSERT INTO "texts" VALUES ('ZZ101257', '千年昆仑镜', '十神器之卡。
INSERT INTO "texts" VALUES ('ZZ101258', '千年炼妖壶', '十神器之卡。
INSERT INTO "texts" VALUES ('OCG00001', '伟大的战士 泰勒', '这张卡不能特殊召唤。这张卡用战斗将怪兽破坏并送入墓地时，给予对手LP破坏的怪兽的攻击力数值的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('OCG00002', '阴阳神 葛叶', '←1 【灵摆】 1→
INSERT INTO "texts" VALUES ('OCG00003', '帝国之创始者 双子王', '←1 【灵摆】 1→
INSERT INTO "texts" VALUES ('OCG00004', '阿莱沃', '这张卡不能特殊召唤。不用自己场上3只鸟兽族怪兽作为祭品进行祭品召唤就不能出场。这张卡直接攻击对方造成对方基本分为0的时候，这张卡的控制者得到比赛的胜利。这张卡不能在正式比赛中使用。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('OCG00005', '星尘巨神', '光属性调整＋2只以上调整以外的天使族怪兽。
INSERT INTO "texts" VALUES ('OCG00006', '闪电帝皇', '这张卡不能特殊召唤。不用自己场上3只雷族怪兽作为祭品进行祭品召唤就不能出场。这张卡直接攻击对方造成对方基本分为0的时候，这张卡的控制者得到比赛的胜利。这张卡不能在正式决斗中使用。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('OCG00007', '无敌流星', '这张卡不能特殊召唤。不用自己场上3只兽战士族怪兽作为祭品进行祭品召唤就不能出场。这张卡直接攻击对方造成对方基本分为0的时候，这张卡的控制者得到比赛的胜利。这张卡不能在正式比赛中使用。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('OCG00008', '湾岸战兽 门桥地龙', '这张卡不能特殊召唤。要通常召唤这张卡的场合，必须将自己场上的3只恐龙族怪兽解放来高等召唤。这张卡的直接攻击使对手的LP变为0的场合，这张卡的操作者比赛胜利。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('OCG00009', '军神 提尔', '这张卡不能特殊召唤。这张卡必须用场上3只天使族怪兽做祭品通常召唤。如果这张卡给予对方直接攻击并且对方基本分变为0，这张卡的控制者获得比赛的胜利。这张卡不能在决斗中使用。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('OCG00010', '传说的白龙', '8星怪兽×3
INSERT INTO "texts" VALUES ('OCG00011', '罗汉狮子 宿傩', '这张卡不能特殊召唤。这张卡必须用场上3只兽战士族怪兽做祭品通常召唤。如果这张卡给予对方直接攻击并且对方基本分变为0，这张卡的控制者获得比赛的胜利。这张卡不能在决斗中使用。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('OCG00012', '圣域侍从 高超魔导士', '这张卡不能特殊召唤。要通常召唤这张卡的场合，必须将自己场上的3只魔法师族怪兽解放来高等召唤。这张卡的直接攻击使对手的LP变为0的场合，这张卡的操作者比赛胜利。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('OCG00013', '金牙王 兰帝亚', '8星怪兽×3
INSERT INTO "texts" VALUES ('OCG00014', '音响兵器 罗蕾莱', '这张卡不能特殊召唤。这张卡必须用场上3只机械族怪兽做祭品通常召唤。如果这张卡给予对方直接攻击并且对方基本分变为0，这张卡的控制者获得比赛的胜利。这张卡不能在决斗中使用。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('OCG00015', '银冠女王 涅瑞娅', '6星怪兽×3
INSERT INTO "texts" VALUES ('OCG00016', '兽王 奇美拉', '这张卡不能特殊召唤。不用自己场上3只　兽族　怪兽作为祭品进行祭品召唤就不能出场。这张卡直接攻击对方造成对方基本分为0的时候，这张卡的控制者得到比赛的胜利。这张卡不能在正式决斗中使用。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('OCG00017', '破坏王 泽克泽克斯', '这张卡不能特殊召唤。不用自己场上3只恶魔族怪兽作为祭品进行祭品召唤就不能出场。这张卡直接攻击对方造成对方基本分为0的时候，这张卡的控制者得到比赛的胜利。这张卡不能在正式决斗中使用。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('OCG00018', '赤色星兽 格里兹利', '地属性调整＋2只以上调整以外的兽族怪兽。
INSERT INTO "texts" VALUES ('OCG00019', '武道神的甲胄', '这张卡不能特殊召唤。不用自己场上3只战士族怪兽作为祭品进行祭品召唤就不能出场。这张卡直接攻击对方造成对方基本分为0的时候，这张卡的控制者得到比赛的胜利。这张卡不能在正式决斗中使用。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('OCG00020', '命运之女王 伊特妮娅', '这张卡不能特殊召唤。不用自己场上3只天使族怪兽作为祭品进行祭品召唤就不能出场。这张卡直接攻击对方造成对方基本分为0的时候，这张卡的控制者得到比赛的胜利。这张卡不能在正式决斗中使用。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('OCG00021', '魔导神的雕像', '这张卡不能特殊召唤。不用自己场上3只魔法师族怪兽作为祭品进行祭品召唤就不能出场。这张卡直接攻击对方造成对方基本分为0的时候，这张卡的控制者得到比赛的胜利。这张卡不能在正式决斗中使用。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('OCG00022', '传说的暗之魔导师', '7星怪兽×3
INSERT INTO "texts" VALUES ('OCG00023', '娱乐☆英雄 盘面执行者', '6星怪兽×3
INSERT INTO "texts" VALUES ('OCG00024', '悠久之黄金都市 格兰波利斯', '8星怪兽×3
INSERT INTO "texts" VALUES ('OCG00025', '罗阿邪神将 阿吉巴', '这张卡不能特殊召唤。这张卡必须用场上3只恶魔族怪兽做祭品通常召唤。如果这张卡给予对方直接攻击并且对方基本分变为0，这张卡的控制者获得比赛的胜利。这张卡不能在决斗中使用。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('OCG00026', 'Get Your Game On!', '这张卡只能在「2007游戏王TCG世界锦标赛」中使用。自己场上所有的名字带有「元素英雄」或「新宇」的怪兽攻击力加倍。不能在正式决斗中使用。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('OCG00027', '极刀之武者 左京', '←10 【灵摆】 10→
INSERT INTO "texts" VALUES ('OCG00028', '辉银之天空船-列奥号', '←10 【灵摆】 10→
INSERT INTO "texts" VALUES ('OCG00029', '来于异界的谢尔加', '←10 【灵摆】 10→
INSERT INTO "texts" VALUES ('OCG00030', '天空之女神 朱诺', '←1 【灵摆】 1→
INSERT INTO "texts" VALUES ('OCG00031', '革命之铁骑士', '机械族效果怪兽3只以上 
INSERT INTO "texts" VALUES ('OCG00032', '联合之龙王', '龙族效果怪兽3只以上
INSERT INTO "texts" VALUES ('OCG00033', '黑衣之诏刀师', '魔法师族效果怪兽3只以上 
INSERT INTO "texts" VALUES ('OCG00034', '神峰之天津龙', '龙族效果怪兽3只以上
INSERT INTO "texts" VALUES ('OCG00035', ' 黑森林的航天阁', '岩石族效果怪兽3只以上 
INSERT INTO "texts" VALUES ('OCG00036', ' 天元之荒鹫王', '兽族效果怪兽3只以上 
INSERT INTO "texts" VALUES ('OCG00037', '山岳斗士 TOMOHIRO', '祭品1只怪兽。给予对方基本分500点伤害。「放跑优胜令人懊悔！下次一定要得到优胜！！」', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('OCG00038', '骷髅祭司 YASUSHI', '「血之代偿」＋「黑森林的魔女」
INSERT INTO "texts" VALUES ('OCG00039', '暗道化师 MASAHIRO', '发动自己墓地里1只反转效果怪兽的效果。「信赖卡组是得到胜利的秘诀！」', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('OCG00040', '大家的王', '过去曾舍弃故乡和同伴的活像小丑的王，那颗积伤成疾的心，因真诚关怀的心而得到救赎。决定选择自己的命运生存下去的那个男子，有朝一日一定会成为拯救世界，受万民爱戴，为大家带来幸福的真正的王吧。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('OCG00041', '杰拉', '强有力的攻击从身体中不断涌现出来。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('OCG00042', '超级战狮', '狮子化为兽人，用锋利的爪子切碎对方。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('OCG00043', '恶魔镜', '恶魔之镜将映照的事物全部吸进镜子的世界。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('OCG00044', '遗言之札', '自己场上存在的怪兽的攻击力被卡的效果变成0的场合：抽卡直到自己手卡有5张为止。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('OCG00045', '胜利的方程式', '①：只有对手场上有怪兽存在的场合，可以宣言『勝利の方程式は全て揃った！(胜利的方程式全部集齐了！)』发动。从额外卡组特殊召唤1只「CNo.」怪兽以外的「No.」多维怪兽。那之后，将这张卡叠放在那只怪兽下面作为多维素材。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('OCG00046', '希望的创造者', '①：这张卡因对手被破坏并送入墓地的下次自己的抽卡阶段开始时，自己LP比对手少的场合，可以宣言『一飞冲天啊！我！』发动。从卡组选1张卡放置在卡组最上面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('OCG00047', '奇迹的创造者', '①：可以宣言『异热同心力场！』，以自己场上的1只「CNo.39」多维怪兽为对象发动。这个回合，对象怪兽可以直接攻击。这次决斗中自己有发动过「希望的创造者」和「胜利的方程式」的效果的场合，再在这个回合里适用以下。
INSERT INTO "texts" VALUES ('ZZ101259', '圣兽纹章', '从自己卡组选择一张「王家圣兽」和一张「封魂圣杯」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ200001', '元素英雄 紫晶新宇侠', '「元素英雄 新宇侠」＋地属性「宝玉兽」怪兽
INSERT INTO "texts" VALUES ('ZZ200002', '元素英雄 翠玉新宇侠', '「元素英雄 新宇侠」＋水属性「宝玉兽」怪兽
INSERT INTO "texts" VALUES ('ZZ200003', '元素英雄 琥珀新宇侠', '「元素英雄 新宇侠」＋地属性「宝玉兽」怪兽
INSERT INTO "texts" VALUES ('ZZ200004', '元素英雄 红玉新宇侠', '「元素英雄 新宇侠」＋光属性「宝玉兽」怪兽
INSERT INTO "texts" VALUES ('ZZ200005', '元素英雄 黄玉新宇侠', '「元素英雄 新宇侠」＋地属性「宝玉兽」怪兽
INSERT INTO "texts" VALUES ('ZZ200006', '元素英雄 钴尖晶新宇侠', '「元素英雄 新宇侠」＋风属性「宝玉兽」怪兽
INSERT INTO "texts" VALUES ('ZZ200007', '元素英雄 青玉新宇侠', '「元素英雄 新宇侠」＋风属性「宝玉兽」怪兽
INSERT INTO "texts" VALUES ('ZZ101260', '奥西里斯之铠甲-头盔', '这张卡不能特殊召唤。这张卡的召唤不会无效化。这张卡通常召唤成功时，对方不能针对此卡发动魔法·陷阱·效果怪兽的效果。此外，此卡从场上离开时，可以选择墓地1张除此卡外名字带有「奥西里斯」的卡片加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101261', '奥西里斯之铠甲-羽翼', '这张卡不能特殊召唤。这张卡的召唤不会无效化。这张卡通常召唤成功时，对方不能针对此卡发动魔法·陷阱·效果怪兽的效果。此外，1回合1次，将我方场上存在除此卡以外名字带有「奥西里斯」的怪兽送入墓地，给予对方那只怪兽攻击力数值的生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101262', '奥西里斯之铠甲-护腿', '这张卡不能特殊召唤。这张卡的召唤不会无效化。这张卡通常召唤成功时，对方不能针对此卡发动魔法·陷阱·效果怪兽的效果。此外，每当此卡战斗破坏对方怪兽时，从对方卡组将被破坏的怪兽等级数量张数的卡片送入墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101263', '奥利哈钢 七武神·光之越', '我方墓地里存在7张等级5以上冠有「奥利哈钢」之名的怪兽才能特殊召唤，此卡在我方的准备阶段时可以选择我方手牌·场地·墓地中最多3张冠有「奥利哈钢」之名的怪兽，任意放置在手牌·场地·墓地中，此卡的攻击力上升被选择的怪兽之攻击力总和x2的数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101264', '奥利哈钢 七武神·天之惩', '我方墓地里存在7张等级5以上冠有「奥利哈钢」之名的怪兽才能特殊召唤。我方的主要阶段时可以宣告1种除光之外的属性。此卡攻击力·守备力各自称为场地上被选择属性的怪兽中最强的2只怪兽攻击力·守备力的合计数值。对手每完成一个动作，此卡的攻击力·守备力各上升200点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101265', '奥利哈钢 七武神·风之刃', '我方墓地里存在7张等级5以上冠有「奥利哈钢」之名的怪兽才能特殊召唤。此卡在宣言攻击时，此卡的攻击力上升被宣告攻击的怪兽之攻击力总和x2的数值，对手场地·手牌中守备力在此卡上升数值以下的怪兽卡被破坏。对手的手牌给我方确认后返回牌组重新洗牌后抽出与放回相同数量的卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101266', '千年万灵幡', '十神器之卡。
INSERT INTO "texts" VALUES ('ZZ101267', '千年鸣鸿刀', '十神器之卡。
INSERT INTO "texts" VALUES ('ZZ101268', '千年青釭剑', '十神器之卡。
INSERT INTO "texts" VALUES ('ZZ101269', '千年神农鼎', '十神器之卡。
INSERT INTO "texts" VALUES ('ZZ101270', '千年东皇钟', '十神器之卡。
INSERT INTO "texts" VALUES ('ZZ101271', '千年射日弓', '十神器之卡。
INSERT INTO "texts" VALUES ('ZZ101272', '千年墨炎剑', '十神器之卡。
INSERT INTO "texts" VALUES ('ZZ101273', '天龙 速迅龙', '对方场上的卡比自己场上存在的卡的数量多2张以上的场合，这张卡可以从手卡特殊召唤。此卡在场上对方玩家不能发动魔法/陷阱卡。
INSERT INTO "texts" VALUES ('ZZ101274', '天龙 夜光龙', '只要此卡在场上4星以上不能攻击。
INSERT INTO "texts" VALUES ('ZZ101275', '天龙 烈炎龙', '此卡在场上存在时自己的手牌的数量无上限。超量召唤时当11星怪兽使用。
INSERT INTO "texts" VALUES ('ZZ101276', '天龙 圣海龙', '1回合1次，从手牌把1只名字带有「天龙」的怪兽送去墓地，对方怪兽召唤无效。
INSERT INTO "texts" VALUES ('ZZ101277', '天龙 圣雷龙', '1回合1次，指定没有使用的怪兽卡区域1处发动，只要这张卡在场上存在，指定的怪兽卡区变成不能使用。
INSERT INTO "texts" VALUES ('ZZ101278', '圣龙 战斗龙', '龙族怪兽×3
INSERT INTO "texts" VALUES ('ZZ101279', '圣龙 幻神龙', '调整＋调整以外的龙族怪兽1只
INSERT INTO "texts" VALUES ('ZZ101280', '圣龙 蓝霸龙', '4星龙族怪兽×2
INSERT INTO "texts" VALUES ('ZZ101281', '圣龙 龙尊', '11星龙族怪兽×2
INSERT INTO "texts" VALUES ('ZZ101282', '圣龙 龙帝', '12星龙族怪兽×2
INSERT INTO "texts" VALUES ('ZZ101283', '天龙 华丽进化', '将我方场上2只怪兽与手牌1只怪兽送入墓地，可以从额外卡组将1只名字带有「圣龙」的怪兽特殊召唤上场。
INSERT INTO "texts" VALUES ('ZZ101284', '天龙 神圣回复', '场上名字带有「天龙」的怪兽被破坏送入墓地时，我方生命值回复怪兽攻击力的一半数值。
INSERT INTO "texts" VALUES ('ZZ101285', '机甲天龙 金海龙', '对方卡的效果令我方手牌返回到卡组时，返回卡组的怪兽卡全部召唤上场。
INSERT INTO "texts" VALUES ('ZZ200008', '黄金乡的盗掘者', '←1 【灵摆】 1→
INSERT INTO "texts" VALUES ('TSK00006', '幻影·飞鱼', '在海里像幻影般忽隐忽现的飞鱼，以不可思议的闪躲方式攻击对手。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00060', '邪恶的机械兽', '手持双卫击炮的兽战士，以敏捷的身手发动的攻击威力十分惊人。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00069', '电击手', '拥有一对长长的大触手，能释放出千万伏特的超强电力，一旦被它遮住，就只能乖乖地任它摆布。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00070', '火山王·亚夫斯西', '诞生于超高温的火焰中，掌管所有炎族怪兽，身上的皮肤的坚硬无比的岩石，从嘴里喷出火红色的灼热岩浆能毁灭所有的生物。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00102', '牛鬼', '从壶中钻出来的牛鬼。要小心它手臂上的另一头。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00128', '猫之妖精', '猫的妖精，虽然外部十分可爱，但是却能快速的攻击敌人。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00130', '砖头人卡姆', '拥有邪恶意志的砖头怪物，双眼会泛出幽幽的蓝光。干扰对手的思想。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00145', '狂暴猛龙', '身体有着如岩石般坚硬的外壳保护，攻击力极高的龙族之王。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00312', '花的精灵', '守护花朵的天使族精灵，繁华盛开时会在花丛中飞舞，阻止敌人对花朵的攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00319', '不死鸟', '一直持续守护皇宫的不死鸟。有一对像机器一样的翅膀。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00321', '地下灵王', '从应该没有任何人在的第 18 层地狱中，突然出现了。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00324', '绿色魔怪', '能利用地震来攻击对手的恶魔。光靠强大的身形就能让敌人颤抖，落荒而逃。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00329', '武装突袭兵', '装备了大炮的实战部队，具备各种战斗的技术，不管在怎样的状态下都能冷静地达成作战目标。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00335', '蝴蝶公主', '与「青虫」一样，不知道成长为哪种虫的小型幼虫。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00001', '异次元千面昆虫女王', '需献祭一只怪物才能攻击。场上每只昆虫族怪物能让昆虫女王的攻击力上升200点。如果她回合中有破坏对方怪物，该回合结束时在我方场上产下一个昆虫复制体。当此卡片翻到正面时，对方场上设置的每一张魔法、陷阱都将让对方蒙受500点损伤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00042', '肉弹火焰兽', '将3张卡作为祭品才能召唤此卡，此卡可将对手场上的怪兽全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00048', '魔虾精灵', '能发出强力的魔光穿透对方怪兽身体。当此卡被送往墓地时，仍能进行召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00063', '海神的坐骑', '当「海神的坐骑」以正面状态留在场上时，所有水族怪兽将不会成为魔法卡的目标。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00147', '隐形恶魔精灵', '当此卡翻到正面时，全场内若是有2张以上的魔法，陷阱卡片以背面显示，则可选择2张加以破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00156', '科学钢龙王', '翻面效果：将场上一张陷阱卡加以破坏。此卡以正面表示时，对手一只以侧面守备表示的怪物无效化。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00167', '闪电装甲精灵', '·此卡也可作装备卡使用，装备光属性怪兽攻击力和守备力各增加800点。
INSERT INTO "texts" VALUES ('TSK00278', '贪吃熊', '·当它翻面发动效果时，可从牌组里抽出一张「贪吃熊」至场上以背面守备。之后牌组进行洗牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00280', '古代的机械少女', '本牌不能进行召唤。当该牌攻击有守备标志怪兽时。如果该牌的攻击能力超过有守卫标志怪兽的守卫能力，对对方的生命力的破坏力相当于超过部分的能量。当该牌进行攻击时，在破坏步骤结束之前，对手不能出魔法、陷阱牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00281', '光之暗杀者', '将「光之暗杀者」翻面后，将牌组最上方三张牌移除，并对敌方玩家造成800点伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00317', '恶魔-调理师', '当这张卡片直接攻击玩家时，对方从牌组里抽出两张卡片送往墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00318', '城之宝塔', '当这张卡片在场上时，恶魔族怪兽的攻守每回合上升200点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00326', '异次元神鸟', '丢3次硬币，其中若有2次为正面，则可破坏对方的一只怪物。此效果只能在我方回合内发动一次。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00337', '烟雾凤凰', '攻击「烟雾凤凰」的兽族以外的怪物，此回合结束后被破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00340', '野人-2', '我方场上每存在一张正面表示的「野人-1」，攻击力就可上升500点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00172', '圣·火翼鸟', '将两只光属性的怪兽作祭品成功召唤此卡时。·场地上暗属性的怪兽在此回合内不能发动攻击。·将对手场上一只5级以下的怪兽破坏并送往墓地，此效果一回合只能使用一次。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00202', '绿蝙蝠女妖', '当它翻到正面时，可让场上任一只怪兽回到手牌里。当此卡存在场上时，兽族怪兽的攻击力将提高500点。只要牌组锁定为兽族的话，就能让所有怪兽强化。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00059', '第四次元战士', '来自未知的第四次元空间，身上长着一对媲美鹰的大翅膀，音速般的飞行速度，让其常常大胜而归。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00144', '变种墨鱼', '住在深海中的变种墨鱼，能从海中引发黑暗的大海啸来攻击对手。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00107', '红叶的女王', '掌管着植物族的女王。用红叶当暗器攻击敌人是她的专长。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00105', '水陆的帝王', '体型庞大的水陆帝王，拥有掌管一切水属性怪兽命运的大权。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00333', '半蛇马', '蛇与马合二为一的传说中的怪兽。非常善于奔跑，没有人能追得上，有气以其速度所出的攻击更是惊人。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00013', '爆发的光源', '能让所有光属性怪物的攻击力上升1000点。但守备力降低500点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00014', '光之保护甲', '只要这张卡片在战斗场上，我方在场上的全部怪兽攻击力增加500点。在这一回合对手的怪兽不能发动攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00051', '假装失败的灵魂', '黑暗的灵魂能施出咒语迷惑对手，把自己所承受攻击力一半的损伤转移给对方。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00338', '魔法融合师', '将2只以上的特定怪兽进行融合，召唤出融合怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00315', '宇宙之光', '能让所有光属性怪兽的攻击力上升500点，但守备力降低400点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00016', '战斗飞鸟', '对方手牌中有4枚以上时发动，可看对方的手牌，让对手一张怪兽卡回到牌组，再重新洗牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00021', '电波巨浪', '破坏对手的魔法卡及陷阱卡其中的一张，破坏后可从自己的游戏卡取一张组合。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00040', '封印之路', '能让对方在2回合之内不能发动攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00149', '隐身陷阱', '对手发动攻击时启动，可以抵消其攻击并获得对方一只6级以下怪兽的控制权，对方怪兽被破坏时此卡送往墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00330', '美丽的城堡', '在发动回合里让一只怪兽的守备力上升500点，卡片在回合结束时被破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00331', '终极战争', '在发动回合里让一只怪物的攻击力上升500点，卡片在呵呵结束时被破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101286', '冰结之菲茨杰拉德', '调整以外的1只怪兽－暗黑调整
INSERT INTO "texts" VALUES ('ZZ101287', '漆黑之朱姆沃尔特', '调整以外的1只怪兽－暗黑调整
INSERT INTO "texts" VALUES ('ZZ101288', '百眼龙', '调整以外的1只怪兽－暗黑调整
