INSERT INTO "texts" VALUES ('ZZ102115', '娃娃怪兽·小熊熊', '生活在豪华的家庭里，然而渐渐被遗忘在一边，感受到孤独，开始积累怨念。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102116', '娃娃怪兽·小机器人改', '经历过一次破坏的小机器人，与冠有「娃娃怪兽」之名的「龙君」部分肢体缝合而成，在城市的破旧角落忙碌着。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102117', '娃娃怪兽·小熊熊改改', '经历过两次破坏的小熊熊，分别与冠有「娃娃怪兽」之名的「龙君」·「小机器人改」部分肢体缝合而成，被遗忘而导致的孤寂与怨恨感仍然弥漫着难以散去。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102118', '酸性史莱姆', '这张卡因为战斗破坏时，给予对方800点伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102119', '基因狼人', '被遗传基因操作所强化的狼人。本来的和善之心已被完全破坏，肉体变成只为战斗而生。那个破坏力无可估量。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102120', '青眼光龙', '这张卡不能通常召唤。把自己场上1只「青眼究极龙」解放的场合才能特殊召唤。
