INSERT INTO "texts" VALUES ('SOD00015', '天国骑马', '当它攻击恶魔怪兽或被恶魔族怪兽攻击时，不会受到任何伤害，还能将攻击损害加载对手身上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SOD00016', '陆星战士', '当对手攻击它时，它可以回到手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK90001', '蚁狮', '「蚁狮」以隐藏的形态出现，当踏入「蚁狮」领域的怪兽攻击力会下降500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK90002', '蚁狮', '「蚁狮」以隐藏的形态出现，当踏入「蚁狮」领域的怪兽攻击力会下降500。「蚁狮」+「火器付机甲铠」后攻击力上升700。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RDS90002', '登上绳回收器·海龟', '背上的登上绳回收器强力无比！将此卡片从手牌中丢弃掉，可以使1只怪兽的攻击力增加1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RDS90003', '猛犸象的墓地', '猛犸象的亡魂一直守护着同伴的墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RDS90004', '电子传送带', '装备在女性型怪兽上。攻击力增加500点、防守力增加400点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK90006', '旋转蜘蛛', '它可以所对手的怪兽的眼镜遮住，然后开始旋转当箭头停在哪里，哪里的决斗者
INSERT INTO "texts" VALUES ('TSK90007', '幻想之咒缚', '受到这张卡诅咒的怪兽的特殊能力无效。攻击力下降500点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
