INSERT INTO "texts" VALUES ('ZZ102166', '千年地灵', '将此卡放置在魔法·陷阱卡区域发动，
INSERT INTO "texts" VALUES ('ZZ102158', '于贝尔', '①：这张卡不会被战斗破坏，这张卡的战斗发生的对自己的战斗伤害变成0。
INSERT INTO "texts" VALUES ('ZZ102159', '至高神石板', '通过「神石板的仪式」降临。
