INSERT INTO "texts" VALUES ('ZZ102168', '命运英雄 恐惧人', '「幽狱之时计塔」的效果特殊召唤的场合，自己场上名字带有「命运英雄」的怪兽以外的自己怪兽全部破坏。那之后，可以从自己墓地把最多2只名字带有「命运英雄」的怪兽特殊召唤。这张卡特殊召唤的回合，自己场上的名字带有「命运英雄」的怪兽不会被破坏，对控制者的战斗伤害变成0。这张卡的攻击力·守备力变成自己场上除这张卡外的名字带有「命运英雄」的怪兽的原本攻击力合计数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
