INSERT INTO "texts" VALUES ('ZZ102173', '卫星基地', '这张卡不会被和5星以下的怪兽的战斗破坏。此外，每次自己的结束阶段这张卡的守备力上升1000。这张卡的守备力在自己场上的怪兽进行战斗时回到0。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
