INSERT INTO "texts" VALUES ('ZZ102175', '充能', '「卫星加农炮」的攻击力上升2000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102176', '陷阱推进器', '舍弃1张手牌。可以发动手牌中的1张陷阱卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102177', '残骸回收站', '自己场上的1只「卫星加农炮」被战斗破坏时可以发动。从自己场上或者手卡把2只「卫星加农炮」送去墓地，从融合卡组把1只「镭射卫星X-06S巴尔萨姆」攻击表示特殊召唤。（这个特殊召唤视为融合召唤）。这个效果特殊召唤时，「镭射卫星X-06S巴尔萨姆」的攻击力上升3000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102178', '阿克夏记录', '从卡组抽2张卡。抽出的卡是至今为止使用过的卡的场合，那些卡从游戏中除外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102179', '二重门', '这张卡和墓地里的1张同名卡从游戏中除外。从自己的卡组抽2张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102180', '噩梦洗牌', '只要这张卡以表侧表示存在，不可以用卡片效果以外的方式确认自己的墓地。从墓地随机选择1张卡，设置在与这张卡相邻的魔法陷阱卡区域。自己回合的准备阶段时，将那张卡与随机选择的墓地的1张卡交换。因这个效果设置的卡发动的时候，这张卡送入墓地。没有符合发动条件的卡的场合，把自己手牌以及场上的卡全部送入墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102181', '三角阵之力', '这张卡发动后，可以从卡组选择2张「三角阵之力」发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102182', '永久里化', '1回合1次，可以使对手场上的1张魔法陷阱卡回到盖伏的状态。用这个效果回到盖伏状态的卡，这个回合不能发动。装备怪兽因战斗破坏的时候，可以把这张卡送入墓地使破坏无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102183', '砂上的楼阁', '玩家从卡组特殊召唤怪兽时，把这张卡加入手牌，然后从卡组上方把3张卡送入墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102184', '最后计谋', '对手的魔法卡发动时可以发动。那1张魔法卡在送入墓地后可以加入手牌，在这场决斗中可以当作自己的卡使用。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102185', '不灭阶级', '把自己场上的2只怪兽祭品。从自己墓地把1只等级7以上的怪兽特殊召唤。这个特殊召唤无视召唤条件。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102186', '破坏力千式', '支付1000点LP发动。场上存在的攻击力1000以下的表侧攻击表示的怪兽以及守备力1000以下的表侧守备表示的怪兽全部破坏。之后，双方玩家受到1000点的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102187', '零之洞', '对手召唤、反转召唤、特殊召唤的效果怪兽的效果无效并破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102188', '零之妖精', '这张卡当作装备卡使用，装备怪兽的原攻击力变为0。装备怪兽在1次战斗阶段中可以进行2次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102189', '三角屏障', '这张卡发动的时候，墓地里的同名卡也可以发动。这张卡在自己场上有3张的时候，1回合1次，可以使自己场上的1只怪兽的战斗伤害变为0。使用这个效果的回合，这张卡以外的「三角屏障」的效果不能发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102190', '破坏封印', '把自己场上表侧表示存在的这张卡和这张卡以外的1张「破坏封印」送去墓地。从自己的卡组把1张名字带有「被封印」的卡加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102191', '混沌形态', '发动后变成自己场上1只怪兽的装备卡。装备怪兽成为攻击对象的时候，从自己墓地随机选择1只怪兽。装备怪兽的攻击力、守备力变为与选择了的怪兽的攻击力、守备力相同的数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102192', '魔蔷薇', '发动后，变成自己场上1只怪兽的装备卡。装备怪兽因战斗受到的伤害变为0。这张卡从场上离开的时候，装备怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102193', '炼金兽·铁之火龙', '这张卡不能通常召唤。这张卡可以对对手进行直接攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102194', '炼金兽·铜之鳞蟒', '这张卡不能通常召唤。这张卡可以对对手进行直接攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102195', '炼金兽·铅之狮子', '这张卡不能通常召唤。这张卡可以对对手进行直接攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102196', '炼金兽·锡之尖鹰', '这张卡不能通常召唤。这张卡可以对对手进行直接攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102197', '炼金兽·汞之鲫鱼', '这张卡不能通常召唤。这张卡可以对对手进行直接攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102198', '炼金兽·银之月颜', '这张卡不能通常召唤。这张卡可以对对手进行直接攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK90011', '魔法转移', '能将魔法卡的使用权转移。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK90012', '敌袭警报-黄色警报-', '对手玩家攻击宣言时发动。从手卡特殊召唤1只怪兽。战斗流程结束后回到手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00115', '迷之傀儡师', '这张卡在与光属性怪兽战斗时，在计算时攻击力增加1000点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00193', '暗黑魔人', '此卡片在我方的结束阶段时，可以有一次改变显示形式的机会。此卡无法进行普通召唤，必须将自己墓地里一张暗属性怪兽从游戏中剔除才能进行特殊召唤。当此卡在战斗中被破坏并送进墓地时，就能将场上所有魔法·陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00003', '神永兵', '以旋转的刀锋击败场上的所有怪兽（包括敌方、我方的怪兽）。每次攻击能使对手损伤500点的生命值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00316', '光速犬', '必须从手牌中献上星星数合计7个以上的卡片为祭品才能召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RDS00069', '魔法转移', '转移魔法效果。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00369', '医护天使', '回复500点的生命值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00368', '光明的通道', '可以在手牌抽2张卡到场上。光属性的怪兽攻击力提升300点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102199', '进化帝 鸣腔龙', '恐龙族4星怪兽×2只以上
INSERT INTO "texts" VALUES ('CRV00087', '郁金香', '​每一次准备阶段，自己能观看对手的一张手牌。
INSERT INTO "texts" VALUES ('CRV00101', '导弹炮—人造人', '当“人造人“与导弹炮—人造人同时存在场上时，对方场上正面表示的卡牌全部被破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('CRV00096', '毁灭将军', '当该怪兽受到对方攻击时，可以以削弱一半攻击力或防守力为代价来抵挡对方怪兽的攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('CRV00090', '凝胶鱼', '当该怪兽发动攻击时，可以从对方的场面上选择一张卡片，并把它返回到手牌中。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('CRV00086', '骗人的幽灵', '此牌可以当做魔法卡放在魔法卡区域，当打开此牌时，它会返回到自己的手牌中。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('CRV00102', '战争公主·高星亚', '当场上存在“恶魔的召唤”时，此怪兽不受对方的攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('CRV00081', '天国的勇士', '当场上存在“天国的炮兵”和此牌时，此牌攻击力会提升500分。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('CRV00079', '天国的炮兵', '此卡可以对魔法卡进行攻击，每破坏一张卡，攻击力提高500分。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('CRV00072', '冰冻卫士', '当此卡与火属性怪兽战斗时，此卡可以直接给予对手500分的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('CRV00071', '天国彩虹桥—匕卜洛斯特', '此卡会随对手每只送入墓地的怪兽，可让一只“瓦尔基莉—布林希尔岱”提高500分，攻击力。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('CRV00089', '爆炸的仙人掌', '当发动此牌后自己场面上的所有卡牌被破坏。并能从牌组中补充相同数量的卡片。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('CRV00069', '钻石剑的复活', '此卡可在龙族怪兽被召唤时使用，将召唤的怪兽当祭品献上，召唤出钻石头龙，而钻石头龙的攻击力和防御力是当祭品的怪兽的2倍。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('CRV00103', '闪电之光', '此牌能使“恶魔的召唤”攻击力提高1000点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('CRV00070', '火神龙 提玛利欧斯', '火神龙的攻击力会随双方墓地的卡片的张数的增加而增加，每一张增加500分的攻击力。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('CRV00073', '防御者 德斯塞斯', '当防御者艾亚托斯在战斗中被破坏时，可以从牌组中召唤此卡。当此卡被破坏时可以从手中丢弃一张牌，让它复活。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('CRV00061', '超级恢复剂', '这张卡只能当自己场上没有怪兽而对方怪兽的攻击力总和超过自己的生命值时才可以发动，它能将自己的生命值提高一倍。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('CRV00066', '黑暗的奇袭', '这张卡能让自己再次发动攻击时，让上一轮死去的怪兽复活。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('CRV00083', '克隆工厂', '当该卡片在场上正面表示存在时，可以从墓地上返回一至二张卡片到手牌中。（不论种类）', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('CRV00065', '防御轮', '此卡能让陷阱卡对自己造成的伤害失效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('CRV00091', '精神之王·迪亚斯', '能直接控制对方的两只怪兽，当对方发动攻击时，即可夺取对方的一张手牌并加入到自己的手牌中。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('CRV00063', '火箭海聶默斯加农炮', '这张卡只能装备在战士族怪兽上，当装备了此卡的怪兽发动攻击时，能将对方场上所有怪兽破坏并伤害对手1000分生命值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('CRV00080', '修制姆贝洛克的黄金城', '这张卡不会被魔法卡或陷阱卡所破坏。这张牌能让自己从牌组中召唤出四星级以下的怪兽。当对方发动攻击，对方会受到此怪兽攻击力的一半的损伤，这只怪兽同时会被破坏，只要此卡存在场上时，每回合要把牌组一半的牌丢进墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('CRV00077', '尼白龙戒指', '将尼白龙戒指装备到怪兽上，此怪兽不受其持有者控制，但怪兽的持有者每回合可以抽2张牌，当所抽的牌是怪兽卡时必须丢弃其中一张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('CRV00067', '欧雷卡姆斯的魔法剑', '它可以破坏场上一只怪兽的特殊效果。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('CRV00074', '生命之瓶', '此卡可以从自己的墓地中，以攻击状态召唤一只怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('CRV00076', '磁力战士', '将磁力战士α，β，γ送去墓地才能召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('CRV00097', '装备甲昆虫王', '当装备了此牌的昆虫族怪兽，会在每回合的准备阶段，就能破坏对方的一张手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('CRV00098', '太空海盗龙', '当该怪兽受到对方自己攻击时，每一回合都会提升生命值150点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('CRV00099', '千兆雷管炮', '此牌能将对手场面上所有怪兽的效果破坏掉。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('CRV00100', '玛哥勒克斯•火焰龙', '当此怪兽被召唤到场面上时，攻击它的怪兽，魔法卡或陷阱卡都被燃烧掉（水属性除外）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('CRV00095', '水疗院的飓风', '此卡存在场面时，所有水属性的怪兽不受破坏，当此牌被破坏时，所有水属性的怪兽也被破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('CRV00094', '残骸盗贼', '当此怪兽存在场面时，将一张牌送进墓地，能从墓地抽出另外一张牌加入到手牌中。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('CRV00082', '牺牲的锁链', '能把对方场面正面表示的一至二只怪兽破坏掉。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('CRV00075', '同花大顺', '发动此卡后，献上国王，王后和王子为祭品，可以从牌组，手牌，墓地中召唤同花大顺毁灭者。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('CRV00085', '令人惊愕的旭日', '当发动此牌时，手牌中牌组中的暗属性怪兽全部都会被送入墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('CRV00078', '罗给之炎', '只要此卡在场上，攻击力2000以下的怪兽无法攻击，当此卡被破坏时，可以特殊召唤出“瓦尔基莉—布林希尔岱”。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RDS90001', '甲壳虫·比托鲁', '此卡只要在战场上用正面表示存在。
INSERT INTO "texts" VALUES ('TSK90013', '炽天使剑士', '每有1只其他的天使攻击力上升300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK90014', '平行变异体', '当战斗被破坏时可以当做装备卡装备在对方怪兽上，得到对方怪兽的控制权。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK90015', '强引之取引', '对手召唤怪兽时发动。支付自己所有怪兽和一半生命值，把对手的怪兽全部变为自己的。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102200', '强防剑士', '己方场上有强防斧兵表侧表示存在的场合，可直接攻击对方的生命值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102201', '狂暴怒狮', '此卡在场上表侧表示每一回合攻击力上升300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102202', '咆哮死灵', '反转：双方场上陷阱魔法卡全部从游戏中除外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102203', '人马骑士', '此卡在场上表侧表示存在，兽战士族（此卡除外）上升600攻击力。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102204', '兽人战体', '此卡不能通常召唤，从墓地中除外三只兽族、兽战士族怪兽时特殊召唤。
INSERT INTO "texts" VALUES ('ZZ102205', '圣光战士', '此卡在场上表侧表示存在，己方每回合回复300生命点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102206', '电磁兽人', '此卡直接攻击到对方生命值时可祭生从手牌，
INSERT INTO "texts" VALUES ('ZZ102207', '电磁狂暴兽', '此卡因电磁兽人的效果特殊召唤时，对方场上表示的怪兽全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102208', '暗黑术士', '被此卡攻击受到伤害后，此卡在场上表侧表示每一回合对方生命值下降500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102209', '暗黑魔尊', '此卡不能特殊召唤，祭掉场上二只恶魔族怪兽才能召唤。此卡在场上表侧表示存在对方不能攻击此卡以外的恶魔族怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102210', '巨萼怪', '以二张植物族怪兽做此卡的祭品召唤成功时，对方
INSERT INTO "texts" VALUES ('ZZ102211', '食魂鱼', '状态：自己回合开始时，这张卡在自己场上表侧守备表示存在时，除外自己和对方墓地里所有怪兽，这张卡的攻击力和守备力上升除外数量×200！
INSERT INTO "texts" VALUES ('ZZ102212', '形体抓取者', '状态：守备表示时复制自己的卡组统领的攻守数值，攻击表示时复制对方的卡组统领的攻守数值！
INSERT INTO "texts" VALUES ('ZZ102213', 'Ｘ·Ｅ·Ｎ·Ｏ', '状态：这张卡变成表侧时，寄生敌人并将其得到！那只怪兽在战斗中被破坏的话，在现在位置以外的自己侧的召唤区域复活！被寄生的怪物的生态·死亡特性无效化。
INSERT INTO "texts" VALUES ('ZZ102214', '咒怨', '移动：每次移动时，给予对方50点伤害！
INSERT INTO "texts" VALUES ('ZZ102215', '异形的从者', '生态：表侧守备表示时，敌我双方每回合额外增加1点召唤能量！
INSERT INTO "texts" VALUES ('ZZ102216', '电磁蓑衣虫', '活动：这张卡变成表侧时，可以夺取对方全体机械族怪兽的控制权！
INSERT INTO "texts" VALUES ('ZZ102217', '再造的死神', '活动：这张卡变成表侧时，敌我双方手牌全部丢到墓地！
INSERT INTO "texts" VALUES ('ZZ102218', '纽特', '活动：这张卡变成表侧时，自己的旧神族怪兽的攻击力和守备力上升500点！
INSERT INTO "texts" VALUES ('ZZ102219', '时间吞噬者', '生态：表侧守备表示期间，计算回合数的效果加倍进行。
INSERT INTO "texts" VALUES ('ZZ102220', '莫伊斯彻星人', '生态：表侧守备表示时，敌方卡组领袖的能力无效。
INSERT INTO "texts" VALUES ('ZZ102221', 'N·U·L·L', '生态：以表侧守备表示迎接自己的回合的话，所有的卡都会被「N·U·L·L」吸引1格！
INSERT INTO "texts" VALUES ('TSK90003', 'E·HERO 业林侠', '1回合只有1次在自己的准备流程时才能发动。可以当做一只名字带有
INSERT INTO "texts" VALUES ('TSK90004', '财宝妖精', '如果能装备上「剧毒十字弓」的话它攻击力就会暴增。任何坚硬的物体都会被它的剧毒瞬间侵蚀。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK90005', '时间移动', '对象的1只怪兽时间转移到下个回合的主要流程。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102222', '地狱归来的黑色守护神 艾克佐迪亚', '调整以外的1只怪兽－暗黑调整
INSERT INTO "texts" VALUES ('ZZ102223', '邪神 进化之化身', '这张卡不能通常召唤。把自己场上4只怪兽解放的场合或者把自己场上1只原本卡名是「邪神 神之化身」的怪兽解放的场合才能特殊召唤。
INSERT INTO "texts" VALUES ('ZZ102224', 'No.1000 梦幻神 原数天地', '11星怪兽×4 
INSERT INTO "texts" VALUES ('ZZ102225', '海神龙 波塞冬', '10星怪兽×3 
INSERT INTO "texts" VALUES ('ZZ102226', '冥王龙 哈迪斯', '10星怪兽×3 
INSERT INTO "texts" VALUES ('ZZ102227', '天皇龙 宙斯', '10星怪兽×3 
INSERT INTO "texts" VALUES ('ZZ102228', 'CNo.1000 梦幻虚神 纽美罗尼厄斯', '12星怪兽×5
INSERT INTO "texts" VALUES ('ZZ102229', '真红眼龙骑士·黑魔导少女', '「黑魔术少女」＋「真红眼黑龙」或者龙族通常怪兽', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102230', '冥界之门－决斗仪式', '自己场上、墓地存在「千年石板」魔法卡和「千年」永续魔法卡7种类的场合，这张卡才能发动。①：这张卡不会因为卡的效果离开场上。②：自己的抽卡阶段，作为代替从卡组选择1张卡加入手中。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102231', '乌加多之眼', '场上存在「冥界之门－决斗仪式」时，这张卡才能发动。①：自己场上的卡的效果不会被无效化，控制权不会改变，不能被对方解放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102232', '爱西丝神官', '①：自己场上的「神官」怪兽存在2只以上的场合，这张卡可以从手中特殊召唤。②：1回合1次，可以查看自己卡组最上方的1张卡，如果那张卡是「千年」永续魔法卡的场合，可以把那张卡加入手中。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102233', '塞特神官', '①：这张卡特殊召唤时，可以把自己墓地1张「千年」永续魔法卡加入手中。②：1回合1次，可以把自己场上1张「千年」永续魔法卡送去墓地，选择对方场上1张卡发动。那张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102234', '玛哈德神官', '①：自己场上存在「无名的法老王－阿图姆」的场合，这张卡可以特殊召唤。②：自己场上的光属性怪兽不会被战斗破坏。③：这张卡和暗属性怪兽战斗的场合，这张卡的攻击力上升1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102235', '夏达神官', '①：自己场上的光属性怪兽被战斗或卡的效果破坏时，把手中的这张卡丢弃才能发动。那个破坏无效。只要这张卡在墓地存在，自己场上的光属性怪兽攻击力和守备力上升200。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102236', '卡利姆神官', '①：1回合1次，可以丢弃1张手牌发动。从卡组把1只「神官」怪兽加入手中。②：这张卡被战斗破坏送去墓地时，可以把手中1只光属性怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102237', '阿克纳帝神官', '①：1回合1次，可以把手中的1只「神官」怪兽特殊召唤。②：自己的回合结束时，这张卡变成守备表示。③：自己场上存在其他「神官」怪兽的场合，这张卡不会成为攻击或卡的效果对象。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102238', '黑暗大神官 阿克纳帝', '这张卡不能通常召唤。把自己场上1只「阿克纳帝神官」解放才能特殊召唤。①：1回合1次，可以把这张卡以外自己场上、手中的卡全部送去墓地发动。抽出那个送去墓地的卡的数量的卡。②：这张卡1回合1次不会被战斗或卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102239', '盗贼王 巴库拉', '这张卡不能通常召唤。①：自己或对方墓地存在永续魔法卡3张以上的场合可以特殊召唤。②：1回合1次，可以把自己场上1张永续魔法卡送去墓地，选择对方场上1张正面表示的魔法、陷阱卡发动。那张卡在自己场上放置。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102240', '无名的法老王－阿图姆', '这张卡不能通常召唤。①：自己墓地的「神官」怪兽存在3只以上的场合，这张卡可以特殊召唤。②：1回合1次，可以从卡组选择1只「神官」怪兽特殊召唤到自己场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102241', '千年魔导书', '①：从卡组把1张「千年」永续魔法卡加入手中。②：自己场上的魔法、陷阱卡被破坏时，可以把墓地的这张卡除外发动。那个效果无效并破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100117', '高速魔法－增压', '自己的高速指示物增加4个。回合结束时，自己的高速指示物减少至1个。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100142', '高速魔法－冲夺', '自己的高速指示物有4个以上的场合发动。直到回合结束为止，获得对手场上表侧守备表示存在的1只怪兽的控制权。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100144', '高速魔法－风暴之末', '自己用的高速指示物有10个以上时可以发动。场上存在的全部怪兽破坏。这个效果破坏送入墓地的怪兽每有1只，那些怪兽的控制者受到300的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100169', '高速魔法－高速之力', '自己的高速指示物4个以上时可以发动。直到自己的下一个回合的结束阶段时，自己场上存在的卡不能被对手的魔法·陷阱效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100234', '高速魔法－幻像之风', '自己的高速指示物有2个以上的场合可以发动。把自己墓地存在的1只等级2以下的怪兽特殊召唤。由这个效果特殊召唤的怪兽，这个回合的结束阶段时破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100241', '高速魔法－收购', '自己的高速指示物有4个以上的场合发动。选择场上1张表侧表示有放置「指示物」的卡破坏，回复「指示物」数量×100的基本分。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100354', '高速魔法－零之复苏', '自己的高速指示物有3个以上的场合可以发动。这个回合内，1只被效果破坏的怪兽攻击表示特殊召唤。由这个效果特殊召唤的怪兽攻击力变为0。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100534', '高速魔法－降档', '把自己的高速指示物除去6个发动，从自己卡组抽2张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100535', '高速魔法－闪电权杖', '自己高速指示物在2个以上的场合，选择自己场上的1只怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100536', '高速魔法－速击之翼', '自己的高速指示物有4个以上的场合发动。选择自己场上的1只怪兽发动。选择怪兽攻击力直到这个回合结束流程时上升自己的高速指示物数量×100点数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100537', '高速魔法－同调去除', '自己高速指示物有2以上时。直到结束阶段获得对方1只同调怪兽控制权。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100808', '高速魔法－音速炸弹', '自己高速指示物有4个以上的场合可以发动。给对方自己场上1只怪兽的攻击力的一半数值的伤害。（如果这个效果会使对方玩家的基本分变为0的场合，这个效果不发动。）', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100809', '高速魔法－银色航迹', '自己的高速指示物有5个以上的场合可以发动。自己场上存在的1只风属性怪兽的攻击力在那个回合的战斗阶段期间上升1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100813', '高速魔法－召唤提速', '自己的高速指示物有4个以上时才能发动。把手牌中一只等级4以下怪兽特殊召唤。那只怪兽在这个回合不能进行攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100865', '高速魔法－最终攻击', '自己的高速指示物有8个以上的场合发动。选择自己场上正面的1只怪物攻击力变为2倍。此怪兽不能进行直接攻击。这个回合结束时此怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101200', '高速魔法－暴君之力', '自己的高速指示物10个以上的场合可以发动。这个回合自己场上存在的卡不会被破坏。对方场上存在的卡被破坏时，给予对方基本分300点伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101206', '青眼黑翼龙', '这个卡名的①③的效果1回合各能使用1次。
INSERT INTO "texts" VALUES ('ZZ101217', '半蛇兽 迪尔邦多', '①：这张卡攻击宣言时发动。这张卡的攻击力上升500。
INSERT INTO "texts" VALUES ('ZZ101218', '精灵兽 迪尔邦多', '①：可以把自己场上1只「半蛇兽 迪尔邦多」送去墓地，把手卡的这张卡特殊召唤。
INSERT INTO "texts" VALUES ('ZZ101219', '精灵超兽 迪尔邦多', '①：对方场上存在攻击力为0的怪兽的场合，可以把手中的这张卡特殊召唤。
INSERT INTO "texts" VALUES ('ZZ101220', '精灵邪兽 迪尔邦多', '①：可以把自己墓地3只暗属性怪兽除外。把手中的这张卡特殊召唤。
INSERT INTO "texts" VALUES ('ZZ101214', '奥贝里斯克的巨神兵-立方体', '这张卡不能特殊召唤。这张卡通常召唤的场合，必须把自己场上3只怪兽解放在自己场上召唤或者把对方场上3只怪兽解放在对方场上召唤，召唤的这张卡的控制权在下个回合的结束阶段回归原本持有者。
INSERT INTO "texts" VALUES ('ZZ101216', '奥斯里斯的天空龙-错三角', '这张卡不能特殊召唤。这张卡通常召唤的场合，必须把自己场上3只怪兽解放在自己场上召唤或者把对方场上3只怪兽解放在对方场上召唤，召唤的这张卡的控制权在下个回合的结束阶段回归原本持有者。
INSERT INTO "texts" VALUES ('ZZ101221', '太阳神之翼神龙-球体形', '这张卡不能特殊召唤。这张卡通常召唤的场合，必须把自己场上3只怪兽解放在自己场上召唤或者把对方场上3只怪兽解放在对方场上召唤，召唤的这张卡的控制权在下个回合的结束阶段回归原本持有者。
INSERT INTO "texts" VALUES ('ZZ101885', '奥斯里斯的天空龙-判官秤', '①：可以选择对方场上1只正面表示的怪兽,把自己场上1张卡送去墓地发动。对象怪兽攻击力和守备力下降2000。这个效果让对象怪兽攻击力或守备力变成0的场合，把那只怪兽破坏。
INSERT INTO "texts" VALUES ('ZZ101886', '奥贝里斯克的巨神兵-方尖碑', '①：1回合1次，可以选择自己墓地1只神属性怪兽特殊召唤到自己场上。那之后把2只方尖碑衍生物（岩石族·地·1星·攻/守0）以守备表示特殊召唤到自己场上。
INSERT INTO "texts" VALUES ('ZZ101225', '太阳神之翼神龙-不死鸟', '这张卡不能通常召唤，用这张卡的效果才能特殊召唤。
INSERT INTO "texts" VALUES ('ZZ102242', '六甲秘祝－「前」', '①：自己墓地存在「六甲秘祝」魔法卡3张以上的场合，或者丢弃手中3张「六甲秘祝」魔法卡才能发动。对方的怪兽召唤、反转、特殊召唤其中1个无效并破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102243', '六甲秘祝－「斗」', '①：自己墓地存在「六甲秘祝」魔法卡的场合，或者丢弃手中1张「六甲秘祝」魔法卡才能发动。对方的魔法卡发动无效并破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102244', '六甲秘祝－「临」', '①：自己墓地存在「六甲秘祝」魔法卡的场合，或者丢弃手中1张「六甲秘祝」魔法卡才能发动。对方的陷阱卡发动无效并破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102245', '六甲秘祝－「兵」', '①：自己墓地存在「六甲秘祝」魔法卡的场合，或者丢弃手中1张「六甲秘祝」魔法卡才能发动。对方的怪兽的效果发动无效并破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102246', '六甲秘祝－「列」', '①：自己墓地存在「六甲秘祝」魔法卡2张以上的场合，或者丢弃手中2张「六甲秘祝」魔法卡才能发动。从卡组选择2张「六甲秘祝」魔法卡在自己场上盖放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102247', '六甲秘祝－「行」', '①：自己墓地存在「六甲秘祝」魔法卡3张以上的场合，或者丢弃手中3张「六甲秘祝」魔法卡才能发动。从自己或对方额外卡组选择1只怪兽特殊召唤到自己场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102248', '六甲秘祝－「阵」', '①：自己墓地存在「六甲秘祝」魔法卡2张以上的场合，或者丢弃手中2张「六甲秘祝」魔法卡才能发动。由对方造成的1次战斗伤害或效果伤害由对方代受。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102249', '六甲秘祝－「皆」', '①：自己墓地存在「六甲秘祝」魔法卡2张以上的场合，或者丢弃手中2张「六甲秘祝」魔法卡才能发动。以对方场上1只怪兽为对象，得到那只怪兽的控制权。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102250', '六甲秘祝－「者」', '①：自己墓地存在「六甲秘祝」魔法卡3张以上的场合，或者丢弃手中3张「六甲秘祝」魔法卡才能发动。从自己墓地选择这个卡名以外任意张「六甲秘祝」魔法卡在自己场上盖放。（同名卡最多1张。）', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101892', '真红眼的浴炎龙', '「真红眼」怪兽×2
INSERT INTO "texts" VALUES ('ZZ101893', '真红眼的究极龙', '「真红眼」怪兽×3
INSERT INTO "texts" VALUES ('ZZ101566', '真红眼的选择', '①：把手中1只「真红眼」怪兽送去墓地才能发动。从以下效果中选择其中1个适用。
INSERT INTO "texts" VALUES ('ZZ101710', '真红眼的咆哮', '①：自己场上正面表示的「真红眼」怪兽成为对方的魔法、陷阱、效果怪兽的效果对象时才能发动。那个效果无效并破坏，那之后对方的基本分减半。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101728', '真红眼燃尽', '①：把自己场上正面表示的1只「真红眼」怪兽解放才能发动。这个回合自己的手牌、场上、墓地的卡不受对方的卡的效果影响，自己受到的战斗和效果伤害全部变成0。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101884', '真红眼的浴火重生', '①：自己场上的「真红眼」融合怪兽被卡的效果或战斗破坏送去墓地时才能发动。把那只怪兽特殊召唤，那之后那只怪兽以外自己场上的怪兽全部破坏，这个效果特殊召唤的融合怪兽的攻击力上升这个效果破坏的怪兽全部攻击力合计数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102251', '护法天众－少净天', '①：自己场上有「护法天」怪兽以正面表示存在的场合，对方把效果怪兽的效果发动时，把手中的这张卡丢弃才能发动。那个效果无效并破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102252', '护法天众－善见天', '①：自己场上有「护法天」怪兽以正面表示存在的场合，对方把魔法、陷阱卡发动时，把手中的这张卡丢弃才能发动。对方发动的卡无效并破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102253', '护法天众－光音天', '①：自己场上有「护法天」怪兽以正面表示存在的场合，对方发动攻击时，把手中的这张卡丢弃才能发动。对方场上以正面攻击表示的怪兽全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102254', '护法天众－梵众天', '这个卡名的①的效果1回合只能使用1次。①：自己场上有「护法天」怪兽以正面表示存在的场合，把手中的这张卡丢弃才能发动。翻开自己卡组最上面的3张卡，把那之中的「护法天」怪兽全部加入手中，那以外的卡全部送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102255', '护法天龙－阿耨达龙王', '这个卡名的②的效果1回合只能使用1次。①：自己场上存在「护法天」怪兽的场合，手中的这张卡可以特殊召唤。②：这张卡特殊召唤成功时以对方场上1张卡为对象才能发动。那张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102256', '护法天龙－善住龙王', '这个卡名的②的效果1回合只能使用1次。①：自己场上存在「护法天」怪兽的场合，手中的这张卡可以特殊召唤。②：这张卡特殊召唤成功时才能发动。翻开自己卡组最上面的3张卡，把那之中的「护法天」怪兽尽可能特殊召唤，那以外的卡全部送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102257', '护法天龙－摩那苏婆帝龙王', '这个卡名的②的效果1回合只能使用1次。①：自己场上存在「护法天」怪兽的场合，手中的这张卡可以特殊召唤。②：这张卡特殊召唤成功时才能发动。从自己墓地把1只「护法天」怪兽加入手中。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102258', '护法天龙－婆楼那龙王', '这个卡名的②的效果1回合只能使用1次。①：自己场上存在「护法天」怪兽的场合，手中的这张卡可以特殊召唤。②：这张卡特殊召唤成功时才能发动。从自己卡组把1只「护法天」怪兽加入手中。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102259', '护法天神－无量光天', '包含2只「护法天神」连接怪兽的怪兽2只以上
INSERT INTO "texts" VALUES ('ZZ102260', '护法天神－难陀婆难陀龙王', '包含「护法天神」连接怪兽的怪兽2只以上
INSERT INTO "texts" VALUES ('ZZ102261', '护法天神－阿修罗', '包含「护法天」怪兽的怪兽2只以上
INSERT INTO "texts" VALUES ('ZZ102262', '护法天神－迦楼罗', '包含「护法天」怪兽的怪兽2只以上
INSERT INTO "texts" VALUES ('ZZ102263', '护法天神－摩睺罗伽', '包含「护法天」怪兽的怪兽2只以上
INSERT INTO "texts" VALUES ('ZZ102264', '护法天神－夜叉', '效果怪兽2只
INSERT INTO "texts" VALUES ('ZZ102265', '护法天神－紧那罗', '效果怪兽2只
INSERT INTO "texts" VALUES ('ZZ102266', '护法天神－乾达婆', '效果怪兽2只
INSERT INTO "texts" VALUES ('ZZ102267', '地狱鬼卒－鼠齿', '①：对方把墓地的怪兽特殊召唤时，可以把自己手中、墓地的这张卡特殊召唤。②：这张卡特殊召唤成功时必定发动。抽1张卡。
INSERT INTO "texts" VALUES ('ZZ102268', '地狱鬼卒 虎臂', '①：自己场上存在「地狱鬼卒」怪兽@对方把墓地的怪兽特殊召唤时，把自己手中或场上的这张卡解放才能发动。那些特殊召唤的怪兽全部除外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102269', '地狱鬼卒 龙颚', '①：这张卡和对方的特殊召唤的怪兽战斗的场合，只在伤害计算时这张卡的攻击力变成3000，并且在那次战斗这张卡不会被战斗破坏。②：这张卡被战斗破坏送去墓地时才能发动。从自己卡组把1只「地狱鬼卒」怪兽在自己场上特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102270', '地狱鬼卒 马面', '①：这张卡召唤成功时，把自己墓地1只「地狱鬼卒」怪兽除外才能发动。从自己卡组把1只「地狱鬼卒」怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102271', '地狱鬼卒 猴掌', '①：自己场上有「地狱鬼卒」怪兽以正面表示存在的场合，手中的这张卡可以特殊召唤。②：只要这张卡在怪兽区域正面表示存在，对方从墓地特殊召唤的怪兽的效果无效化。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102272', '地狱鬼卒 狗眼', '①：这张卡召唤、特殊召唤成功时变成守备表示。②：只要这张卡在怪兽区域正面表示存在，对方把墓地的怪兽特殊召唤的场合，随机丢弃对方1张手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102273', '地狱鬼卒－牛头', '暗属性怪兽2只
INSERT INTO "texts" VALUES ('ZZ102274', '地狱鬼卒 兔耳', '暗属性怪兽2只
INSERT INTO "texts" VALUES ('ZZ102275', '地狱鬼卒 蛇鳞', '暗属性怪兽2只
INSERT INTO "texts" VALUES ('ZZ102276', '地狱鬼卒 羊身', '  
INSERT INTO "texts" VALUES ('ZZ102277', '地狱鬼卒 鸡舌', '暗属性怪兽2只
INSERT INTO "texts" VALUES ('ZZ102278', '地狱鬼卒 猪鼻', '暗属性怪兽2只
INSERT INTO "texts" VALUES ('ZZ101887', '救世黑翼龙', '「救世龙」＋「黑翼龙」＋调整以外的怪兽1只
INSERT INTO "texts" VALUES ('ZZ101888', '救世蔷薇龙', '「救世龙」＋「黑蔷薇龙」＋调整以外的怪兽1只
INSERT INTO "texts" VALUES ('ZZ101889', '救世妖精龙', '「救世龙」＋「古代妖精龙」＋调整以外的怪兽1只
INSERT INTO "texts" VALUES ('ZZ101895', '救世工具龙', '「救世龙」＋「动力工具龙」＋调整以外的怪兽1只
INSERT INTO "texts" VALUES ('ZZ102279', '高速魔法－高速能量', '自己的高速指示物有2个以上的场合可以发动。直到这个回合结束时，自己场上的1只怪兽的攻击力上升自己的高速指示物数×200点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102280', '高速魔法－同调归还', '自己的高速指示物有5个以上的场合可以发动。1只从游戏中被除外的同调怪兽特殊召唤。这个同调怪兽在这个回合的结束阶段时从游戏中除外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102281', '高速魔法－星之力', '自己高速指示物4个以上的场合，将自己场上1只怪兽从游戏中除外，直到这个回合的结束阶段，自己场上存在的1只怪兽的攻击力上升那只怪兽的等级×100点的数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102282', '高速魔法－召唤封锁', '自己使用的高速指示物有4个以上的场合可以发动。将1张手卡送去墓地，从自己卡组抽1张卡。这张卡发动的回合，对方玩家不能特殊召唤怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102283', '高速魔法－无声燃烧', '自己用的高速指示物有4个以上的场合可以发动。这个回合没有攻击的自己场上的怪兽每有1只就给予对手基本分300点伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102284', '高速魔法－命运之咒缚', '自己的高速指示物有2个以上的场合才能发动。选择自己场上正面表示的一只怪兽放置2个诅咒指示物。自己回合1次，可以把那只怪兽的1个诅咒指示物取消，给予对手那只怪兽攻击力一半的伤害，这个回合那只怪兽不能进行攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102285', '高速魔法－差距风暴', '自己的高速指示物数量跟对手的相差10个以上的场合发动。破坏场上存在的魔法、陷阱卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102286', '高速魔法－死者同调', '自己的高速指示物有5个以上的场合发动。选择自己额外卡组的1只同调怪兽。选择怪兽的同调召唤时需要的调整怪兽及调整以外的怪兽从自己墓地选择并从游戏中除外，选择的同调怪兽在自己的场上特殊召唤。这个特殊召唤当作同调召唤。这个效果特殊召唤的怪兽在结束阶段时从游戏中除外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102287', '高速魔法－起爆化', '自己的高速指示物有2个以上的场合发动。选择自己的魔法·陷阱区的1张卡片选择破坏。对手场上存在的全部怪兽的表示形式变更的。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102288', '高速魔法－反应器舱', '自己的高速指示物有4个以上的场合发动。选择自己场上正面存在的一只攻击力1000以下的怪兽，给予对手那只怪兽原本攻击力的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102289', '高速魔法－高速碰撞', '自己的高速指示物有2个以上的场合发动。选择自己场上的一张卡和双方场上另一张卡，选择的2张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102290', '高速魔法－防御炸裂', '自己的高速指示物有2个以上的场合发动。选择场上一只防守表示的怪兽，变成正面攻击表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102291', '高速魔法－超速', '自己的高速指示物有4个以上的场合发动。把自己的高速指示物全部除去，把自己墓地的一张等级3以下的怪兽卡和一张魔法卡或陷阱卡加入手卡。此卡发动后的3个回合，自己的高速指示物不会因「高速世界」或「高速世界2」的效果而增加。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102292', '高速魔法－同调恐慌', '自己高速指示物7个以上时，可以从额外卡组尽可能特殊召唤与这次决斗中在场上同调召唤的怪兽的同名怪兽。这个效果特殊召唤的同调怪兽攻击力变为0，效果无效化。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102293', '高速魔法－升调123', '自己高速指示物有4个以上时 选择场上1只怪兽掷1次骰子。根据出现的数字，选择怪兽适用以下效果。●1·2：等级上升1。●3·4：等级上升2。●5·6：等级上升3。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102294', '高速魔法－高速融合', '自己的高速指示物有4个以上时才能发动。从手牌或场上将融合怪兽决定了的融合素材怪兽送入墓地，从额外卡组将那1只融合怪兽当作融合召唤地特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102295', '高速魔法－能量权杖', '自己的高速指示物有6个以上时发动。把自己卡组1张怪兽卡送入墓地。自己场上1只攻击表示怪兽攻击力在这个回合进行战斗的伤害计算时，上升这张卡的效果送入墓地的怪兽攻击力数值。这张卡效果发动后的下次自己回合抽卡流程时自己不能抽卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102296', '高速魔法－累加上升', '自己的高速指示物有2个以上时才能发动。把任意手卡送入墓地，每送去墓地一张手卡，增加2个高速指示物。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102297', '高速魔法－一半捕获', '自己的高速指示物有3个以上的场合发动。选择对手场上一只怪兽攻击力减半，自己恢复其攻击力减少的数值的生命值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102298', '高速魔法－高速抽卡', '自己的高速指示物有12个时才能发动。抽2张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102299', '高速魔法－超调谐', '自己的高速指示物有3个以上的场合发动。解放自己场上一只怪兽，把自己手上1只等级等于或低于那只被解放怪兽的等级的调整怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102300', '高速魔法－高速风暴', '自己的高速指示物有3以上的场合可以发动。给与对方玩家1000点的伤害。自己的准备阶段时这张卡在墓地存在的场合，去除3个高速指示物，这张卡回到手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102301', 'I：P伪装舞会莱娜', '连接怪兽以外的怪兽2只
INSERT INTO "texts" VALUES ('ZZ102302', '封印之门', '这张卡被破坏并送去墓地的时候，从自己的墓地把
INSERT INTO "texts" VALUES ('ZZ102303', '最强的决斗者', '从场上·手牌·卡组三者存在的「黑魔导」「青眼白龙」「真红眼黑龙」除外，可从墓地·手牌·卡组特殊召唤。所有的魔法·陷阱·怪兽效果由我方选择接受或不接受。这张卡在场上存在的场合双方只能通过效果·战斗伤害决定出胜负。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102304', '热烈的决斗者', '对方召唤·特殊召唤神属性怪兽，可以将手牌或卡组一张神属性怪兽送入墓地，此卡从手牌·卡组·墓地特殊召唤。所有的魔法·陷阱·怪兽效果由我方选择接受或不接受。此外，可以把这张卡作为祭品，选择卡组三张神属性怪兽加入手牌，这个效果无法被无效，这个效果在对方回合也能发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102305', '激战的决斗者', '对方召唤·特殊召唤神属性怪兽，可以将手牌或卡组一张神属性怪兽送入墓地，此卡从手牌·卡组·墓地特殊召唤。所有的魔法·陷阱·怪兽效果由我方选择接受或不接受。可以把这张卡从游戏中除外，双方尽可能从卡组把怪兽无条件特殊召唤，可以占用魔法·陷阱区域。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102306', '终结的决斗者', '对方召唤·特殊召唤神属性怪兽，可以将手牌或卡组一张神属性怪兽送入墓地，此卡从手牌·卡组·墓地特殊召唤。所有的魔法·陷阱·怪兽效果由我方选择接受或不接受。此外，可以把这张卡当作祭品，双方场上·手牌·卡组·额外卡组·墓地所有神属性怪兽全部从游戏中除外，本场决斗不能再使用。这个效果无法被无效，这个效果在对方回合也能发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
