INSERT INTO "texts" VALUES ('ZZ102445', '超魔导龙骑士-混沌魔导龙剑士', '「黑魔导」或魔法师族仪式怪兽＋龙族仪式怪兽
INSERT INTO "texts" VALUES ('OCG00048', '追放者艾克莉西娅', '那颗纯白之心，今后将填满众多回忆。
INSERT INTO "texts" VALUES ('OCG00049', '黑衣的阿不思', '其名所彰显的，是被闭锁于黑暗的过去，还是光辉闪耀的未来呢。 ', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('OCG00050', '铁兽战线', '开火吧—— ', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('OCG00051', '二位圣女', '有时像温柔的姐姐，有时又像是严格的老师。
INSERT INTO "texts" VALUES ('OCG00052', '凶导者阿尔贝', '被深渊分隔之人。嘲笑光明，也欺瞒黑暗。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102446', 'ZYX-战车龙', '机械族怪兽1只＋机械族同盟怪兽2只
INSERT INTO "texts" VALUES ('ZZ102447', '元素英雄 闪光贤者翼侠', '「于贝尔」或记载它的怪兽＋「英雄」融合怪兽1只
INSERT INTO "texts" VALUES ('TSK00360', '守护的天使', '天使的宿命，永远守护着善良的人类，从无怨言。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00341', '愤怒的千年树妖', '每当发怒时就会从身体流出让所有物体都熔化的熔岩。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00247', '黄色鹿妖', '使用各种手段恶作剧的黄色鹿妖，总是喜欢作弄别人。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00270', '火焰兽', '火山王·亚夫斯西的跟随者，借着火山王的势力，到处挑衅生事，
INSERT INTO "texts" VALUES ('TSK00239', '邪恶骑士', '被邪恶骑士之心所寄宿，体质健硕的战士族怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00262', '背面袭击', '当这张卡片从攻击表示转为守备表示时，可让自己的牌组重新洗牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00359', '死亡之手·卡尔斯', '不管遇到多难缠的对手都逃不出他魔法之手，然后把对手拉倒地狱的深渊。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00379', '魔法守护者', '「锁链使用者」＋「无脸人」
INSERT INTO "texts" VALUES ('TSK00374', '彩虹精灵', '拥有优美的姿态和鲜艳的色彩。
INSERT INTO "texts" VALUES ('TSK00206', '钢刀战士托斯', '对手的战场上与墓地中每有一只龙族怪兽，
INSERT INTO "texts" VALUES ('TSK00365', '失修的机械堡垒', '在发动的回合里，「古代的机械」字样的怪兽的守备力上升500点，卡片在回合结束时被破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00255', '天魔之澡', '必须牺牲两只怪兽，成功进行牺牲召唤，可从牌组抽取此卡2张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00212', '结束战斗', '此卡通常不能召唤。把自己墓地的2只水属性怪兽清除在游戏终了之后可特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00181', '最终决战', '我方生命值在1000点以下时，可在敌方回合后发动。
INSERT INTO "texts" VALUES ('TSK00216', '光之星', '可将对方场上一只攻击状态的怪兽改成守备状态一次，另外可以提升我方场上一只怪兽的攻击力500点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00227', '邪恶的笑脸', '存在自己牌堆上的怪兽，并且在攻击对手时可以发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00356', '半人兽', '和马融为一体的兽战士族怪兽，能以惊人的腕力挥动武器攻击，杀伤力十分强大。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102448', '黑暗大邪神-佐克·内洛法', '这张卡不能通常召唤。把场上和墓地合计等级为99或以上的暗属性怪兽从游戏中除外的场合才能特殊召唤。这张卡不会被神属性以外的怪兽战斗破坏。
INSERT INTO "texts" VALUES ('ZZ102449', '迪亚邦德的黑暗之魂', '这张卡不能通常召唤。把一只「迪亚邦德之核」解放的场合才能特殊召唤。
INSERT INTO "texts" VALUES ('ZZ102450', '终极迪亚邦德', '「迪亚邦德」 怪兽1只 ＋ 1只暗属性怪兽
INSERT INTO "texts" VALUES ('ZZ102451', '黑暗容器', '这个卡名的卡在1回合只能发动1张。
INSERT INTO "texts" VALUES ('ZZ102452', '螺旋波', '这张卡可以视为「迪亚邦德」卡。
INSERT INTO "texts" VALUES ('ZZ102453', '佐克炼狱', '这张卡和发动和效果不会被无效。这个卡名的卡在1回合只能发动1张。这张卡发动的回合，不能攻击。
INSERT INTO "texts" VALUES ('ZZ102454', '影域', '你在一场决斗中只能使用1张「影域」。这张卡和发动和效果不会被无效。1回合1次，这张卡不会被效果破坏。
INSERT INTO "texts" VALUES ('ZZ102455', '迪亚邦德进化', '这张卡可以视为「迪亚邦德」卡。
INSERT INTO "texts" VALUES ('ZZ102456', '命运的沙漏', '这张卡可以视为「迪亚邦德」卡。
INSERT INTO "texts" VALUES ('ZZ102457', '黑暗显现', '以这回合被送入墓地的一只「黑暗大邪神-佐克·内洛法」为对象才能发动，选择的怪兽无视条件特殊召唤。
INSERT INTO "texts" VALUES ('TSK00120', '独角魔人', '发动战斗损伤以外的损伤攻击后，可以将自己的损伤移给对方。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00028', '预言者贝克斯', '自己墓地没有魔法卡存在时，彼此玩家不可以进行战斗。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00019', '时光回溯机', '可从自己墓地特殊召唤守备表示的普通怪兽一只，当此卡不存在于战场上时，此怪兽会被破坏，而此怪兽被破坏时，此卡片也会被破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00424', '地狱的小丑', '能指定对方的一张手牌丢到墓地里去。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00405', '回收符', '可以让战斗情景回到上一回合的战斗再重新开始。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00018', '火炎流星弹', '会给予对手自己场上正面表示的光属性怪兽数×300的点数伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00190', '魔性之球', '用球体发出的热量让战士族强化，攻击力和守备力各增加300点！可以重复使用。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00242', '神奇使者', '破坏对方场上攻击力最强的正面表示怪兽。
INSERT INTO "texts" VALUES ('TSK00362', '古代的智者', '虽然攻击力守备力都不高，不过他的智慧和念力可以让对手折服。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00246', '凤凰王子', '居无定所的小王子，整天飞来飞去，帮助有需要的人。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00353', '鬼盔之女王', '拥有坚硬无比的盔甲。只要此卡留在场上所有攻击力在
INSERT INTO "texts" VALUES ('TSK10353', '海龙王', '支配着大海的一切生物。一旦此卡召唤成功就可以把自己场上存在的「海」送到墓地，除了这张卡，把互相的手中牌和场上的牌全部卡送到墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00352', '魔城之域', '当这张卡在战斗被破坏时，对手也受到相应的损伤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00055', '野蛮的鲸怪', '借着「光之宫殿」唤出，需牺牲手中或场上星星数合计8个以上的怪兽卡才能召唤，
INSERT INTO "texts" VALUES ('TSK00357', '嗜血者', '当此卡转为攻击表示时，可以当场将场上任何一只怪兽送往墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00389', '火炎的战士', '「月光兽」＋「铜人」
INSERT INTO "texts" VALUES ('TSK00199', '终极格斗战士', '让被打败的伙伴把怨念附于剑上，以提升攻击力。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00187', '沼地飞龙', '覆盖着鱼鳞的沼地飞龙，能够自由的穿梭在沼地的危险地带。防守能力极高。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00178', '雪地战士', '将这张卡奉献为祭品后，可破坏场上的任意一只怪兽。
INSERT INTO "texts" VALUES ('TSK00322', '狩猎死神', '反转：破坏一张场上的陷阱卡，选择的卡片已经被设定好时，需确认这张卡，若是陷阱卡则加以破坏，若是魔法卡则返回原地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00252', '红衣魔鬼', '自己墓地的魔法卡1张会从游戏中除去，在对手回合结束时，此卡片的攻击力会增加200点，此效果一回合可以使用一次。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00272', '紫色妖姬', '此卡不会被未指定对象的魔法或陷阱卡所破坏，而且不会
INSERT INTO "texts" VALUES ('TSK00257', '森林之女·纳斯', '被称为树魔的纳斯，它是千年树妖的女儿，威力一般。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00271', '勾魂使者', '此卡片无法进行普通召唤，必须将自己墓地一张光属性怪兽从墓地中剔除了，才能
INSERT INTO "texts" VALUES ('TSK00348', '双极圣女', '掌管着水与火的圣女，她的性格也想水火不容两极分化飘浮不定。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00192', '死灵魔兽', '玩家可以从墓地中选出最多三张怪兽卡并移除，每一张移除的怪兽卡能让此卡的攻击力上升300点直到对方回合结束。
INSERT INTO "texts" VALUES ('TSK00177', '恐怖怨灵', '当这张卡被送往墓地时，可从牌组里抽出攻击力1500以下的怪兽放进手牌里，接着牌组重新洗牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00179', '人头马身弓箭手', '只要该牌在自己的场地上以正面表示状态存在，当场地上的怪兽回到所属方的手牌时，该怪兽的所有者从手牌中选择1张牌放在墓地里。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00139', '人头马身兽', '人与兽合为一体的怪兽，性格非常凶暴，箭一离手，可将天空射穿。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00210', '装甲武装龙', '抛3回硬币，其中2回以上为正面时可破坏1只对手的怪兽。此效果只有在自己的回合使用一次。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00175', '日月之神', '从墓地剔除两只怪兽，特殊召唤此卡。
INSERT INTO "texts" VALUES ('TSK00058', '被奴役的佳义兽', '被奴役的恶魔族战士，总在寻找时机逃脱，对奴役它的敌人进行恐怖的报复。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00180', '神圣女战士', '只要有怪兽召唤或反转召唤（包括转为正面表示时），每只怪兽可让玩家回复1000生命点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102458', '超级电荷·加农水炮龟', '「超级水箭龟」＋「捷克罗姆」
INSERT INTO "texts" VALUES ('ZZ102459', '死神棺鬼', '「死神棺」＋「耿鬼」
INSERT INTO "texts" VALUES ('ZZ102460', '超级戟脊·班基拉斯龙', '「超级·班基拉斯」＋「戟脊龙」
INSERT INTO "texts" VALUES ('TSK00184', '魔法城堡', '可以观看对手的手牌，并且指定一张灵体怪兽卡丢进墓地。
INSERT INTO "texts" VALUES ('TSK00182', '调皮小魔女', '可在普通召唤之外在另外召唤出怪兽，每召唤一只要支付1000点生命点。
INSERT INTO "texts" VALUES ('ZZ102461', '琰魔战士·葬', '龙族·暗属性等级10的同调怪兽×1
INSERT INTO "texts" VALUES ('TSK00203', '贤者的王宫', '将我方场上的一张龙族怪兽卡奉献为祭品后，可以破坏掉场上守备力比奉献怪兽的攻击力还要低的所有正面状态怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00125', '魔法森林', '当此卡发动时，场上的兽族、昆虫族、植物族的攻击力提升400点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00201', '无底悬崖', '对方以怪兽攻击我方时发动，能破坏对方所有攻击表示的怪兽。将对方以单一怪兽为目标的魔法转移到别的目标。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00417', '魔法的封印', '只要此存在场上，所有的魔法卡都不可以发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00407', '使用魔法的武器', '能让魔法师族的怪兽攻击力上升400点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00244', '外来使者', '此卡可使战斗场上的天使族攻击力·守备力增加1000点。
INSERT INTO "texts" VALUES ('TSK00413', '魔群的聚集', '在敌方待命阶段，指定敌方四张手卡丢到墓地里。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00419', '贵族地下室', '从牌组里抽出两张卡丢到墓里去。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00108', '突风之扇', '如果本卡存在于战场上，我方的风属性怪兽攻击力提高400点，守备力提高200点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00200', '盔甲战士', '手握流行大锤的盔甲战士，战斗时必须一对一单挑，否则无法尽兴。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00114', '机械王', '当此卡从游戏中被消除时，在此次游戏的最后，可以把这张卡从自己战场上以表侧攻击进行特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00354', '水花精灵', '优美的姿态，连攻击敌人的武器都像一朵盛开的花朵那么漂亮。趁敌人在欣赏水花时攻击敌人。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00363', '勇猛的死士', '被他所打到的人都会粉身碎骨。此卡可以直接攻击玩家。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00375', '元素天使', '传说中有着再生力量的天使。是能源守护者。
INSERT INTO "texts" VALUES ('TSK00346', '鹰之驯兽师', '此卡在场上表侧表示存在时，可以获得敌方场上一只兽战士族怪兽的控制权。直到该回合结束。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00183', '圣诞独眼恶魔', '由心地邪恶的人制造的眼珠恶魔，会以黑暗炸弹攻击敌人。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00106', '岩石精灵', '可爱的小精灵。它的出现魔法卡对它无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00383', '魔兽 地狱破坏者', '必须靠「白骨的聚会」才能降临，必须从场地或手牌中，献上星星数合计6个以上的祭品才能召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00112', '火焰草', '头顶长了两个眼镜的火焰草。拥有眼观四方的超强观察力。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00328', '风的守护者', '可以抵消背面状态的「风的守护者」为目标的魔法卡效果，抵消后此卡更改为正面守备状态。
INSERT INTO "texts" VALUES ('TSK00186', '红神龙', '此卡片不会遭到不指定对象的魔法或陷阱所破坏。此外，与攻击力1900以下的怪兽战斗时不会被破坏。
INSERT INTO "texts" VALUES ('TSK00196', '复仇的泥怪', '当此卡从守备表示转为攻击表示时，可让对方的一只怪兽回到手牌里，先以背面表示出牌，变成攻击显示之后就可发动效果。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102462', '终焉破灭之女神 露茵', '「世界末日」或「世界不灭」降临的8星天使族怪兽×1
INSERT INTO "texts" VALUES ('ZZ102463', '终焉破灭之美神 露茵', '「世界末日」或「世界不灭」降临的10星天使族怪兽×1
