INSERT INTO "texts" VALUES ('ZZ102465', '电气雷龙', '「电气」8星同调怪兽×1
INSERT INTO "texts" VALUES ('TSK00188', '死亡宫殿', '可以破坏场上任意一张具有抵消陷阱能力的卡片。提高恶魔族的攻守能力各500点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00110', '电击鞭', '此卡出现时雷族怪兽的攻击力和守备力提高300点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00332', '原始神·麻烦', '在回合结束之前威力提升·降低的效果将倒反，回合结束时此卡被送往墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00163', '火的魔术师', '操纵火的魔术师，将自己的全部生命都用在练习的疯狂魔术师。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00118', '宇宙双头兽', '当成功召唤此卡时，可破坏场上对方的2张魔法卡或陷阱卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00146', '天空龙', '混沌之天际雷声隆隆，连串的锁中系着一张古代的魔法引导书，夸示着无限的神力。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00185', '落地狼', '拥有一副锋利的尖牙的落地狼，要小心他的利爪。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00347', '冥府的鬼战士', '翻面效果：对手场上的每一张魔法或陷阱卡都将对对手玩家造成300点的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00191', '复仇机械巨人', '笨重的机械巨人，一心想着报复。心中充满了仇恨。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00198', '钢铁士兵', '愤怒的钢铁士兵，得罪他你的处境会很危险', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
