INSERT INTO "texts" VALUES ('ZZ102708', '殉道者之暗黑城入口', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。
INSERT INTO "texts" VALUES ('ZZ102709', '青眼的白龙', '传说中以非常高的攻击力自夸的龙，任何对手都可以加以粉碎，其破坏力无法估计。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102710', '青眼白龙', '以骇人的攻击力著称的白龙，能够席卷一切，破坏力无法估量。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102711', '青眼白龙', '以高攻击力而骄傲的传说之龙。不论是怎样的对手都能粉碎，其破坏力无法估量。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
