INSERT INTO "texts" VALUES ('ZZ102992', '黑魔导女孩紫晶杖', '此卡只能给「黑魔导女孩 LV6」的怪兽装备，
INSERT INTO "texts" VALUES ('ZZ102993', '黑魔导女孩紫晶戒', '此卡只能给「黑魔导女孩 LV6」的怪兽装备，
