INSERT INTO "texts" VALUES ('ZZ103001', 'VW-极超强击虎', '4星机械族怪兽＋光属性机械族同盟怪兽
INSERT INTO "texts" VALUES ('ZZ103002', '究极龙魔导师', '「青眼究极龙」（或者「青眼」怪兽×3）＋「混沌」仪式怪兽
INSERT INTO "texts" VALUES ('ZZ103003', '混沌幻魔 阿米泰尔-虚无幻影罗生闷', '「神炎皇 乌利亚」＋「降雷皇 哈蒙」＋「幻魔皇 拉比艾尔」
INSERT INTO "texts" VALUES ('ZZ103004', '红莲蔷薇龙', '调整＋调整以外的怪兽1只以上
INSERT INTO "texts" VALUES ('ZZ103005', '废品战士', '「废品同调士」＋调整以外的怪兽1只以上
INSERT INTO "texts" VALUES ('ZZ103006', '欧贝利斯克之巨神兵', '在他降临大地时，烧灼的疾风将狂吹大地，所有生物都变成了尸骸。', '送去墓地', '对方怪兽全部破坏', '把3只解放作召唤', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103007', '奥西里斯之天空龙', '混沌之天际雷声隆隆，连串的锁中系着一张古代的魔法引导书，夸示着无限的神力。', '送去墓地', '攻击下降', '把3只解放作召唤', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103008', '原始生命态 尼比鲁', '这个卡名的效果1回合只能使用1次。
INSERT INTO "texts" VALUES ('ZZ103009', '太阳神之翼神龙', '歌咏的精灵。拥有伟大的力量掌管着万物的生命、灵魂甚至骨骸。', '攻守上升', '破坏', '把3只解放作召唤', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103010', '超越龙 流星衔尾龙', '这张卡不能通常召唤，用卡的效果才能特殊召唤。这个卡名的①②③的效果1回合各能使用1次。
INSERT INTO "texts" VALUES ('ZZ103011', '究极传导恐兽', '这张卡不能通常召唤。从自己墓地把2只恐龙族怪兽除外的场合可以特殊召唤。
INSERT INTO "texts" VALUES ('ZZ103017', '千年·被封印的机械大法师', '使用千年神器仿制的黑暗大法师。在被法老王唤醒后，无限的破坏力，任何敌人都会在一瞬间消灭殆尽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103012', '千年·被封印的机械大法师', '使用千年神器的力量仿造的机械形态黑暗大法师，解除封印后似乎有无限的力量。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103013', '千年·被封印的机械右腕', '封印了千年的机械臂，解除封印后不知还能否活动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103014', '千年·被封印的机械左腕', '封印了千年的机械臂，解除封印后不知还能否活动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103015', '千年·被封印的机械右足', '封印了千年的机械足，似乎是某种大型机器人的一部分。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103016', '千年·被封印的机械左足', '封印了千年的机械足，似乎是某种大型机器人的一部分。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103018', '晶钢强化青眼黑龙', '「灰钢真红眼黑龙」＋「晶体青眼白龙」
INSERT INTO "texts" VALUES ('ZZ103019', '灰钢真红眼黑龙', '1回合1次，将2张手牌舍弃，从卡组抽1张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103020', '青眼蓝焰龙', '被破坏时，从卡组将最多2张「青眼蓝焰龙」加入手牌。此卡作为超量素材时，超量怪兽攻击力上升500点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103021', '晶体青眼白龙 Ⅱ', '1回合1次，将自己场上这张卡以外的2只怪兽破坏，可从卡组将1张卡加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103022', '龙的孕育', '被卡的效果从手牌送入墓地时，可从墓地特殊召唤2只以外的龙族怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103023', '青黑晶钢融合', '从自己手牌、墓地、场上把「灰钢真红眼黑龙」＋「晶体青眼白龙」的融合素材怪兽送去墓地，把1只融合怪兽「晶钢强化青眼黑龙」从额外卡组特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103024', '晶钢复活', '将墓地存在的「晶钢强化青眼黑龙」召唤到场上。「晶钢强化青眼黑龙」被破坏时此卡破坏，可从墓地将「灰钢真红眼黑龙」＋「晶体青眼白龙」特殊召唤上场。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103025', '晶钢复活 Ⅱ', '将墓地存在的「晶钢强化青眼黑龙Ⅱ」召唤到场上。「晶钢强化青眼黑龙Ⅱ」被破坏时此卡破坏，
INSERT INTO "texts" VALUES ('ZZ103026', '灵之召唤', '每把我方墓地1只魔法师族怪兽从游戏中除外，可以选择我方墓地1只魔法师怪兽正面攻击表示特殊召唤，此外，这张卡从场上送去墓地时，选择我方墓地2只怪兽无视条件特殊召唤到我方场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103027', '晶体青眼白龙 Ⅱ', '1回合1次，将自己场上这张卡以外的2只怪兽破坏，可从卡组将1张卡加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103028', '焰火红龙', '此卡只能融合召唤，把场上或墓地的1只「真红魔龙」和手牌的4只龙族怪兽融合才能进行融合召唤（不需融合魔法卡），
INSERT INTO "texts" VALUES ('ZZ103029', '斗爪狐', '与这张卡战斗过的怪兽在结束阶段时破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103030', '沉默战队', '将场上1只名字带有「沉默」的怪兽送入墓地，此卡可以从手牌特殊召唤上场，因此效果特殊召唤成功的回合，此卡不受对方任何卡片效果影响。选择对方场上1只怪兽，选择的怪兽攻击力下降我方墓地暗属性怪兽数量×800点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103031', '地缚神的印章', '此卡召唤崇高后的第2个我方回合的准备阶段，将此卡从我方场上解放，可以从手牌无条件特殊召唤「地缚神 阿斯利亚·皮斯科」，由于此效果召唤上场的「地缚神 阿斯利亚·皮斯科」不受场地卡条件限制，攻击力上升1000点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103032', '武装龙LVMAX', '1回合1次舍弃1张手牌破坏对方魔法陷阱区所有卡片，被此卡战斗破坏的怪兽不送入墓地，直接召唤到我方场上来。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103033', '古代机械青眼白龙', '移除我方墓地1只龙族怪兽，此卡可以从手牌特殊召唤到场上，此卡的攻击力增加被移除怪兽的攻击力数值。当此卡发动攻击宣言时，如果我方手牌存在名字带有「青眼」的怪兽时，给对方观看，直到战斗伤害阶段结束时，对方不能发动卡片效果。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103034', '天龙裁决', '每当我方名字带有「奥西里斯」的怪兽召唤成功时，放开对方卡组最上面1张卡。只要是怪兽的场合就送入墓地，之后继续翻牌，是其他卡的场合覆盖回卡组最上方，并结束翻牌。当此卡因对方卡效果被破坏时，无条件强制破坏对方场上1张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103035', '魔术之禁', '1回合1次，我方抽牌阶段前发动。移除我方墓地1张名字带有「奥利哈钢」的魔法师族怪兽，可以选择以下1个效果发动：·本回合可以抽3张卡。·抽1张卡，如果是名字带有「奥利哈钢」的魔法师族怪兽时可以将那只怪兽送入墓地，给予对方那只怪兽的攻击力数值的生命值伤害。此效果发动成功的回合我方可以继续抽卡。直到抽到其他卡为止。当此卡被对方破坏时，移除我方墓地3只名字带有「奥利哈钢」的魔法师族怪兽可以让那个破坏效果无效，并破坏对方魔法陷阱区所有卡片。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103036', '青龙铠甲', '此卡只能装备给名字带有「青眼」的怪兽上。装备的怪兽1回合1次不受对方任何卡效果影响。当此卡被破坏时，可以将装备怪兽送入密度，并将此卡拿回手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103037', '末日归途', '当我方场上存在名字带有「奥利哈钢」的怪兽2只以上时，破坏我方场上所有怪兽，从卡组无条件特殊召唤1张名字带有「奥利哈钢」的魔法师族怪兽。当此卡因对方卡效果被破坏时，无条件强制破坏对方场上1张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103038', '科技属 重甲侠', '此卡可以直接攻击对方。每当此卡给予对方生命值造成直接伤害时，攻击力上升1000点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103039', '科技属 暗影战士', '此卡召唤成功，把对方场上1张卡送去墓地时，我方回复1000点生命值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103040', '青炎王', '此卡召唤成功后，攻击力上升我方场上除此卡外正面表示存在的怪兽数量×500点。
INSERT INTO "texts" VALUES ('ZZ103041', '电子烈焰龙', '此卡被魔法·陷阱卡效果破坏时，可以选择对方场上1只怪兽代替被破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103042', '神炎红龙', '限此卡在场上正面表示存在，对方发动怪兽效果时，必须舍弃1张手牌。没有舍弃的场合，那只效果怪兽的效果无效化。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103043', '小星虫', '当对方特殊召唤时将此卡从手牌送入墓地，对方那次召唤无效，怪兽送入墓地。限此卡在墓地存在。每回合我方生命值增加200点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103044', '别西卜', '自己的主要阶段时，每除去我方墓地的1张卡，可以将对方场上的1只怪兽作为祭品。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103045', '烈焰卡拉', '这张卡造成对方玩家生命值伤害的时候，随机选择对方2张手牌送入墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103046', '吸魂之龟', '双方墓地每有1张卡，此卡攻击力上升100点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103047', '万兽王 布吉', '这张卡不能通常召唤，这张卡与对方怪兽进行战斗时，可以将对方怪兽与此卡从游戏中除外，这个效果除外的怪兽在战斗阶段结束时回到场上。同时这张卡的攻击力上升对方怪兽等级×200的数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103048', '古神兽 鬼鳗', '此卡被怪兽攻击破坏送入墓地时，可以选择卡组1张水属性怪兽特殊召唤上场，此召唤被对方卡的效果破坏时，对方受到此卡攻击数值的生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('DCOR0011', '异世雷皇-哈特蒙', '此卡成功召唤的场合，破坏对方场上所有怪兽，每破坏1只怪兽，我方从卡组抽1张卡。此卡的攻击力直接战斗阶段结束时上升1000点，这个回合，这张卡在同1次战斗阶段中可以作2次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('DCOR0039', '变色飞龙', '丢弃1张手牌，这张卡可以从手牌正面表示特殊召唤上场。1回合1次，自己的主要阶段时可以从手牌·墓地或除外区把除这张卡以外的1只龙族怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('DCOR0044', 'No.17 闪光海恶龙', '3星怪兽×2
INSERT INTO "texts" VALUES ('ZZ103052', '背后的力量', '我方场上有4星以下怪兽存在时发动，只要这张卡在场上存在，对方若不从卡组把1张魔法卡送去墓地，则不能把陷阱·魔法卡发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103053', '魔导反击', '对方的抽卡阶段可以发动，确认对方抽的卡。那张卡是魔法或陷阱卡的场合，从以下效果中选择1个适用。那以外的卡的场合，这张卡破坏。
INSERT INTO "texts" VALUES ('ZZ103054', '累赘小鬼', '此卡装备在对方怪兽身上，被装备的怪兽不能发动效果，攻击力每回合下降500点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103055', '血路', '我方的怪兽被战斗破坏时，对方攻击的怪兽从游戏中除外，对方承受此怪兽攻击数值的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103056', '灵魂交替', '对方攻击宣言时发动，我方场上的1只怪兽和对方场上的1只怪兽攻击力调换。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103057', '魂引', '自己场上没有怪兽存在的场合，选择对方墓地的1只怪兽在自己场上特殊召唤。（此效果不会无效化）3个回合后，怪兽的控制权转移给对方。我方不能将此怪兽作祭品和同调素材。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103058', '捕灵', '只要这张卡在场上存在，双方每有1只怪兽被破坏或除去，此卡增加1个魔力指示物。我方怪兽的攻击力就上升魔力指示物数量×200。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103059', '陨石破坏', '自己场上有2只怪兽正面表示存在的场合，破坏对方场上全部怪兽，我方回合结束时，因此卡效果破坏的怪兽回到对方场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('DCOR0012', '漆黑之铠', '场上存在名字带有「武装龙」的怪兽卡时此卡发动。
INSERT INTO "texts" VALUES ('DCOR0013', '神的再生', '支付2000点生命值，把墓地与除外区的神属性怪兽正面攻击表示特殊召唤上场。把这张卡从场上离开时，在下1个对方回合的准备阶段回到手牌。此卡的发动不能被无效化。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103062', '外宇宙装甲守护神', '只要此卡正面表示存在我方场上，对方不能以此卡以外的名字带有「装甲」的怪兽作为攻击对象。当此卡被破坏送入墓地时，将我方场上所有名字带有「装甲」的怪兽送入墓地代替此卡破坏。1回合1次，可以将我方场上名字带有「装甲」的怪兽送入墓地让对方1次魔法·陷阱·怪兽效果无效化并破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103063', '植物堡垒级守护神', '只要此卡正面表示存在我方场上，对方不能以此卡以外的名字带有「植物」的怪兽作为攻击对象。当此卡被破坏送入墓地时，将我方场上所有名字带有「植物」的怪兽送入墓地代替此卡破坏。1回合1次，可以将我方场上名字带有「植物」的怪兽送入墓地让对方1次魔法·陷阱·怪兽效果无效化并破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103064', '盔甲 终极守护神', '只要此卡正面表示存在我方场上，对方不能以此卡以外的名字带有「盔甲」的怪兽作为攻击对象。
INSERT INTO "texts" VALUES ('SOD00019', '黄泉天轮', '当此卡场面表示时，可以排除对方墓地里所有的怪兽卡，彼此、每一回合都可无条件地召唤一只怪兽，此卡发动时对方场面上的怪兽就会被消灭。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00020', '艾亚尼可斯之火', '将场上除了恶魔族还有火族以外的怪兽全部破坏，再从墓地特殊召唤一只恶魔族或火族怪兽。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00021', '守护神的宝牌', '舍弃5张手牌，每回合可以抽两张卡片。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00022', '捻线绸的针', '付出900点生命点，可以破坏对方一头怪兽。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00023', '快乐女郎朱雀之阵', '只要我方场上有两只以上的快乐女郎时，才能发动火焰之翼会挡下一切攻击，使其无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00024', '守护者之武器', '此卡在墓地里有防护怪兽时，就能用它可以破坏对方的魔法卡所发动的攻击效果。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00025', '恶魔の三面镜', '可对对方用通常召唤以外的手段的方法召唤出来的怪兽数量，在自己场上特殊召唤出相同数量的我方场上怪兽的复印品这些复印品无法攻击（魔法卡的效果除外）。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00026', '残像人之盾', '将攻击者的攻击力加到堕落天使·夏巴的攻击力上。其攻击无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00027', '堕落天使的施舍', '在发动此卡的回合内，双方玩家可以借由魔法的效力，让丢到墓地里的牌回到手牌中。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00028', '神奇的飞行器', '能使对方反转，召唤失效一个回合。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00029', '隐形人', '丢弃一张手牌，在对方场上以正面表示存在的“永续”魔法卡全部被破坏了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00030', '力量平衡', '当玩家没有手牌时，才能发动此卡，对方要把任意挑选的一半手牌丢进墓地，而玩家则可以抽出跟其数目一样张数的卡。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00031', '机械装置的魔法镜', '此卡可以发动对方墓地中的魔法卡或陷阱卡。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00032', 'Walkunan Ritt', '可以特殊召唤出所有华尔基莉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00033', '天赐宝牌', '当此卡在场面正面表示时，双方都可以从自己卡组抽出卡牌，使双方手上都有六张卡片。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00034', '手中掌握', '可以令自己说出对方的手牌中的卡片，强制发动此卡。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00035', '女神的圣剑', '能使守护者爱亚多斯召唤到场上。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00036', '古代书籍', '让玩家的一张手牌跟牌组最上面的牌交换，要维持此魔法，必须剑一张卡送进墓地。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00037', '清廉的墓地', '在对方抽卡时，对方墓地有几只怪兽，而每只怪兽会对对方造成100分的损害，但在我方墓地出现怪兽时，此卡则被破坏。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00038', '死灵魔术', '能使对方墓地里的怪兽一次性复活到对方场上。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00039', '爆炸专家“加累思”', '该卡片能够给发动陷阱卡的对方以1500点的伤害值。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00040', '融合速攻', '可将在手牌、卡组、墓地、亚空间的所有融合怪兽特殊召唤到场上，进行攻击，但这个情况只能维持一回合。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00041', '奥利哈钢的结界', '使我方主场可放置十只怪兽，且每只我方场上怪兽加上500攻击力。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00042', '死者的加护', '当怪兽被破坏时舍弃两张手牌，在对方进攻的回合也能发动的强制终止战斗的卡。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00043', '死者转生', '可以令墓地中一只怪兽回到牌组中。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00044', '千年·古之轮', '可以特殊召唤两只千年远古巨人的复制品呈攻击，当持有者没有发动攻击时，也会受到500点损伤值。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00045', '守护者爱亚托斯', '特殊效果：只有女神圣剑在场，此卡才能召唤，它能把对方墓地中所有怪兽移出游戏，再吸他们的攻击力。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00046', '大洋深处的蛙人', '当该卡受到对方攻击时，只要对方场面上有一只同居水族怪兽时，就不会受到对方的直接攻击。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00047', '进化电浆兽', '能把此卡同时当做“飓风”或“神奇羽毛扫”来使用。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00048', '藤蔓公主', '当它被召唤时，能控制对方一只怪兽。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00049', '无名之龙-海聂默斯之爪', '能与时间魔术师合体时间魔法锤，用骰子摇出数字。对方场上的怪兽逐一摇出数字，这些数字就是怪兽暂时离开场上多少回合，再回到场上。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00050', '无名之龙-克里提钨斯之牙', '能与死之牌组破坏病毒融合，能破坏攻击力1500以上的对方的龙。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00051', '无名之龙-提玛欧斯之眼', '能与黑魔导女孩融合，成为龙骑士黑魔导女孩，舍弃一张卡能使对方一头怪兽攻击力化为0。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00052', '堕落天使·夏巴', '此卡在战场上表侧表示时，已方场上其它天使族怪兽各加攻击力300。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00053', '召唤僧·沙摩普里斯', '此卡不能做为祭品，此卡在场上表侧表示时每回合可特召堕落天使·夏巴一只，这个效果每回合可使用1次，特召出来的堕落天使·夏巴不可直接攻击对方。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00054', '堕落天使·卡多纳', '此卡在场上表侧表示，己方场上其它天使族怪兽。各加守备力300。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00055', '魔幻兽', '能破坏战场上对方正面表示的2头怪兽。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00056', '放射性的怪物', '当该怪兽放射出气时，对方的一切怪兽都失去攻击力。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00057', '百手机械神兵', '当受到对方直接攻击时，攻击力会提高1000点。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00058', '毁灭巨兽', '当该怪兽受到对方破坏时，可以把它力量转移到自己场面上的其它一只怪兽，此怪兽不可直接攻击对方。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00059', '袭击者', '从自己手牌上抽出一张恶魔族怪兽，该怪兽可以得到“杀人者”的效果，直接攻击对方直到那一轮终了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00060', '长生不老的恶魔', '此卡召唤时，丢掉对手3只怪物，召唤到场上时，控制者每一回合受到1500点伤害。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00061', '剑术家', '当该卡牌正面表示，可从对方场上选择一只1500一下怪兽然后送回墓地。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00062', '雪人“小妖”', '当该卡牌正面表示时，当受到攻击时，可以立即返回到手牌上，然后放到最上面。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00063', '速攻吸血蛆', '从第一回合开始就能攻击。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00064', '地狱铁钻龙', '可以将此怪兽与墓地中的任意一张卡片对换。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00065', '电浆兽', '能把此卡当做“飓风”或“神奇羽毛扫”中的一张魔法卡来使用。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00066', '千年·千兆火神', '对方的龙族怪兽发动攻击的时候，可以把该卡片放到卡叠的最上面，然后阻止这次的攻击。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00067', '千年·远古石人', '当此卡表攻击时，而没对敌人发动攻击时，持有者会受到300点损伤值。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00068', '千年·功夫娘娘', '当此卡攻击时而没有攻击的那一轮，就可以提高300的攻击力。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00069', '千年·火焰鸟', '当该怪兽存在于场上的时候，在自己场上的全部鸟族都可以拉强攻击力800点。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00070', '千年·大勇士', '当该卡片在自己场地的时候，自己场地中所有兽族卡都要增加200点攻击力。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('VB700001', '无名战士-酷力提欧克斯', '能与死之牌组破坏病毒融合，能破坏攻击力1500以上的对方的龙。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103065', '晶钢强化青眼黑龙Ⅱ', '「灰钢真红眼黑龙Ⅱ」＋「晶体青眼白龙Ⅱ」
INSERT INTO "texts" VALUES ('ZZ103066', '古神兽 蚰翼', '此卡被对方卡的效果破坏送入墓地时，可以从墓地选择1张卡加入手牌。此卡发动攻击时，对方场上没有暗属性怪兽的场合，此卡攻击力上升500点，此效果可以发动3个回合。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103067', '古神兽 祖玛', '此卡被怪兽攻击破坏送入墓地时，可以选择卡组1张光属性怪兽特殊召唤上场，此召唤不会被任何卡片效果影响。召唤成功的回合，被召唤的怪兽卡不能发动攻击。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103068', '古神兽 河蟹', '此卡被怪兽攻击破坏送入墓地时，可以选择卡组1张地属性怪兽特殊召唤上场，同时对方受到此卡攻击力除以等级数值的生命值伤害。此卡每攻击破坏对方1张怪兽卡，此卡攻击力上升500点。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103069', '异兽 双头怪', '反转：被对方怪兽的攻击反转的场合，给予对方生命值，对方怪兽的攻击力数值的伤害。
INSERT INTO "texts" VALUES ('ZZ103070', '异兽 自作の孽', '对方发动魔法/陷阱卡时，效果由对方承受。
INSERT INTO "texts" VALUES ('TTOE0036', '闪焰凤凰翼人', '「E-HERO 闪光火焰翼人」＋「E-HERO 凤凰小子」
INSERT INTO "texts" VALUES ('SOD00071', '飞龙天舞', '送四张怪兽到墓地，可让龙女提高攻击力1200点。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00072', '岩石兽', '可以把它放在场面上最前面如果对方墓地有一只水族卡时，该怪兽就不受到魔法卡，圈套卡的破坏。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00073', '神秘的保护兽', '不论在哪一回合中，如果自己场上的一头怪兽受攻击时，对方也要把一张卡送回墓地。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00074', '金刚剑的复活', '把一只龙族当祭品，可以召唤钻石龙。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00075', '剑神铁骑士', '必须让铁骑士解除封印才能召唤。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00076', '欲望的代价', '发动此卡的玩家可以从手牌召唤出两只沉眠于其中的怪兽。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00077', '万物吸力车', '当该卡出现在场面上，对方发动攻击时，就能吸收对方一半攻击力然后转移自己场面上的一头怪兽上。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00078', '快乐的羽毛吹风', '当此卡可在快乐女郎发动攻击时，可以让对方的怪兽的特殊效果无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00079', '金龙的天堂', '若有龙族在场，所有龙族攻守上升800点，但以后每回合要下降100点。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00080', '时间女神的恶作剧', '跳过一回合', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00081', '100年的觉醒', '把一只怪兽当祭品，可以召唤藤蔓公主。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00082', '巨人的修行', '把一只怪兽作祭品，可以召唤绿巨人。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('SOD00083', '蔓藤公主', '当它召唤时可以操纵对手的一只怪兽。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103071', '机皇帝 无限录∞', '这张卡不能通常召唤。自己场上有名字带有「机皇」的怪兽正面表示存在的场合可以特殊召唤。1回合1次，得到对方场上·墓地的1只怪兽的使用权，回合结束时，那只怪兽送入墓地，此卡的攻击力上升我方场上1只怪兽攻击力的2倍数值。此卡存在场上时，对方不能召唤·反转召唤·特殊召唤怪兽。回合结束时，从墓地特殊召唤1只名字带有「机皇」的怪兽。此卡被破坏送入墓地时，我方获得比赛胜利。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103072', '机皇帝 智空大帝∞', '这张卡不能通常召唤。从手牌·场上·卡组把2只机械族的怪兽送去墓地的场合才能特殊召唤。1回合1次，把对方场上或额外卡组1只怪兽当作装备卡使用给这张卡装备。这张卡的攻击力上升这个效果装备的怪兽的攻击力数值。此卡被破坏时，对方那只怪兽的装备卡代替破坏。此卡存在场上时，名字带有「机皇帝」的怪兽不受对方任何卡的影响和战斗破坏。我方回合结束时，从墓地特殊召唤1只名字带有「机皇帝」的怪兽。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103073', '机皇帝 核心录∞', '这张卡不能通常召唤。从卡组·手牌把「机皇帝 神陆∞」、「机皇帝 神空∞」、「机皇帝 神智∞」各1张送去墓地的场合才能特殊召唤。1回合1次，可以把对方场上或墓地的1只怪兽当作装备卡使用给这张卡装备，这张卡的攻击力与守备力上升「机皇帝 神陆∞」、「机皇帝 神空∞」、「机皇帝 神智∞」的攻击力与守备力总和。此卡召唤时，对方场上所有的卡发动无效，回合结束时，可以把这张卡的效果装备的1只怪兽送去墓地，给予对方此卡攻击力数值的生命值伤害。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103074', '机皇帝 神星∞', '这张卡不能通常召唤。从手牌·场上·卡组把3只名字带有「机皇」的怪兽送去墓地的场合才能特殊召唤。1回合1次，可以把对方场上·墓地的1只怪兽当作装备卡使用给这张卡装备。这张卡的攻击力上升3000点。1回合1次，在我方的准备阶段，祭掉场上1只机械族怪兽时，给予对方那个怪兽攻击力数值的伤害。我方受到生命值伤害时，可以从墓地特殊召唤1只名字带有「机皇兵」的怪兽。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103075', '神空攻击部无限组合', '这张卡不能通常召唤。从手牌·场上·卡组的「神空攻击部」、「神空攻击部3」、「神空攻击部5」送入墓地的场合才能从手牌特殊召唤。成功召唤时，此卡的攻击力上升3只祭品的攻击力之和，此卡可对对方作直接攻击。此外，在我方回合结束时，我方场上每存在1只带有「机皇」的怪兽，从卡组抽1张卡。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103076', '神陆零件无限组合', '这张卡不能通常召唤。从手牌·场上·卡组的「神陆攻击部」、「神陆攻击部3」、「神陆攻击部5」送入墓地的场合才能从手牌特殊召唤。成功召唤时，此卡的攻击力上升我方墓地所有1星怪兽的数量×1000点的数值。1回合1次，指定对方场上1只怪兽装备到此卡身上，此卡1回合可以作2次攻击。回合结束时，从墓地特殊召唤1只「机皇帝 神陆∞」。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103077', '神智零件无限组合', '这张卡不能通常召唤。从手牌·场上·卡组的「神智头部」、「神智攻击部」、「神智守备部」、「神智下肢部」送入墓地的场合才能从手牌特殊召唤。成功召唤时，此卡的攻击力与守备力上升场上攻击力最高的怪兽的攻击力与守备力的2倍数值，此卡被效果破坏时，可丢弃1张手牌破坏无效。此卡受到的战斗伤害为0。回合结束时，从墓地特殊召唤1只「机皇帝 神智∞」。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103078', '机皇帝 吸取者∞', '这张卡不能通常召唤。场上存在名字带有「机皇帝」的3只以上怪兽的场合才能特殊召唤，从对方场上或额外卡组把最多3只怪兽当作装备卡给这张卡装备。这张卡的攻击力上升这个效果装备怪兽的数量×1000点的数值，回合结束时，取1只同调怪兽送入墓地。（若对方没有同调怪兽，我方获得比赛胜利）', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103079', '机皇帝 神智∞', '这张卡以外的在自己场上存在的怪兽不能攻击。这张卡的攻击力·守备力上升自己场上存在的这张卡以外的名字带有「神智」、「神空」、「神陆」的怪兽的攻击力数值。1回合1次，可以把对方场上存在的1只同调怪兽作为装备卡给这张卡装备。这个效果把对方怪兽作为装备的场合，这张卡的攻击力上升装备的同调怪兽的原本攻击力数值。这张卡被破坏时，自己场上存在的怪兽全部破坏。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103080', '神智守备部', '名字带有「∞」的怪兽不在自己场上存在的场合，这张卡破坏。可以把对方怪兽的攻击对象变更为这张卡。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103082', '神智守备部3', '名字带有「∞」的怪兽不在自己场上存在的场合，这张卡破坏。可以把对方怪兽的攻击对象变更为这张卡。1回合1次，这张卡不会被战斗破坏。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103083', '神智攻击部', '名字带有「∞」的怪兽不在自己场上存在的场合，这张卡破坏。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103084', '神智下肢部', '名字带有「∞」的怪兽不在自己场上存在的场合，这张卡破坏。这张卡不会被对方卡的效果破坏。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103085', '神智头部3', '名字带有「∞」的怪兽不在自己场上存在的场合，这张卡破坏。1回合1次，可以把对方魔法·陷阱卡的发动及效果无效并破坏。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103086', '机皇帝 神陆∞', '这张卡以外的在自己场上存在的怪兽不能攻击。这张卡的原本攻击力，和自己基本分相同。1回合1次，可以把对方场上存在的1只同调怪兽作为装备卡给这张卡装备。这个效果把对方怪兽作为装备的场合，这张卡的攻击力上升装备的同调怪兽的原本攻击力数值。这张卡被破坏时，把自己场上存在的怪兽全部破坏。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103087', '神陆攻击部', '名字带有「∞」的怪兽不在自己场上存在的场合，这张卡破坏。可以把战斗破坏的对方的1只同调怪兽作为装备卡，给自己场上存在的名字带有「∞」的怪兽装备。此外这时，攻击守备表示怪兽的场合，若装备怪兽的攻击力超越那个守备力，给予对方生命值那个数值的伤害。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103088', '神陆守备部', '名字带有「∞」的怪兽不在自己场上存在的场合，这张卡破坏。对方怪兽的攻击宣言时，那个攻击对象可以变更为自己场上存在的名字带有「机皇帝」的怪兽装备的1只同调怪兽。这时，作为装备卡的同调怪兽作为怪兽卡。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103089', '神陆下肢部', '名字带有「∞」的怪兽不在自己场上存在的场合，这张卡破坏。1回合1次，自己场上存在的怪兽不会被战斗破坏。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103090', '机皇帝 神空∞', '这张卡以外的在自己场上存在的怪兽不能攻击。这张卡的攻击力·守备力上升自己场上存在的这张卡以外的名字带有「神智」、「神空」、「神陆」的怪兽的攻击力数值。1回合1次，可以把对方场上存在的1只同调怪兽作为装备卡给这张卡装备。这个效果把对方怪兽作为装备的场合，这张卡的攻击力上升装备的同调怪兽的原本攻击力数值。这张卡被破坏时，自己场上存在的怪兽全部破坏。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103091', '神空头部', '名字带有「∞」的怪兽不在自己场上存在的场合，这张卡破坏。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103092', '神空守备部', '名字带有「∞」的怪兽不在自己场上存在的场合，这张卡破坏。1回合1次，可以把对方的1只怪兽的攻击无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103093', '神空攻击部', '名字带有「∞」的怪兽不在自己场上存在的场合，这张卡破坏。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103094', '神空下肢部3', '名字带有「∞」的怪兽不在自己场上存在的场合，这张卡破坏。1回合1次，把名字带有「∞」的1只怪兽的破坏无效。1回合1次，可以在对方怪兽的攻击宣言时把那只怪兽的攻击无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103095', '神空攻击部5', '名字带有「∞」的怪兽不在自己场上存在的场合，这张卡破坏。只要这张卡在自己场上正面表示存在，自己场上存在的名字带有「∞」的怪兽可以直接攻击对方玩家。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103081', '机皇帝的归来', '此卡发动时，1回合1次，从卡组·场上·墓地把「机皇帝 神陆∞」、「机皇帝 神空∞」、「机皇帝 神智∞」任意1只特殊召唤上场。以此卡召唤的怪兽不受对方魔法·陷阱的效果影响。集齐以此卡效果上场的「机皇帝 神陆∞」、「机皇帝 神空∞」、「机皇帝 神智∞」3只怪兽时，我方获得比赛胜利。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103096', '机皇帝之守备封印', '场上有机械族怪兽正面表示存在时发动，对方场上的所有怪兽变成正面攻击表示。指定我方场上名字带有「机皇帝」的怪兽对那些怪兽进行攻击（1只怪兽只能进行1次攻击）。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103097', '机皇帝之魔法陷阱咒符', '这张卡仅当自己场上存在名字带有「机皇帝」的怪兽时才能发动。这张卡在场上存在时，对方陷阱·魔法卡不能发动，对方场上所有陷阱·魔法卡效果无效化。当我方有名字带有「机皇帝」的怪兽离场时，对方受到那离场时那只怪兽的攻击力数值的伤害。此卡被送入墓地的第2次自己的准备阶段时这张卡加入手牌。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103098', '机皇帝的机械地带', '发动此卡时，丢弃1张手牌，我方上升4000点生命值，此卡不受对方魔法·陷阱·效果怪兽的影响。场上正面表示存在的名字带有「机皇」的怪兽攻击时，攻击怪兽的攻击力比攻击对象的攻击力低的场合，攻击怪兽的攻击力在伤害计算阶段时上升3000点。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103099', '机皇帝的魔法再生', '从我方卡组·墓地选择2张魔法卡加入手牌，以此卡效果选择的魔法卡可以正面表示放置在魔法与陷阱卡区域发动。此外，对方有卡送入墓地时，对方受到送入墓地卡的数量x2000点数值伤害。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103100', '机皇帝阵-反埋伏', '把生命值支付1000点发动。自己墓地和手牌存在的名字带有「机皇」的怪兽在自己场上尽可能特殊召唤（同名卡最多1张）。我方场上存在有被装备到，怪兽时，那些怪兽可以对对方作直接攻击。这张卡在墓地存在的场合，可以作为自己的抽卡阶段时的代替，把这张卡加入手牌。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103101', '机皇帝的召唤', '此卡发动时，从卡组·场上·墓地把「机皇帝 神陆∞」、「机皇帝 神空∞」、「机皇帝 神智∞」特殊召唤上场。以此卡召唤的怪兽，不会被战斗破坏。此卡的发动，不受对方卡的影响。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103102', '机皇帝的漩涡轮回', '场上存在名字带有「机皇帝」的怪兽时，1回合1次，选择以下1个效果发动：
INSERT INTO "texts" VALUES ('ZZ103103', '机皇帝之墓地伤害', '我方受生命值伤害时才能发动，下次的，对方回合的抽卡阶段跳过，并给予对方生命值自己墓地存在的卡的数量×500点数值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103104', '机皇帝的安全装置', '选择场上正面表示存在的1只名字带有「机皇」的怪兽发动。选择的怪兽不会成为对方卡的效果的对象，不会被破坏以及对方的效果破坏。丢弃1张手牌，破坏对方场上的1只怪兽。此外，在我方的准备阶段，选择的怪兽可以对对方直接攻击。这张卡不在场上存在时，那只怪兽破坏，那只怪兽从场上离开时这张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103105', '机皇帝的核心牲祭', '当自己场上存在名字带有「机皇」的怪兽时才能发动，所有玩家将手牌中的怪兽卡全部丢进墓地。我方可从墓地特殊召唤名字带有「神陆」、「神空」、「神智」的怪兽上场。回合结束时，双方从卡组抽2张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103106', '机皇帝之不灭的宣告', '对方有怪兽召唤·反转召唤·特殊召唤时发动，破坏那只怪兽。此外，丢弃1张手牌，我方从卡组·墓地特殊召唤1只名字带有「机皇帝」的怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103107', '机皇帝创世之光', '对方的魔法·陷阱卡的发动，怪兽的召唤·反转召唤·特殊召唤的全部效果无效并破坏，并终止对方的回合，跳到我方回合。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103108', '镭射锁定', '对方在魔法·陷阱区域盖伏卡片时，给予对方生命值200点伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103109', '智慧攻击部3', '把自己场上的1只名字带有「神智攻击部」的怪兽解放发动。把手牌1只「神智攻击部3」在自己场上特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103110', '智慧头部3', '把自己场上的1只名字带有「神智头部」的怪兽解放发动。把手牌1只「神智头部3」在自己场上特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SOD00084', '堕落天使·加纳', '此卡在场上表侧表示时，双方场上其他天使族怪兽各提高攻击力300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SOD00085', '天马的翅膀', '装备在WalkunRan怪兽上，可以以一半攻击力对方。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103111', '大地之核', '这张卡被卡的效果破坏送去墓地时，自己场上的怪兽全部破坏，从自己的卡组·手卡·墓地把「机皇帝神陆∞」「神陆头部」「神陆攻击部」「神陆守备部」「神陆下肢部」各1只特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103112', '神陆头部', '自己场上没有「∞」怪兽存在的场合，这张卡破坏。自己的「∞」怪兽攻击宣言时，可以选择对方场上1只同调怪兽的效果直到这个回合结束前无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103113', '神陆头部5', '自己场上没有「∞」怪兽存在的场合，这张卡破坏。1回合1次，可以选择对方场上1只同调怪兽当作装备卡给自己1只的「∞」怪兽装备。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103114', '神陆攻击部3', '自己场上没有「∞」怪兽存在的场合，这张卡破坏。自己的「∞」怪兽战斗破坏对方的同调怪兽时，可以把那只同调怪兽当作装备卡给那只「∞」怪兽装备。
INSERT INTO "texts" VALUES ('ZZ103115', '无限墙', '自己场上有表侧表示的「机皇帝」怪兽的场合才能发动。这个回合要让自己场上存在的卡破坏的效果无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103116', '无限狂宴', '这个回合因「机皇神 机录∞」的效果送入墓地的同调怪兽在墓地存在的场合可以发动。
INSERT INTO "texts" VALUES ('ZZ103117', '流放罪', '只能在战斗阶段发动。场上表侧表示存在的同调怪兽全部从游戏中除外。因这个效果从游戏中除外的怪兽在战斗阶段结束时效果无效化回到场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103118', '攻击部加农炮', '自己场上存在的名字带有「机皇帝」的怪兽用战斗没能破坏对手怪兽的回合，可以将自己场上存在的1只名字带有「攻击部」
INSERT INTO "texts" VALUES ('ZZ103119', '机皇创世', '把自己手上的「智慧之核」「天空之核」「大地之核」各1张送去墓地，从自己卡组·手卡·墓地把1只「机皇神 机录∞」特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103120', '荒诞偷窃者', '这张卡召唤成功时，选择对手场上的1只怪兽发动。直到这个回合的结束阶段时，这张卡的攻击力上升选择怪兽的原守备力的数值，选择的怪兽的攻击力变为0。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103121', '天空之核', '这张卡被卡的效果破坏送去墓地时，自己场上的怪兽全部破坏，从自己的卡组·手卡·墓地把「机皇帝神空∞」「神空头部」「神空攻击部」「神空守备部」「神空下肢部」各1只特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103122', '神空下肢部', '自己场上没有「∞」怪兽存在的场合，这张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103123', '神空攻击部3', '自己场上没有「∞」怪兽存在的场合，这张卡破坏。1回合1次，选择自己场上1只i表侧表示的怪兽为对象才能发动。直到回合结束时那只怪兽的攻击力减半，可以对对方直接攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103124', '神空下肢部5', '这张卡不能通常召唤，把自己场上1只「神空下肢部3」送去墓地才能特殊召唤。自己场上没有「∞」怪兽存在的场合，这张卡破坏。1回合1次，可以把对方1只怪兽的攻击无效。自己的怪兽战斗破坏对方的怪兽的场合，给与对方基本分300伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103125', '幽灵转换', '自己场上存在的1只怪兽成为卡的效果的对象时可以发动。可以将那个效果的对象变更为自己墓地里存在的1只怪兽。
INSERT INTO "texts" VALUES ('ZZ103126', 'X形吸收召唤', '自己场上以表侧攻击表示存在的怪兽成为对手怪兽的攻击力对象时可以发动。成为攻击对象的自己的怪兽返回手牌，从自己的手牌以表侧攻击表示特殊召唤1只比那只怪兽攻击力低的1只怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103127', '无限冲击', '只能在自己的回合发动。这个回合自己不能宣言攻击。对手场上没有怪兽存在时，给予对手LP自己场上存在的怪兽数目×400点伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103128', '无限之力', '自己场上存在名字带有「∞」的怪兽的场合，因对手卡的效果发生伤害时可以发动。那个效果伤害变为0，对手场上存在的怪兽全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103129', '天空A3', '把自己场上1只名字带有「神空攻击部」的怪兽送去墓地，把手卡的1只「神空攻击部3」特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103130', '双电流', '对手怪兽的攻击宣言时可以发动。将自己场上存在的1只怪兽和对手场上存在的1只怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103131', '无限牢', '可以舍弃1张手牌，将自己墓地存在的1张怪兽卡当作魔法卡盖伏在魔法陷阱区。此外，可以将表侧表示的这张卡送入墓地，这个效果盖伏在魔法陷阱区的怪兽卡返回手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103132', '无限灵机', '自己受到的伤害每有100点，在这张卡上放置1个灵机指示物。
INSERT INTO "texts" VALUES ('ZZ103133', '智慧之核', '这张卡被卡的效果破坏送去墓地时，自己场上的怪兽全部破坏，从自己的卡组·手卡·墓地把「机皇帝 神智∞」「神智头部」「神智攻击部」「神智守备部」「神智下肢部」各1只特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103134', '神智头部', '自己场上没有「∞」怪兽存在的场合，这张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103135', '神智攻击部3', '自己场上没有「∞」怪兽存在的场合，这张卡破坏。自己的「∞」怪兽向守备表示的怪兽攻击的场合，若攻击力超过那个守备力，给予对方基本分那个数值的战斗伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103136', '神智攻击部5', '这张卡不能通常召唤，把自己场上1只「神智攻击部3」送去墓地才能特殊召唤。自己场上没有「∞」怪兽存在的场合，这张卡破坏。
INSERT INTO "texts" VALUES ('ZZ103137', '回音镜', '对手怪兽的攻击没有战斗破坏自己守备表示怪兽的场合可以发动。从自己卡组抽1张卡。抽到的卡是怪兽卡的场合，给予对手LP那只怪兽等级×300点的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103138', '无限防御阵形', '这个回合自己场上存在的效果怪兽的效果无效化。自己场上存在的卡不会被效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103139', '炸弹爆破', '只有在自己的回合才能发动。选择这个回合没有进行过战斗的自己场上存在的最多3只机械族怪兽破坏。给予对手LP被这个效果破坏的怪兽的数量×400点伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103140', '智慧G3', '把自己场上1只名字带有「神智守备部」的怪兽送去墓地，把手卡的1只「神智守备部3」特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103141', '分歧', '自己场上存在的机械族怪兽被选择为攻击对象的场合，可以使那个攻击对象变更为自己场上存在的其他机械族怪兽。
INSERT INTO "texts" VALUES ('ZZ103142', '极光抽卡', '手牌只有这张卡的场合可以发动。从自己的卡组抽2张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103143', '混沌炸裂', '从自己卡组顶端将3张卡送入墓地。破坏场上1只等级4以下的怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103144', '混沌浑浊', '这张卡根据墓地中存在的「混沌浑浊」的数目获得以下效果。
INSERT INTO "texts" VALUES ('ZZ103145', '未来破坏', '将自己卡组中与自己手牌张数同样数目的卡送入墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103146', '双重献祭', '自己场上怪兽召唤、特殊召唤成功时可以发动。那只怪兽与对手场上1只怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103147', '等级炮', '召唤、特殊召唤、反转召唤怪兽的玩家受到那只怪兽的等级×200点的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103148', '诅咒同调', '对手同调怪兽的攻击让自己LP受到伤害的场合可以发动。只要这张卡在场上表侧表示存在，同调怪兽不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103149', '能量重力', '对手怪兽的攻击力变化时可以发动。发动后，变为自己场上存在的1只怪兽的装备卡。那1只对手怪兽的攻击力变为0，变化的攻击力的数值加在装备怪兽的攻击力上。装备怪兽攻击的回合的结束阶段时这张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103150', '伤害提升', '将使自己的卡的效果造成的伤害无效的对手的卡的效果无效并破坏，给予的伤害的数值加倍。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103160', '诸神遗迹·羽蛇神 库库尔坎', '库库尔坎从远古就主宰着晨星·魔法，主宰着一族的死亡和重生，当他从天而降时伴随强烈的闪电龙卷云，瞬间消灭敌人。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103161', '诸神遗迹·巨臂龙神 科托斯', '科托斯是希腊神祇盖亚和乌拉诺斯所生的3个孩子之一，是巨大又喜欢兴风作浪的怪物，在海中的魔力是众神中最强大的魔神之一，3位巨臂龙神在诸神之战中帮助宙斯取得最后的胜利，之后就成为亚特兰提斯的守护神。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103162', '诸神遗迹·太阳蛇神 瓦吉特', '瓦吉特从远古的史前时代就一直是下埃及的守护神，与上埃及的秃鹫鹰神奈赫贝特一起守护埃及，瓦吉特常以毒蛇的形态环绕太阳，喷发熔岩流星。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103163', '诸神遗迹·巨臂龙神 古革斯', '古革斯是希腊神祇盖亚和乌拉诺斯所生的3个孩子之一，其力量之巨大足以毁天灭地，虽然在诸神之战中帮助宙斯取得最后的胜利而成为亚特兰提斯的看守神，但常常无法控制自己的力量而被两位兄弟囚禁在亚特兰提斯的海底。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103151', '暗征龙骑士-玄黯', '此卡由于暗属性怪兽作祭品召唤成功时，可以破坏对方场上1张覆盖的卡，对方不能针对这个效果发动陷阱卡。此卡被战斗破坏送入墓地时，可以选择墓地1只暗属性怪兽加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103152', '地征龙骑士-艮山', '此卡由于地属性怪兽作祭品召唤成功时，可以破坏对方场上1张覆盖的卡，对方不能针对这个效果发动陷阱卡。此卡被战斗破坏送入墓地时，可以选择墓地1只地属性怪兽加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103153', '风征龙骑士-巽风', '此卡由于风属性怪兽作祭品召唤成功时，可以破坏对方场上1张覆盖的卡，对方不能针对这个效果发动陷阱卡。此卡被战斗破坏送入墓地时，可以选择墓地1只风属性怪兽加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103154', '水征龙骑士-坎渊', '此卡由于水属性怪兽作祭品召唤成功时，可以破坏对方场上1张覆盖的卡，对方不能针对这个效果发动陷阱卡。此卡被战斗破坏送入墓地时，可以选择墓地1只水属性怪兽加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103155', '合金装甲·低空巡航 废墟号', '恒古之国AEON的合金机甲巡航艇，只负责巡航一般贫民区，是旧科技时代遗留下来的战争机械。此卡以正面表示存在我方场地时，我方场地上的卡因对方怪兽的攻击被破坏时，可以将此卡送往墓地来代替破坏，我方的生命值不会受到损伤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103156', '六武众 皐月', '只要我方场地上有「六武众 皐月」以为冠有「六武众」之名的怪兽存在，1回合1次，此卡可以破坏对方场地上的守备怪兽·魔法·陷阱卡，此卡发动效果的回合不能宣告攻击，此卡被破坏时，可以用此卡以外的冠有「六武众」之名的怪兽代替破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103157', '六武众 隐剑', '只要我方场地上有「六武众 隐剑」以为冠有「六武众」之名的怪兽存在，可以选择对方场地上的2只怪兽返回持有者手牌，之后，此卡在同一个战斗阶段中可以攻击2次，此卡被破坏时，可以用此卡以外的冠有「六武众」之名的怪兽代替破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103158', '六武众 疾影', '只要我方场地上有「六武众 疾影」以为冠有「六武众」之名的怪兽存在，此卡可以直接攻击对方决斗者，选择我方墓地中名字带有「六武众」的怪兽加入手牌，此卡被破坏时，可以用此卡以外的冠有「六武众」之名的怪兽代替破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103159', '真六武书卷影武者', '「六武书卷」＋名字带有「真六武众」的怪兽
INSERT INTO "texts" VALUES ('ZZ103164', '无名龙 克里提钨斯之牙', '藉由「克里提钨斯 传说剑的仪式」来降临，此卡的降临不须献祭卡片，
INSERT INTO "texts" VALUES ('ZZ103165', '无名龙 海聶默斯之爪', '藉由「海聶默斯 传说剑的仪式」来降临，此卡的降临不须献祭卡片，
INSERT INTO "texts" VALUES ('ZZ103166', '无名龙 提玛欧斯之眼', '藉由「提玛欧斯 传说剑的仪式」来降临，此卡的降临不须献祭卡片，
INSERT INTO "texts" VALUES ('ZZ103167', '传说骑士 提玛欧斯', '当此卡不能通常召唤或设置，只能藉由「千年之心」来召唤，1回合1次，我方可以发动1张存在我方的手牌·卡组·墓地里的魔法卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103168', '传说骑士 海聶默斯', '当此卡不能通常召唤或设置，只能藉由「千年之心」来召唤，
INSERT INTO "texts" VALUES ('ZZ103169', '传说骑士 克里提钨斯', '当此卡不能通常召唤或设置，只能藉由「千年之心」来召唤，
INSERT INTO "texts" VALUES ('ZZ103170', '合神龙·提玛欧斯', '「传说骑士 提玛欧斯」＋「传说骑士 海聶默斯」＋「传说骑士 克里提钨斯」
INSERT INTO "texts" VALUES ('ZZ103179', '地缚 力的集约', '选择我方场上正面表示存在的1只名字带有「地缚神」怪兽排除到游戏外才能发动。
INSERT INTO "texts" VALUES ('ZZ103171', '地缚神-A地带', '此卡存在场上时，我方场上正面表示存在的名字带有「地缚神」的怪兽不会成为对方任何卡的对象。
INSERT INTO "texts" VALUES ('ZZ103172', '地缚神的守护', '场上有等级8以上的怪兽存在时才能发动。这张卡发动后继续留在场上，用对方回合计算的3回合后的对方结束阶段破坏。
INSERT INTO "texts" VALUES ('ZZ103173', '地缚神 查库指引者', '可以选择将场上的这张卡送入墓地，从卡组将「地缚神 查库·查略亚」特殊召唤上场，特殊召唤成功时，「地缚神 查库·查略亚」的效果无效。', '特殊召唤', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103174', '地缚神 阿斯利亚指引者', '可以选择将场上的这张卡送入墓地，从卡组将「地缚神 阿斯利亚·皮斯科」特殊召唤上场，特殊召唤成功时，「地缚神 阿斯利亚·皮斯科」的效果无效。', '特殊召唤', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103175', '地缚神 卡拉指引者', '可以选择将场上的这张卡送入墓地，从手牌将「地缚神 卡拉伊瓦」特殊召唤上场，特殊召唤成功时，「地缚神 卡拉伊瓦」的效果无效。
INSERT INTO "texts" VALUES ('ZZ103176', '地缚神 卡帕克指引者', '可以选择将场上的这张卡送入墓地，从手牌将「地缚神 卡帕克·阿普」特殊召唤上场，特殊召唤成功时，「地缚神 卡帕克·阿普」的效果无效。
INSERT INTO "texts" VALUES ('ZZ103177', '地缚神 库西略指引者', '可以选择将场上的这张卡送入墓地，从手牌将「地缚神 库西略」特殊召唤上场，特殊召唤成功时，「地缚神 库西略」的效果无效。
INSERT INTO "texts" VALUES ('ZZ103178', '地缚神 憎', '只要这张卡在场上正面表示存在，名字带有「地缚神」的怪兽只能有1只正面表示存在的效果无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103180', '暗神的爆发', '得到对方1只怪兽的控制权，在每次对方的准备阶段对方回复1000生命值。这张卡发动后，从手牌·卡组·墓地里面选择1只名字带有「地缚神」的怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103181', '黑羽大师 神鹰装备模式', '「黑羽」调整怪兽＋「黑羽大师 漆黑的神鹰·乔」
INSERT INTO "texts" VALUES ('ZZ103182', '黑羽大师 漆黑的神鹰·乔', '「黑羽」调整怪兽＋「黑羽」调整以外的怪兽1只以上 
INSERT INTO "texts" VALUES ('ZZ103183', '黑羽大师 星影归还·神怒斩', '「黑羽 星影的神怒剑」调整怪兽＋调整以外的怪兽2只以上 
INSERT INTO "texts" VALUES ('ZZ103184', '黑羽 星影的神怒剑', '「黑羽」调整怪兽＋调整以外的怪兽1只以上 
INSERT INTO "texts" VALUES ('ZZ103185', '黑羽 魔岩岛の索魂兽鸦', '我方名字带有「黑羽」的怪兽成为对方的攻击对象时，该发动攻击的怪兽被破坏，对方的生命受到该发动攻击的怪兽攻击力数值的损伤，此卡的攻击力上升该发动攻击的怪兽攻击力数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103186', 'BT黑羽 神鸟王', '名字带有「黑羽」的调整＋调整以外的怪兽3只以上
INSERT INTO "texts" VALUES ('ZZ103187', '邪心英雄 暗辉翼魔', '「元素英雄 羽翼侠」＋「元素英雄 电光侠」
INSERT INTO "texts" VALUES ('ZZ103188', '破坏龙魔导 甘多拉', '「甘多拉」怪兽＋魔法师族怪兽
INSERT INTO "texts" VALUES ('ZZ103189', '甘多拉龙骑士 沉默联合', '「甘多拉」怪兽＋「沉默魔术师 LV8」＋「沉默剑士 LV7」
INSERT INTO "texts" VALUES ('ZZ103190', '奥利哈钢 欧贝利斯克的翼神天龙', '神属性或幻神兽族怪兽3只以上
INSERT INTO "texts" VALUES ('ZZ103191', '迪欧斯之龙', '「迪欧斯」＋等级5以上龙族怪兽
INSERT INTO "texts" VALUES ('ZZ103192', '迪欧斯', '自己场上没有怪兽或怪兽的攻击全在2000点以下的场合，这张卡可以从手牌特殊召唤。
INSERT INTO "texts" VALUES ('ZZ103193', '迪欧斯衍生物', '由「迪欧斯」的效果特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103194', '沉默的剑士 LV0', '自己·对方的准备阶段发动。这张卡的等级上升1星。
INSERT INTO "texts" VALUES ('ZZ103195', '沉默的剑士 LV4', '这张卡不能通常召唤。只能由「沉默的剑士」怪兽的效果特殊召唤。
INSERT INTO "texts" VALUES ('ZZ103196', '沉默的剑士 LV5', '这张卡不能通常召唤。只能由「沉默的剑士」怪兽的效果特殊召唤。
INSERT INTO "texts" VALUES ('ZZ103197', '沉默的剑士 LV6', '这张卡不能通常召唤。只能由「沉默的剑士」怪兽的效果特殊召唤。
INSERT INTO "texts" VALUES ('ZZ103198', '沉默的剑士 LV7', '这张卡不能通常召唤。只能由「沉默的剑士」怪兽的效果特殊召唤。
INSERT INTO "texts" VALUES ('ZZ103199', '破坏龙 甘多拉-暗冥界', '「破坏龙 甘多拉」×1
INSERT INTO "texts" VALUES ('ZZ103200', '恶魔扎枪士', '这张卡召唤成功时，可以选择对方1只怪兽破坏。这张卡在召唤的那个回合不能进行攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103201', '恶魔斗牛士', '「斗牛士降临的仪式 黑暗入场式」降临。自己的场上·手卡合计6星以上的怪兽作为祭品。这张卡不会被战斗破坏，这张卡的战斗对控制者造成的战斗伤害变成0。和这张卡进行过战斗的怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103202', '恶魔斗牛骑手', '场上有「暗之斗牛场」存在时，这张卡可以向对方直接攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103203', '暗之斗牛场', '只要这张卡在场上存在，双方攻击表示的怪兽必须要进行攻击，攻击对象由对方进行选择。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103204', '斗牛士降临的仪式 黑暗入场式', '「恶魔斗牛士」降临必须。把自己的场上·手卡合计6星以上的怪兽作为祭品。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103205', '吸血鬼蝙蝠群', '这张卡被破坏的场合，可以从卡组将同名卡送去墓地让破坏无效。只要这张卡在场上存在，自己场上的所有不死族怪兽攻击力上升200点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103206', '不死的狼人', '这张卡因为战斗被破坏时从卡组将同名卡攻击力上升500点特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103207', '幻魔之门', '自己的灵魂寄托给幻魔发动。对手场上的怪兽全部破坏，可以特殊召唤墓地的1只怪兽。（此时无视召唤条件）这张卡发动后决斗败北的场合，自己的灵魂成为幻魔之物。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103208', '创世危机', '自己场上不存在“吸血鬼创世主”时，自己场上的所有不死族怪兽和这张卡破坏。1回合1次从卡组将一张不死族怪兽卡加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103209', '不死的王国赫鲁巴尼亚', '将手牌的1只不死族怪兽送去墓地可以将场上的怪兽全部破坏。使用了这个效果时，不能进行通常召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103210', '不死族之棺', '盖放的这张卡被破坏送去墓地时，从自己的墓地中特殊召唤一只不死族怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103211', '妖疑的红月', '手牌的1只不死族舍弃。回复对手的攻击怪兽的攻击力部分的生命值战斗阶段结束。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103212', '上古邪术师', '名字带有「上古」的卡不会被名字带有「上古」以外的怪兽战斗破坏，也不受名字带有「上古」以外的怪兽效果影响。只要这张卡正面表示存在于我方场上，我方发动卡片效果时，可以选择让那个效果加倍。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103213', '上古之月下悲戚', '这张卡不会被名字带有「上古」以外的魔法·陷阱卡破坏或无效。
INSERT INTO "texts" VALUES ('ZZ103214', '上古战斧斗士 塞拉', '名字带有「上古」的卡不会被名字带有「上古」以外的怪兽战斗破坏，也不受名字带有「上古」以外的怪兽效果影响。
INSERT INTO "texts" VALUES ('ZZ103215', '元素英雄 自然新宇侠', '「元素英雄 新宇侠」＋「新空间侠·大地鼹鼠」＋「新空间侠·光辉青苔」
INSERT INTO "texts" VALUES ('ZZ103216', '废品熔炼员', '「同调士」调整+调整以外的怪兽1只
INSERT INTO "texts" VALUES ('ZZ103217', '星尘的回音', '这个卡名的卡在1回合只能发动1张。①:给与自己伤害的效果由对方发动时才能发动。那个效果发生的对自己的效果伤害变成2倍由对方代受。自己的场上有「星尘龙」存在的场合，再让自己的基本分回复那次伤害的数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103218', '废品战士·废铁一击', '「同调士」调整+调整以外的怪兽1只以上
INSERT INTO "texts" VALUES ('ZZ103219', '电子终结龙 湮灭', '「电子终结龙」+「电子龙」怪兽3只以上
INSERT INTO "texts" VALUES ('ZZ100230', '链接龙', '这张卡召唤、反转召唤、特殊召唤成功的时候，成为对手1只怪兽的装备卡，变更装备这张卡的怪兽的表示形式。之后，装备了这张卡的怪兽的表示形式不能再变更。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100256', '褐色战士', '只要这张卡在场上存在，1回合1次从自己的卡组将1只等级4以下的兽战士族怪兽加入手牌。这张卡攻击表示的时候，自己场上的兽战士族怪兽的攻击力上升400点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100270', '龙之心', '从卡组选择3只龙族怪兽送入墓地。自己场上的龙族怪兽的攻击力只在这个回合里上升1000点。发动这张卡的场合，自己在发动回合里不能召唤怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100531', '聚光灯', '选择自己场上的1只怪兽。选择了的怪兽的攻击力上升300点。选择了的怪兽不在场上存在的场合，可以变更这个效果的对象为另外的怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100597', '命运的引导', '只能装备兽战士族怪兽，装备这张卡的怪兽可以直接攻击对手。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100601', '究极的舞台服装', '选择自己场上的1只怪兽。选择了的怪兽的攻击力和守备力上升3000点。
INSERT INTO "texts" VALUES ('ZZ100602', '被诅咒的指环', '对手的攻击宣言时可以发动。这张卡成为对手的攻击怪兽的装备卡。装备了这张卡的怪兽不能通过战斗破坏对手的怪兽（损伤计算适用）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100788', '攻击性防御', '对手怪兽直接攻击时可以发动。那只攻击怪兽的攻击力在伤害计算时减半。之后，自己从卡组抽1张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100875', '奇迹的瞬间', '装备了「命运的引导」的「漆黑之豹战士」因战斗破坏被送到墓地的时候发动可能。从卡组或手牌特殊召唤1只「褐色战士」。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101222', '魔法反射装甲·金属正离子', '这张卡发动后选择自己场上的1只怪兽，把这张卡当作装备卡使用给那只怪兽装备。装备怪兽为对象的魔法卡的效果无效并破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101890', '黑暗原型', '这张卡因战斗破坏送入墓地的场合效果可以发动。从卡组选择1个持有和这个时候玩家受到的战斗伤害相同数值的攻击力的怪兽，再将合计与选择的怪兽等级相同的手牌送入墓地。选择了的1只怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101904', '黑暗念力眼', '这张卡被破坏的时候，回合结束前得到1只对手怪兽的操控权。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102355', '千之惩罚者', '自己场上的1只怪兽作为对象发动。将对象怪兽以外的自己场上的1只怪兽做祭品。这个回合，对象怪兽的攻击力变为1000点，做祭品的怪兽攻击力每有1000点，对象怪兽就可以攻击1次。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ102596', '能量馈赠', '选择手牌里的1只怪兽送入墓地。对手1只怪兽的攻击力上升那只怪兽的攻击力的数值。因这个效果上升攻击力的怪兽在战斗的伤害计算步骤结束后破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103220', '零之眼魔', '自己场上以表侧攻击表示存在的怪兽被选择为攻击对象的时候可以发动。那1只怪兽的攻击力变为0。从卡组抽1张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103221', '鹰身女妖的宠物双头龙', '「鹰身女妖的宠物龙」＋「鹰身女妖的宠物龙」
INSERT INTO "texts" VALUES ('ZZ103222', '鹰身女妖的女神', '「鹰身」怪兽5只以上
INSERT INTO "texts" VALUES ('ZZ103223', '漏洞的钱包', '对方的手牌在6张以上时可以发动。对方随机选择手牌舍弃到墓地使手牌最后只有五张。受到这个效果的回合，对方不能使用手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103224', '银河-星光的冲击', '从自己或者对方场上与手牌与场上把所有卡送去墓地，从卡组或墓地选择1只怪兽特殊召唤上场，不能对应这张卡的发动把魔法、陷阱、效果怪兽的效果发动，被那只怪兽破坏的卡不送入墓地直接排除到游戏外。对方每次准备阶段，我方回复1000点生命值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103225', '接触变形', '名字带有「元素英雄」的怪兽才能装备，发动后选择自己的额外卡组1只7星以下名字带有「元素英雄」的融合怪兽，装备的怪兽得到选择怪兽的效果。结束阶段时把这张卡加入卡组洗切。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103226', '钢盔的护卫', '发动此卡，我方场上的「星尘龙」、「救世星龙」、「流星龙」、「流天类星龙」、「罪 星尘龙」不受对方任何卡的效果影响，且不受任何攻击、对方怪兽卡与魔法、陷阱卡的两个区域将不能使用。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103227', '魔法师的合体攻击', '对方发动攻击宣言时，此卡可以发动，指定我方场上1只魔法师族怪兽，被指定的怪兽的攻击力上升场上与手牌所有魔法师族怪兽数量×1000，其余怪兽守备表示存在场上。对方承受对方场上所有怪兽攻击力的数值伤害，回合结束时，我方被指定的怪兽攻击装备依旧不变，其他怪兽恢复本身状态。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103228', '木黑魔导少女', '场上存在「B2地带」的场合，这张卡可以从手牌特殊召唤。场上正面表示存在的这张卡攻击力·守备力变为0，并且不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103229', '龙骑士黑魔导女孩', '把场上或手牌的「黑魔导女孩」和「提玛欧斯之眼」送去墓地时，召唤此卡。此卡召唤成功时，每回合可以破坏对方一张卡片，墓地或场上每有一张魔法师族的怪兽时此卡攻击力上升墓地怪兽数量每一只加400。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103230', '魔法师的光辉', '此卡不能通常召唤。把1只名字带有「黑魔导」的怪兽从手牌送入墓地才能特殊召唤。此卡不受魔法、陷阱、效果怪兽的效果影响，召唤成功的场合，得到对方手牌中任意数量的卡的控制权（卡片由我方选择），当对手手牌是0张的场合，对方三回合内不能从卡组抽取任何卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103231', '超魔导剑士·破魔连斩', '「超魔导剑士·圣堂武士」＋「魔导战士·破坏剑士」
INSERT INTO "texts" VALUES ('ZZ103232', '清净之祭品', '此卡发动时，可把我方墓地名字带有「净」的怪兽尽可能的特殊召唤上场，以此卡的效果被召唤上场的怪兽不会被对方魔法·陷阱·效果怪兽的效果无效化，且每回合有1次不会被战斗破坏，让每只怪兽的攻击力上升1200点。我方场上正面表示存在的所有怪兽不会被「清净世界」的效果所适用。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103257', '混沌帝皇龙战士', '这张卡不能通常召唤。从自己墓地把所有怪兽除外的场合才能特殊召唤。
INSERT INTO "texts" VALUES ('ZZ103256', '暗黑同调 蜘蛛茧', '对方场上存在怪兽自己场上不存在怪兽的场合，这张卡可以从手牌特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103255', '真六武众-机山', '自己场上有「真六武众-机山」以外的名字带有「六武众」的怪兽正面表示存在的场合，这张卡可以从手牌特殊召唤。自己场上有这张卡以外的名字带有「六武众」的怪兽正面表示2只以上存在的场合，这张卡的攻击·守备力上升300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103254', '火焰蛋LV5', '效果伤害发生时可以发动。对方玩家的手牌里存在的1只等级5的怪兽特殊召唤。无法特殊召唤的场合，给予对手玩家的生命值500点的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103253', '怒视LV5', '给予对手的生命值自己场上存在的等级5怪兽的数量×500点的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103252', '双火山', '自己回合的准备阶段时，给予对手生命值500点伤害。可以将这张卡送入墓地，给予对方生命值500点伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103251', '装甲超量', '从自己的目的选择1只超量怪兽，当做自己场上存在的1只超量怪兽的装备卡装备。装备怪兽当作用这张卡的喜爱过装备的怪兽的同名卡，变为与那只怪兽的攻击力相同。可以将用这个效果装备的怪兽送入墓地，装备怪兽在战斗阶段中可以只再攻击一次。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103250', '待机的冰洞', '自己场上存在的1只守备表示的怪兽的等级上升1。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103249', '背头雪暴蜥', '这张卡被战斗破坏时，对方场上存在的攻击表示的怪兽表示形式不能再变更。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103248', '锤击火焰龙', '翻转：这张卡的等级上升1。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103247', '悲伤的故事 ～悲伤的回忆～', '这张卡发动的回合，这张卡以外的魔法卡不能发动。抽卡阶段时抽到的卡是怪兽卡的场合，双方玩家把那张卡返回走自己的卡组中洗切。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103246', '悲伤的故事 ～忌讳之日～', '这张卡发动的回合，这张卡以外的魔法卡不能发动。抽卡阶段时抽到的卡是陷阱卡的场合，双方玩家把那张卡返回走自己的卡组中洗切。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103245', '悲伤的故事 ～不可动摇的真实～', '这张卡发动的回合，这张卡以外的魔法卡不能发动。抽卡阶段时抽到的卡是魔法卡的场合，双方玩家把那张卡返回走自己的卡组中洗切。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103244', '进化 混沌的魔龙', '此卡不能通常召唤，将2张手牌名字带有「进化」的怪兽送入墓地可以特殊召唤。此卡召唤成功后，双方手牌和场上的卡全部破坏送入墓地，每有1张给予对方400点生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103243', '圣刻 蓝魔龙', '此卡被卡的效果从手牌特殊召唤上场时，选择对方最多2张手牌破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103242', '圣刻 红魔龙', '此卡被卡的效果从手牌送入墓地时，给予对方2000点生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103241', '圣火紫炎', '发动此效果后，场上存在名字带有「六武众」炎属性怪兽以外的炎属性怪兽全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103240', '六武众的元素师', '此卡召唤成功后，可以将对方场上的怪兽卡转变成任意1种属性。1回合1次，丢弃1张手牌，破坏对方魔法陷阱区1张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103239', '六武众的武者', '此卡召唤成功后，将我方场上1只名字带有「六武众」的怪兽送入墓地，选择以下一个效果发动：·选择对方场上1张卡片破坏。·给予对方送入墓地的怪兽攻击力数值的生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103238', '六武众的魔法师', '当我方场上有名字带有「六武众」的怪兽被破坏送入墓地时，此卡可以从手牌特殊召唤，此卡不受魔法·陷阱卡的效果影响。此卡战斗破坏对方怪兽时，给予对方追加那只怪兽的攻击力数值的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103237', '六武众的流浪武痴', '当对方场上有2只怪兽存在时，此卡可以从手牌特殊召唤上场，此卡召唤成功后，攻击力上升双方场上魔法陷阱区卡片数量×300的攻击力数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103236', '六武兵团', '此卡发动后，从手牌无条件特殊召唤1只战士族族怪兽，如果召唤出来的怪兽名字带有「六武众」，攻击力上升1000点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103235', '灵使军团', '此卡发动后，从手牌无条件特殊召唤1只魔法师族怪兽，如果召唤出来的怪兽名字带有「灵使」，攻击力上升1000点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103234', '灵魂附魔', '对方场上有怪兽特殊召唤成功的场合可以发动，我方得到那只怪兽的控制权。当那张卡破坏时，给予对方那张卡等级×300点的生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103233', '罪 奥西里斯之天空龙', '此卡通常召唤时必须牺牲3只怪兽。此卡通常召唤不能被无效化。此卡通常召唤成功时，魔法·陷阱·效果不能发动。此卡不会成为魔法·陷阱·效果怪兽的对象，此卡特殊召唤回合结束送入墓地，此卡攻击力为我方手牌数×1000。在任何阶段，当对方召唤怪兽时，如果以攻击形式表示，则减少它2000点攻击力，如果以守备形式表示，则减少它2000点守备力。如果因为这个特殊能力而将其攻击力或守备力降为0，则将那只怪兽破坏。此卡场上离开时，我方宣告胜利。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103258', '星尘龙', '调整＋调整以外的怪兽1只以上
INSERT INTO "texts" VALUES ('ZZ103259', '流星龙', '同调怪兽调整＋「星尘龙」
INSERT INTO "texts" VALUES ('ZZ103260', '黑鳍条枪兵', '水属性3星怪兽×2
INSERT INTO "texts" VALUES ('ZZ103261', '永火死亡龙', '暗属性调整＋调整以外的怪兽1只以上
INSERT INTO "texts" VALUES ('ZZ103262', '圣刻 蓝魔龙', '此卡被卡的效果从手牌特殊召唤上场时，选择对方最多2张手牌破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103263', '元素英雄 热焊电弧侠', '「元素英雄 爆热女郎」+「元素英雄 电光侠」
INSERT INTO "texts" VALUES ('ZZ103264', '星尘庇护战士', '调整＋调整以外的怪兽1只以上
INSERT INTO "texts" VALUES ('ZZ103265', '究极爆裂模式', '自己场上所有同调怪兽解放才能发动。包含那些怪兽卡名的「/爆裂体」怪兽从卡组·手卡·墓地·除外区尽可能攻击表示特殊召唤。
INSERT INTO "texts" VALUES ('ZZ103266', '地缚神 神龙之首', '这张卡不能通常召唤。把自己场上名字带有「地缚神」的卡送去墓地的场合才能特殊召唤。每送入1只怪兽去墓地，可破坏对方1张卡。1回合1次，可以把对方1只怪兽当做装备卡使用给这张卡装备，这张卡的攻击力上升这个效果装备的怪兽的攻击力数值。此外，这张卡不会被对方的魔法、陷阱、效果怪兽的效果破坏。自己的装备阶段时有1次可以把这张卡的效果装备的1只怪兽送去墓地，给予对方2000点的生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103267', '地缚神 赫比', '此卡不用祭品可以直接召唤上场。此卡不受对方卡中以名字带有「地缚神」的卡为对象的效果影响。在自己的准备阶段时，可以从卡组抽2张卡，若是怪兽卡，可直接召唤上场，若是魔法、陷阱卡，可直接盖放魔法陷阱卡区域。1回合只有1次，可以给对方场上的怪兽放置1个「毒指示物」，每放置1个，对方的怪兽攻击力下降1000点。被这个效果把攻击力变成0的怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103268', '地缚神 奥偌赤玛鹿', '这张卡不受魔法与陷阱卡的效果影响，这张卡不能通常召唤。自己的场上以及墓地名字带有「地缚神」的卡合计3种类以上存在的场合才能特殊召唤。只要这张卡正面表示存在，自己的其他怪兽不能攻击宣言。这张卡在特殊召唤回合可以发动以下任意效果：·把自己墓地名字带有「地缚神」的怪兽全部从游戏中除外，每除外1张，这张卡的攻击力上升2000点。·可以把自己手牌全部送去墓地，从卡组抽取同样数量的卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103269', '地缚神 断层天楼', '名字带有「地缚神」的怪兽攻击时，攻击怪兽的攻击力比攻击对象的攻击力低的场合，攻击怪兽的攻击力上升那只怪兽的攻击力数值。此卡存在场上时，这张卡的控制者不会受到战斗伤害。回合结束时，我方从手牌、卡组特殊召唤1只名字带有「地缚神」的怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103270', '地缚神的供品', '支付一半生命值发动。在「地缚神的祭坛」上放置2个地缚神指示物。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103271', '机械昆虫 加农炮甲虫', '除此卡外，场上每存在1只「机械昆虫」，此卡攻击力上升2000。此卡被破坏可从卡组、墓地将2只机械族怪兽召唤上场。
INSERT INTO "texts" VALUES ('ZZ103272', '机械昆虫 青钢蟋蟀', '此卡在场上，对方所有陷阱卡无效。
INSERT INTO "texts" VALUES ('ZZ103273', '机械昆虫 魔蝎王之卵LV1', '它是用昆虫的DNA配合先进的科技用机械合成的卵，生命力极其顽强。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103274', '机械昆虫 机枪黄蜂', '除此卡外，场上每存在1只「机械昆虫」，此卡攻击力上升500。
INSERT INTO "texts" VALUES ('ZZ103275', '机械昆虫 大炮知了', '除此卡外，场上每存在1只「机械昆虫」，此卡攻击力上升1000。
INSERT INTO "texts" VALUES ('ZZ103276', '机械昆虫 绿钢跳蚤', '此卡在场上，对方所有魔法卡无效。
INSERT INTO "texts" VALUES ('ZZ103277', '机械昆虫 黄钢毒蜂', '装备到对方怪兽身上，可得到怪兽的控制权。1回合1次，可破坏对方场上1只怪兽。
INSERT INTO "texts" VALUES ('ZZ103278', '机械昆虫 魔蝎王之卵LV2', '解放此卡送入墓地可从墓地特殊召唤1只5星以下的怪兽。将场上的「机械昆虫 魔蝎王之卵LV1」解放，此卡可从手牌特殊召唤。
INSERT INTO "texts" VALUES ('ZZ103279', '机械昆虫 红钢蜘蛛', '此卡在场上，对方所有怪兽卡效果无效。1回合1次，可破坏对方场上1张魔法、陷阱卡。
INSERT INTO "texts" VALUES ('ZZ103280', '机械昆虫 橙钢蝎子', '此卡在场上，对方所有魔法、陷阱卡效果无效。1回合1次，可破坏对方场上1只怪兽。
INSERT INTO "texts" VALUES ('ZZ103281', '机械昆虫 荒废的穴', '我方墓地全部卡返回卡组洗切。
INSERT INTO "texts" VALUES ('ZZ103282', '机械昆虫 木机穴', '此卡在场上，我方场有名字带有「机械昆虫」存在时，对方所有怪兽效果无效。
INSERT INTO "texts" VALUES ('ZZ103283', '机械昆虫 钢机穴', '此卡在场上，我方场有名字带有「机械昆虫」存在时，对方所有魔法、陷阱卡无效。
INSERT INTO "texts" VALUES ('ZZ103284', '机械昆虫 金蝎', '「机械昆虫 黄钢毒蜂」＋机械族怪兽1只 
INSERT INTO "texts" VALUES ('ZZ103285', '冥界之王 阿努比斯', '此卡的召唤和效果不会被无效化，不受对方卡效果影响。只能当我方生命值归零时，从卡组·墓地·游戏外特殊召唤上场。此卡召唤成功时，将双方卡组·墓地·魔法陷阱区所有卡片移除到游戏外。限此卡在场，跳过双方抽卡阶段，我方胜负条件不受生命值影响，当我方场上不存在怪兽时对方宣布胜利，此卡召唤5回合后我方宣告胜利。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103286', '究极冥界之王 阿努比斯', '让玩家生命值为1，此卡可从手牌·卡组·墓地特殊召唤到场上，此卡效果强制发动，且不会被无效化。此卡不受魔法·陷阱·效果怪兽的影响。并不会被战斗破坏。1回合1次，选择1个效果发动。·可以特殊召唤1只邪神族怪兽到场上。·破坏对方所有卡片。·对方除手牌以外的卡全部被封印不能使用。对方手牌没有时，我方取得胜利。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103287', '真红眼钢铁龙', '「真红眼黑龙」＋「特殊金属化」', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103288', '千年智慧轮', '从场地和手牌把等级直到8以上的卡作为祭品，可以将「马哈特神官」特殊召唤上场。此效果不会被无效化。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103289', '千年秤', '从场地和手牌把等级直到8以上的卡作为祭品，可以将「卡利姆神官」特殊召唤上场。此效果不会被无效化。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103290', '千年积木', '从场地和手牌把等级直到10以上的卡作为祭品，可以将「法老王 亚图姆」特殊召唤上场。此效果不会被无效化。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103291', '千年首饰', '从场地和手牌把等级直到8以上的卡作为祭品，可以将「爱西斯神官」特殊召唤上场。此效果不会被无效化。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103292', '千年锡杖', '从场地和手牌把等级直到8以上的卡作为祭品，可以将「瑟特神官」特殊召唤上场。此效果不会被无效化。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103293', '千年眼', '从场地和手牌把等级直到8以上的卡作为祭品，可以将「阿克纳帝神官」特殊召唤上场。此效果不会被无效化。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103294', '千年钥匙', '从场地和手牌把等级直到8以上的卡作为祭品，可以将「夏达神官」特殊召唤上场。此效果不会被无效化。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103295', '玛哈特神官', '此卡特殊召唤成功后，可以得到对方场上1只怪兽的控制权。我方回合结束后那只怪兽回到对方场上，攻击力下降500。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103296', '卡利姆神官', '此卡特殊召唤成功后，可以破坏对方场上覆盖的1张卡，对方不能对应此效果发动陷阱卡。此卡攻击对方守备表示的怪兽时，不计算生命值伤害，直接将那只怪兽破坏送入墓地。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103297', '瑟特神官', '此卡特殊召唤成功后，可以随机将卡组2张卡加入手牌。1回合1次，舍弃1张手牌，对方对应此卡发动的效果无效并破坏。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103298', '阿克纳帝神官', '此卡特殊召唤成功后，可以将我方墓地1只怪兽特殊召唤上场。可以将场上正面表示存在的这张卡移除到游戏外，选择将墓地尽可能多的4星怪兽特殊召唤上场。特殊召唤的怪兽效果无效化。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103299', '夏达神官', '此卡特殊召唤成功后，被效果移除到游戏外的卡回到卡组。此卡攻击力上升回到卡组卡片数量×500。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103300', '神官仆从  但丁', '此卡特殊召唤成功的场合，选择对方场上1只怪兽卡破坏，对方受到破坏怪兽攻击力的数值的生命值伤害。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103301', '神官的追随者 伊琳娜', '此卡守备表示存在于场上时，我方场上存在的名字带有「神官」的怪兽攻击力上升1000点，此卡被破坏破坏的场合，从卡组选择1张同名卡加入手牌。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103302', '神官见习考验', '选择墓地一张名字带有「神官」的卡加入手牌。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103303', '神官的驭兽者 洛可可', '此卡正面表示存在于场上时，1回合1次，选择墓地1只4星以下兽族怪兽特殊召唤到场上。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103304', '神官的御用魔术师 斯洛', '我方场上没有怪兽时，此卡可以从手牌特殊召唤上场。特殊召唤成功时，选择对方场上覆盖的1张卡回到持有者的手牌。发动这个效果的回合，此卡不能发动攻击宣言。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103305', '神官的御用刺客 伐克', '此卡正面攻击表示存在时，可以选择舍弃我方手牌，此卡可以直接攻击对方生命值。发动这个效果的回合结束后，此卡破坏。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103306', '神官的觉醒者 血逝', '我方场上只存在此卡时，此卡攻击力上升对方场上卡片数量x400点。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103307', '神官的烛之荣耀', '我方场上怪兽被破坏送入墓地时发动，下个我方回合，那只怪兽特殊召唤到场上。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103308', '神官的讶异', '我方场上1只名字带有「神官」的龙族怪兽被效果送入墓地时发动，可以将手牌·卡组·墓地1只「青眼白龙」特殊召唤上场。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103309', '神官的终极守护', '这个回合，我方场上的怪兽不受对方任何卡的效果影响。这个效果不会无效化。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103310', '神官的究极封印阵', '当我方场上名字带有「神官」的卡属性达到5种时，我方将赢得这场决斗的胜利。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103311', '神官的魔宠', '我方场上有名字带有「神官」的怪兽时，此卡可以从手牌特殊召唤，此卡召唤成功时，对方场上的陷阱卡全部破坏。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103312', '神官的元素师', '此卡正面攻击表示存在场上时，1回合1次，宣言1种属性，下个回合对方不能召唤宣言属性的怪兽。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103313', '神官的免疫装甲', '此卡只能装备在名字带有「神官」的怪兽身上。装备怪兽的攻击·守备力上升1000点。此卡不受陷阱卡的效果影响。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103314', '神官 幽灵军团', '此卡正面攻击表示存在场上时，我方回合，可攻击对方场上所有的怪兽，此卡不会被战斗破坏。此外，场上每存在1张此卡以外的名字带有「神官」的怪兽，此卡攻击力上升1000。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103315', '神官 精灵狮', '这张卡特殊召唤成功时，对方场上攻击力2000以上的怪兽回到对方手牌，对方场上没有怪兽时此卡攻击力·守备力上升1000点。此卡可以在对方回合发动攻击，攻击结束后此卡送入墓地。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103316', '神官的代言', '对方针对我方名字带有「神官」的卡发动卡的效果时可以发动，对方发动的卡的效果由对方承受。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103317', '神官的空中支援', '我方场上每存在1只名字带有「神官」的怪兽，对方场上的所有怪兽攻击力下降1000点。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103318', '神官 超时空魔导师', '此卡特殊召唤上场时，攻击力减半，且不能发动攻击宣言。此卡被战斗破坏送入墓地时，对方受到此卡攻击力与守备力之和的生命值伤害。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103319', '神官 符咒术士', '此卡发动攻击时，可选择对方1只攻击表示存在的怪兽改变其表现方式，选择的怪兽守备力变为0。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103320', '神官 魔人先锋', '此卡攻击守备表示的怪兽守备力在3000以下时，给予对方直接伤害。此卡被选为攻击对象时改变其表示方式。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ103321', '冥骸主宰龙-莫忘冥地王灵', '「莫忘」怪兽×5
INSERT INTO "texts" VALUES ('ZZ103322', '神之补给', '每当我方发动支付生命值的效果时，变成我方恢复生命值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ103323', '超魔导龙剑士-白魔导剑士', '「黑魔术师」＋「破坏之剑士」＋「青眼白龙」
INSERT INTO "texts" VALUES ('ZZ103324', '元素英雄 苍穹新宇侠', '「元素英雄 新宇侠」＋「新空间侠·苍穹蜂鸟」
INSERT INTO "texts" VALUES ('ZZ103325', '新空间侠·苍穹蜂鸟', '这个卡名在规则上也当作「新空间侠·天空蜂鸟」使用。这张卡用「新空间侠界限」的效果才能特殊召唤。
INSERT INTO "texts" VALUES ('ZZ103326', '空间爆裂龙', '包含同调怪兽的怪兽2只
INSERT INTO "texts" VALUES ('ZZ103327', '破坏龙 甘多拉', '这张卡不能特殊召唤。
INSERT INTO "texts" VALUES ('ZZ103328', '急袭猛禽-起翼叛逆猎鹰', '鸟兽族13星怪兽×5
INSERT INTO "texts" VALUES ('ZZ103329', '终极龙 红莲蔷薇', '龙族同调怪兽＋调整3只以上
INSERT INTO "texts" VALUES ('ZZ103330', '终极龙 火山烈焰', '龙族同调怪兽＋调整3只以上
INSERT INTO "texts" VALUES ('ZZ103331', '终极龙 幻兽妖森', '龙族同调怪兽＋调整3只以上
INSERT INTO "texts" VALUES ('ZZ103332', '终极龙 紫光破灭', '龙族同调怪兽＋调整3只以上
