INSERT INTO "texts" VALUES ('ZZ103968', '机皇兵 神智二型', '这个卡名的作为①的方法的特殊召唤1回合只能有1次，作为②的效果1回合只能使用1次。
INSERT INTO "texts" VALUES ('ZZ103969', '奥菲莉之虫惑魔', '地属性4星怪兽×2
