INSERT INTO "texts" VALUES ('ZZ103984', '破坏剑-心破坏之剑', '包含「破坏剑-」怪兽或者「破坏剑士」怪兽的怪兽2只
INSERT INTO "texts" VALUES ('ZZ103985', '眷血祖-吸血鬼·威廉姆', '6星怪兽×2
