INSERT INTO "texts" VALUES ('ZZ104000', '我我我少女', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" VALUES ('ZZ104001', '莫忘的补给', '这个卡名的②③的效果1回合各能使用1次。
INSERT INTO "texts" VALUES ('ZZ104002', '传说中的钓鱼场', '这个卡名的③④的效果1回合各能使用1次。
INSERT INTO "texts" VALUES ('ZZ104003', '津波融合', '自己或对方的场上·墓地的怪兽作为融合素材除外，把1只「传说的渔人」融合怪兽融合召唤。
INSERT INTO "texts" VALUES ('ZZ104004', '传说的渔人 七海的猎人', '「传说的渔人」＋水属性怪兽1只
INSERT INTO "texts" VALUES ('ZZ104005', '潜入海里', '这个卡名的卡在1回合只能发动1张。
INSERT INTO "texts" VALUES ('ZZ104006', '传说中的逆戟鲸', '这张卡召唤·特殊召唤成功时，从卡组或墓地选择1张「海」或「传说的渔人」加入手卡。 
INSERT INTO "texts" VALUES ('ZZ104007', 'G·HERO 漂泊者', '「英雄」4星怪兽×2
INSERT INTO "texts" VALUES ('ZZ104008', '剑之达人 迦南', '自己场上·墓地存在「女剑士 迦南」时，这张卡可以从手牌·墓地特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('A1000057', '黑暗魔界的霸王', '这是一张战斗力很强的卡。它可以产生“魔导波”攻击对方。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('A1000058', '牛头战士', '“牛头战士”属于火系的怪兽，这是一张战斗力很强的卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('A1000059', '人头马身', '它具有强大的攻击力，用手上的刀攻击对方。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('A1000061', '万兽龙', '在瞬间能把对方斩成五段，号称瞬间五连斩。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ104009', '迷宫的魔战车', '守卫迷宫的无敌重战车！只要此卡存在战场上，我方手牌中的恶魔族怪兽攻击力和防守力增加1000点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ104010', '格斗战士阿鲁提', '仅凭锻炼出来的肉体与武器战斗的战士。手牌中有魔法、陷阱和装备卡片时，可以扣放在场中。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ104011', '牛头兽', '因与此卡战斗，而被送入墓地的怪兽，可回到对手牌组最上层。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ104012', '巴巴利安2号', '将战斗作为唯一的生存意义的野蛮民族的战士。将最后打到的卡片上星的数量进行合计，多的一方获胜。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ104013', '快乐淑女1', '人身上长有羽毛的怪兽，在我方回合发动时，进行尖锐攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ104014', '快乐淑女2', '若与“万花筒”一起使出，将成为使场上的快乐女士的攻击、防守力都增加500的装备卡片。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ104015', '乌贼兽', '付出500点的生命点。破坏对方战场上攻击力在1000点以上的怪兽一只。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ104016', '海蜇', '拥有能够吸取电荷、使其无效的力量的海蜇。此卡发动时，所有雷属性的怪兽对它的攻击无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ104017', '法老王的宝座', '当受到攻击时，发动这张卡可以令对方的攻击无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ104018', '雷骑士', '这张卡能使场上一只雷属性的怪兽攻击力增加400点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ104019', '死者复活', '死者复活是在怪兽被破坏时发动的陷阱卡，让被消灭的怪兽复活。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ104020', '平等等级四', '这张卡会在怪兽被消灭时启动，彼此可以特殊召唤一只4星级怪兽到场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RDS00075', '逐渐碎裂的斧头', '本卡片覆盖后经过的轮数，乘上五百所得的数值，从对方的攻击力抠除。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ104022', '魔术丝帽', '已经用过的魔物卡片可以和手中的任何一张主人魔物卡片交换。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ104023', '游戏', '拥有此卡，你的攻击力将随着对手的卡片变动。对手的攻击力大于守备力的时，你的攻击力可提升三倍；相反的，你的攻击力只能维持现状，但守备力可增加两倍。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('WDK00059', '黄金天马', '千年诞生一次的黄金天马！', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ104021', '红色赫科特', '邪恶的女神三姐妹之一。会使用令人生畏的妖术。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('KA000025', '紫罗兰色女巫师', '恶魔女巫三姐妹之一，能够使用令人惊恐的巫术呼风唤雨。如果你把恶魔巫女三姐妹的卡片收集齐了并打出来，就可以召唤女巫“高贡”到场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('KA000101', '女巫“高贡”', '这是威力特别强大的女巫恶魔，它由巫女三姐妹合体而成。如果你把恶魔巫女三姐妹的卡片收集齐了并打出来，就可以连续三次进行战斗。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('KA000098', '黄色女巫师', '恶魔女巫三姐妹之一，能够使用令人惊恐的巫术呼风唤雨。如果你把恶魔巫女三姐妹的卡片收集齐了并打出来，就可以召唤女巫“高贡”到场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('WDK00021', '炼狱之龙', '使用邪恶的妖术而复活的龙。使用过一次的魔法、陷阱、装备卡片成为弃牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('WDK00073', '瓦洛克斯', '用怪兽般的钩爪将敌人撕裂！此卡被送往墓地时，可变成装备卡（攻击力-500）装备在战场上一只怪兽身上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('WDK00067', '大地的龙脉', '仅为恶魔族的怪兽增加800点攻击力。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RDS00061', '封印的黄金柜', '把一张卡片封印在黄金柜。该卡片不会被任何魔法效果影响，对方玩家也无法使用。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RDS00062', '时光飞跃', '发动这项魔法的瞬间，时间回跳到三轮之后的攻击状态。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RDS00065', '地缚灵的邀请', '当对手为攻击状态时发动。表示攻击的怪兽会被迫发动攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RDS00074', '魔法师之圆', '使用魔法师攻击时，就会发动，两方玩家可从牌堆拿出一张魔法师卡片，用攻击状态特殊召唤到场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RDS00076', '魔法师合作', '当自己场上召唤出两只以上的魔法师，可发动攻击力三千的联合魔法。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RDS00078', '士兵娃娃', '当士兵娃娃存在对方玩家为准备状态时，会在出现一个娃娃士兵。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ104024', '倒转的女神', '将危及转变为机会的希望女神。从手牌中选取1张牌、同时出牌，战斗开始。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ104025', '宇宙之龙', '变成流血坠落的、来自宇宙的龙！', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('KA000060', '阿克斯袭击者', '这是使用铁斧头的盔甲战士，它的斧头一挥舞，敌人就闻风而逃。战斗结束后，从卡叠上面抽出一张卡片，并加到手卡上面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('KA000064', '阴影里的僵尸', '能够隐藏在阴影里，用尖锐的爪在敌人的背后发动袭击。在场上正面朝下的魔法、陷阱、装备卡、在战斗中随时都可以使用。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('KA000080', '幽灵铠甲武士', '它是在战斗中战败的武士的冤魂，手里挥舞着一把宝剑。在场上正面朝下的魔法、陷阱、装备卡、在战斗中随时都可以使用。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('KA000103', '岩石炮', '这是由岩石变身而来的格斗战士、计算一下最后倒下的卡片星星的总数，多的一方为胜利者。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('KA100103', '勒可多斯龙王', '它是巨大的恐龙，能够用巨大的颚和牙齿把猎物咬碎。战斗结束后，从卡叠上面抽出一张卡片，并加在手卡上面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('KA000104', '月夜的盾剑骑士', '这是影子般的战士，修炼有一剑封喉的剑法！！当手卡中有魔法卡、陷阱卡、装备卡的时候，就可以把它们正面朝下放在场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('KA000105', '氖光骑士', '他能够发出五颜六色的炫目彩光，真是华丽的骑士！！在场上正面朝下的魔法、陷阱、装备卡、在战斗中随时都可以使用。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('KA000120', '加各尔角兽', '这是通过魔术手法产生出来的人造怪兽。准备好与同伴一样张数的卡片，然后放在卡叠上面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RDS00070', '死牌相抵', '当玩家结束该回合牌时，场上有多少怪兽，就从牌堆丢掉相同张数的牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RDS00077', '诅咒的双胞胎娃娃', '双胞胎各拿着红色与黑色的盒子。玩家各选一个，红色盒子为玩家带来500点生命值，黑盒子会为场上带来诅咒。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('BLO00001', '再生怪力人', '可以从对方的卡组和墓地中抽出所有“死者苏生”到自己的手中。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('BLO00002', '石中剑', '增加一只怪兽攻击力、防备力一倍。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('VB700002', '地魔', '每回合能使对方受到100点的伤害值，若同时场上存在三只地魔，每回合可以伤害对方1800点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('VB700003', '邪龙神', '这张卡只有用魔法卡、陷阱卡、怪兽卡各一张当作祭品，才能召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('VB700004', '诞生的祝福', '当怪物被特殊召唤到场上时，可以终止对方回合。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('VB700005', '魂的利雷', '当生命值成为0时，让手中的怪兽召唤到场上，将战斗的胜败托付给此怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('VB700006', '记忆的容器', '可将墓地中的卡片全部回到卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ104026', '六芒星的诅咒', '对手的魔物攻击力比自己高的时候用这张卡片，可使对手的攻击力变成0。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ104027', '谢莉尔·布兰', '每有一张手牌，我方场上的怪兽攻击力和守备力上升200点，当这张卡被卡的效果破坏送去墓地时，我方场上所有怪兽返回手牌。此外，此卡可以当做一只怪兽召唤的祭品。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00351', '食人恐龙', '当此卡进行攻击宣言时，只要此卡的攻击力超越对方守备力时，超越的数值可直接造成对方的生命值的损伤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00366', '双极之剑', '装备此卡的怪兽攻击力与守备力各上升500点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00372', '骷髅武士', '当骷髅武士被送到墓地时，这张卡将被返回牌组的最上方。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00377', '同类之争', '当此卡攻击转为守备状态时，破坏敌方场上的一只怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00380', '铃铛猫', '此卡以正面方式存在场上时，场上所有地属性的怪兽攻击力全部上升500点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00268', '反击鼠', '当它翻到正面时，可破坏场上的一张陷阱卡片。在破坏陷阱后，就只能用来防御了。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ104028', '始源终极龙', '←10 【灵摆】 10→
INSERT INTO "texts" VALUES ('ZZ104029', '霸王龙 扎克', '←1 【灵摆】 1→
INSERT INTO "texts" VALUES ('ZZ104030', '魔女杀戮-钢', '只要这张卡在战斗中被移除到墓地外，就可以从墓地中特殊召唤一只恶魔族怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ104031', '魔女杀戮-姬', '当场上有魔女杀戮-钢和魔女杀戮-姬的时候可以破坏对方场上一张魔法卡和陷阱卡各一张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ104032', '魔女转换', '把所有的光属性的卡片变成暗属性的卡片，每变换一张并回复自己100的血。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ104033', '魔女的宣告', '将一张魔女的杀戮的卡片从手里丢到墓地里，可以从卡组里特殊召唤二只暗属性的怪兽以防守状态到场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ104034', '魔女的返回', '把上个回合墓地里的魔女杀戮的怪兽卡从墓地里复活。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ104035', '魔女杀戮-红', '当这张卡片在场上的时候所有暗属性以外的卡片攻击力下降400点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ104036', '魔女杀戮-莲', '当场上有魔女杀戮-钢、姬、红、莲的时候破坏对方场上的所有怪兽卡并从墓地里抽取一张魔法卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ104037', '魔女结界', '强制对方的回合结束并使对方三个回合不能攻击和抽牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ104038', '魔女的化身', '场上有暗属性的怪兽魔女杀戮的怪兽攻加100乘以卡片数量。
INSERT INTO "texts" VALUES ('ZZ104039', '诸神遗迹·守护棘龙', '沙漠水源的守护之龙，数千年来一直监视水源的动静，对入侵者毫不留情的攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ104040', '空牙团的铁臂 沃德', '连接怪兽以外的「空牙团」怪兽1只
INSERT INTO "texts" VALUES ('ZZ104041', '幻影骑士团 尖锐死枪', '战士族怪兽2只以上
INSERT INTO "texts" VALUES ('ZZ104042', '精灵兽 地兔', '自己对「精灵兽 地兔」1回合只能有1次特殊召唤。
INSERT INTO "texts" VALUES ('ZZ104043', '邪心英雄 深红连魔', '「邪心英雄」怪兽＋通常怪兽 
INSERT INTO "texts" VALUES ('ZZ104044', '命运英雄 顽石人', '这个卡名的①的效果1回合只能使用1次。①：自己场上的「命运英雄」怪兽被效果送去墓地的场合才能发动。这张卡从手卡特殊召唤。这个效果特殊召唤的这张卡直到回合结束时不会被战斗·效果破坏。②：把墓地的这张卡除外才能发动。这个回合，自己场上的「英雄」怪兽不会被战斗·效果破坏。这个效果在对方回合也能发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ104045', '幻影英雄 原型人', '这个卡名的①②的效果1回合各能使用1次。
INSERT INTO "texts" VALUES ('ZZ104046', '守墓的唤灵师', '暗属性3星怪兽×2
INSERT INTO "texts" VALUES ('ZZ104047', '虫之魔妖-常元', '①：「虫之魔妖-常元」在自己场上只能有1只表侧表示存在。 ②：这张卡在墓地存在，自己场上的「魔妖」怪兽成为对方的效果的对象时或者成为对方怪兽的攻击对象时才能发动。这张卡特殊召唤。这个效果发动的回合，自己不是「魔妖」怪兽不能从额外卡组特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ104048', '虫之魔妖-净元虫', '连接怪兽以外的「魔妖」1只
INSERT INTO "texts" VALUES ('ZZ104049', '芳香法师-薄荷', '①：只要自己基本分比对方多并有这张卡在怪兽区域存在，对方不能从卡组把卡送去墓地。②：1回合1次，自己基本分回复的场合发动。给与对方500伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ104050', '芳香炽天使-薄荷', '调整＋调整以外的怪兽1只以上
INSERT INTO "texts" VALUES ('ZZ104051', '幻影骑士团 折半刀', '战士族·暗属性4星怪兽×2
INSERT INTO "texts" VALUES ('ZZ104052', '魔女术组合·召唤小组', '属性不同的魔法师族怪兽2只
INSERT INTO "texts" VALUES ('ZZ104053', '灰篮九头蛇', '调整+调整以外的怪兽1只以上
INSERT INTO "texts" VALUES ('ZZ104054', '龙瀑还归', '这个卡名的卡在1回合只能发动1张。
INSERT INTO "texts" VALUES ('ZZ104055', '狱火机·曼德斯', '「狱火机十进管」＋「狱火机・撒旦」＋「狱火机」怪兽1只以上
INSERT INTO "texts" VALUES ('ZZ104056', '时间怪盗 监察者', '包含「时间怪盗」怪兽的怪兽2只
INSERT INTO "texts" VALUES ('ZZ104057', '电子化猫机灵', '2星怪兽×2
INSERT INTO "texts" VALUES ('ZZ104058', '科技属 铁甲狂战士', '调整＋调整以外的怪兽1只以上
INSERT INTO "texts" VALUES ('ZZ104059', '古代的机械上级素体', '这个卡名的②的效果1回合只能使用1次。
INSERT INTO "texts" VALUES ('ZZ104060', '佑炎星-秃鹰宁', '←2 【灵摆】 2→
INSERT INTO "texts" VALUES ('ZZ104061', '影依之骑士 天市右垣七', '光属性·暗属性怪兽2只
INSERT INTO "texts" VALUES ('ZZ104062', '侵略的泛发袭击', '这个卡名的卡1回合只能发动1张。
INSERT INTO "texts" VALUES ('ZZ104063', '真海皇 安凯奥斯', '这个卡名的①②的效果1回合各能使用1次。①：把手卡的这张卡和「真海皇 安凯奥斯」以外的卡组的1只「海皇」怪兽送去墓地才能发动。从卡组把1只「海皇龙 波塞德拉」特殊召唤。②：这张卡为让「真海皇 安凯奥斯」以外的水属性怪兽的效果发动而被送去墓地的场合发动。自己从卡组抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ104064', '魔女术工匠·栽培女巫', '这个卡名的作为①的方法的特殊召唤1回合只能有1次，作为②的效果1回合只能使用1次。①：这张卡可以把手卡1张魔法卡丢弃，从手卡特殊召唤。②：从手卡丢弃1张魔法卡，以除外的自己的「魔女术」怪兽任意数量为对象才能发动。那些怪兽回到手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ104065', '三形金字塔的化身', '3星怪兽×2
INSERT INTO "texts" VALUES ('ZZ104066', '退炎星-雷剑齿', '←6 【灵摆】 6→
INSERT INTO "texts" VALUES ('ZZ104067', '曙光之圣刻印', '①：只要这张卡在魔法与陷阱区域存在，「圣刻」怪兽的效果把龙族通常怪兽特殊召唤的场合，也能把通常怪兽以外的龙族怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ104068', '剑斗兽 替斗', '①：这张卡用「剑斗兽」怪兽的效果特殊召唤成功的场合，支付800基本分才能发动。自己从卡组抽1张，给双方确认。确认的卡是「剑斗兽」卡的场合，自己可以再抽1张。②：这张卡进行战斗的战斗阶段结束时让这张卡回到持有者卡组才能发动。从卡组把「剑斗兽 替斗」以外的1只「剑斗兽」怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ104069', '雾动机龙·南方巨兽龙', '机械族·水属性怪兽2只以上
INSERT INTO "texts" VALUES ('ZZ104070', '堕天使 安士白', '自己对「堕天使 安士白」1回合只能有1次特殊召唤，那些作为①②的效果1回合各能使用1次。
INSERT INTO "texts" VALUES ('ZZ104071', '炎神鸟 斯摩夫', '这个卡名的①②的效果1回合各能使用1次。①：以对方的魔法与陷阱区域1张卡为对象才能发动。那张卡破坏，这张卡从手卡特殊召唤。②：这张卡在墓地存在，对方的魔法与陷阱区域没有卡存在的场合才能发动。这张卡守备表示特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。这个效果的发动后，直到回合结束时自己不是鸟兽族怪兽不能特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ104072', '电子鱼人-操作员', '鱼族怪兽1只
INSERT INTO "texts" VALUES ('ZZ104073', '屋敷童', '这个卡名的效果1回合只能使用1次。
