INSERT INTO "texts" VALUES ('ZZ104096', '海晶少女的集结', '这个卡名的卡在1回合只能发动1张。①：只有对方场上有怪兽存在的场合才能发动。从自己的手卡·卡组·墓地各选1只「海晶少女」怪兽特殊召唤，自己失去1500基本分。这个效果的发动后，直到回合结束时自己不是水属性怪兽不能从额外卡组特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
