INSERT INTO "texts" VALUES ('ZZ105283', '暗岩战士', '通常怪兽＋效果怪兽1只以上 
INSERT INTO "texts" VALUES ('ZZ105284', '暗黑护卫·女骑士盖亚', '通常怪兽＋效果怪兽1只以上 
INSERT INTO "texts" VALUES ('ZZ105285', '被封印者的左眼', '收集五种身体碎片，使它复活的人，将可使任何的敌人在一瞬间消灭。
INSERT INTO "texts" VALUES ('ZZ105286', '被封印者的右眼', '收集五种身体碎片，使它复活的人，将可使任何的敌人在一瞬间消灭。
INSERT INTO "texts" VALUES ('SOD00087', '千年·黑暗巨角兵', '当该怪兽发动攻击的时候，随意地从对方的手牌中抽出一张卡牌，然后让对方把此卡送回它自己的墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SOD00088', '千年“波萨克”火龙', '当发动攻击的时候，你墓地中的每张龙族卡都可以提高100点攻击力。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SOD00089', '千年·水族之王', '能将场地改为海并在场上的水族怪兽不会受到攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SOD00090', '千年·装甲龙', '当该怪兽发动攻击的时候，可以对方的场地中选出一张卡片，然后送回它自己的墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SOD00091', '千年·速攻吸血蛆', '能在第一个回合直接攻击对手，丢弃一张卡，可使它以防守状态来结束此回合。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SOD00092', '千年·磁龟', '此卡能变为对方持有，但每回合损伤1000点生命值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SOD00093', '千年·爆龙兵', '当该怪兽从自己的墓地中被召唤到场上的时候，可以从自己的手卡中选出一头龙族怪兽，当祭品然后也把它放到场上，然后直接攻击对方。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SOD00094', '千年·小飞龙', '当该怪兽被攻击的时候，如果自己场上有一张魔法或圈套卡（正面表示）就可以把它放入自己的墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SOD00095', '千年·陆星剑客', '场上出陆星卡片时，每张卡使其攻击力提升300点的攻击力。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('A1000064', '迷宫的魔鬼战车', '进入攻击状态，先进入到战斗场。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('A1000012', '附有火炮的盔甲', '昆虫人间的魔法卡等级5', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SOD00096', '藤蔓公主', '当它被召唤时，能控制对方一只怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SOD00097', '创始圣天使', '当该卡作祭品进行祭品召唤的时候，自己的能恢复3000点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SOD00098', '梦幻武士', '当该卡受到对方攻击时，对方也要受到500点伤害值同时宣告这一轮结束。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SOD00099', '堕落天使·炎夏巴', '此卡不能普通召唤必须以堕落天使夏巴祭生才能特召，此卡特召成功时，除天使族怪兽以外全部怪兽卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SOD00100', '激战怪斗士', '该怪兽可以用来直接攻击，也可以用来反转，让对方一头怪兽攻击力2000以下送回自己的墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SOD00101', '埋没神的救济', '在墓地中可能发动，在对方抽卡时，对方墓地有几只怪兽而每只怪兽会对方造成100分的损害，但在我方墓地中出现怪兽时此卡则被破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SOD00102', '凤凰之阵', '可使对应我方场上快乐女郎的数目来破坏对方场上的怪兽，然后对方受到破坏的怪兽的攻击总和的伤害值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SOD00103', '恶梦的铁锁', '让一只怪兽下降800攻击力，并加上自己800分生命值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SOD00104', '斩雪剑', '当场上有战士族防守时，可以发动，让对方的陷阱，魔法无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SOD00105', '生死的判官', '当使用骰子可指定点数。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SOD00106', '受伤转移', '将对方攻击力移到我方另一只怪兽上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SOD00107', '魔力的布施', '恢复1000生命值，然后每回合可以预测魔法卡使用的张数如果猜对了，那每张卡可以恢复500生命点，如果错误，反扣1000点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SOD00108', '水晶之封印', '能将一头怪兽封印，此怪兽既不能攻击，也不能成为祭品，若怪兽攻击力产生变化，则封印解除。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SOD00109', '渐渐的生命', '令对方丢弃从盖牌之后到使用为止相等回合数的手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SOD00110', '普丹的制裁', '对方攻击时，可以发动，让一张手牌中的魔法卡跟牌组最上的一张卡交换。然后洗牌，结束此回合。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('CRV00092', '喇叭花·寄生虫', '此怪兽被送入墓地后，在每一回合的结束阶段时，能从对方手牌中抽出一张卡片丢进墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('CRV00093', '链锯的斗士', '当该怪兽存在场面时，对手二回合才能抽一张牌，并能对发动攻击的怪兽攻击力损失一半。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('CRV00064', '音波迅猛龙', '速足的杀手龙＋翼手龙 
INSERT INTO "texts" VALUES ('CRV00088', '飞行者·艾里斯', '装备了此卡片怪兽，能避开对方怪兽的3次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105287', '武装龙 LV10', '此卡不可通常召唤，只能通过「武装龙 LV7」特殊召唤把手牌一张怪兽卡送去墓地对方场上的表侧表示的怪兽全部被破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105288', '魔导兽刻尔伯洛斯', '每次自己或者对方发动魔法卡，这张卡放置一个魔力指示物。这张卡每拥有一个魔力指示物，这张卡的攻击力上升500。这张卡进行战斗的回合的战斗流程结束时，这张卡的魔力指示物全部去除。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('DCOR0015', '武装的再生', '支付2000点生命值，把墓地与除外区的神属性怪兽正面攻击表示特殊召唤上场。这张卡从场上离开时，在下1个对方回合的准备阶段回到手牌。此卡的发动不能被无效化。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('DCOR0023', '黑玫瑰龙', '3星怪兽×2
INSERT INTO "texts" VALUES ('VB700008', '无名战士-亨利欧斯', '能与实践魔术师合体时间魔法锤，用骰子摇出数字。对方的场上的怪兽逐一摇出数字，这些数字就是怪兽暂时离开场上多少回合，再回到场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('VB700009', '无名战士-奇玛利欧斯', '能与黑魔导女孩融合，成为龙骑士黑魔导女孩，舍弃一张卡能使对方一头怪兽攻击力化为0。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('VB700010', '磁力金环', '当此存在时，对方所有怪兽无法攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('BLO00003', '陷阱克星', '当此卡在场时，自己不会受任何陷阱卡的影响，而且它能随着场上的盔甲怪兽，而且只增加攻击200，而陷阱克星战斗过的怪兽攻击力，将变成我方的生命值一样高。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('BLO00004', '大爆炸爆风', '破坏一头怪兽，并且对方将受到怪兽攻击力的伤害值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('BLO00005', '促进盾', '能牺牲一只盔甲怪兽来破坏对方一只怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('BLO00006', '主动盔甲', '当此卡在场时，将不会受到任何伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('BLO00007', '爆裂手腕', '此卡会随着场上，盔甲怪兽增加，每只提高攻击力200。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('BLO00008', '超越靴', '当此卡在场时，将不会受到任何伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('BLO00009', '金属龙', '可将两张魔法卡献出，破坏对方一头怪兽，而且对方受到此怪兽攻击力的伤害值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('BLO00010', '双十字盔甲', '在自己的回合时不能攻击，当它被选为攻击对象时，能破坏对手的怪兽，这回合结束时，此卡也被破坏让对方受到一半攻击力的伤害值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('BLO00011', '沙门骰子', '支付1000分生命点后，掷出投掷如出现1或2本回合我方可普通召唤2次。如出现3或4可以召唤墓地中的一头怪兽，如出现5或6则不用祭品就可以直接召唤任何怪兽卡、陷阱卡、魔法卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('BLO00012', '加星者', '只要手牌中有同等作为祭品的怪兽的等级与掷出点数的数值合值，相同等级别怪兽，可以特殊召唤出那只怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('BLO00013', '斗气盔甲', '在生命值低于2000时，被对方直接攻击时就可以发动生命值减半时对攻击无效，即可以召唤出“斗气盔甲”这只怪兽的攻击力等于伤害对方的生命值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('BLO00014', '虫蛀食', '让对方场上所有怪兽的攻击力下降100分。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('BLO00015', '战士起义', '当自己场上有化学特殊兵，魔界的机械兵以及赛法滋考特才能发动这回合无法攻击，但对方必须丢掉所有手牌并破坏对方场面上所有卡片。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105289', '杰克·阿特拉斯的D·轮', '此卡只能被「杰克·阿特拉斯」的同步怪兽同步召唤使用。这张卡在同1次的战斗阶段中可以作3次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105290', '十六夜 秋的D·轮', '此卡只能被「十六夜 秋」的同步怪兽同步召唤使用。这张卡翻转时，对方场上一张卡回到手卡。
INSERT INTO "texts" VALUES ('ZZ105291', '杰克·阿特拉斯', '「杰克·阿特拉斯的D·轮」＋调整以外的怪兽1只以上
INSERT INTO "texts" VALUES ('ZZ105292', '十六夜 秋', '「十六夜 秋的D·轮」＋调整以外的怪兽1只以上
INSERT INTO "texts" VALUES ('ZZ105293', 'D·轮的能量存储', '每次自己场上表侧表示存在的名字带有「D·轮」的怪兽被破坏，我方的基本分上升500点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105294', 'D·轮的时速', '这张卡的发动时，自己基本分比对方地的场合，自己恢复1000分基本分。并破坏对方场上所有的魔法、陷阱卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105295', '黑魔导之执行官', '这张卡不能通常召唤。自己场上存在的1只「黑魔术师」作为祭品的场合才能特殊召唤。只要这张卡在场上表侧表示存在，每次双方玩家发动通常魔法，给予对方基本分1000分伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105296', '千禧卡之1', '将自己墓地中的2只黑暗属性的怪兽从比赛中免除后，到此局结束前此卡片都可从比赛中免除。也可用于对方的控制局中，但此效果一局只是使用一次。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105297', '千禧卡之2', '即使是在恶魔族中也只有优秀的人才能拥有。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105298', '千禧卡之3', '守卫黑暗世界的战士。在水中和陆上都有着高战斗力。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105299', '千禧卡之4', '此卡片可将在战斗中破坏并送到墓地的1只对方的怪兽，通过正面防守显示特殊召唤到自己的阵地上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105300', '千禧卡之5', '此卡片不能进行普通召唤。分别除去自己墓地的一只光属性和一只黑暗属性的怪兽，就能进行特殊召唤。交上1000点的生存点数，就能好够将双方纸牌和阵地上的卡片全部送到墓地。在此效果下，每张送到墓地的卡片将减少对方300点的点数。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105301', '千禧卡之6', '只有当此卡存在于阵地上时，以墓地的卡片为对象。并且在墓地发动效果的魔法、阴谋怪兽的效果全部无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105302', '千禧卡之7', '只有在「大海」存在于阵地上时，此卡片能够直接攻击对方。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105303', '千禧卡之8', '此卡片在对恶魔族怪兽进行贡品召唤时，可从甲板上特殊召唤1只「斯卡卢」。然后搅乱甲板。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105304', '千禧卡之9', '此卡片在战斗中破坏怪兽并送到墓地时，可回复自己所破坏的怪兽的等级×300点的生存点数。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105305', '千禧卡之10', '自己的阵地上有3只拉克达时，如果将其中的2只作为贡品，就可抽出3张卡片。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105306', '千禧卡之11', '根据对方所控制的卡片效果，将此卡从纸牌送到墓地时，将减少对方2000点的生存点数。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105307', '千禧卡之12', '恐龙族中最强劲的卡片，两个头能够同时攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SP401090', '燃烧人 使比库特', '每到一处地方，都带着熊熊烈火的燃烧人，四处寻找对手，并与之一决高下。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SP401091', '被奴役的佳义兽', '被奴役的恶魔族战士，总在寻找时机逃脱，对奴役它的敌人进行恐怖的报复。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SP401093', '拼装组合', '此牌只要存在场上的正面，不能发动陷阱卡，场上所有的陷阱卡都变为无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SP401098', '第四次元战士', '来自未知的第四次元空间，身上长着一对媲美鹰的大翅膀，音速般的飞行速度，让其常常大胜而归。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SP401099', '邪恶的机械兽', '手持双卫击炮的兽战士，以敏捷的身手发动的攻击威力十分惊人。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SP401069', '迷惑烟雾', '住在密林里的美丽精灵，能让手上的烟释放浓密的烟雾使敌人视线模糊，再将它们一一解决。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SP401070', '魔鬼的刀斧', '沉睡魔鬼的刀斧，一旦被主人唤醒，能发挥无法想象的威力。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SP401072', '光之战士·奥发', '勇敢的正义神战士，挥剑速度有如音速一般的快，由于心中的强烈正义感。对一切邪恶的攻击毫不留情。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SP401074', '坚不可摧', '只要这张卡片还存在，就可让指定的一只怪兽无法攻击也无法变更显示形式。当指定的怪物被破坏时，此卡也会破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SP401077', '森林之子玛洛', '居住在野兽出没的森林里，以神秘的魔法控制野兽，平时性格十分温和，一旦破坏它的宁静，就会毫不留情的攻击你。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SP401079', '海神的坐骑', '当「海神的坐骑」以正面状态留在场上时，所有水族怪兽将不会成为魔法卡的目标。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SP401081', '前锋机械战将', '巨大的机械枪已经成为身体的一部分，善战的个性，总在战斗时冲锋陷阵，快速取得胜利。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SP401089', '野蛮的鲸怪', '借着「光之宫殿」唤出，需牺牲手中或场上星星数合计8个以上的怪兽卡才能召唤，
INSERT INTO "texts" VALUES ('SP401970', '迷失方向的幼龟', '在深山里游荡，寻找出口的幼龟，身上的尖刺是它最好的防御武器。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SP401092', '重装出击', '有着一身精湛剑术的战士，能以极快的速度将敌人玩弄于股掌之间，再以精准的剑术攻击敌人。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SP401095', '蛮撞的铁牛', '性格暴躁的铁牛，力大无比，能在一瞬间以比风还快的速度向敌人发起攻击，让敌人防不胜防。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SP401096', '顽强的牛头战士', '凭着自身的蛮力所向无敌，即使被打倒了，还是能再站起来重新比赛。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SP401100', '千里眼·赤帕加娃', '两只巨大的眼镜能看见千里以外的东西，逃脱功夫一流，让敌人产生一闪而过的幻觉。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SP401078', '焰角兽', '火山王·亚夫斯西的跟随者，借着火山王的势力，导出挑衅生事，尖锐的火焰角能将任何东西挑起撕裂。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SP401080', '变异外星人', '将「变异外星人」翻面后，指定场上一只怪兽。只要「变异外星人」还留在场上，该怪兽将无法进行攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SP401085', '书与夜', '潜伏在书与夜间的空隙中，从背后偷袭敌人，不光明的攻击让它取得战利品。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SP401087', '划破长空的怒吼', '·当此卡在战斗中破坏敌方怪兽 并将其送往墓地，敌方玩家将受到500点的伤害。
INSERT INTO "texts" VALUES ('SP401088', '来自黑暗的阿萨斯', '从场上或手牌里献出星星数合计8个以上的3张卡片作为祭品，破坏对手场上2只攻击力1800分以上的怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SP401101', '天使的衬衣', '光属性怪兽的攻击力上升700点，所有炎属性怪兽在战斗阶段终了时都将遭到破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SP401105', '千年禁锢笼', '此卡还存在场上时，对手场上所有的魔法卡不能发动，回合终了时，对手选择两张魔法卡送往墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SP401097', '控制思想', '敌方以怪兽攻击时，可以抵消其攻击并立刻获得一只没有参与攻击的正面显示状态怪兽的控制权，在战斗终了后该怪兽的控制权将交还给敌方控制。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SP401104', '镜面反射', '当对手发动攻击时启用，将对己方为对象的攻击直接转移给对方，对手将受到攻击力×2的伤害点数，当此卡还存在场上时，对手对己方的攻击无效化。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SP401109', '无形的墙壁', '对手发动攻击后启动，对手对我方的攻击无效化，此卡被攻击3次后被破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK90029', '强化战车', '拥有可以抵挡千斤重击的铠甲。被它碾过的东西都会粉碎。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK90030', '同胞之绊', '同胞之绊召唤时，支付1000点LP，就可以从卡牌中召唤出同种族四星以下的两只怪兽上场进行攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('WDK00002', '骸骨兽', '到处出没的骸骨怪兽，攻击力虽弱但若聚集在一起就不得了了。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('WDK00004', '蚕食尸体的龙', '蚕食腐肉的凶暴且凶恶的恐龙。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('WDK00009', '印普', '来自魔界的下级恶魔。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('WDK00063', '蘑菇人', '徘徊在森林中的不可思议的蘑菇人。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK90221', '双筒炮盔甲战士', '在手中牌只有这一张时，可以用这张牌在手中牌里进行特殊召唤。在用这张牌进行召唤、反转召唤、特殊召唤成功时，在自己的领地上和手中牌里每有其他的牌时，可以从底牌抽取2张牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK90344', '水之妖精', '拥有来去自如的操纵水的力量。如果此卡在战斗中破坏送进墓地，给对方生命值造成300点的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK90345', '庞大的章鱼怪', '潜在深海中和海水融为一体出其不意的现身攻击，被他一击就足以致命。是深海中最狡猾的怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK90348', '吸血的拳士', '当此卡受到伤害时，可以从以下效果中选择一项发动：
INSERT INTO "texts" VALUES ('TSK90351', '小矮人-1', '如果有「小矮人」的怪兽存在场上，此卡的攻击力就会上涨200。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK90361', '玩偶舞者', '在我方攻击控制时，这张卡可以当做装备卡当做怪兽的武器。此卡不能单独使用。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK90362', '幸运天使', '传说被他的箭射中的人都会幸运一生。此在战斗场上时每一只天使族的怪兽攻击力上升500点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK90364', '往冥界的入口', '当此卡存在在场上时，恶魔族的怪兽攻击力和守备力各上升500点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK90365', '月光兽', '「火炎的战士」融合材料之一。在夜晚才会出来猎食，是非常残暴的猛兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK90367', '招灵法师', '据说它很擅长招灵之术，总是招很多恶灵来帮它做一些坏事。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK90370', '地狱的法师尊者', '必须靠「八卦之器」才能降临，必须从场地或手牌中，献上星星数合计7个以上的祭品才能召唤。与其它的仪式怪物相比能力也不差。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK90371', '无脸人', '是「魔法守护者」融合材料之一。当此卡被送往墓地时，敌方须从我方墓地中选出一张卡，放置我方牌组的最上方。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00197', '绿野骑士', '在召唤出这张怪兽时可指定一个种族。在绿野骑士与该种族怪兽进行战斗时，在伤害计算阶段中绿野骑士的攻击力可以提升1000点。对于限定种族的套牌有绝大的威力。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00207', '战士·布鲁士', '当此牌作为贡品，破坏牌堆上的一只怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00209', '恶魔宫殿', '可以破坏场上任意两张具有抵消陷阱能力的卡片。提高恶魔族的攻守能力各800点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00213', '迷你蜈蚣', '将此牌送到墓地时，自己可增加300点生命点数。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00217', '封印的魔法箱', '自己的卡被消除了7张的时候可以发动。破坏存在于赛场上的所有怪兽卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00219', '钢之化身', '这张卡在与光属性怪物战斗时，在计算时攻击力增加1000分。魔法卡对它的攻击发动无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00221', '独角飞鹰兽', '倒退：牌堆上的2张魔法、陷阱牌返回到主人的手牌里。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00222', '孤独的甲壳虫', '居住在深山里的虫怪兽。有着坚硬的背，小心它锋利的爪子！', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00230', '独角黄金龙', '威力无穷的独角龙，有着又长又尖的须和下巴。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00231', '千年树妖的战斗', '此卡片的攻击力为自己墓地存在的怪兽卡数×300的数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00234', '牛面兽', '手持有刀斧的牛面兽，总是寻找机会逃脱，对攻击它的敌人进行恐怖的袭击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00235', '空幻骑士', '整天骑在怪物身上的它，威力一般，但潜在力量很强大。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00238', '王家的圣殿', '当自己或者对方发动魔法卡的时候给此卡一个魔力指数。当给了第四个魔力指数破坏此卡，这时发动魔法的那一方就受到1000的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00240', '魔法师·托拉司', '当此卡对对方玩家造成损伤时，对方要丢弃一张手牌。虽然攻击力不高，但是能让对方丢弃手牌的能力却非常好用。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00245', '孔翟天使', '对手攻击过来的攻击力道，有一次可变成0，玩家自行发动时机。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00250', '冥界魔师哈迪', '场上每存在一张正面显示的魔法使用族卡，此卡片的攻击力就会上升1000点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00251', '被封印的女孩', '攻击此卡的怪兽将被放回控制者手中，但本方损伤点数仍需计算。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00253', '火焰人-使特', '每到一处地方，都带着熊熊烈火的燃烧人，四处寻找对手，并与之一决高下。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00256', '愤怒的小树妖', '复活；从自己的底牌选一张装备魔法卡加入手中。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00258', '粗暴鳄', '在粗暴鳄翻面后，将敌方场上的一只怪兽送回拥有者的手牌中。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00259', '携手作战', '当“携手作战”翻至正面后，每一张墓地内的战士族卡的攻击力可提升100点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00263', '吞噬生命的龙', '从自己的领地上或者墓地，把根据融合怪物牌决定的怪兽从游戏中除去，把一只龙族的融合怪兽从融合底牌中进行特殊召唤。（这个特殊召唤为融合召唤。）', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00265', '恶魔飞龙', '它能零区域上的“千年树妖”的攻击力、守备力提升800点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00267', '特殊的对手', '对手的战场上与墓地中每有一个龙族怪兽，这张卡片的攻击力就增加500点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00273', '弯刀女战士', '当此卡片翻到正面时，全场内若是有2张以上的魔法，陷阱卡片以背面显示，则可选择2张加以破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00274', '守护者·西鲁', '反转：使自己的牌堆拿一张有「守护者」文字的卡片放入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00275', '豌豆战士', '每当自己的墓地里将两张水属性怪兽从游戏中剔除，就能特殊召唤在自己场上叫出一只攻击显示的「豌豆战士」的复制体。可以作为植物族的主力怪兽运用。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00342', '磷龙之突击', '表侧表示怪兽时，若这张卡的攻击力超过守备表示怪兽的守备力，给予对方基本分那个数值的战斗伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00355', '鬼盔之武者', '成功召唤出「鬼盔之武者」后，可从手牌中召唤出特殊召唤出一只「鬼盔之女王」到场上。此卡可直接攻击对方玩家。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00358', '人鱼儿', '多了人的手脚更让它在陆地和水里来去自如。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00370', '沉没的小船', '只要此卡以正面状态存在场上，所有陷阱的效果都会被抵消。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00371', '地狱之门', '每当自己怪兽被送往墓地时就可以发动，能将场上一只怪兽加以破坏，还对对手造成200点损伤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00376', '岩石魔', '巨大坚硬的身本。他去到之处必定地动山摇。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00384', '变种螳螂', '当此卡因战斗被送进墓地时，可从牌组里召唤一攻击力1500以下的昆虫族的怪兽到场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00385', '惊恐的妖猫', '当此卡被遭到战斗破坏时，可以选择敌方场上一张魔法或陷阱卡丢到墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00388', '铜人', '「火炎的战士」融合材料之一。据说力大无比能熟练使用各种武器。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00392', '发狂的战士', '当发狂的战士攻击敌方时，不须计算伤害就直接破坏该怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00394', '落难的公主', '如果受到敌方的攻击，可以将攻击转移到我方其它怪兽身上，在进行伤害计算。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00401', '神圣之火', '只要从场上或手牌里献上星星数合计10个以上的卡片做为祭品，任何仪式卡都可以进行仪式召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00403', '猎鹰之遥望', '能观看敌方的一张盖牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00404', '远射', '在一回合当有人使用陷阱卡时就可发动，该回合内能让场上的所有陷阱效果全部失效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00406', '白龙展翅', '将我方场上的一只等级五以上龙族怪兽收回手牌中后，可以破坏掉双方场上的所有魔法与陷阱卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00414', '宝石的能量', '支付300点生命值，能让的怪兽的攻击力或守备力上升500点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('TSK00421', '通往暗界之路', '只要这张卡存在，除了暗属性的怪兽以外其他的怪兽都不能进行攻击宣言。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
