INSERT INTO "texts" VALUES ('SOD00111', '复制龙', '当玩家成功召唤时，才能召唤，并能变成被召唤出来的怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
