INSERT INTO "texts" VALUES ('ZZ105373', '黑魔导女孩', '①：这张卡的攻击力上升双方墓地的「黑魔术师」「黑混沌之魔术师」数量×300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105374', '电子天龙头', '这张卡不能通常召唤。把我方场上以及墓地存在的机械族怪兽全部从游戏中除外才能特殊召唤。这张卡的攻击力、守备力变成这张卡的特殊召唤时从游戏中除外的怪兽数量×1000点的数值。这张卡特殊召唤成功时，可以破坏对方场上所有怪兽，对方受到那些怪兽攻击力的生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
