INSERT INTO "texts" VALUES ('ZZ105402', '真红眼黑龙', '拥有真红之眼的黑龙。愤怒的黑炎会把映入其眼者全部烧成灰烬。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105403', '真红眼黑重钢龙', '这张卡不能通常召唤，用把5星以上的龙族怪兽解放发动的「金属化·强化反射装甲」的效果可以特殊召唤。这个卡名的①②的效果1回合各能使用1次。
INSERT INTO "texts" VALUES ('ZZ105404', '真红眼黑钢龙', '这张卡不能通常召唤。把有「金属化·魔法反射装甲」装备的自己场上1只「真红眼黑龙」解放的场合可以从卡组特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105405', '真红眼的凶星龙-流星之龙', '①：这张卡只要在场上·墓地存在，当作通常怪兽使用。
INSERT INTO "texts" VALUES ('ZZ100638', '同调看守者', '发生效果伤害时，可以将那个伤害无效，手牌这张卡和墓地1只协调怪兽从游戏中除外，从额外卡组特殊召唤1只等级与这个效果除外怪兽等级合计数值相同的同步怪兽。这个效果特殊召唤的怪兽效果无效化。这个特殊召唤当作同步召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100642', '伪守卫者', '对手直接攻击宣言时，这张卡可以从墓地以表侧守备表示特殊召唤。这个方法特殊召唤的场合，这张卡从场上离开时从游戏中除外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100776', '波动之壁', '可以无效等同自己场上存在的同调怪兽数量的对手怪兽的攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ100783', '平衡射手', '自己场上存在的1只怪兽的攻击力因卡的效果下降的场合怪兽的攻击力不变化，给予对手玩家变化数值的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105406', '再生战士', '这张卡从手牌送入墓地的场合，可以在自己场上特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105407', '侦查战士', '这张卡因为魔法、陷阱、效果怪兽的效果加入手牌时，可以在自己场上特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105408', '同调信奉者', '自己场上存在的同步怪兽被对手怪兽选作攻击对象时，那个战斗无效，这张卡可以从手牌特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105409', '潜行巨人', '自己场上没有怪兽存在，对手场上存在怪兽的场合，可以通过特殊召唤墓地1只等级1的怪兽使这张卡不需解放召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105410', '仲裁的裁定者', '自己场上存在的卡在战斗阶段里被破坏的场合，可以通过将手牌的这张卡送入墓地来结束战斗阶段。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105411', '苍穹隼', '这张卡召唤成功时，可以特殊召唤手牌1只等级4以下的龙族怪兽。这张卡作为同步素材时，只能用于风属性怪兽的同步召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105413', '马赫同调士', '这张卡作为同步素材送入墓地时，将这张卡以外的1只作为同步素材使用的怪兽返回手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105414', '希望的转生', '舍弃2张手牌。2回合后自己的准备阶段选择卡组1张怪兽卡加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105415', '爆裂同步召唤', '发动回合，对手怪兽的效果伤害只有1次变为0。可以从自己的额外卡组无视召唤条件特殊召唤1只持有与用这个效果变为0的效果伤害相同数值的攻击力的同步怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105417', '链箭', '选择场上存在的1只怪兽发动。选择的1只怪兽的攻击力只在伤害计算时上升500点。选择的怪物用战斗破坏对手怪兽的场合，直到这个回合的结束阶段时，对方场上的1只怪兽的攻击力下降1000点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105421', '次元航行', '尽可能选择从游戏中除外的同步怪兽在自己场上特殊召唤。这个效果特殊召唤的同步怪兽的效果无效化，也不能攻击。此外 ，那些怪兽在结束阶段时从游戏中除外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105422', '炸裂突破', '自己场上只存在1只怪兽的场合可以发动。自己场上存在的1只怪兽战斗破坏对手等级8以上的怪兽送入墓地的场合，那只怪兽攻击力下降800点，在战斗阶段中可以接着发动仅1次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105423', '减半护盾', '因对手1只怪兽发生的战斗伤害或者效果伤害减半。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105424', '调和的结晶', '将这个回合破坏送入墓地的包含同步怪兽的2只怪兽从自己的墓地除外发动。自己墓地存在的1只同步怪兽在自己场上特殊召唤，给予对手LP那只怪兽攻击力一半数值的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105425', '铁之决心', '支付自己的一半LP发动。这个回合，因战斗发生的对自己造成的战斗伤害变为0。之后，结束战斗阶段。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105426', '连接未来', '将1张手牌送入墓地发动。对手的魔法、陷阱卡的发动无效。那个时候发动无效的卡返回卡组洗切。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105427', '恐慌波动', '将自己场上存在的1张卡破坏发动。这个回合，场上以表侧表示存在的全部魔法、陷阱、效果怪兽的效果无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105428', '兑现防守', '选择自己场上存在的原守备力比原攻击力高的攻击表示怪兽发动。那只怪兽变为守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105429', '反射护罩', '自己受到效果伤害时可以发动。给予对手LP那个数值的伤害作为代替。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105430', '冲击复活', '对手怪兽攻击宣言时可以发动。这个战斗里自己受到的战斗伤害减半。战斗伤害计算后，从自己的墓地特殊召唤1只持有受到的战斗伤害数值以下的攻击力的怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105431', '车后气流', '自己场上的「高速世界」放置的高速指示物比对手的少的场合，对手使用名字带有「Sp」的魔法卡时可以发动。这张卡发动的下个回合的准备阶段时，自己场上的「高速世界」放置的高速指示物的数量变为与对手的相同。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105432', '星之移位', '选择自己场上表侧表示存在的1只同步怪兽发动。选择的怪兽返回额外卡组。那之后，从额外卡组选择1只与返回怪兽等级相同名字不同的同步怪兽特殊召唤。这个效果特殊召唤的同步怪兽的效果无效化。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105433', '固定之力', '支付1000LP，这个回合自己场上存在的1只怪兽的「结束阶段时从场上离开的效果」无效化。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105434', '孤高的守人', '发动后这张卡作为装备卡，装备自己场上存在的1只怪兽。只在对手回合里，与装备怪兽以外的战斗伤害变为0。装备怪兽因战斗破坏的场合，这张卡破坏作为代替。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105435', '同步破坏者', '自己场上的同步怪兽战斗破坏对手场上的怪兽时，给予对手LP被破坏怪兽攻击力一半数值的伤害。被破坏的对手怪兽是同步怪兽的场合，再给予对手LP被破坏怪兽攻击力一半数值的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105436', '同步离场', '自己场上存在的1只同步怪兽返回额外卡组。之后，如果返回额外卡组的同步怪兽的同步召唤时使用的一组同步素材怪兽在自己的墓地齐集，可以将那一组怪兽在自己的场上特殊召唤。用这个效果特殊召唤的怪兽这个回合的结束阶段时送入墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105437', '同步光环', '1只同调怪兽用战斗没有破坏对手怪兽时，那1只同调怪兽的攻击力直到结束阶段时变为2倍且可以再攻击1次。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105438', '同步强击装置', '发动后这张卡当作使攻击力上升1000点的装备卡，装备自己场上存在的1只同调怪兽。每次自己回合的结束阶段时装备怪兽的攻击力下降800点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105439', '协调炸弹', '将自己场上存在的任意数量的调整怪兽破坏。对手场上与因这个效果破坏的怪兽数量相等的怪兽破坏，破坏的对手怪兽每有1只给予对手1000点的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105440', '波动回弹', '这个回合「同调怪兽从墓地特殊召唤的效果」无效化，给予对手LP那些同调怪兽攻击力数值的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105441', '哈耳摩尼亚之镜', '对手用同调召唤以外的方法特殊召唤同调怪兽时，得到那只怪兽的操作权。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105442', '复仇归来', '怪兽被战斗破坏时可以发动。抽1张卡。将墓地这张卡除外发动。特殊召唤这个回合因卡的效果破坏送入墓地的1只怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105443', '同调护罩力', '自己场上存在同调怪兽时可以发动。将破坏场上的卡的效果无效化。那之后，自己场上存在的同调怪兽每有1只给予对手LP500点伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105444', '星斗偏移', '对手回合的战斗阶段中自己场上存在的1只同调怪兽被对手同调怪兽攻击时可以发动。战斗的双方怪兽从游戏中除外，数对手回合3回合后的战斗阶段结束时在双方场上特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105445', '高与低', '对手怪兽攻击时，以成为攻击对象的自己场上1只怪兽发动以下效果：●确认自己卡组顶端1张卡送入墓地。那张卡是怪兽卡的场合，对象怪兽攻击力上升那只怪兽的攻击力部分的数值。这个效果可以任意发动至最多3回。对象怪兽攻击力高过对手攻击怪兽的场合，对象怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105446', '陨石流', '被解放了的怪兽在场上特殊召唤时，给予那只怪兽的操作者1000点伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105447', '复活票', '自己场上存在的怪兽被战斗破坏时，被战斗破坏的怪兽每有1只，将自己的魔法陷阱卡区域存在的1张卡破坏发动。这个回合，被战斗破坏而在墓地存在的怪兽全部在场上特殊召唤，恢复这个回合战斗发生的战斗伤害的合计分的自己LP。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105448', '上升突击', '对手玩家因卡的效果受到伤害时可以发动。从自己的手牌特殊召唤1只调整怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105449', '同调接力', '选择自己场上存在的1只同调怪兽发动。自己的墓地每存在1只同调怪兽选择的1只同调怪兽的攻击力上升600点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105450', '陨石波', '发动的回合，自己场上表侧表示存在的1只同调怪兽的攻击力上升300点。受到这个效果的怪兽攻击守备表示的怪兽时，若攻击力超过那只怪兽的守备力，给予对手LP超过数值的战斗伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105451', '欺骗同调', '选择自己额外卡组存在的1只同步怪兽送入墓地。选择的怪兽的同步素材怪兽在自己场上齐集的场合，那些怪兽以外的1只怪兽的攻击力直到这个回合的结束阶段时上升选择送入墓地的那1只同步怪兽的攻击力的一半的数值。用这个效果攻击力上升的怪兽以外的怪兽这个回合不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105452', '波动之力', '自己场上存在的1只同步怪兽成为对手怪兽的攻击对象时可以发动。对手场上存在的攻击表示的怪兽全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105453', '同调超界限', '自己回合的战斗阶段时可以发动。这个回合战斗破坏了对手怪兽的1只同步怪兽在战斗阶段里可以再攻击1次。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105454', '返回标记', '对手怪兽的效果造成的伤害或者破坏效果无效。之后，给予对手LP那只怪兽的攻击力数值的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105455', '技能转嫁', '以场上的1只怪兽作为对象发动的对手怪兽的效果转移到别的正确的对象上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105456', '力量转移', '选择自己场上表侧表示存在的1只怪兽发动。直到这个回合的结束阶段，选择的怪兽攻击力变为0。选择的怪兽这个回合被破坏的场合，从卡组抽1张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105457', '计镜像', '对手发动陷阱卡时可以发动。将那个效果作为这张卡的效果发动作为代替。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105458', '逆转的明牌', '对手抽卡阶段以外将卡加入手牌时，自己抽卡直到手牌与对手手牌数目相同。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105459', '往觉醒的飞跃', '自己场上有怪兽召唤时，选择那只怪兽以外的自己场上存在的1只怪兽发动。选择的怪兽从游戏中除外，给予对手LP那只怪兽的等级×100点的伤害。因发动这个效果除外的怪兽在下个回合的准备阶段时，攻击力上升等级数×100点回到自己场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105460', '同步日珥', '场上存在同步怪兽的场合，那些怪兽的操作者给予对手1000点的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105461', '希望的碎片', '自己场上的怪兽给予对手玩家战斗伤害时，从自己的卡组抽1张卡。抽到的卡是陷阱卡的场合，这张卡破坏并送入墓地后从手牌发动那张陷阱卡。（不满足发动条件的场合，抽到的陷阱卡破坏并送入墓地。）并且，抽到的卡是陷阱卡以外的卡的场合，抽到的卡破坏并送入墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105462', '未来之战', '只能在自己的战斗阶段中发动。选择自己场上存在的1只怪兽，从对手卡组上方翻开1张卡。翻开的卡是怪兽卡的场合，那只怪兽以攻击表示在对手场上特殊召唤，强制与选择了的自己的怪兽进行战斗。对手的怪兽被这个战斗破坏的场合，这张卡的效果可以再次使用。翻开的卡是怪兽卡以外的卡的场合，这张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105463', '狂食召唤', '特殊召唤这个回合破坏送入墓地的1只同步怪兽，并将这张卡作为装备卡装备。此外，可以舍弃1张手牌，特殊召唤自己墓地1只同步怪兽。此时，自己LP受到这个效果特殊召唤的同步怪兽攻击力数值的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105464', '困苦', '这张卡发动后变为装备卡装备给自己场上表侧表示存在的1只怪兽。装备怪兽的攻击力与守备力变为0。这回合，1只对手怪兽给予的效果伤害变为0。装备怪兽从场上离开的场合，这张卡破坏。可以将这张卡送入墓地，破坏装备怪兽。这时，场上存在的所有装备卡破坏送入墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105465', '怪兽链', '这张卡发动时在这张卡上放置与自己场上怪兽数目相同的链指示物。对手的结束阶段时这张卡上放置的链指示物取除1个。没有放置链指示物的这张卡破坏。只要这张卡在场上表侧表示存在，双方玩家不能宣言攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105466', '召唤代偿', '怪兽召唤、特殊召唤成功时，那个玩家受到那只怪兽的攻击力一半数值的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105467', '同步爆破', '自己场上存在的同调怪兽攻击宣言时，战斗伤害计算后给予对手玩家500点伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105468', '信赖连锁', '选择自己场上1只怪兽发动。选择的怪兽的攻击力上升自己场上存在的其他同调怪兽的攻击力之和的数值。可以破坏这张卡，结束战斗阶段。只要这张卡在场上表侧表示存在，同调怪兽不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105469', '革命－特技之战', '攻击表示的两只怪兽战斗时，将攻击力较高的怪兽破坏（不进行伤害计算），这个效果破坏视为战斗破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105470', '跋涉之魂', '可以将自己场上攻击表示存在的怪兽的战斗破坏无效。这个效果使用的场合，战斗破坏无效了的怪兽的攻击力下降800点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105471', '防护外层', '当对方场上攻击表示召唤、反转召唤、特殊召唤比自己场上存在的表侧守备表示的怪兽的守备力高的攻击力的怪兽时发动。自己场上的守备表示的怪兽的守备力变为2倍。这张卡发动的2个回合后的自己的准备阶段破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105472', '空间跳跃', '自己回合的战斗阶段中因对手的卡的效果怪兽被破坏或除外的场合可以发动。成为对象的1只怪兽从游戏中除外，给予对手的LP那只怪兽的攻击力数值的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105473', '瓦砾之王', '当自己墓地存在30张以上的卡的时候，自己可以从手牌中发动陷阱卡，这个效果一回合只能发动一次。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105474', '高速世界', '每次自己发动「高速魔法」以外的魔法卡时受到2000生命值伤害。双方玩家在每次双方的准备阶段时在这张卡上放置一个高速指示物（最多12个）。自己受到1000点倍数的基本分伤害时，此卡的高速指示物减少那个倍数。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105475', '高速世界2', '每次自己发动「高速魔法」以外的魔法卡时受到2000生命值伤害。双方玩家在每次双方的准备阶段，自己的高速指示物放置1个在这张卡上（最多12个）。玩家在自己的回合可以使用以下效果：●去除4个高速指示物，自己手上每有一张「高速魔法」魔法卡，给予对手800点的伤害。●去除7个高速指示物，从卡组里抽一张卡。●去除10个高速指示物，破坏场上的一张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105476', '妖化猫', '这张卡用「怪猫变化」的效果才能特殊召唤。这张卡特殊召唤成功时，对方场上4星以下的怪兽全部破坏，给与对方破坏怪兽数量×800伤害。1回合1次，可以从卡组·墓地把1只「遗弃猫」加入手卡。
INSERT INTO "texts" VALUES ('ZZ105477', '遗弃猫', '这张卡在场上表侧攻击表示存在，对方不能选择这张卡以外的怪兽作为攻击对象。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105478', '遗弃猫娘', '只要这张卡在场上表侧攻击表示存在，这张卡不会被战斗破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105479', '双尾猫女郎', '1星怪兽×3 
INSERT INTO "texts" VALUES ('ZZ105480', '猫咪女孩魔法师', '4星怪兽×2 
INSERT INTO "texts" VALUES ('ZZ105481', '猫邀请', '从卡组把1张名字带有「猫」或「猫咪」的卡加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105482', '猫集会', '名字带有「猫」或「猫咪」的怪兽通常召唤成功时，可以从手卡把1只3星以下的名字带有「猫」或「猫咪」的怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105483', '木天蓼涡轮', '自己场上名字带有「猫」或「猫咪」的怪兽才能装备。装备怪兽的攻击力上升1200点。装备怪兽不能向对方怪兽攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105484', '猫粮', '把自己场上1只「遗弃猫」解放，从自己的手卡·卡组·墓地把1只「遗弃猫娘」攻击表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105485', '反击猫拳', '自己的陷阱卡被破坏时才能发动。选择对方场上1张魔法·陷阱卡破坏。自己场上1只名字带有「猫」或「猫咪」的怪兽的攻击力直到结束阶段时变成2倍。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105486', '怪猫变化', '自己场上存在的1只「遗弃猫」被战斗破坏时才能发动。从自己卡组·手卡·墓地把1只「妖化猫」特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105487', '猫世界', '场上名字带有「猫」或「猫咪」的怪兽的攻击力上升那个原本攻击力的数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105489', '给猫金币', '自己场上的1只兽族怪兽成为对方怪兽的攻击对象时才能发动。成为攻击对象的怪兽的攻击力只在伤害步骤上升对方1只攻击怪兽的攻击力一半的数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105490', '奥利哈钢 魔弓牛战士', '此卡只能献祭2只等级4以下冠有「奥利哈钢」之名的怪兽来特殊召唤。
INSERT INTO "texts" VALUES ('ZZ105491', 'ENDDD', '这个卡名的卡1回合只能发动1张。自己场上没有「DD」卡·「契约书」卡以外的卡存在的场合，这张卡的发动从手卡也能用。
INSERT INTO "texts" VALUES ('ZZ105492', 'DDD 不屈王 赫拉克勒斯', '「DD」调整＋调整以外的怪兽1只以上
INSERT INTO "texts" VALUES ('ZZ105493', '灵龙星-睚眦', '这个卡名在规则上也当作「精灵兽」卡使用。自己对「灵龙星-睚眦」1回合只能有1次特殊召唤。
INSERT INTO "texts" VALUES ('ZZ105494', '阴影化身', '这个卡名的①的效果1回合只能使用1次。
INSERT INTO "texts" VALUES ('ZZ105495', '燃烧拳击手 晨星之帝环拳士', '这个卡名的①②的效果1回合各能使用1次。
INSERT INTO "texts" VALUES ('ZZ105496', '时空之银河眼使', '这个卡名的①②的效果1回合各能使用1次。
INSERT INTO "texts" VALUES ('ZZ105497', '三重犬', '这张卡在自己场上以表侧表示存在的场合，可以从自己的手牌特殊召唤1只「三重犬」。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105498', '相扑狗王', '兽族4星怪兽×3 
INSERT INTO "texts" VALUES ('ZZ105499', '双重犬', '自己场上有2只「三重犬」表侧表示存在的场合可以发动。从卡组特殊召唤1只「三重犬」。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105500', '汪汪二人组', '在自己场上特殊召唤２只「汪汪二人组衍生物」（兽族·地·１星·攻／守０）。这些衍生物在这个回合的结束阶段时破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105501', '汪汪大军', '自己场上没有等级３以上的怪兽存在的场合，
INSERT INTO "texts" VALUES ('ZZ105502', '狗王对接', '只能装备攻击表示的名字带有「犬」或「狗」的怪兽。自己场上的兽族怪兽每有1只，装备怪兽的攻击力上升500点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105503', '孤高的远吠', '将自己场上以表侧表示存在的１张装备魔法卡破坏发动。这个回合的伤害计算时，场上全部怪兽的攻击力变为原本的数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105504', '千针骨', '反转：给予对手玩家400点的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105505', '里长臂猿', '反转：对手场上存在的１只守备表示的怪兽的表示形式变更为攻击表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105507', '里虎Ｃ', '对手场上有「宝贝虎龙」被超量召唤时，可以从对手的额外卡组将１只多维怪兽在自己场上特殊召唤，并装备这张卡。
INSERT INTO "texts" VALUES ('ZZ105508', '里雾', '对手场上有怪兽特殊召唤时可以发动。得到那１只怪兽的操作权。这张卡不在场上存在时那只怪兽的操作权返还对手。那只怪兽的操作权转移给对手时，这张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105509', '上弦弹射器', '自己回合的准备阶段时，这张卡放置1个上弦指示物。可以将这张卡上的1个上弦指示物取除，自己1只怪兽的攻击力直到结束阶段时上升500点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105511', '弹簧拳', '只能装备机械族怪兽。装备怪兽攻击力上升时，给予对手玩家LP装备怪兽攻击力一半数值的伤害。发动这个效果的回合，战斗阶段跳过。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105512', '上弦炸弹', '自己场上上弦指示物增加的场合可以发动。给予对手自己场上存在的上弦指示物数目×800点的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105513', '调试人X', '这张卡召唤成功时自己场上存在表侧表示的「调试人Y」的场合，可以从自己的卡组特殊召唤1只「调试人Z」。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105514', '调试人Y', '这张卡召唤成功时自己场上存在表侧表示的「调试人Z」的场合，可以从自己的卡组特殊召唤1只「调试人X」。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105515', '调试人Z', '这张卡召唤成功时自己场上存在表侧表示的「调试人X」的场合，可以从自己的卡组特殊召唤1只「调试人Y」。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105516', '苏碧莉雅', '艾西斯神官的精灵，擅长侦查。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105517', '幻想魔术师', '马哈德的精灵，黑色的魔法袍下无人知道其真实面目。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105518', '献身的爱', '对手的战斗阶段中才能发动。使战斗阶段结束，然后对手抽1张卡。这个回合的结束阶段时自己的基本分变成0。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105519', '升级', '将自己场上的1只超量怪兽解放发动。特殊召唤自己墓地的1只超量怪兽。用这个效果特殊召唤的怪兽不会被卡的效果破坏，攻击力上升解放的怪兽的阶级×100。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105520', '宇宙非常食', '自己场上存在1只「异次元超能人·星斗罗宾」时可以发动。从卡组抽2张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105521', '极限死亡咒印', '装备怪兽的表示形式不能变更，不会被魔法、陷阱、怪兽效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105522', '变换！ 喷射机钢铁号', '将自己场上存在的「异次元超能人·星斗罗宾」「野兽战士 豹人」「凤王兽 铠楼罗」「铁巨人 大铁锤」各1只解放，从卡组、手牌、墓地特殊召唤1只「异次元喷气机·大铁号」。
INSERT INTO "texts" VALUES ('ZZ105523', '星之罗宾永在！', '对手怪兽宣言攻击时可以发动。自己墓地存在的1只「异次元超能人·星斗罗宾」以攻击力0的形式在自己场上表侧攻击表示特殊召唤。对手的攻击对象转移到这张卡特殊召唤的怪兽上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105524', '三人组护罩', '手牌里有3只「三连星之特利恩」的场合对手怪兽攻击宣言时可以发动。可以将那1只怪兽变为守备表示，从手牌特殊召唤3只「三连星之特利恩」。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105525', '团结之翼', '自己场上存在表侧表示的「异次元超能人·星斗罗宾」，对手怪兽宣言攻击时可以发动。对手1只怪兽的攻击无效化，从自己卡组特殊召唤1只「凤王兽 铠楼罗」。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105526', '怒目冰山龙', '这张卡通常召唤成功时，对手的1只攻击表示怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105527', '火山灰', '自己场上存在的1只怪兽变为守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105528', '灼热之渊', '受到效果伤害时可以发到。确认对手的手牌，有怪兽卡的场合，那张卡返回卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105529', '强制变移', '以自己场上存在的1只怪兽为对象发动的对手的陷阱效果的对象，变更为自己场上存在的别的1只怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105530', '间谍出击', '将手牌1只怪兽送入墓地发动。确认对手1张盖伏的魔法陷阱卡，之后将其原样盖伏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105531', '橙色萨满', '对方成功召唤·特殊召唤效果怪兽时，可以从手卡特殊召唤1只名字带有「萨满」的怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105532', '红色萨满', '对方发动陷阱卡时，可以从手卡特殊召唤1只名字带有「萨满」的怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105533', '绿色萨满', '对方发动魔法卡时，可以从手卡特殊召唤1只名字带有「萨满」的怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105534', '虹色萨满', '对方场上有超量怪兽存在，自己场上不存在怪兽的场合，这张卡可以从手卡特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105535', '萨满呼唤', '自己场上有表侧表示存在的攻击力0的魔法师族怪兽2只以上的场合可以发动。从卡组把1只名字带有「萨满」的怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105536', '多维植物', '选择自己场上1只怪兽发动。这张卡当作与选择的怪兽种族、属性、等级相同，攻击力、守备力0的怪兽在怪兽区特殊召唤（这张卡也当作魔法卡使用）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105537', '吊唁之舞', '双方玩家不能从墓地特殊召唤怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105538', '守护神之舞', '对手怪兽宣言攻击时可以发动。确认对手的1张手牌。那张卡是怪兽卡的场合，那个攻击无效，那张怪兽送入墓地。那之后，自己抽1张卡。是怪兽卡以外的卡的场合，那次攻击继续。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105539', '冰结之舞', '双方玩家不能从手牌召唤、特殊召唤、盖伏怪兽。这张卡在发动后的第二个对手的结束阶段时破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105540', '番茄骑兵', '这张卡被破坏送去墓地时，可以从自己的手卡·卡组把1只「番茄骑兵」在自己场上特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105541', '番茄王 红惧王', '3星怪兽×3 
INSERT INTO "texts" VALUES ('ZZ105542', '投射番茄', '把自己场上的1只植物族怪兽解放，给与对方基本分400点伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105543', '番茄矩阵', '自己场上存在的植物族怪兽的攻击力直到自己回合的结束阶段时上升500点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105544', '番茄乐园', '双方玩家对植物族怪兽召唤·反转召唤·特殊召唤成功时，把1只「番茄衍生物」（植物族·地·3星·攻/守0）在自己场上特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105545', '破旧机器人 壶袋鼠', '可以将自己场上这张卡送入墓地，将自己1次战斗伤害变为0。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105546', '破旧机器人 单车驼', '可以将自己场上这张卡送入墓地，将自己墓地1张名字带有「环保魔法」的卡返回手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105547', '破旧机器人 吸尘蛇', '可以将自己场上这张卡送入墓地，将自己墓地1只名字带有「破旧机器人」的怪兽返回手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105548', '破旧机器人 电脑猿', '可以将手牌这张卡送入墓地，自己场上名字带有「破旧机器人」的怪兽攻击力直到结束阶段时上升800点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105549', '回收机器犀牛', '机械族·地属性等级4怪兽×3
INSERT INTO "texts" VALUES ('ZZ105550', '环保魔法～别再浪费啦！～', '选择自己卡组2只名字带有「破旧机器人」的怪兽从游戏中除外。那之后，从卡组将1只名字带有「破旧机器人」的怪兽加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105551', '环保魔法～循环利用吧！～', '可以选择最多2只从游戏中除外的名字带有「破旧机器人」的怪兽在自己场上特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105552', '整地重机 压路机', '这张卡攻击过的对手怪兽在伤害计算后变为里侧守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105553', '掘削重机 大型挖土机', '这张卡从墓地特殊召唤成功时，这张卡的等级上升1。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105555', '拆除和建造', '从自己的墓地特殊召唤１只等级３以下的机械族怪兽。这个效果特殊召唤的怪兽在这个回合不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105556', '大检修', '自己场上存在的机械族怪兽全部等级上升1。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105557', '燃烧的男子赤魂', '选择自己场上存在的1只机械族怪兽发动。和选择了的怪兽进行战斗的怪兽的攻击力下降1000点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105558', '威风小丑', '这张卡进行战斗的场合，掷1次骰子。出现6的场合，进行战斗的对手怪兽破坏。6以外的场合，这张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105559', '掷骰者 赛文', '1回合1次，可以掷1次骰子。这张卡的等级直到结束阶段上升掷出点数相同的数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105560', '三条Ａ', '可以从自己手牌特殊召唤3张等级1的同名怪兽到自己场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105561', '梦幻骰', '掷1个骰子。掷出6点的场合，对手场上所有怪兽攻击力变为0。除此以外的场合，自己场上所有怪兽攻击力变为0。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105562', '解放变换', '将自己场上的1只怪兽解放，从手牌特殊召唤1只与解放的怪兽等级相同的怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105563', '倍倍游戏', '1回合1次，掷1回骰子。出现6的场合，自己的LP变为5倍。6以外的场合，自己的LP回到这张卡发动时的LP。此外，可以使这张卡的掷骰子效果无效，之后每次自己的准备阶段，自己受到1000点伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105566', '太阳的天秤', '1回合1次，掷1次骰子。出现6的场合，对手场上存在的怪兽全部破坏。6以外的场合，选择自己场上存在的1只怪兽破坏。这张卡被破坏送入墓地时，给予对手LP500点伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105567', '骰子危机', '对手场上存在的1只怪兽攻击宣言时可以发动。掷1次骰子。出现6的场合，这张卡变为对手的1只攻击怪兽的装备卡，那1只怪兽的攻击力变为０并得到其操作权。这张卡从场上离开时，装备怪兽的操作权交还持有者。装备怪兽从场上离开时，这张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105568', '丑闻狙击手', '这张卡给予对手LP战斗伤害时，这张卡的等级最多上升2，表示形式变为守备表示。（最多到等级12）', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105569', '滋事狗仔队', '可以将场上的这张卡做祭品，使自己场上的1只怪兽的等级上升2。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105570', '正片负片反转', '选择对手场上以里侧守备表示存在的1只怪兽发动。选择的怪兽的表示形式变成表侧攻击表示。之后，选择的怪兽的原攻击力、守备力交换。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105571', '多维定格', '下个回合，对手场上的超量怪兽以外的怪兽不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105572', '望远镜头', '装备怪兽的攻击力上升自己的手牌数×400点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105573', '修行王国 训练世界', '可以通过将手牌的2只怪兽送入墓地，可以将手牌的1只等级7以上的怪兽无解放召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105574', '火铳花', '自己场上以表侧攻击表示存在的这张卡被选择为攻击对象时，给予对手LP800点伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105575', '炮战花', '和这张卡进行战斗的对手怪兽的攻击力下降800点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105577', '花之裁决', '选择自己场上的1只植物族多维怪兽发动。将选择的怪兽的多维素材全部取除，选择的怪兽的攻击力上升取除的多维素材的数量×800点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105578', '枯山水', '水属性怪兽不能攻击。场上以表侧表示存在的植物族怪兽只有1只的场合，可以从手牌特殊召唤1只等级4以下的植物族怪兽。场上的多维怪兽的攻击力上升其阶级×100点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105579', '蔷薇墓标', '对手发动魔法陷阱卡时，给予对手LP300点伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105564', '言灵之乐', '只要这张卡在场上正面表示存在，可以选择对方场上1只怪兽，那只怪兽攻击力和守备力变为0，不能改变表示形式，不能当作祭品。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105565', '守护女战神', '反转：选择对方场上1只怪兽并得到此怪兽的控制权，此卡不会被战斗破坏，1回合1次不受对方魔法卡效果影响。当此卡被破坏时，被控制的怪兽回到对方场上，我方受到那只怪兽的攻击力数值的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105580', '邪恶地狱龙', '此卡可以直接攻击对方玩家，此卡直接攻击对方玩家造成生命值伤害时攻击力增加1000点，从卡组将1只8星以下的怪兽送入墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('SOD00114', '牺牲限制', '使双方在每回合中当作祭品的怪兽只能有一只。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105581', '裁决之矢', '①：「裁决之矢」在连接怪兽所连接区的自己魔法与陷阱区域只能有1张表侧表示存在。
INSERT INTO "texts" VALUES ('ZZ105582', '奥利哈钢 杰斯拉克', '当自己场上名字带有「奥利哈钢」的怪兽战斗时，可以将手牌中的卡送入墓地，选择对方1只怪兽破坏，我方场上的1只怪兽攻击力上升对方1只怪兽的攻击力。此卡在墓地时，我方场上的怪兽攻击力上升400点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105583', '奥利哈钢 西诺洛斯右腕', '此卡只能通过「奥利哈钢 西诺洛斯」的效果特殊召唤。只要场上存在「奥利哈钢 西诺洛斯」此卡就无法被破坏。此卡攻击力和守备力每和对方怪兽战斗1次就增加对方怪兽攻击力加300点的数值。伤害计算结束时，「奥利哈钢 西诺洛斯」，可以代替自己怪兽承受对方所有攻击。伤害结束时，「奥利哈钢 西诺洛斯」的攻击力下降对方怪兽攻击力的数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105584', '奥利哈钢 西诺洛斯左腕', '此卡只能通过「奥利哈钢 西诺洛斯」的效果特殊召唤。
INSERT INTO "texts" VALUES ('ZZ105585', '奥利哈钢 西诺洛斯', '此卡只能通过「奥利哈钢奇达拉」的效果特殊召唤，
INSERT INTO "texts" VALUES ('ZZ105586', '奥利哈钢之神', '由「达姿的仪式」或「奥利哈钢之圣都 亚特兰提斯」的效果特殊召唤。每破坏1只怪兽，给予对方伤害等于破坏怪兽的原本攻击力的2倍再加2000点。支付500点生命值，可以破坏对方场上全部怪兽。此卡不受魔法·陷阱·效果的影响。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105587', '奥利哈钢之神', '藉由「达姿的仪式」降临。需将我方生命值归0才可召唤，此时我方战斗胜负不受生命值影响。对方发动对此卡的所有魔法·陷阱卡的效果无效并破坏。可当此卡破坏对方怪兽时，给予对方破坏怪兽攻击力两倍多2000点伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105588', '奥利哈钢 盔甲狼战士', '此卡只能献祭2只等级4以下名字带有「奥利哈钢」的怪兽来特殊召唤，此卡攻击对方守备表示的怪兽时，被攻击的守备怪兽变成攻击表示，同时此卡的攻击力上升1000点，
INSERT INTO "texts" VALUES ('ZZ105589', '奥利哈钢 狼兵·猎刃', '我方场地上存在名字带有「奥利哈钢 狼兵」之名的怪兽时，献祭此卡可进行召唤·反转召唤·特殊召唤，此卡被破坏送往墓地时，给对方生命值造成200点的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105590', '奥利哈钢 奇达拉', '舍弃500生命值可从手牌特殊召唤。此卡在场上我方战斗流程中受到的损伤为0。
INSERT INTO "texts" VALUES ('ZZ105591', '双弓的半人马', '限此卡在场，每回合指定我方和对方怪兽各1只，我方进行1次投掷硬币得到以下效果。·正：破坏指定的我方怪兽，给予被破坏怪兽原持有者此怪兽攻击力的伤害。·背：破坏指定的对方怪兽，给予被破坏怪兽原持有者此怪兽攻击力的伤害。此效果发动的回合我方不能进行战斗阶段。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105592', '奥利哈钢的圣光', '·名字带有「奥利哈钢」的魔法·陷阱卡发动效果不能被无效、离场。·此卡只能放在卡组最下方，对方每回合可恢复10000点生命值，但对方不能发动支付生命值发动的效果。·我方魔法陷阱区域不受限制。·对方怪兽效果无法使用（无视对方效果）。·对方不能发动和放置场地魔法。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105593', '古生代化石骑士 骷髅剑士', '岩石族怪兽＋5星以上的怪兽
INSERT INTO "texts" VALUES ('ZZ105594', '莫忘拿破仑', '这个卡名的①②的效果1回合各能使用1次。
INSERT INTO "texts" VALUES ('ZZ105595', '童话动物·小小咪', '这个卡名的①②的效果1回合各能使用1次。
INSERT INTO "texts" VALUES ('ZZ105596', '沉默魔术师', '这张卡不能通常召唤。把自己场上1只魔法师族怪兽解放的场合才能特殊召唤。
INSERT INTO "texts" VALUES ('ZZ105597', '拉比林斯迷宫欢迎欢迎大欢迎', '这个卡名的①②的效果1回合只能有1次使用其中任意1个。
INSERT INTO "texts" VALUES ('ZZ105598', '奥利哈钢 狼兵·獠牙', '我方的此卡被对手的怪兽破坏送往墓地时，可以把此卡从游戏中除外，从我方的手牌·牌组特殊召唤2只冠有「奥利哈钢 狼兵」之名的怪兽到我方场地上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105599', '奥利哈钢 盾剑牛战士', '此卡只能献祭2只等级4或以下冠有「奥利哈钢」之名的怪兽来特殊召唤，此卡每破坏对手1只怪兽，此卡攻击力上升500点，此卡的守备力在参加的战斗阶段时上升500点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105600', '奥利哈钢 金斧牛战将', '「奥利哈钢 狂杀牛剑士」＋「奥利哈钢 盾剑牛战士」
INSERT INTO "texts" VALUES ('ZZ105601', '守护神 欧贝利德', '这张卡不能通常召唤。从自己墓地把3只地属性岩石族怪兽除外的场合可以特殊召唤。
INSERT INTO "texts" VALUES ('ZZ105602', '蹦蹦宠 优越猫', '只要这张卡我方场上正面攻击表示存在，对方不能发动通常陷阱。我方场上存在正面表示的「宠物召唤师」的场合，这张卡不会被卡片效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105603', '陌路的偏执狂', '主要阶段2才能发动。从卡组把1只名字带有「水晶宫」的怪兽加到手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105604', '水晶宫之冒险家', '1回合1次，随机选择对方场上·手牌中的1张卡进行确认。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105605', '水晶宫之长枪兵', '我方场上存在正面表示名字带有「水晶宫」的怪兽时，可以把这张卡从手牌特殊召唤。这个效果特殊召唤的这张卡在结束阶段时破坏。「水晶宫之长枪兵」在我方场上只能有1只正面表示存在。此外，这张卡攻击守备表示的怪兽时，如果攻击力超过那个守备力，给予对方生命值那个数值的战斗伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105606', '宠物妖精', '我方场上存在2只以上正面表示的名字带有「蹦蹦宠」的怪兽的场合，可以把这张卡从手牌特殊召唤。这个效果特殊召唤成功时，我方场上名字带有「蹦蹦宠」的怪兽在回合结束前作为4星怪兽使用。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105607', '蹦蹦宠 滑翔鼬', '这张卡给对方造成战斗伤害时，可以从卡组抽1张卡。我方场上存在正面表示的「宠物召唤师」场合，这张卡可以直接攻击对方生命值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105608', '最后的宝藏', '名字带有「水晶宫」的怪兽战斗破坏对方怪兽送入墓地时才能发动。从我方卡组抽1张卡。这个效果1回合只能使用1次。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105609', '炽炎鸟 紫炎雀', '这张卡在我方场上正面攻击表示的场合，对方在战斗阶段中不能发动陷阱卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105610', '炽炎鸟 混乱炎星', '1回合1次，选择我方场上正面攻击表示存在的1只名字带有「炽炎鸟」的怪兽和对方场上正面攻击表示存在的1只等级6以下怪兽才能发动。选择怪兽的控制权直到回合结束阶段前交换。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105611', '炽炎鸟 中华灵', '这张卡召唤·特殊召唤成功的场合，选择对方场上1只怪兽的表示形式改变。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105612', '炽炎飞溅', '名字带有「炽炎鸟」的怪兽成为对方怪兽的攻击对象时才能发动。那只攻击怪兽破坏，战斗阶段结束。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105613', '蹦蹦宠 极光企鹅', '只要这张卡我方场上正面攻击表示存在，对方不能选择这张卡以外的怪兽作为攻击对象。我方场上存在正面表示的「宠物召唤师」的场合，这张卡不会被战斗破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105614', '迅疾僵尸', '我方把速攻魔法卡发动的场合，这张卡在这个回合的战斗阶段可以进行2次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105615', '波澜之奥忒洛夫', '我方把速攻魔法卡发动的回合，这张卡可以直接攻击玩家。我方场上存在正面表示的「烈阳之康特斯基」时，这张卡不会被战斗破坏，这张卡的战斗发生的对我方战斗伤害变成0。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105616', '炽炎跃动', '名字带有「炽炎鸟」的怪兽成为对方的卡片效果的对象时才能发动。对象怪兽直到我方的第2次准备结束前从游戏中除外。那之后，从卡组抽1张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105617', '超级运动员 极速领跑者', '「超级运动员 极速领跑者」的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。
INSERT INTO "texts" VALUES ('ZZ105618', '黑混沌之青眼魔导士', '「混沌形态」降临。
INSERT INTO "texts" VALUES ('ZZ105619', '古代的机械背饰', '①：1回合1次，可以把1个以下效果发动。
INSERT INTO "texts" VALUES ('ZZ105620', '剑斗兽 刃斗', '①：这张卡用「剑斗兽」怪兽的效果特殊召唤成功的场合才能发动。得到对方场上1只怪兽的控制权。
INSERT INTO "texts" VALUES ('ZZ105621', '元素英雄 闪光爆热火焰翼侠', '「元素英雄 闪光火焰翼侠」＋「元素英雄 爆热女郎」
INSERT INTO "texts" VALUES ('ZZ105622', '元素英雄 影雾女郎·镰', '这个卡名在规则上也当作「元素英雄 影雾女郎」使用。
INSERT INTO "texts" VALUES ('ZZ105623', '元素英雄 火焰女郎·灼', '这个卡名在规则上也当作「元素英雄 火焰女郎」使用。
INSERT INTO "texts" VALUES ('ZZ105624', '元素英雄 新星主 火焰操纵', '「元素英雄」怪兽＋炎属性怪兽
INSERT INTO "texts" VALUES ('ZZ105625', '元素英雄 爆裂急速女郎', '「元素英雄 爆热女郎」＋战士族怪兽
INSERT INTO "texts" VALUES ('ZZ105626', '元素英雄 爆翼女郎', '「元素英雄 爆热女郎」＋风属性怪兽
INSERT INTO "texts" VALUES ('ZZ105627', '元素英雄 爆热女翼侠', '「元素英雄 羽翼侠」＋「元素英雄 爆热女郎」
INSERT INTO "texts" VALUES ('ZZ105628', '元素英雄 爆热铁壁女郎', '「元素英雄 爆热女郎」＋「元素英雄 黏土侠」
INSERT INTO "texts" VALUES ('ZZ105629', '罪神机-开天', '①：这张卡可以直接攻击。
INSERT INTO "texts" VALUES ('ZZ105630', '圣炎之剑士-基亚·弗里德', '这个卡名的②的效果1回合只能使用1次。
INSERT INTO "texts" VALUES ('ZZ105631', 'G石人·水晶支石墓', '包含「G石人·水晶心」或「G石人·无效支石墓」的怪兽2只以上
INSERT INTO "texts" VALUES ('ZZ105632', '暗黑精灵剑士', '这个卡名的①的效果1回合只能使用1次。
INSERT INTO "texts" VALUES ('ZZ105633', '狱神兽之神艺', '「狱神」怪兽+「神艺」怪兽
INSERT INTO "texts" VALUES ('ZZ105634', '茧状体·新宇小子', '这个卡名的①②的效果1回合各能使用1次。
INSERT INTO "texts" VALUES ('ZZ105635', '圣炎王妃 吉祥不死鸟', '4星怪兽×2
INSERT INTO "texts" VALUES ('ZZ105636', '№系猎人-光子模式', '这个卡名的作为①的方法的特殊召唤1回合只能有1次，作为②的效果1回合只能使用1次。
INSERT INTO "texts" VALUES ('ZZ105637', '辉石再诞', '这个卡名在规则上也当作「融合」卡使用。这个卡名的①②的效果1回合各能使用1次。
INSERT INTO "texts" VALUES ('ZZ105638', '冰结界的雪虎', '这个卡名的①的效果1回合只能使用1次。
INSERT INTO "texts" VALUES ('ZZ105639', '拇指鲨', '这个卡名的①的效果1回合只能使用1次。
INSERT INTO "texts" VALUES ('ZZ105640', '雨雪天气 双蓝', '连接怪兽以外的「天气」怪兽2只
INSERT INTO "texts" VALUES ('ZZ105641', '群豪觉醒-紧急激活', '这个卡名的①②的效果1回合各能使用1次。场地区域有卡存在的场合，这张卡的发动从手卡也能用。
INSERT INTO "texts" VALUES ('ZZ105642', 'D.D.杰拉', '这个卡名的①的效果1回合只能使用1次。
INSERT INTO "texts" VALUES ('ZZ105643', '英豪精神', '这个卡名的①的效果1回合只能使用1次。
INSERT INTO "texts" VALUES ('ZZ105644', '混沌No.86 英豪冠军 击灭圣枪王', '战士族5星怪兽×3只以上（最多5只）
INSERT INTO "texts" VALUES ('ZZ105645', '乒乓球小爱神', '这个卡名的①的效果1回合只能使用1次。
INSERT INTO "texts" VALUES ('ZZ105646', '笑容游乐园', '这个卡名的卡1回合只能发动1张。
INSERT INTO "texts" VALUES ('ZZ105647', '极神雷皇 托尔', '「极星」调整＋调整以外的怪兽1只以上
INSERT INTO "texts" VALUES ('ZZ105648', '极神圣帝王 奥丁', '「极星」调整＋调整以外的怪兽1只以上
INSERT INTO "texts" VALUES ('ZZ105649', '极神诡皇 洛基', '「极星」调整＋调整以外的怪兽1只以上
INSERT INTO "texts" VALUES ('ZZ105650', '队长 翼', '场上有「梦幻足球场」以表侧表示存在的场合，这张卡攻击守备表示的怪兽时，若攻击力超过那只怪兽的守备力，给予对手LP超过数值的战斗伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105651', '主力前锋', '场上有「梦幻足球场」以表侧表示存在的场合，这张卡可以不用解放作召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105652', '后卫自由人', '场上有「梦幻足球场」以表侧表示存在的场合，这张卡的等级变为5。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105653', '天才球星十号', '等级5怪兽×3 
INSERT INTO "texts" VALUES ('ZZ105654', '梦幻足球场', '场上以里侧守备表示存在的怪兽变为表侧守备表示。这个时候，翻转效果不发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105655', '致命传球', '选择自己场上存在的1只怪兽发动。选择的怪兽和持有比自己攻击力高的守备力的怪兽进行战斗的场合，选择的怪兽的攻击力直到结束阶段时变为２倍。此外这个时候，进行战斗的对手怪兽的效果无效化。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105656', '眼神交接', '将自己墓地存在的「越位陷阱」加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105657', '团队合作', '自己场上有2只相同种族、等级的怪兽存在的场合，可以从自己的墓地特殊召唤1只和那些怪兽相同种族的怪兽。这个效果特殊召唤的怪兽等级上升1。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105658', '越位陷阱', '自己的魔法陷阱卡区域不存在这张卡以外的卡的场合，自己场上存在的怪兽被战斗破坏时可以发动。那只怪兽的破坏和战斗伤害无效，回合结束。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105659', '磁石荒鷲Δ', '场上的名字带有「磁石」的怪兽被战斗破坏时可以发动。直到这个回合结束时这张卡的攻击力上升400。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105660', '磁石圆盘', '场上的名字带有「磁石」的怪兽被战斗破坏时可以发动。直到这个回合结束时这张卡的攻击力上升400。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105661', '磁石大猿E', '场上的名字带有「磁石」的怪兽被战斗破坏时可以发动。直到这个回合结束时这张卡的攻击力上升400。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105662', '磁石鳞兽Z', '场上的名字带有「磁石」的怪兽被战斗破坏时可以发动。直到这个回合结束时这张卡的攻击力上升400。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105663', '磁石破裂人形', '这张卡被战斗破坏时，给予对方200伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105664', '磁石妨害者', '场上以表侧攻击表示存在的这张卡成为攻击对象时可以发动。这张卡与对手的攻击怪兽返回持有者手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105665', '磁石虹色兽', '表侧表示的同名卡在场上存在的场合，可以使对手的1只怪兽的怪兽效果无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105666', '超电磁龙 马格纳龙', '这张卡只能用「磁石融合」融合召唤来进行特殊召唤。这张卡用战斗破坏对手怪兽的场合，给予对手基本分破坏的怪兽的攻击力数值的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105667', '磁力苏生', '支付500基本分，从自己的墓地以表侧攻击表示特殊召唤1只名字带有「磁石」的怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105668', '磁力融合', '将自己场上的「磁石荒鹰Δ」、「磁石大猿Ε」、「磁石鳞獣Ζ」各1只解放发动。从自己的额外卡组将1只「超电磁龙 马格纳龙」当作融合召唤地特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105669', '击磁石', '支付一半基本分，选择自己场上的1只「超电磁龙 马格纳龙」发动。选择的怪兽的攻击力变为一半，这个回合可以直击攻击对手玩家。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105670', '魔鬼机车', '这张卡作为超量素材时，给予对手LP400点伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105671', '黑暗机轮', '选择自己场上以表侧表示存在的１只机械族・等级３的怪兽发动。从手牌特殊召唤１只选择的怪兽的同名怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105672', '交叠光零爆破', '自己场上有没有多维素材的多维怪兽存在的场合可以发动。对手场上的1只怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105673', '多维陨石', '可以选择自己场上的1只多维怪兽发动。这个回合选择的怪兽攻击守备表示怪兽时，若攻击力超过那只怪兽的守备力，给予对手LP超过数值的战斗伤害。之后，从自己的卡组抽1张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105674', '野性突击者', '自己场上的1只多维怪兽在没有多维素材的状态下被选择为攻击对象时，可以选择那1只怪兽发动。选择的怪兽的攻击力上升对手的攻击怪兽的攻击力数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105675', '多维地狱监禁', '对手场上有超量怪兽被特殊召唤时，可以选择那1只怪兽发动。只要这张卡在场上以表侧表示存在，选择的怪兽不能攻击，对手回合的结束阶段时给予对手LP500点的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105676', '规律的镜舞台', '自己场上以表侧表示存在的全部怪兽的攻击力・守备力，变为那只怪兽的原攻击力・守备力。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105677', '双重检查', '用战斗没能破坏对手的1只怪兽时可以发动。那1只怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105678', '突击检查', '场上的1只里侧守备表示的怪兽的表示形式变为表侧守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105679', '湖之骑士 兰斯洛特', '用这张卡作为素材的超量怪兽得到以下的效果。●这次超量召唤成功时，场上的1只怪兽的攻击力下降800点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105680', '悲恋骑士 崔斯坦', '用这张卡作为素材的超量怪兽得到以下的效果。●这次超量召唤成功时，场上的1只怪兽的守备力下降1000点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105681', '剑之誓', '自己场上有战士族怪兽存在的场合，可以从手牌特殊召唤1只战士族·等级4的怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105682', '奇迹的大剑', '装备怪兽的攻击力上升500点。装备怪兽没能用战斗将对手怪兽破坏时可以发动。可以通过将这张卡送入墓地，从手牌发动1张魔法卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105684', '英雄的受难', '自己场上有名字带有「漫画英雄」的怪兽存在，对方召唤怪兽成功时可以发动。对方必须从自己的卡组选择与召唤成功的怪兽等级相同的2只怪兽在场上特殊召唤，用这个效果特殊召唤的怪兽的效果无效化。无法特殊召唤的场合，给与对方400点伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105685', '超巨大飞船 巨大兴登堡号', '场上有5星以上的怪兽召唤时，对方场上攻击表示存在的9星以下的怪兽全部变成守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105686', '超巨大不沉客船 高雅泰坦尼克号', '1回合1次，可以选择对方场上表侧表示存在的1只守备力0的怪兽破坏，给与对方基本分这个效果破坏的怪兽的攻击力一半数值的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105688', '橡皮艇派对', '在自己场上特殊召唤2只「橡皮艇衍生物」（水族·水·1星·攻／守0）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105689', '命运共有', '对手受到的效果伤害的数值变为一半，自己LP受到那个数值的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105690', '冰山海', '场上以表侧守备表示存在的怪兽的守备力变为0。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105691', '多维外套', '可以选择场上的1只超量怪兽发动。这个回合，选择的怪兽不会被战斗以及卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105692', '多维移动', '对手的战斗阶段时可以发动。自己场上的1只超量怪兽的操作权转移给对手玩家，战斗阶段结束。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105693', '决断的迷宫', '对手怪兽进行了战斗的伤害计算后可以发动。自己必须通过支付500LP，使对手将1张手牌送入墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105694', '不公平条约', '可以将自己的2张手牌送入墓地发动。自己场上以表侧表示存在的1张永续魔法卡发动效果而使自己支付LP的场合，由对手代为支付LP。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105695', '神龙演武', '自己场上的1只龙族超量怪兽被选择为对手怪兽的攻击对象时可以发动。将自己墓地的2只龙族怪兽从游戏中除外。对手的攻击怪兽的攻击力下降除外了的2只怪兽的攻击力的合计数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105696', '叶子变化', '从自己的手牌特殊召唤1只名字带有「狸」的怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105697', '掀千重席', '名字带有「狸」的怪兽被选择为攻击对象时可以发动。进行战斗的1只对手怪兽破坏，给予对手的基本分那只怪兽的攻击力数值的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105698', '石化魔力', '选择场上以里侧守备表示存在的1只怪兽发动。选择的怪兽变为表侧守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105699', '石化仪式', '可以将自己墓地的1只岩石族超量怪兽从游戏中除外发动。从自己的墓地特殊召唤2只岩石族怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105700', '石化堆叠', '可以选择自己场上的2只岩石族怪兽发动。直到结束阶段时，
INSERT INTO "texts" VALUES ('ZZ105506', '蝉终', '给予对手LP战斗伤害时可以发动。下次自己的准备阶段时，可以通过将这张卡送入墓地，给予对手LP那个战斗伤害的数值的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105702', '死亡箱水母', '对手怪兽攻击这张卡的场合，不进行计算伤害将那只对手怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105701', '水母雨', '场上以表侧表示存在的怪兽全部变为水属性。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105687', '水母洞', '对手场上有水属性多维怪兽特殊召唤时可以发动。这个回合，对手场上以表侧表示存在的全部卡的效果无效化。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105683', '水母束缚', '自己场上有水属性怪兽存在的场合，可以选择1只对手怪兽发动。选择的怪兽不能攻击，其效果不能发动。选择的怪兽从场上离开时，这张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105576', '退潮', '有怪兽盖放时，将那只怪兽变为表侧守备表示。这个时候，翻转效果怪兽的效果不能发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105554', '军蚊 血军团', '这张卡召唤成功时，可以从自己的卡组把1只「军蚊 血军团」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105510', '军蚊 血突击队', '自己场上有「No.2 蚊学忍者 影蚊」存在的场合，可以通过将自己场上的这张卡解放，在对手场上的1只怪兽上放置1个「幻觉指示物」。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105488', '蚊学忍法·蚊炎放射', '给与有「幻觉指示物」放置的怪兽的控制者那些怪兽的数量×600的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105420', '蚊学忍法·蚊取闪光', '选择没有超量素材的自己场上的1只超量怪兽才能发动。
INSERT INTO "texts" VALUES ('ZZ105419', '感染蝇', '1回合1次，可以使自己场上全部怪兽的等级变为2倍。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105418', '地狱增殖', '可以选择自己场上的1只等级2以下的怪兽发动。与选择的怪兽同名的卡尽可能多地从手牌特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105416', '感染扩张', '自己没有召唤怪兽的回合可以发动。在自己场上特殊召唤1只「感染虫衍生物」（恶魔族·暗·1星·攻／守300）。只要这张卡在场上存在，自己不能从手牌特殊召唤怪兽。这张卡被破坏时，可以将对手场上的1只怪兽破坏，给予对手LP300点伤害。只要这张卡在场上存在，对手只能以表侧攻击表示召唤、特殊召唤怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105412', '感染媒介', '自己场上的1只恶魔族多维怪兽被破坏的回合可以发动。自己场上的怪兽全部破坏，
INSERT INTO "texts" VALUES ('ZZ100352', '交叠光捕猎', '自己的多维怪兽成为对手的1只多维怪兽的攻击对象时可以发动。攻击怪兽的多维素材全部变为成为攻击对象的怪兽的多维素材。接着这次战斗阶段中，对手怪兽的效果无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ101194', '异晶人的门', '这张卡发动后，这个回合每有1张卡片被破坏送去墓地，给予对方基本分800分伤害。这张卡发动的回合，自己不能通常召唤・特殊召唤。把场上表侧表示存在的这张卡送去墓地，选择对方场上1只表侧表示存在的怪兽才能发动。选择的怪兽的效果无效化。这个效果在对方回合也能发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105703', '虚假形态', '怪兽因卡片效果而改变表示形式时，给与对方基本分表示形式改变的怪兽数量×400的数值的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105704', '虚假生命', '对方的1只怪兽直接攻击宣言时，选择那只怪兽才能发动，无效那次攻击，然后我方恢复那只怪兽攻击力数值的LP。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105705', '战斗之路', '自己场上有怪兽存在，对手场上有怪兽以表侧攻击表示存在的场合，对手必须进行战斗阶段，对手场上以表侧攻击表示存在的怪兽必须攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105706', '异晶人的战斗爆裂', '把自己墓地1张名字带有「异晶人的」的卡片除外才能发动。1回合至多2次，可以让自己或者对方的怪兽的攻击无效。对方的战斗阶段中，通过把场上这张卡送去墓地，选择双方场上各自1只表侧攻击表示的怪兽，强制进行战斗。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105707', '水泡泄放器', '可以通过从手牌将1张同名卡送入墓地，特殊召唤手牌的这张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105708', '交叠光世界', '结束阶段时没有在操作超量怪兽的玩家受到500点伤害。场上的超量怪兽不会被魔法、陷阱、效果怪兽的效果破坏。
INSERT INTO "texts" VALUES ('ZZ105709', '升阶增益', '名字带有「升阶魔法」的魔法卡的效果把超量怪兽特殊召唤成功时，可以从自己的卡组抽1张卡。被名字带有「升阶魔法」的魔法卡的效果特殊召唤的超量怪兽选择作为攻击对象的对方怪兽的效果无效化。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105710', '阶级之壁', '对方的超量怪兽的攻击宣言时才能发动。作为攻击对象的自己场上的1只超量怪兽的阶级比对方的攻击怪兽的阶级高的场合，那只怪兽的攻击无效并让战斗阶段结束。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105711', '战士的诱惑', '选择对方场上1只防备力最高的守备表示的怪兽发动。选择的怪兽变成表侧攻击表示，这回合其攻击力变成手守备力相同的数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105712', 'XYZ宝冠', '超量怪兽才能装备。装备怪兽的阶级变成等级。装备怪兽作为超量召唤所使用的超量素材时，当作2个超量素材使用。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105713', '英豪成长', '战士族才能装备。自己基本分比对方低的场合，装备怪兽的攻击力变成2倍的数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105714', '英豪变换', '自己场上1只名字带有「英豪」的怪兽解放，把自己墓地1只名字带有「英豪」的怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105715', '英豪防御', '自己受到战斗伤害时，把自己场上1只名字带有「英豪挑战者」的怪兽解放才能发动。恢复等同解放的怪兽的攻击力数值的自己的LP。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105716', '乱蝶幻舞', '场地魔法表侧表示存在的场合可以发动。把自己的手卡2只4星以下的名字带有「幻蝶刺客」怪兽特殊召唤。这张卡发动的回合，自己不能进行攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105717', '刺客门', '名字带有「刺客」的怪兽以外怪兽攻击宣言时发动。那只怪兽攻击无效并破坏。场上没有名字带有「刺客」的怪兽表侧表示存在的场合，这张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105718', '胡蝶之舞', '支付1000LP才能发动这张卡。把自己手上任意数量的名字带有「蝶」的怪兽向对方展示，给予对方这个数量×300的LP伤害。
INSERT INTO "texts" VALUES ('ZZ105719', '幻蝶的雄姿', '对方怪兽攻击宣言时可以发动。把攻击对象变更为自己场上1只攻击表示的名字带有「幻蝶」的怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105720', '胡蝶之毒', '自己受到对方卡片效果伤害，自己场上存在名字带有「蝶」的怪兽时，给与对方1000LP伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105721', '废品回收', '把自己墓地2只机械怪兽除外，再选择自己墓地1只机械族超量怪兽发动。选择的怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105722', '机器公园', '1回合1次，当玩家对1只机械族怪兽召唤成功时，可以将其手上的1只机械族怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105723', '破灭的纹章', '名字带有「纹章」的怪兽才能装备。1回合1次，给与对方基本分场上表侧表示存在的怪兽数量×300点的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105724', '爆破纹章', '这张卡的装备怪兽被破坏时，给与被破坏的怪兽控制者基本分攻击力一半的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105725', '暴风纹章', '只能对方战斗阶段中发动。对手场上的魔法陷阱区的卡全部返回手卡，结束对手的战斗阶段。这个回合的结束阶段时，给与对方基本分这个效果返回手卡的卡数量×500点的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105726', '残灭的纹章', '选择对方场上表侧表示存在的1只原本持有者是自己的怪兽才能发动。这个回合的结束阶段时，持有选择怪兽的攻击力以下的对方场上的怪兽全部破坏，给与对方那个攻击力合计数值的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105727', '无敌的纹章', '选择场上表侧表示的1只怪兽发动。选择的怪兽的攻击力下降800。此卡在场上表侧表示存在时，选择的怪兽不会被战斗破坏。选择的怪兽从场上离开时，这张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105728', '帕伦克石棺', '自己场上有表侧存在的名字带有「先史遗产」的怪兽的场合才能发动。自己从卡组抽2张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105729', '山铜锁链', '这张卡发动后，接着进行超量召唤的场合，可以减少1只素材进行超量召唤。
INSERT INTO "texts" VALUES ('ZZ105730', '石之心脏', '自己场上的名字带有「先史遗产」的怪兽用战斗没有破坏对手怪兽时，可以选择那1只怪兽发动。选择的怪兽在这个回合里可以接着再1次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105731', '水晶机巧炮', '这个卡名的卡在1回合只能发动1张，这个卡名的③的效果1回合只能使用1次。
INSERT INTO "texts" VALUES ('ZZ105732', '混沌巫师 破灭的使者', '这张卡不能通常召唤。从自己墓地把光·暗属性怪兽各1只除外的场合可以特殊召唤。
INSERT INTO "texts" VALUES ('ZZ105733', '命运英雄 真红眼暗魔-D', '「命运英雄 血魔-D」＋「真红眼暗龙」
INSERT INTO "texts" VALUES ('ZZ105734', '黑暗电子角', '这只怪兽成功召唤到场上时，可从双方的墓地里找一只四级以下的龙族怪兽装备到自己的身上。在战斗过程中它还能把战斗伤害转移到装备怪兽身上，从而不会被破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105735', '黑暗电子刃', '这只怪兽成功召唤到场上时，可从双方的墓地里找一只4级以下的龙族怪兽装备到自己的身上。而且这只怪兽减少一半的攻击力就能直接攻击对手玩家，在战斗过程中它还能把战斗伤害转移到装备怪兽身上，从而不会被破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105736', '黑暗电子骨', '这只怪兽成功召唤到场上时，可从双方的墓地里找一只龙族怪兽装备到自己的身上。而且在战斗过程中它还能把战斗伤害转移到装备怪兽身上，从而不会被破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105737', '铠黑龙-电子黑暗龙', '此卡不能作融合召唤以外的特殊召唤。此卡特殊召唤成功时，从我方墓地里选择1只龙族怪兽作为此卡的装备卡装备，此卡的攻击力提升等同于那个攻击力的数值。我方墓地里每有1张怪兽卡，此卡的攻击力提升100点。此卡被战斗破坏的回合，装备的怪兽代替破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105738', '电子学融合辅助', '当此卡发动时，以一半生命值为代价，可以用融合召唤的机械族怪兽来代替需要的怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105739', '防守小子', '拥有2700高分的防守小子，在对手的完备状态时，能让玩家从手牌中抽取一张卡片。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105740', '银的反闭-镜子传唤', '我方场上同时存在「银的式神-右京」、银的式神-左京」时可以发动。将自己墓地的1张陷阱卡加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105741', '堕天使护士-蕾菲库儿', '只要这张卡在场上正面表示存在，对方生命值回复的效果变成基于对方基本分伤害的效果。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105742', '燧石龙', '场上的这张卡送入墓地，基于对方500点伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105743', '古生代化石龙', '此卡攻击时，可随意选择要和对方的攻击力还是守备力战斗，并拥有贯通伤害的能力。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105744', '新生代化石龙-Skullgerr', '我方墓地的岩石族怪兽＋对方墓地等级4以下的恐龙族怪兽
INSERT INTO "texts" VALUES ('ZZ105745', '中生代化石骑士-骷髅骑士', '我方墓地的岩石族怪兽＋对方墓地等级5或6的战士族怪兽
INSERT INTO "texts" VALUES ('ZZ105746', '古生代化石机械-骷髅擎天柱', '我方墓地的岩石族怪兽＋对方墓地等级7以上的机械族怪兽
INSERT INTO "texts" VALUES ('SP401061', '人造人类-灵魂震动', '此牌只存在牌堆的正面，不能发动陷阱，牌堆上所有的陷阱牌都变为无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105747', '白夜女王', '这张卡不能特殊召唤。1回合1次，可以破坏场上1张盖伏的卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105748', '初影六武众-沨', '这个卡名的①的效果1回合只能使用1次。
INSERT INTO "texts" VALUES ('ZZ105749', '电子超能心灵', '「电子超能人」＋「本性暴露」
INSERT INTO "texts" VALUES ('ZZ105750', '海马·青眼白龙', '海马濑人牌组的牌魂「青眼的白龙」，本体为奇莎拉的精灵，也是海马兄弟之间的羁绊。此卡成功特殊召唤成功的回合，我方场地上龙族怪兽不会被对手的魔法·陷阱卡·怪兽效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105751', '地缚神 查尔瓦·潘恰伊', '这个卡名的⑤的效果1回合只能使用1次。
INSERT INTO "texts" VALUES ('ZZ105752', '地缚神 恰图·卡克', '这个卡名的⑥的效果1回合只能使用1次。
INSERT INTO "texts" VALUES ('ZZ105753', '地缚神 图鲁·乌丘', '①：「地缚神」怪兽在场上只能有1只表侧表示存在。
INSERT INTO "texts" VALUES ('ZZ105754', '满月', '兽族怪兽才能装备。装备怪兽的攻击力、守备力提升300点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105755', '神·奥卡斯', '挥舞着大剑，以自己强大的力量而自豪的战士。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105756', '幽微', '此卡成功召唤、反转召唤、特殊召唤时，对手跳过下次的抽卡阶段。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105757', '企鹅鱼雷', '此卡能直接攻击对手，直接攻击成功后此卡被破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105758', '骰子迷宫', '战斗阶段时双方玩家仅能选择1只怪兽进行战斗，计算战斗伤害前双方玩家必须先掷骰子，获得对应效果后再进行战斗。掷出1时，自己怪兽的攻击力下降1000点。掷出2时，自己怪兽的攻击力上升1000点。掷出3时，自己怪兽的攻击力下降500点。掷出4时，自己怪兽的攻击力上升500点。掷出5时，自己怪兽的攻击力减半。掷出6时，自己怪兽的攻击力加倍。自己场上没有怪兽时此卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105759', '次元骰子', '场上存在「骰子迷宫」时可以发动。将自己场上2只怪兽作祭品，从自己卡组特殊召唤1只「神·奥卡斯」到自己场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105760', '完美机械王', '「机械王」＋「机械中士」
INSERT INTO "texts" VALUES ('ZZ105761', 'F·G·D 五头神龙', '借由「邪龙复活的仪式」降临。仪式召唤成功时破坏对手场上所有的卡。此卡仪式召唤的回合不能进行攻击。此卡与地、水、炎、风、暗属性怪兽战斗时不会被战斗破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105762', '巨型·雷克斯', '对手场上没有怪兽存在的场合，此卡不能进行攻击宣言。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105763', '提迈欧斯之眼', '选择自己场上1只卡名带有「黑魔导」怪兽为对象才能发动。那只怪兽送去墓地，把有那只怪兽的卡名作为融合素材记述的1只融合怪兽从额外卡组融合召唤。「提迈欧斯之眼」在1回合只能发动1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105764', '守护者·爱亚托斯', '「女神之圣剑-爱亚托斯」在自己场上存在时才可召唤、反转召唤或特殊召唤。自己的墓地没有怪兽时，此卡可以不用祭品进行特殊召唤。把装备在此卡上的「女神之圣剑-爱亚托斯」破坏，可将对手墓地从上往下开始除外怪兽卡，直到出现怪兽卡以外的卡为止，然后将因此效果被除外怪兽的攻击力加到此卡上。此卡因战斗破坏送入墓地时从卡组以正面守备表示特殊召唤1只「守护者·德斯塞斯」到自己场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105765', '残暴翼龙', '自己场上只有此卡时，此卡就能直接攻击对手。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105766', '残暴恐龙', '「迅足的似鸟龙」＋「残暴翼龙」
INSERT INTO "texts" VALUES ('ZZ105767', '虫蛀蚀', '怪兽召唤成功时可以发动。全场的怪兽攻击力都下降100点。双方都受到自己场上怪兽数×100点生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105768', '真红领主', '借由「真红眼·轮回转世」降临。如果在1回合内发动2次魔法卡（不包含连锁）时，可以在第2张魔法卡效果生效时将场上除此卡外的怪兽全部破坏。这个效果在对手的回合也可以发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105769', '守护者·德斯塞斯', '①：此卡成功召唤时，从手牌或卡组将1张「死神之大镰-德斯塞斯」装备到此卡上。
INSERT INTO "texts" VALUES ('ZZ105770', '盔甲 资料脑', '场上有名字带有「盔甲」的怪兽存在时，此卡从手牌特殊召唤。此卡成功召唤时得到以下效果：·跳过对方下1回合的抽卡阶段；·此卡的攻击力与守备力上升我方手牌数量×800点的数值；·当此卡存在墓地时，可在下回合的我方准备阶段以攻击表示特殊召唤到场上；·从卡组把1张名字带有「盔甲」的怪兽加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105771', '盔甲 陷阱克星手腕', '这张卡在自己场上攻击表示时得到以下效果：·此卡在我方场上守备表示时，此卡的攻击力与守备力上升场上怪兽数量×1000点的数值；·我方场上名字带有「盔甲」的怪兽不受对方陷阱卡效果影响；·1回合1次，可以选择自己墓地的1只名字带有「盔甲」的怪兽在自己场上盖放；·这个卡战斗破坏怪兽的场合，给予对方生命值这只怪兽攻击力数值的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105772', '盔甲 燃烧手臂', '翻转：此卡的攻击力与守备力上升对方那只怪兽的攻击力数值，对方受到那个数值的差值伤害。此卡成功召唤时，此卡的攻击力与守备力上升4000点，对方以我方场上怪兽为对象的魔法、陷阱卡破坏。我方回合的结束阶段时，除外对方墓地的1只怪兽，我方从墓地特殊召唤1只名字带有「盔甲」的怪兽正面表示存在我方场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105773', '盔甲 黑洞护盾手腕', '场上有名字带有「盔甲」的怪兽存在时，此卡从手牌特殊召唤。此卡成功召唤时得到以下效果：·我方生命值上升我方墓地卡的数量×500点的数值；·此卡被破坏时送入墓地时，可以上升2000点攻击力，从而特殊召唤到我方场上（攻击力累计上升）；·此卡能对对方怪兽各作1次攻击。·若此卡给与对方直接攻击时，这张卡的控制者获得比赛的胜利。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105774', '斗气盔甲', '场上有名字带有「盔甲」的怪兽3只以上存在的场合，此卡可从手牌特殊召唤。成功召唤时，此卡不受对方魔法、陷阱、效果怪兽的效果影响，此卡被送入墓地的下1回合，从墓地特殊召唤到我方场上。此卡的攻击力上升全场怪兽的攻击力数值的总和。回合结束时，付出2000点生命值，从卡组或手牌特殊召唤1只名字带有「盔甲」的怪兽上场。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105775', '盔甲 大爆炸暴风手臂', '此卡成功召唤时，每丢弃1张手牌，此卡的攻击力与守备力上升2000点，此效果发动时，可以把手牌的1张名字带有「盔甲」的怪兽特殊召唤到场上。此卡存在场上时，对方不能选择以此卡以外的怪兽作为攻击对象。此卡被破坏时送入墓地时，可观看对方所有手牌，选择1张卡送入墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105776', '盔甲 促进盾', '此卡存在场上时，我方场上所有名字带有「盔甲」的怪兽不会被破坏，并且所有的伤害为0。此卡召唤成功时，攻击力和守备力上升我方与对方手牌、场上卡的数量×1000点的数值，下1回合的准备阶段，我方可以从游戏外尽可能的召唤怪兽上场。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105777', '盔甲 爆裂手环-电击', '场上有名字带有「盔甲」的怪兽存在时，此卡从手牌特殊召唤。此卡成功召唤时得到以下效果：·此卡的攻击力与守备力上升场上所有怪兽的攻击力与守备力之和；·这张卡可以直接攻击对方玩家，攻击成功时，跳过对方1回合；·对方怪兽不能以这张卡为攻击对象；·这张卡不受对方魔法、陷阱、效果怪兽的效果影响；·对方受到生命值的伤害数值，我方生命值上升那个数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105778', '盔甲 精神盔甲头', '此卡成功召唤时得到以下效果：·指定场上的1只怪兽，此卡的攻击力与守备力上升指定那只怪兽的攻击力与守备力数值；·当此卡在墓地时，可在自己的准备阶段从卡组把与此卡的同名卡尽可能的特殊召唤上场；·此卡存在场上时，对方怪兽不能攻击，不能发动怪兽效果；·场上每存在1只名字带有「盔甲」的怪兽，对方受到500点生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105779', '盔甲 主动装甲', '这张卡在自己场上攻击表示时得到以下效果：·此回合我方所受到所有的战斗伤害为0；·此卡的攻击力与守备力上升墓地卡的数量×1000点的数值；· 我方场上每有1张卡，我方从卡组抽1张卡；·场上有装备怪兽时，那只装备怪兽可直接攻击对方玩家。·选择对方场上1只怪兽直到这个回合的结束阶段时得到控制权。·选择墓地1只怪兽在自己场上特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105780', '盔甲 完全魔法引力', '可以把任意张墓地的卡加入我方卡组中，再在我方的卡组中抽出10张卡片，且特殊召唤所有抽出的卡中名字带有盔甲的怪兽正面攻击表示存在场上，其余不是怪兽卡则送入墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105781', '盔甲的引力', '从卡组特殊召唤出1只等级4以下的名字带有「盔甲」的怪兽上场，以此效果召唤出来的怪兽不受对方怪兽效果的影响。此卡使用完毕或被破坏后，不送去墓地，直接加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105782', '盔甲 巨影的幻境', '只要装备这张卡，装备怪兽不会被战斗破坏。装备怪兽破坏时，这张卡破坏。此卡被破坏后，可以不送去墓地当作怪兽卡使用，正面攻击表示存在场上，获得场上1只名字带有「盔甲」的怪兽攻击力与守备力同等的数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105783', '盔甲 断绝拳', '场上背面守备表示存在的怪兽全部变成正面攻击表示，这个时候反转效果怪兽的效果不发动。场上正面表示存在的效果每有1只给予对方生命值500点伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105784', '沉默剑士LV0', '每次自己的准备阶段时场上以攻击表示存在的这张卡的攻击力上升500点，4个回合的自己准备阶段，可以解放此卡，我方额外卡组中特殊召唤一张「沉默剑士LV4」到场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105785', '沉默剑士LV4', '这张卡不能通常召唤。只能通过「沉默剑士LV0」的效果特殊召唤。每次自己的准备阶段时场上以攻击表示存在的这张卡的攻击力上升500点，3个回合的自己准备阶段，可以解放此卡，从我方额外卡组中特殊召唤一张「沉默剑士LV7」到场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105786', '沉默剑士LV7', '这张卡不能通常召唤。只能通过「沉默剑士LV4」的效果特殊召唤。每次自己的准备阶段时场上以攻击表示存在的这张卡的攻击力上升500点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105787', '绝杀神印', '对方场上存在和发动名字带有「魔导」、「奥西里斯」、「太阳神」、「欧贝利斯克」的卡片时，选择以下其中一个效果发动，这张卡片不会被对方无效和破坏：
INSERT INTO "texts" VALUES ('ZZ105788', '毒化的太阳欧贝利', '名字带有「欧贝利斯克」、「太阳神」的使用者手牌数量2张以上的回合。生命值在回合结束时变为0。无效此卡的卡片破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105789', '碎魂者 熔海邪神', '此卡的召唤不会被破坏和无效，此卡召唤成功后，对方名字带有「六芒」的卡片效果无效并破坏移除到游戏外。只要此卡正面表示存在于场上，对方就不能发动和使用名字带有「六芒」的卡片，此卡不受名字带有「六芒」的卡效果影响。此卡不能特殊召唤，将对方场上3只怪兽作为祭品才能通常召唤。此卡召唤成功后对方场上攻击力3000以下的怪兽全部破坏，我方回复被破坏怪兽攻击力总数值一半的生命值。此卡被破坏送入墓地时，选择对方1只怪兽代替破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105790', '碎魂者 狂野的战狼', '此卡的召唤不会被破坏和无效，此卡召唤成功后，对方名字带有「六芒」的卡片效果无效并破坏移除到游戏外。
INSERT INTO "texts" VALUES ('ZZ105791', '碎魂者 遥控魔女', '此卡的召唤不会被破坏和无效，此卡召唤成功后，对方名字带有「六芒」的卡片效果无效并破坏移除到游戏外。
INSERT INTO "texts" VALUES ('ZZ105792', '碎魂者 红火暗杀组', '此卡的召唤不会被破坏和无效，此卡召唤成功后，对方名字带有「六芒」的卡片效果无效并破坏移除到游戏外。
INSERT INTO "texts" VALUES ('ZZ105793', '碎魂者 地狱狂魔', '此卡的召唤不会被破坏和无效，此卡召唤成功后，对方名字带有「六芒」的卡片效果无效并破坏移除到游戏外。
INSERT INTO "texts" VALUES ('ZZ105794', '碎魂者之同伴的支援', '此卡的发动不会被破坏和无效，只要此卡正面表示存在于场上，对方就不能发动和使用名字带有「六芒」的卡片，此卡不受名字带有「六芒」的卡效果影响，对方名字带有「六芒」的卡片效果无效并破坏移除到游戏外。1回合1次，我方场上每有1张名字带有「碎魂者」的怪兽，我方抽1张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105795', '碎魂者 预知女神', '此卡的召唤不会被破坏和无效，此卡召唤成功后，对方名字带有「六芒」的卡片效果无效并破坏移除到游戏外。
INSERT INTO "texts" VALUES ('ZZ105796', '空无的碎石', '对方使用名字带有「碎石者」的卡片时，此卡可从卡组加入手牌。将对方使用的「碎石者」 的卡片全部破坏送入我方墓地，我方从墓地特殊召唤相同数量的怪兽上场。这张卡不会被无效和破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105797', '海皇·水神赛德娜', '1回合1次，可以将1只我方场地上以正面表示等级4以下的水属性怪兽当做装备卡给此卡装备，此卡以此效果装备怪兽时，可以使对方场地上的魔法·陷阱卡无效化，此卡攻击力上升800点，此卡被破坏时，可以用装备中的怪兽代替此卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105798', '星际', '每丢弃1张手牌，可以选择自己墓地中的1只怪兽，选择的怪兽在自己场上特殊召唤。我方准备阶段时，损失因此卡效果特殊召唤出来的怪兽数量×300的生命值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105799', '沉默魔术师LV0', '对方每从卡组抽出1张卡，这张卡的攻击力上升500，名字中的LV+1。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105800', '欧贝利斯克之远征军', '只要此卡正面表示存在于场上，对方场上所有名字带有「植物」和「装甲」的卡片效果无效并破坏，对方无法召唤和发动名字带有「植物」和「装甲」的卡片。此卡在场上特殊召唤成功后，1回合1次，选择对方场上攻击力比此卡低的1只怪兽破坏。我方回复对方破坏的怪兽等级×1000点生命值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105801', '欧贝利斯克之三头判官', '只要此卡正面表示存在于场上，对方场上所有名字带有「植物」和「装甲」的卡片效果无效并破坏，对方无法召唤和发动名字带有「植物」和「装甲」的卡片。
INSERT INTO "texts" VALUES ('ZZ105802', '欧贝利斯克之迦鲁', '只要此卡正面表示存在于场上，对方场上所有名字带有「植物」和「装甲」的卡片效果无效并破坏，对方无法召唤和发动名字带有「植物」和「装甲」的卡片。
INSERT INTO "texts" VALUES ('ZZ105803', '欧贝利斯克之黑桃熊', '只要此卡正面表示存在于场上，对方场上所有名字带有「植物」和「装甲」的卡片效果无效并破坏，对方无法召唤和发动名字带有「植物」和「装甲」的卡片。
INSERT INTO "texts" VALUES ('ZZ105804', '欧贝利斯克之废铁龙', '只要此卡正面表示存在于场上，对方场上所有名字带有「植物」和「装甲」的卡片效果无效并破坏，对方无法召唤和发动名字带有「植物」和「装甲」的卡片。
INSERT INTO "texts" VALUES ('ZZ105806', '欧贝利斯克之护卫兵', '只要此卡正面表示存在于场上，对方场上所有名字带有「植物」和「装甲」的卡片效果无效并破坏，对方无法召唤和发动名字带有「植物」和「装甲」的卡片。
INSERT INTO "texts" VALUES ('ZZ105807', '欧贝利斯克之火焰使者', '只要此卡正面表示存在于场上，对方场上所有名字带有「植物」和「装甲」的卡片效果无效并破坏，对方无法召唤和发动名字带有「植物」和「装甲」的卡片。
