INSERT INTO "texts" VALUES ('ZZ105886', 'BT黑羽 凤凰重生', '「BT黑羽 神鸟凤王」的降临必需。特殊召唤时，必须以对方的场上把等级中合计12颗星以上的怪兽作为祭品。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105887', 'BT黑羽 黄毛', '将场上1只名字带有「黑羽」的怪兽送入墓地，可从手牌将两只名字带有「黑羽」的怪兽特殊召唤上场。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
