INSERT INTO "texts" VALUES ('ZZ105889', 'BT黑羽 奇叉爪仙', '这张卡召唤成功时，可以把自己墓地存在的「BT黑羽 奇雅扇仙」正面表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ105890', 'BT黑羽 奇猎守护者', '自己场上有名字带有「黑羽」的怪兽2只以上存在的场合，可从手牌特殊召唤。召唤成功时，可从手牌将2只「BT黑羽 高柏饿鹰」特殊召唤上场。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
