INSERT INTO "texts" VALUES ('ZZ106724', '封印兽 伊努恩', '场上有「封印之真言」时，可以从手卡特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ106725', '封印兽 努努拉欧', '场上有「封印之真言」时，可以从手卡特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ106726', '封印兽 佤兹姆', '场上有「封印之真言」时，被战斗破坏时，从墓地把2张3星以下的封印兽加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ106727', '封印兽 查尔姆嘉尔', '有「封印之真言」时，1回合1次，把对方场上1张魔法或陷阱破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ106728', '封印兽 保阿·保郎', '有「封印之真言」时，和这张卡进行过战斗的怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ106729', '封印兽 妮芙努', '召唤时，可以把墓地1只封印兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ106730', '封印兽 保龙', '有「封印之真言」时，不会成为魔法·陷阱·怪兽的效果的对象。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ106731', '封印之真言', '封印兽的能力开放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ106732', '尸中的真言', '场上有「封印之真言」时，可以抽出墓地的封印兽的数量。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ106733', '古文书的结界', '「封印之真言」不会被破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ106734', '苦痛之曼怛罗', '有封印兽时，把攻击怪兽破坏，从卡组把「封印之真言」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ106735', '兽中隐藏的真言', '封印兽被破坏时，从卡组把1张「封印之真言」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ106736', '真言之咒缚', '下降800基本分。让1只怪兽不能攻击，每回合结束时攻击力下降500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ106737', '受过严格训练的精灵', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ106738', '奇袭精灵', '在自己的战斗流程里，自己场上每存在1张其他的「精灵」，这张卡可以增加1次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ106739', '好学精灵', '这张卡被送去墓地时，可以从自己卡组抽1张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ106740', '回力镖精灵', '每个战斗阶段1次，可以改变攻击对象。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ106741', '空气圈鸟', '这张卡以外的「气圈」怪兽存在的场合，对方不能攻击宣言。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ106742', '微风气圈鸟', '对方场上有5星级以上的怪兽时，可以从手卡特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ106743', '合成气圈鸟', '这张卡召唤·特殊召唤时，把自己墓地1只4星级以下的「气圈」怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ106744', '虚拟气圈鸟', '从场上送去墓地时，从墓地把4星级以下「气圈」怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ106745', '无力气圈', '让1只对方怪兽的攻击力·守备力回到原本数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ106746', '大气障壁', '「气圈」怪兽在自己场上时，对方怪兽不能攻击，全部效果都不能把自己怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ106747', '大气再生', '「气圈」怪兽被破坏时，把墓地的4星级以下的「气圈」怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ106748', '大气传达', '「气圈」怪兽特殊召唤时，从卡组把4星级以下的「气圈」怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ106749', '大气万世', '自己场上的「气圈」怪兽被攻击时，给与对方基本分那次战斗伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ106750', '风压补偿', '战斗中破坏怪兽的怪兽变为守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ106751', '娱乐伙伴 人鱼☆女仆', '①：1回合1次，这张卡被选择作为攻击对象时才能发动。这张卡的表示形式变更。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ106753', '暗黑之龙王', '黑暗深处栖息的龙。双眼不太好使。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ106757', '牲祭人偶', '祭掉自己场上1只怪兽发动。从手卡特殊召唤1只可以通常召唤的7星怪兽。特殊召唤出的怪兽本回合不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ106758', '发掘作业', '①：丢弃1张手卡，自己从卡组抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ106759', '绝望之国的爱丽丝', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ106760', '心理木偶', '一种恶毒的木偶，会表演奇怪的、令人衰弱的舞蹈。
INSERT INTO "texts" VALUES ('ZZ106761', '神科学因子 卡斯帕', '①：1回合1次，自己主要阶段才能发动。这张卡的等级下降2星，这张卡以外的自己场上的全部表侧表示怪兽的等级变成1星。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ106762', '神科学因子 梅尔基奥尔', '①：1回合1次，自己主要阶段才能发动。从自己的手卡・场上把融合怪兽卡决定的融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组融合召唤。那个时候，这张卡可以作为1只融合素材怪兽的代替。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
