INSERT INTO "texts" VALUES ('ZZ107691', '机巧忍者部队 九', '机械族·地属性怪兽2只以上
INSERT INTO "texts" VALUES ('ZZ107692', '邪遗式狂乱乌贼怪', '「遗式」仪式魔法卡降临
INSERT INTO "texts" VALUES ('ZZ107693', '侵入魔鬼的幼体', '这个卡名的①②的效果1回合各能使用1次。
INSERT INTO "texts" VALUES ('ZZ107694', '圣骑士 兰斯洛特', '这个卡名的作为①的方法的特殊召唤1回合只能有1次，作为②的效果决斗中只能使用1次。
INSERT INTO "texts" VALUES ('ZZ107695', '机皇神 机录曲枝∞', '这张卡不能通常召唤。
INSERT INTO "texts" VALUES ('ZZ107696', '音响战士 效果器', '←9 【灵摆】 9→
INSERT INTO "texts" VALUES ('ZZ107697', '编年史超越学者-科技属 超图书馆员', '调整＋调整以外的怪兽1只以上
INSERT INTO "texts" VALUES ('ZZ107698', '刷拉拉拉将军', '4星怪兽×2只以上
INSERT INTO "texts" VALUES ('ZZ107699', '超越希望 怀抱梦想 No.39 希望皇 彼端超霍普', '这个卡名在规则上也当作「希望皇霍普」卡使用。
INSERT INTO "texts" VALUES ('ZZ107700', '闪光的异热同心', '这张卡不能通常召唤，用这张卡的效果才能特殊召唤。
INSERT INTO "texts" VALUES ('ZZ107701', '隆隆隆石人-强袭形态', '这张卡不能通常召唤。
INSERT INTO "texts" VALUES ('ZZ107702', '发条修理员', '这个卡名的①②的效果1回合各能使用1次。
INSERT INTO "texts" VALUES ('ZZ107703', '齿轮齿轮锚点车', '3星「齿轮齿轮」怪兽×2
INSERT INTO "texts" VALUES ('ZZ107704', '时械伪神 Z-ONE', '这个卡名在规则上也当作「时械神」卡使用。
INSERT INTO "texts" VALUES ('ZZ107705', '银河眼光子龙皇神话', '这个卡名的③的效果1回合只能使用1次。
INSERT INTO "texts" VALUES ('ZZ107706', '混沌No.90 银河眼光子皇', '光属性8星怪兽×3
INSERT INTO "texts" VALUES ('ZZ107707', '星圣·左旗一', '这个卡名的①的效果1回合只能使用1次。
INSERT INTO "texts" VALUES ('ZZ107708', '入魔巨龙 耶梦加得', '4星「入魔」怪兽×3
INSERT INTO "texts" VALUES ('ZZ107709', '怒怒怒斗笠剑士-我我我流', '这个卡名的①②的效果1回合各能使用1次。
INSERT INTO "texts" VALUES ('ZZ107710', '辉装合体 天狼霍普雷', '4星「异热同心武器」怪兽×3
INSERT INTO "texts" VALUES ('ZZ107711', '爆走特急 混沌冲天飞马', '这个卡名的①的效果1回合只能使用1次。
INSERT INTO "texts" VALUES ('ZZ107712', '圣刻煌龙-天神龙', '10星怪兽×3
INSERT INTO "texts" VALUES ('ZZ107713', '利斧保镖', '这个卡名的①的效果1回合只能使用1次。
INSERT INTO "texts" VALUES ('ZZ107714', '幻蝶刺客 光子蝶', '这个卡名的①的效果1回合只能使用1次。
INSERT INTO "texts" VALUES ('ZZ107715', '光芒使者 女武神', '①：这张卡可以把「光芒使者 女武神」以外的自己场上·墓地的1只光属性怪兽除外，从手卡特殊召唤。
INSERT INTO "texts" VALUES ('ZZ107716', '混沌No.17 海恶龙 海恶鲨龙兽', '水属性4星怪兽×3
INSERT INTO "texts" VALUES ('ZZ107717', '森之圣灵 阿赛德', '调整＋调整以外的地属性怪兽1只以上
INSERT INTO "texts" VALUES ('ZZ107718', '电子鱼人-推进者', '①：这张卡召唤的场合，以「电子鱼人-推进者」以外的自己墓地1只「电子鱼人」怪兽为对象才能发动。那只怪兽特殊召唤。
INSERT INTO "texts" VALUES ('ZZ107719', '机关傀儡-诅咒人偶', '这个卡名的①②的效果1回合各能使用1次。
INSERT INTO "texts" VALUES ('ZZ107720', '英豪冠军 希望之断钢剑王', '4星怪兽×2
INSERT INTO "texts" VALUES ('ZZ107721', '先史遗产 迈达斯纪念碑', '这个卡名的②的效果1回合只能使用1次。
INSERT INTO "texts" VALUES ('ZZ107722', '魔偶甜点·布丁公主 奇迹提拉米苏', '5星「魔偶甜点」怪兽×3
INSERT INTO "texts" VALUES ('ZZ107723', '爆裂拳', '①：自己场上的有「爆裂模式」的卡名记述的怪兽直到回合结束时，攻击力变成2倍，不受对方的效果影响。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ107724', '宿命之朱罗纪', '这个卡名的②的效果1回合只能使用1次。
INSERT INTO "texts" VALUES ('ZZ107725', '禁忌的圣水', '这个卡名的卡1回合只能发动1张，不能对应这张卡的发动让魔法·陷阱·怪兽的效果发动。
INSERT INTO "texts" VALUES ('ZZ107726', '命运重现', '这个卡名的卡1回合只能发动1张。
INSERT INTO "texts" VALUES ('ZZ107727', '废铁生态', '这个卡名的卡1回合只能发动1张。
INSERT INTO "texts" VALUES ('ZZ107728', '幻视', '这个卡名的效果1回合只能使用1次。
INSERT INTO "texts" VALUES ('ZZ107729', '薰风的团结', '这个卡名的卡1回合只能发动1张。
INSERT INTO "texts" VALUES ('ZZ107730', '极星宝 战车', '这个卡名的①②的效果1回合各能使用1次。
INSERT INTO "texts" VALUES ('ZZ107731', '超量命运抉择', '这个卡名的②的效果1回合只能使用1次。
INSERT INTO "texts" VALUES ('ZZ107732', '我我我拦截', '这个卡名的卡1回合只能发动1张。
INSERT INTO "texts" VALUES ('ZZ107733', '进化的对立面', '①：以自己场上1只龙族超量怪兽为对象才能发动。和那只怪兽阶级不同的1只「进化帝」超量怪兽在作为对象的怪兽上面重叠当作超量召唤从额外卡组特殊召唤，这张卡作为那个的超量素材。
INSERT INTO "texts" VALUES ('ZZ107734', '集结！甲虫装机！', '这个卡名的卡1回合只能发动1张。
INSERT INTO "texts" VALUES ('ZZ107735', '阳炎的遭遇', '①：可以从以下效果选择1个发动（这个卡名的以下效果1回合各能选择1次）。
INSERT INTO "texts" VALUES ('ZZ107736', '魔人再演 交响乐队', '这个卡名的卡1回合只能发动1张。
INSERT INTO "texts" VALUES ('ZZ107737', '灵神的斗争', '①：从卡组把1只「灵神」怪兽加入手卡。场上或自己的墓地有「灵神」怪兽存在的场合，可以作为代替把属性和那只「灵神」怪兽相同的1只「元素灵剑士」怪兽从卡组加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ107738', '死灵王 雷斯', '统治着不死族群和驱使亡者军团的骷髅帝王，手持着拥有死灵魔力的蓝色魔球权杖。任何敢挑战其统治的生者会成为它的麾下亡魂。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ107739', '海贼的狮子船长', '海盗船的船长，熟知大海的可怕。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ107740', '回旋镖小子', '操纵着自己制作的回力镖，为了生活而狩猎。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ107741', '赤鬃蓝鬃兽', '双手持剑，对斩杀敌人这件事产生快感。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ107742', '矢冠毒蠍', '栖息在暗域的节肢猎手，头顶的赤色箭冠是它宣告的死亡信号。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ107743', '威严天使', '很有气质的正义天使，以凛然的意志守护秩序，其威严足以震慑一切邪恶。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ107744', '迷唇怪', '在黑暗中看到了漂亮的嘴唇，说不定是“迷唇怪”呢。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ107745', '冰剑天使', '冰之剑的天使战士，剑身结着永不消融的霜华，能冻结一切靠近的邪恶。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('OCG00057', '混沌之三幻魔', '不能通常召唤的10星怪兽×3
INSERT INTO "texts" VALUES ('OCG00058', '黑色混沌之魔术师 黑混沌', '「光与暗之仪式」降临。
INSERT INTO "texts" VALUES ('OCG00059', '光与暗之战士 混沌战士', '「光与暗之仪式」降临。
INSERT INTO "texts" VALUES ('ZZ107746', 'CF-蟒蛇 手枪', '此卡由于对方卡片效果而被送去墓地时，可以随机抽取我方卡组1张卡给对方确认。
INSERT INTO "texts" VALUES ('ZZ107747', 'CF-沙漠之鹰 手枪', '舍弃手牌1张名字带有「CF」的卡，此卡可以直接攻击对方玩家生命值。攻击成功后，此卡破坏，我方从卡组抽1张卡加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ107748', 'CF-VZ61 手枪', '我方场上只有此卡时，可以选择投掷硬币1次。根据情况发动以下效果：●正面，我方可以直接攻击对方玩家。●反面，此卡破坏，对方受到此卡攻击力数值的生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ107749', 'CF-瓦尔特P38 手枪', '反转：选择卡组或墓地1张名字带有「CF」的卡加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ107750', 'CF-MK23 SOCOM 手枪', '1回合1次，此卡不会被战斗破坏。此卡因卡片效果从场上离开时，给予对方·对方场上怪兽数量×500点的生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ107751', 'CF-AK47 步枪', '此卡攻击力等于祭品怪兽等级合计数量×400。此卡在场表侧攻击表示时，玩家双方需支付500点生命值才能发动魔法·陷阱卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ107752', 'CF-AK47FS 步枪', '我方场上有1张名字带有「CF」的卡，此卡攻击力上升300点。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ107753', 'CF-HK G36C 步枪', '此卡攻击守备表示的怪兽时，不计算生命值伤害，直接将那只怪兽破坏。发动这个效果的回合，对方不能发动陷阱卡的效果。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ107754', 'CF-FAMAS 步枪', '此卡特殊召唤成功时，可以选择对方场上1张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ107755', 'CF-丰和64式 步枪', '反转：选择对方场上1张攻击力最高的卡回到持有者手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ107756', 'CF-M4A1 步枪', '此卡正面攻击表示在场时，1回合1次，投掷1次骰子。出现单数时，破坏对方场上1张魔法·陷阱卡。出现双数时，随机抽取对方1张手牌丢弃去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ107757', 'CF-KOBA 1022 步枪', '此卡正面攻击表示在场上时，1回合1次，投掷3次骰子。给予对方生命值那个投掷结果的合计数目×100数值的生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ107758', 'CF-SG550 步枪', '当这张卡成为对方卡片效果的对象时，可以选择投掷1次骰子，掷出2·4·6，则对方卡片效果无效并将其破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ107759', 'CF-G3A3 步枪', '此卡在我方墓地时，每个我方回合可以选择投掷1次骰子，点数是6的场合，此卡特殊召唤上场。其它数值时，对方受到那个点数×100点的生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ107760', 'CF-MP5A4 冲锋枪', '当对方怪兽特殊召唤成功时，可以选择投掷1次骰子，若掷出1或6，此卡攻击力加倍，掷出其它数字的场合，此卡攻击力减半。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ107761', 'CF-M4 SR16 冲锋枪', '此卡召唤成功时，可以选择卡组1张等级4以下名字带有「冲锋枪」的卡特殊召唤上场。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ107762', 'CF-MP5KA4 CQB 冲锋枪', '1回合1次，投掷1次骰子，若掷出2·4·6，这只怪兽可以对对方每只怪兽作出1次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ107763', 'CF-MP5K PDW 冲锋枪', '此卡由于陷阱卡效果而被送入墓地时，下个我方回合，墓地的与此卡同名的卡尽可能多的特殊召唤到场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ107764', 'CF-P90 冲锋枪', '对方场上有永续陷阱时，此卡可以从手牌特殊召唤上场。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ107765', 'CF-M3 散弹枪', '每舍弃1张手牌，此卡即可攻击对方怪兽1次。（此卡不可以直接攻击对方玩家生命值）', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ107766', 'CF-CA870 散弹枪', '此卡召唤成功时，舍弃手牌1张名字带有「散弹枪」的卡，可以将舍弃的那张卡的效果叠加到这张卡上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ107767', 'CF-黄金沙漠之鹰 手枪', '这张卡不能特殊召唤，只能用2只名字带有「沙漠之鹰」的怪兽作为祭品的场合才能通常召唤。此卡召唤成功后破坏对方场上所有卡片。只要此卡攻击表示存在于我方场上，每当我方准备阶段，可以将手牌1张卡送入墓地，从卡组中抽1张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ107768', 'CF-黄金AK47 步枪', '这张卡不能通常召唤。将我方墓地20张名字带有「CF」的卡除外时，此卡可以从手牌·卡组·墓地特殊召唤上场。此卡特殊召唤成功时，可以将对方墓地所有卡除外，给予对方除外卡的数量×200的生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ107769', 'CF-黄金战斧', '这张卡不能特殊召唤，只能将我方场上有「CF」的卡做祭品才能通常召唤。这张卡不受对方怪兽卡效果影响。当对方发动魔法·陷阱卡效果时，将我方场上有「CF」的怪兽送入墓地让那张卡的发动无效并破坏。这张卡因对方的卡的效果从场上离开时，可以从自己墓地选择最多3只名字带有「CF」的卡片特殊召唤到我方场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ107770', 'CF-M60E3 机枪', '此卡召唤成功时，攻击·守备力等于墓地名字带有「CF」的卡片数目×300。1回合1次，可以选择将墓地2张名字带有「CF」的卡片移除到游戏外，破坏对方场上1张覆盖的卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ107771', 'CF-M203 榴弹发射器', '这张卡不能特殊召唤，只能用3只名字带有「CF」的怪兽作为祭品的场合才能通常召唤。此卡召唤成功后破坏对方场上所有卡片。每到我方回合的准备阶段，给予对方我方场上存在的名字带有「CF」的卡片数量×500的生命值伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ107772', 'CF-战斧', '当我方场上不存在除此卡外名字带有「CF」的怪兽时，此卡不受对方怪兽卡效果影响。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ107773', 'CF-64式小铳 狙击枪', '此卡不能通常召唤。只要此卡以表侧攻击表示存在，对方不能选择我方其他卡片作为攻击对象。每到我方每回合准备阶段，此卡增加1个「弱点指示物」。当对方发动魔法·陷阱·怪兽效果时去除此卡1个「弱点指示物」，让那个效果发动无效，并破坏那张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('ZZ107774', '殉道者之时间限制', '此卡不受名字带有「奥利哈钢」的卡效果影响，限此卡在场上时，名字带有「奥利哈钢」的卡效果无效。
